                    <FormItem>
                      <FormLabel>{translate('ticketing.title', 'عنوان')} *</FormLabel>
                      <FormControl>
                        <Input {...field} placeholder={translate('ticketing.titlePlaceholder', 'عنوان مشکل را بنویسید...')} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
