            margin-top: 25px;
            margin-bottom: 12px;
            font-size: 18px;
        }

        h4 {
            color: #2563eb;
            margin-top: 20px;
            margin-bottom: 10px;
            font-size: 16px;
        }

        p {
            margin-bottom: 12px;
            text-align: justify;
            line-height: 1.8;
        }

        ul, ol {
            margin-bottom: 15px;
            padding-right: 20px;
        }

        li {
            margin-bottom: 8px;
            line-height: 1.6;
        }

        code {
            background-color: #f3f4f6;
            padding: 2px 6px;
            border-radius: 4px;
            font-family: 'Courier New', monospace;
            font-size: 14px;
        }

        pre {
            background-color: #f8fafc;
            border: 1px solid #e5e7eb;
            border-radius: 8px;
            padding: 15px;
            margin: 15px 0;
            overflow-x: auto;
            direction: ltr;
            text-align: left;
        }

        blockquote {
            border-right: 4px solid #fbbf24;
            background-color: #fffbeb;
            padding: 15px;
            margin: 15px 0;
            border-radius: 4px;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            font-size: 14px;
        }

        th, td {
            border: 1px solid #d1d5db;
            padding: 12px;
            text-align: center;
        }

        th {
            background-color: #f3f4f6;
            font-weight: bold;
            color: #374151;
        }

        .header {
            text-align: center;
            margin-bottom: 40px;
            padding: 20px;
            background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
            border-radius: 10px;
        }

        .footer {
            text-align: center;
            margin-top: 40px;
            padding: 20px;
            border-top: 2px solid #e5e7eb;
            color: #6b7280;
            font-size: 14px;
        }

        .section {
            margin-bottom: 30px;
            page-break-inside: avoid;
        }

        .highlight {
            background-color: #fef3c7;
            padding: 15px;
            border-radius: 8px;
            border-right: 4px solid #f59e0b;
            margin: 15px 0;
        }

        .english {
            direction: ltr;
