import React, { useState, useEffect, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Search, Filter, X, ChevronDown, Star, ShoppingCart, Eye, Flame } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { useToast } from '@/hooks/use-toast';
import { Slider } from '@/components/ui/slider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';

interface ShopProduct {
  id: number;
  name: string;
  category: string;
  description: string;
  shortDescription?: string;
  price: string;
  compareAtPrice?: string;
  priceUnit: string;
  inStock: boolean;
  stockQuantity: number;
  sku: string;
  imageUrls?: string[];
  thumbnailUrl?: string;
  tags?: string[];
  isFeatured: boolean;
  isFlammable?: boolean;
  specifications?: any;
  features?: any;
  applications?: any;
}

interface SearchFilters {
  category?: string;
  priceMin?: number;
  priceMax?: number;
  inStock?: boolean;
  tags?: string[];
  sortBy?: 'name' | 'price' | 'created' | 'relevance';
  sortOrder?: 'asc' | 'desc';
}

interface SearchResults {
  products: ShopProduct[];
  total: number;
  filters: {
    categories: { name: string; count: number }[];
    priceRange: { min: number; max: number };
    availableTags: string[];
  };
}

export default function ShopSearch() {
  const { toast } = useToast();
  const [searchQuery, setSearchQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');
  const [filters, setFilters] = useState<SearchFilters>({
    sortBy: 'relevance',
    sortOrder: 'desc'
  });
  const [currentPage, setCurrentPage] = useState(0);
  const [showFilters, setShowFilters] = useState(false);
  const [priceRange, setPriceRange] = useState<[number, number]>([0, 1000]);
  const itemsPerPage = 12;

  // Debounce search query
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(searchQuery);
      setCurrentPage(0);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchQuery]);

  // Search products query
  const { data: searchResults, isLoading, error } = useQuery<{
    success: boolean;
    data: SearchResults;
    query: any;
  }>({
    queryKey: ['shopSearch', debouncedQuery, filters, currentPage],
    queryFn: async () => {
      const params = new URLSearchParams({
        q: debouncedQuery,
        limit: itemsPerPage.toString(),
        offset: (currentPage * itemsPerPage).toString(),
        sortBy: filters.sortBy || 'relevance',
        sortOrder: filters.sortOrder || 'desc'
      });

      if (filters.category) params.append('category', filters.category);
      if (filters.priceMin !== undefined) params.append('priceMin', filters.priceMin.toString());
      if (filters.priceMax !== undefined) params.append('priceMax', filters.priceMax.toString());
      if (filters.inStock !== undefined) params.append('inStock', filters.inStock.toString());
      if (filters.tags?.length) {
        filters.tags.forEach(tag => params.append('tags', tag));
      }

      const response = await fetch(`/api/shop/search?${params}`);
      if (!response.ok) throw new Error('Search failed');
      return response.json();
    }
  });

  // Update price range when search results change
  useEffect(() => {
    if (searchResults?.data?.filters?.priceRange) {
      const { min, max } = searchResults.data.filters.priceRange;
      if (min !== priceRange[0] || max !== priceRange[1]) {
        setPriceRange([min, max]);
        if (!filters.priceMin && !filters.priceMax) {
          setFilters(prev => ({ ...prev, priceMin: min, priceMax: max }));
        }
      }
    }
  }, [searchResults?.data?.filters?.priceRange]);

  const handleFilterChange = (key: keyof SearchFilters, value: any) => {
    setFilters(prev => ({ ...prev, [key]: value }));
    setCurrentPage(0);
  };

  const handlePriceRangeChange = (value: [number, number]) => {
    setPriceRange(value);
    setFilters(prev => ({ ...prev, priceMin: value[0], priceMax: value[1] }));
    setCurrentPage(0);
  };

  const handleTagToggle = (tag: string) => {
    const currentTags = filters.tags || [];
    const newTags = currentTags.includes(tag)
      ? currentTags.filter(t => t !== tag)
      : [...currentTags, tag];
    handleFilterChange('tags', newTags.length ? newTags : undefined);
  };

  const clearFilters = () => {
    setFilters({ sortBy: 'relevance', sortOrder: 'desc' });
    setCurrentPage(0);
    if (searchResults?.data?.filters?.priceRange) {
      const { min, max } = searchResults.data.filters.priceRange;
      setPriceRange([min, max]);
    }
  };

  const formatPrice = (price: string, unit: string) => {
    return `$${parseFloat(price).toLocaleString()} / ${unit}`;
  };

  const products = searchResults?.data?.products || [];
  const totalPages = Math.ceil((searchResults?.data?.total || 0) / itemsPerPage);
  const availableFilters = searchResults?.data?.filters;

  return (
    <div className="container mx-auto px-4 py-6">
      <div className="mb-6">
        <h1 className="text-3xl font-bold mb-2">Advanced Product Search</h1>
        <p className="text-gray-600 mb-4">Search through our comprehensive chemical product catalog with advanced filters</p>

        {/* Search Bar */}
        <div className="flex gap-4 mb-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search products, categories, specifications, SKU, features..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 text-lg py-3"
            />
          </div>
          <Button
            variant="outline"
            onClick={() => setShowFilters(!showFilters)}
            className="flex items-center gap-2"
          >
            <Filter className="w-4 h-4" />
            Filters
            {Object.keys(filters).length > 2 && (
              <Badge variant="secondary" className="ml-1">
                {Object.keys(filters).length - 2}
              </Badge>
            )}
          </Button>
        </div>

        {/* Active Filters */}
        {(filters.category || filters.tags?.length || filters.inStock !== undefined) && (
          <div className="flex flex-wrap gap-2 mb-4">
            {filters.category && (
              <Badge variant="secondary" className="flex items-center gap-1">
                Category: {filters.category}
                <X 
                  className="w-3 h-3 cursor-pointer" 
                  onClick={() => handleFilterChange('category', undefined)}
                />
              </Badge>
            )}
            {filters.tags?.map(tag => (
              <Badge key={tag} variant="secondary" className="flex items-center gap-1">
                {tag}
                <X 
                  className="w-3 h-3 cursor-pointer" 
                  onClick={() => handleTagToggle(tag)}
                />
              </Badge>
            ))}
            {filters.inStock !== undefined && (
              <Badge variant="secondary" className="flex items-center gap-1">
                {filters.inStock ? 'In Stock' : 'All Stock'}
                <X 
                  className="w-3 h-3 cursor-pointer" 
                  onClick={() => handleFilterChange('inStock', undefined)}
                />
              </Badge>
            )}
            <Button variant="ghost" size="sm" onClick={clearFilters}>
              Clear all
            </Button>
          </div>
        )}
      </div>

      <div className="flex gap-6">
        {/* Filters Sidebar */}
        <Collapsible open={showFilters} onOpenChange={setShowFilters}>
          <CollapsibleContent className="w-80">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center justify-between">
                  Filters
                  <Button variant="ghost" size="sm" onClick={clearFilters}>
                    Clear all
                  </Button>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Sort */}
                <div>
                  <Label className="text-sm font-medium">Sort by</Label>
                  <div className="flex gap-2 mt-2">
                    <Select 
                      value={filters.sortBy || 'relevance'} 
                      onValueChange={(value) => handleFilterChange('sortBy', value)}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="relevance">Relevance</SelectItem>
                        <SelectItem value="name">Name</SelectItem>
                        <SelectItem value="price">Price</SelectItem>
                        <SelectItem value="created">Newest</SelectItem>
                      </SelectContent>
                    </Select>
                    <Select 
                      value={filters.sortOrder || 'desc'} 
                      onValueChange={(value) => handleFilterChange('sortOrder', value)}
                    >
                      <SelectTrigger className="w-24">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="asc">A-Z</SelectItem>
                        <SelectItem value="desc">Z-A</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* Categories */}
                {availableFilters?.categories && availableFilters.categories.length > 0 && (
                  <div>
                    <Label className="text-sm font-medium">Categories</Label>
                    <div className="mt-2 space-y-2">
                      {availableFilters.categories.map(cat => (
                        <div key={cat.name} className="flex items-center space-x-2">
                          <Checkbox
                            id={`cat-${cat.name}`}
                            checked={filters.category === cat.name}
                            onCheckedChange={(checked) => 
                              handleFilterChange('category', checked ? cat.name : undefined)
                            }
                          />
                          <label 
                            htmlFor={`cat-${cat.name}`}
                            className="text-sm cursor-pointer flex-1"
                          >
                            {cat.name} ({cat.count})
                          </label>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Price Range */}
                {availableFilters?.priceRange && (
                  <div>
                    <Label className="text-sm font-medium">
                      Price Range: ${priceRange[0]} - ${priceRange[1]}
                    </Label>
                    <div className="mt-2">
                      <Slider
                        value={priceRange}
                        onValueChange={handlePriceRangeChange}
                        max={availableFilters.priceRange.max}
                        min={availableFilters.priceRange.min}
                        step={10}
                        className="w-full"
                      />
                    </div>
                  </div>
                )}

                {/* Stock Status */}
                <div>
                  <Label className="text-sm font-medium">Availability</Label>
                  <div className="mt-2 space-y-2">
                    <div className="flex items-center space-x-2">
                      <Checkbox
                        id="in-stock"
                        checked={filters.inStock === true}
                        onCheckedChange={(checked) => 
                          handleFilterChange('inStock', checked ? true : undefined)
                        }
                      />
                      <label htmlFor="in-stock" className="text-sm cursor-pointer">
                        In Stock Only
                      </label>
                    </div>
                  </div>
                </div>

                {/* Tags */}
                {availableFilters?.availableTags && availableFilters.availableTags.length > 0 && (
                  <div>
                    <Label className="text-sm font-medium">Tags</Label>
                    <div className="mt-2 flex flex-wrap gap-1">
                      {availableFilters.availableTags.slice(0, 10).map(tag => (
                        <Badge
                          key={tag}
                          variant={filters.tags?.includes(tag) ? "default" : "outline"}
                          className="cursor-pointer"
                          onClick={() => handleTagToggle(tag)}
                        >
                          {tag}
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </CollapsibleContent>
        </Collapsible>

        {/* Results */}
        <div className="flex-1">
          {/* Results Header */}
          <div className="flex justify-between items-center mb-4">
            <div className="text-sm text-gray-600">
              {isLoading ? (
                'Searching...'
              ) : (
                `${searchResults?.data?.total || 0} visible products found`
              )}
              {debouncedQuery && ` for "${debouncedQuery}"`}
            </div>
          </div>

          {/* Products Grid */}
          {isLoading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {Array.from({ length: 8 }).map((_, i) => (
                <Card key={i} className="animate-pulse">
                  <div className="h-48 bg-gray-200 rounded-t-lg"></div>
                  <CardContent className="p-4">
                    <div className="h-4 bg-gray-200 rounded mb-2"></div>
                    <div className="h-3 bg-gray-200 rounded mb-2"></div>
                    <div className="h-6 bg-gray-200 rounded"></div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : error ? (
            <div className="text-center py-12">
              <p className="text-red-500">Error searching products. Please try again.</p>
            </div>
          ) : products.length === 0 ? (
            <div className="text-center py-12">
              <div className="mb-4">
                <Search className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500 text-lg">No products found matching your criteria.</p>
                <p className="text-gray-400 text-sm mt-2">Try adjusting your search terms or clearing filters</p>
              </div>
              <Button variant="outline" onClick={clearFilters} className="mt-4">
                Clear all filters
              </Button>
            </div>
          ) : (
            <>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 mb-8">
                {products.map((product) => (
                  <Card key={product.id} className="group hover:shadow-lg transition-shadow">
                    <div className="relative">
                      {product.thumbnailUrl ? (
                        <img
                          src={product.thumbnailUrl}
                          alt={product.name}
                          className="w-full h-48 object-cover rounded-t-lg"
                        />
                      ) : (
                        <div className="w-full h-48 bg-gray-100 rounded-t-lg flex items-center justify-center">
                          <div className="text-gray-400">No image</div>
                        </div>
                      )}
                      {product.isFeatured && (
                        <Badge className="absolute top-2 left-2">
                          <Star className="w-3 h-3 mr-1" />
                          Featured
                        </Badge>
                      )}
                      {!product.inStock && (
                        <Badge variant="destructive" className="absolute top-2 right-2">
                          Out of Stock
                        </Badge>
                      )}
                      {product.isFlammable && (
                        <Badge variant="outline" className="absolute bottom-2 left-2 bg-orange-100 text-orange-800 border-orange-300">
                          <Flame className="w-3 h-3 mr-1" />
                          آتش‌زا
                        </Badge>
                      )}
                    </div>

                    <CardContent className="p-4">
                      <h3 className="font-semibold text-sm mb-1 line-clamp-2">{product.name}</h3>
                      <p className="text-xs text-gray-600 mb-2">{product.category}</p>
                      {product.shortDescription && (
                        <p className="text-xs text-gray-500 mb-3 line-clamp-2">
                          {product.shortDescription}
                        </p>
                      )}

                      <div className="flex items-center justify-between mb-3">
                        <div>
                          <div className="font-bold text-lg">
                            {formatPrice(product.price, product.priceUnit)}
                          </div>
                          {product.compareAtPrice && (
                            <div className="text-xs text-gray-500 line-through">
                              ${parseFloat(product.compareAtPrice).toLocaleString()}
                            </div>
                          )}
                        </div>
                        <div className="text-xs text-gray-500">
                          SKU: {product.sku}
                        </div>
                      </div>

                      {/* Product weight display */}
                      {product.weight && (
                        <div className="flex items-center gap-1 mb-3 text-xs text-gray-600">
                          <span className="font-medium">وزن:</span>
                          <span>
                            {parseFloat(product.weight).toFixed(1)} {product.weightUnit || 'kg'}
                          </span>
                        </div>
                      )}

                      {product.tags && product.tags.length > 0 && (
                        <div className="flex flex-wrap gap-1 mb-3">
                          {product.tags.slice(0, 3).map(tag => (
                            <Badge key={tag} variant="outline" className="text-xs">
                              {tag}
                            </Badge>
                          ))}
                        </div>
                      )}

                      <div className="flex gap-2">
                        <Button 
                          size="sm" 
                          className="flex-1" 
                          disabled={!product.inStock}
                          onClick={() => {
                            toast({
                              title: "Added to Cart",
                              description: `${product.name} has been added to your cart.`,
                            });
                          }}
                        >
                          <ShoppingCart className="w-3 h-3 mr-1" />
                          Add to Cart
                        </Button>
                        <Button size="sm" variant="outline">
                          <Eye className="w-3 h-3" />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex justify-center items-center gap-2">
                  <Button
                    variant="outline"
                    disabled={currentPage === 0}
                    onClick={() => setCurrentPage(currentPage - 1)}
                  >
                    Previous
                  </Button>

                  <div className="flex gap-1">
                    {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => {
                      const pageNum = Math.max(0, Math.min(currentPage - 2 + i, totalPages - 1));
                      return (
                        <Button
                          key={`page-${pageNum}`}
                          variant={currentPage === pageNum ? "default" : "outline"}
                          size="sm"
                          onClick={() => setCurrentPage(pageNum)}
                        >
                          {pageNum + 1}
                        </Button>
                      );
                    })}
                  </div>

                  <Button
                    variant="outline"
                    disabled={currentPage === totalPages - 1}
                    onClick={() => setCurrentPage(currentPage + 1)}
                  >
                    Next
                  </Button>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

shared/persistent-cart-schema.ts.content:
import { pgTable, text, serial, timestamp, decimal, boolean, integer, json, varchar } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// =============================================================================
// PERSISTENT CART SYSTEM
// =============================================================================
// این جدول سبد خرید مشتریان را در دیتابیس ذخیره می‌کند
// تا حین لاگین مجدد حفظ شود

export const persistentCarts = pgTable("persistent_carts", {
  id: serial("id").primaryKey(),
  customerId: integer("customer_id").notNull(), // شناسه مشتری
  productId: integer("product_id").notNull(), // شناسه محصول
  quantity: integer("quantity").notNull().default(1), // تعداد محصول در سبد
  unitPrice: decimal("unit_price", { precision: 10, scale: 2 }), // قیمت واحد (برای محفوظ ماندن قیمت)
  addedAt: timestamp("added_at").notNull().defaultNow(), // زمان اضافه شدن به سبد
  updatedAt: timestamp("updated_at").notNull().defaultNow(), // آخرین بروزرسانی
  sessionId: varchar("session_id", { length: 255 }), // شناسه جلسه (اختیاری)
  isActive: boolean("is_active").default(true), // آیا این آیتم هنوز فعال است؟
  notes: text("notes"), // یادداشت‌های اضافی
});

export const insertPersistentCartSchema = createInsertSchema(persistentCarts);
export type InsertPersistentCart = z.infer<typeof insertPersistentCartSchema>;
export type PersistentCart = typeof persistentCarts.$inferSelect;

// Schema برای بروزرسانی سبد خرید
export const updatePersistentCartSchema = insertPersistentCartSchema.partial();
export type UpdatePersistentCart = z.infer<typeof updatePersistentCartSchema>;

client/src/pages/super-admin-settings.ts.content:
import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Eye, EyeOff, Shield, Mail, Phone, Key, UserPlus, Trash2, CheckCircle, XCircle } from "lucide-react";

interface SuperAdmin {
  id: number;
  username: string;
  email: string;
  phone?: string;
  isActive: boolean;
  emailVerified: boolean;
  phoneVerified: boolean;
  lastLoginAt: string | null;
  createdAt: string;
}

interface PendingVerification {
  id: number;
  email: string;
  phone?: string;
  verificationCode: string;
  type: 'email' | 'sms';
  expiresAt: string;
  createdAt: string;
}

export default function SuperAdminSettings() {
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [newAdminData, setNewAdminData] = useState({
    username: '',
    email: '',
    phone: '',
    password: '',
    confirmPassword: ''
  });
  const [resetEmailData, setResetEmailData] = useState({
    email: '',
    verificationCode: '',
    newPassword: '',
    confirmNewPassword: ''
  });
  const [verificationData, setVerificationData] = useState({
    adminId: 0,
    type: 'email' as 'email' | 'sms',
    code: ''
  });

  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Clear form function
  const clearForm = () => {
    setNewAdminData({
      username: '',
      email: '',
      phone: '',
      password: '',
      confirmPassword: ''
    });
    setShowPassword(false);
    setShowConfirmPassword(false);
  };

  // Ensure form is clear on component mount
  useEffect(() => {
    clearForm();
  }, []);

  // Fetch super admins
  const { data: superAdmins = [], isLoading: loadingAdmins } = useQuery({
    queryKey: ['/api/super-admin/admins'],
  });

  // Fetch pending verifications
  const { data: pendingVerifications = [], isLoading: loadingVerifications } = useQuery({
    queryKey: ['/api/super-admin/pending-verifications'],
  });

  // Create new super admin
  const createAdminMutation = useMutation({
    mutationFn: async (data: typeof newAdminData) => {
      return await apiRequest('/api/super-admin/create', 'POST', data);
    },
    onSuccess: (response) => {
      toast({
        title: "Super Admin Created",
        description: response.message || "New super admin created successfully. Email verification code sent.",
      });
      clearForm();
      queryClient.invalidateQueries({ queryKey: ['/api/super-admin/admins'] });
      queryClient.invalidateQueries({ queryKey: ['/api/super-admin/pending-verifications'] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Error creating super admin",
        variant: "destructive"
      });
    }
  });

  // Send verification code
  const sendVerificationMutation = useMutation({
    mutationFn: async ({ adminId, type }: { adminId: number, type: 'email' | 'sms' }) => {
      return await apiRequest('/api/super-admin/send-verification', 'POST', { adminId, type });
    },
    onSuccess: (response) => {
      toast({
        title: "Verification Code Sent",
        description: response.message || "Verification code sent successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Error sending verification code",
        variant: "destructive"
      });
    }
  });

  // Verify code
  const verifyCodeMutation = useMutation({
    mutationFn: async (data: typeof verificationData) => {
      return await apiRequest('/api/super-admin/verify', 'POST', data);
    },
    onSuccess: (response) => {
      toast({
        title: "Verification Successful",
        description: response.message || "Account verified successfully",
      });
      setVerificationData({ adminId: 0, type: 'email', code: '' });
      queryClient.invalidateQueries({ queryKey: ['/api/super-admin/admins'] });
      queryClient.invalidateQueries({ queryKey: ['/api/super-admin/pending-verifications'] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Invalid verification code",
        variant: "destructive"
      });
    }
  });

  // Password reset request
  const passwordResetMutation = useMutation({
    mutationFn: async (email: string) => {
      return await apiRequest('/api/super-admin/forgot-password', 'POST', { email });
    },
    onSuccess: (response) => {
      toast({
        title: "Recovery Code Sent",
        description: response.message || "Password recovery code sent to your email",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Error sending recovery code",
        variant: "destructive"
      });
    }
  });

  // Reset password with code
  const resetPasswordMutation = useMutation({
    mutationFn: async (data: typeof resetEmailData) => {
      return await apiRequest('/api/super-admin/reset-password', 'POST', data);
    },
    onSuccess: (response) => {
      toast({
        title: "Password Changed",
        description: response.message || "Password changed successfully",
      });
      setResetEmailData({
        email: '',
        verificationCode: '',
        newPassword: '',
        confirmNewPassword: ''
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Error changing password",
        variant: "destructive"
      });
    }
  });

  // Delete super admin
  const deleteAdminMutation = useMutation({
    mutationFn: async (adminId: number) => {
      return await apiRequest(`/api/super-admin/admins/${adminId}`, 'DELETE');
    },
    onSuccess: (response) => {
      toast({
        title: "Super Admin Deleted",
        description: response.message || "Super admin deleted successfully",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/super-admin/admins'] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Error deleting super admin",
        variant: "destructive"
      });
    }
  });

  const handleCreateAdmin = () => {
    if (newAdminData.password !== newAdminData.confirmPassword) {
      toast({
        title: "Error",
        description: "Password and confirm password do not match",
        variant: "destructive"
      });
      return;
    }
    if (newAdminData.password.length < 6) {
      toast({
        title: "Error",
        description: "Password must be at least 6 characters long",
        variant: "destructive"
      });
      return;
    }
    createAdminMutation.mutate(newAdminData);
  };

  const handleResetPassword = () => {
    if (resetEmailData.newPassword !== resetEmailData.confirmNewPassword) {
      toast({
        title: "Error",
        description: "New password and confirmation do not match",
        variant: "destructive"
      });
      return;
    }
    if (resetEmailData.newPassword.length < 6) {
      toast({
        title: "Error",
        description: "Password must be at least 6 characters long",
        variant: "destructive"
      });
      return;
    }
    resetPasswordMutation.mutate(resetEmailData);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800 p-6">
      <div className="max-w-6xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            <Shield className="h-8 w-8 text-blue-600" />
            Super Admin Management
          </h1>
          <p className="text-slate-600 dark:text-slate-300 mt-2">
            Create, manage and verify super admin accounts
          </p>
        </div>

        <Tabs defaultValue="create" className="space-y-6">
          <TabsList className="grid w-full grid-cols-4">
            <TabsTrigger value="create">Create Super Admin</TabsTrigger>
            <TabsTrigger value="manage">Manage Admins</TabsTrigger>
            <TabsTrigger value="verify">Verify Account</TabsTrigger>
            <TabsTrigger value="reset">Reset Password</TabsTrigger>
          </TabsList>

          {/* Create Super Admin */}
          <TabsContent value="create">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <UserPlus className="h-5 w-5" />
                  Create New Super Admin
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="username">Username</Label>
                    <Input
                      id="username"
                      value={newAdminData.username}
                      onChange={(e) => setNewAdminData(prev => ({ ...prev, username: e.target.value }))}
                      placeholder="Enter username"
                    />
                  </div>
                  <div>
                    <Label htmlFor="email">Email</Label>
                    <Input
                      id="email"
                      type="email"
                      value={newAdminData.email}
                      onChange={(e) => setNewAdminData(prev => ({ ...prev, email: e.target.value }))}
                      placeholder="Enter email address"
                    />
                  </div>
                  <div>
                    <Label htmlFor="phone">Phone Number (Optional)</Label>
                    <Input
                      id="phone"
                      value={newAdminData.phone}
                      onChange={(e) => setNewAdminData(prev => ({ ...prev, phone: e.target.value }))}
                      placeholder="Enter phone number"
                    />
                  </div>
                </div>
                <div>
                  <Label htmlFor="password">Password</Label>
                  <div className="relative">
                    <Input
                      id="password"
                      type={showPassword ? "text" : "password"}
                      value={newAdminData.password}
                      onChange={(e) => setNewAdminData(prev => ({ ...prev, password: e.target.value }))}
                      placeholder="Enter password"
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="absolute right-0 top-0 h-full px-3"
                      onClick={() => setShowPassword(!showPassword)}
                    >
                      {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </Button>
                  </div>
                </div>
                <div>
                  <Label htmlFor="confirmPassword">Confirm Password</Label>
                  <div className="relative">
                    <Input
                      id="confirmPassword"
                      type={showConfirmPassword ? "text" : "password"}
                      value={newAdminData.confirmPassword}
                      onChange={(e) => setNewAdminData(prev => ({ ...prev, confirmPassword: e.target.value }))}
                      placeholder="Confirm password"
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="absolute right-0 top-0 h-full px-3"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    >
                      {showConfirmPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </Button>
                  </div>
                </div>
                <Button 
                  onClick={handleCreateAdmin}
                  disabled={createAdminMutation.isPending || !newAdminData.username || !newAdminData.email || !newAdminData.password}
                  className="w-full"
                >
                  {createAdminMutation.isPending ? "Creating..." : "Create Super Admin"}
                </Button>
              </CardContent>
            </Card>
          </TabsContent>

          {/* Manage Super Admins */}
          <TabsContent value="manage">
            <Card>
              <CardHeader>
                <CardTitle>Super Admin List</CardTitle>
              </CardHeader>
              <CardContent>
                {loadingAdmins ? (
                  <div className="text-center py-8">Loading...</div>
                ) : (
                  <div className="space-y-4">
                    {superAdmins?.map((admin: SuperAdmin) => (
                      <div key={admin.id} className="flex items-center justify-between p-4 border rounded-lg">
                        <div className="flex-1">
                          <div className="flex items-center gap-3">
                            <h3 className="font-semibold">{admin.username}</h3>
                            <Badge variant={admin.isActive ? "default" : "secondary"}>
                              {admin.isActive ? "Active" : "Inactive"}
                            </Badge>
                            {admin.emailVerified && (
                              <Badge variant="outline" className="text-green-600">
                                <Mail className="h-3 w-3 mr-1" />
                                Email Verified
                              </Badge>
                            )}
                            {admin.phoneVerified && (
                              <Badge variant="outline" className="text-blue-600">
                                <Phone className="h-3 w-3 mr-1" />
                                Phone Verified
                              </Badge>
                            )}
                          </div>
                          <p className="text-sm text-slate-600 mt-1">{admin.email}</p>
                          {admin.phone && (
                            <p className="text-sm text-slate-600">{admin.phone}</p>
                          )}
                          {admin.lastLoginAt && (
                            <p className="text-xs text-slate-500 mt-1">
                              Last login: {new Date(admin.lastLoginAt).toLocaleDateString('en-US')}
                            </p>
                          )}
                        </div>
                        <div className="flex items-center gap-2">
                          {!admin.emailVerified && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => sendVerificationMutation.mutate({ adminId: admin.id, type: 'email' })}
                            >
                              <Mail className="h-4 w-4 mr-1" />
                              Verify Email
                            </Button>
                          )}
                          {admin.phone && !admin.phoneVerified && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => sendVerificationMutation.mutate({ adminId: admin.id, type: 'sms' })}
                            >
                              <Phone className="h-4 w-4 mr-1" />
                              Verify Phone
                            </Button>
                          )}
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => deleteAdminMutation.mutate(admin.id)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Verify Account */}
          <TabsContent value="verify">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Account Verification</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <Label htmlFor="adminSelect">Select Admin</Label>
                    <select
                      id="adminSelect"
                      className="w-full p-2 border rounded-md"
                      value={verificationData.adminId}
                      onChange={(e) => setVerificationData(prev => ({ ...prev, adminId: parseInt(e.target.value) }))}
                    >
                      <option value={0}>Select an admin</option>
                      {superAdmins?.filter((admin: SuperAdmin) => !admin.emailVerified || (admin.phone && !admin.phoneVerified)).map((admin: SuperAdmin) => (
                        <option key={admin.id} value={admin.id}>
                          {admin.username} - {admin.email}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <Label htmlFor="verificationType">Verification Type</Label>
                    <select
                      id="verificationType"
                      className="w-full p-2 border rounded-md"
                      value={verificationData.type}
                      onChange={(e) => setVerificationData(prev => ({ ...prev, type: e.target.value as 'email' | 'sms' }))}
                    >
                      <option value="email">Email</option>
                      <option value="sms">SMS</option>
                    </select>
                  </div>
                  <div>
                    <Label htmlFor="verificationCode">Verification Code</Label>
                    <Input
                      id="verificationCode"
                      value={verificationData.code}
                      onChange={(e) => setVerificationData(prev => ({ ...prev, code: e.target.value }))}
                      placeholder="Enter 6-digit code"
                      maxLength={6}
                    />
                  </div>
                  <Button
                    onClick={() => verifyCodeMutation.mutate(verificationData)}
                    disabled={verifyCodeMutation.isPending || !verificationData.adminId || !verificationData.code}
                    className="w-full"
                  >
                    {verifyCodeMutation.isPending ? "Verifying..." : "Verify Code"}
                  </Button>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Pending Verification Codes</CardTitle>
                </CardHeader>
                <CardContent>
                  {loadingVerifications ? (
                    <div className="text-center py-4">Loading...</div>
                  ) : (
                    <div className="space-y-3">
                      {pendingVerifications?.map((verification: PendingVerification) => (
                        <div key={verification.id} className="p-3 border rounded-lg">
                          <div className="flex items-center justify-between">
                            <div>
                              <p className="font-medium">{verification.email}</p>
                              <p className="text-sm text-slate-600">
                                {verification.type === 'email' ? 'Email' : 'SMS'} - 
                                Code: {verification.verificationCode}
                              </p>
                              <p className="text-xs text-slate-500">
                                Expires: {new Date(verification.expiresAt).toLocaleString('en-US')}
                              </p>
                            </div>
                            <Badge variant={new Date(verification.expiresAt) > new Date() ? "default" : "destructive"}>
                              {new Date(verification.expiresAt) > new Date() ? "Active" : "Expired"}
                            </Badge>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          {/* Password Reset */}
          <TabsContent value="reset">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>Password Recovery Request</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <Label htmlFor="resetEmail">Super Admin Email</Label>
                    <Input
                      id="resetEmail"
                      type="email"
                      value={resetEmailData.email}
                      onChange={(e) => setResetEmailData(prev => ({ ...prev, email: e.target.value }))}
                      placeholder="Enter email address"
                    />
                  </div>
                  <Button
                    onClick={() => passwordResetMutation.mutate(resetEmailData.email)}
                    disabled={passwordResetMutation.isPending || !resetEmailData.email}
                    className="w-full"
                  >
                    {passwordResetMutation.isPending ? "Sending..." : "Send Recovery Code"}
                  </Button>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Change Password with Code</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <Label htmlFor="resetCode">Recovery Code</Label>
                    <Input
                      id="resetCode"
                      value={resetEmailData.verificationCode}
                      onChange={(e) => setResetEmailData(prev => ({ ...prev, verificationCode: e.target.value }))}
                      placeholder="6-digit code from email"
                      maxLength={6}
                    />
                  </div>
                  <div>
                    <Label htmlFor="newPassword">New Password</Label>
                    <Input
                      id="newPassword"
                      type="password"
                      value={resetEmailData.newPassword}
                      onChange={(e) => setResetEmailData(prev => ({ ...prev, newPassword: e.target.value }))}
                      placeholder="Enter new password"
                    />
                  </div>
                  <div>
                    <Label htmlFor="confirmNewPassword">Confirm New Password</Label>
                    <Input
                      id="confirmNewPassword"
                      type="password"
                      value={resetEmailData.confirmNewPassword}
                      onChange={(e) => setResetEmailData(prev => ({ ...prev, confirmNewPassword: e.target.value }))}
                      placeholder="Re-enter new password"
                    />
                  </div>
                  <Button
                    onClick={handleResetPassword}
                    disabled={resetPasswordMutation.isPending || !resetEmailData.verificationCode || !resetEmailData.newPassword}
                    className="w-full"
                  >
                    {resetPasswordMutation.isPending ? "Changing..." : "Change Password"}
                  </Button>
                </CardContent>
              </Card>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

server/barcode-batch-generator.ts.content:
// Batch Barcode Generator for Existing Products
import { generateEAN13Barcode } from "@shared/barcode-utils";
import { storage } from "./storage";
import { showcaseStorage } from "./showcase-storage";

export async function generateBarcodesForExistingProducts() {
  try {
    console.log('Starting batch barcode generation for existing products...');

    // Get all showcase products without barcodes
    const allProducts = await showcaseStorage.getAllShowcaseProducts();
    const productsWithoutBarcodes = allProducts.filter(p => !p.barcode || p.barcode.trim() === '');

    console.log(`Found ${productsWithoutBarcodes.length} products without barcodes out of ${allProducts.length} total`);

    const results = [];

    for (const product of productsWithoutBarcodes) {
      try {
        // Generate barcode with new format
        const generatedBarcode = await generateEAN13Barcode(product.name, product.category);

        // Update product with barcode
        await showcaseStorage.updateShowcaseProduct(product.id, {
          barcode: generatedBarcode
        });

        results.push({
          id: product.id,
          name: product.name,
          category: product.category,
          barcode: generatedBarcode,
          success: true
        });

        console.log(`✓ Generated barcode ${generatedBarcode} for product: ${product.name}`);

      } catch (error) {
        console.error(`✗ Failed to generate barcode for product ${product.name}:`, error);
        results.push({
          id: product.id,
          name: product.name,
          category: product.category,
          barcode: null,
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }

    console.log(`Batch generation complete. Success: ${results.filter(r => r.success).length}/${results.length}`);
    return results;

  } catch (error) {
    console.error('Batch barcode generation failed:', error);
    throw error;
  }
}

// Function to regenerate all barcodes (use with caution)
export async function regenerateAllBarcodes() {
  try {
    console.log('Starting regeneration of ALL product barcodes...');

    const products = await showcaseStorage.getAllShowcaseProducts();
    console.log(`Found ${products.length} products for barcode regeneration`);

    const results = [];

    for (const product of products) {
      try {
        // Generate new barcode
        const generatedBarcode = generateEAN13Barcode(product.name, product.category);

        // Update product with new barcode
        await showcaseStorage.updateShowcaseProduct(product.id, {
          barcode: generatedBarcode
        });

        results.push({
          id: product.id,
          name: product.name,
          category: product.category,
          oldBarcode: product.barcode,
          newBarcode: generatedBarcode,
          success: true
        });

        console.log(`✓ Updated barcode for ${product.name}: ${product.barcode} → ${generatedBarcode}`);

      } catch (error) {
        console.error(`✗ Failed to regenerate barcode for product ${product.name}:`, error);
        results.push({
          id: product.id,
          name: product.name,
          category: product.category,
          oldBarcode: product.barcode,
          newBarcode: null,
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }

    console.log(`Regeneration complete. Success: ${results.filter(r => r.success).length}/${results.length}`);
    return results;

  } catch (error) {
    console.error('Barcode regeneration failed:', error);
    throw error;
  }
}

shared/webrtc-schema.ts.content:
import { pgTable, varchar, text, timestamp, boolean, jsonb, integer } from "drizzle-orm/pg-core";
import { createInsertSchema, createSelectSchema } from "drizzle-zod";
import { z } from "zod";

// WebRTC Rooms table
export const webrtcRooms = pgTable("webrtc_rooms", {
  id: varchar("id").primaryKey(),
  name: varchar("name").notNull(),
  description: text("description"),
  createdBy: varchar("created_by").notNull(),
  isActive: boolean("is_active").default(true),
  maxParticipants: integer("max_participants").default(10),
  settings: jsonb("settings"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Room Participants table
export const roomParticipants = pgTable("room_participants", {
  id: varchar("id").primaryKey(),
  roomId: varchar("room_id").references(() => webrtcRooms.id).notNull(),
  userId: varchar("user_id").notNull(),
  userName: varchar("user_name").notNull(),
  socketId: varchar("socket_id"),
  isHost: boolean("is_host").default(false),
  isMuted: boolean("is_muted").default(false),
  hasVideo: boolean("has_video").default(true),
  isScreenSharing: boolean("is_screen_sharing").default(false),
  joinedAt: timestamp("joined_at").defaultNow(),
  leftAt: timestamp("left_at"),
});

// Chat Messages table
export const chatMessages = pgTable("chat_messages", {
  id: varchar("id").primaryKey(),
  roomId: varchar("room_id").references(() => webrtcRooms.id).notNull(),
  userId: varchar("user_id").notNull(),
  userName: varchar("user_name").notNull(),
  message: text("message").notNull(),
  messageType: varchar("message_type").default("text"), // text, file, system
  createdAt: timestamp("created_at").defaultNow(),
});

// Zod schemas
export const insertWebrtcRoomSchema = createInsertSchema(webrtcRooms);
export const selectWebrtcRoomSchema = createSelectSchema(webrtcRooms);

export const insertRoomParticipantSchema = createInsertSchema(roomParticipants);
export const selectRoomParticipantSchema = createSelectSchema(roomParticipants);

export const insertChatMessageSchema = createInsertSchema(chatMessages);
export const selectChatMessageSchema = createSelectSchema(chatMessages);

// Types
export type WebrtcRoom = typeof webrtcRooms.$inferSelect;
export type InsertWebrtcRoom = typeof webrtcRooms.$inferInsert;

export type RoomParticipant = typeof roomParticipants.$inferSelect;
export type InsertRoomParticipant = typeof roomParticipants.$inferInsert;

export type ChatMessage = typeof chatMessages.$inferSelect;
export type InsertChatMessage = typeof chatMessages.$inferInsert;

// WebRTC Events
export interface WebRTCEvents {
  "join-room": { roomId: string; userName: string; userId: string };
  "leave-room": { roomId: string; userId: string };
  "offer": { roomId: string; offer: RTCSessionDescriptionInit; to: string };
  "answer": { roomId: string; answer: RTCSessionDescriptionInit; to: string };
  "ice-candidate": { roomId: string; candidate: RTCIceCandidateInit; to: string };
  "chat-message": { roomId: string; message: string; userId: string; userName: string };
  "toggle-audio": { roomId: string; userId: string; isMuted: boolean };
  "toggle-video": { roomId: string; userId: string; hasVideo: boolean };
  "start-screen-share": { roomId: string; userId: string };
  "stop-screen-share": { roomId: string; userId: string };
}

client/src/pages/SecureUploadExample.tsx.content:
import { useState } from 'react';
import SecureFileUploader from '@/components/SecureFileUploader';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Shield, FileCheck, AlertTriangle, CheckCircle } from 'lucide-react';

interface UploadLog {
  id: string;
  fileName: string;
  status: 'success' | 'failed';
  timestamp: string;
  report?: string;
  errors?: string[];
}

export default function SecureUploadExample() {
  const [uploadLogs, setUploadLogs] = useState<UploadLog[]>([]);
  const [systemStatus, setSystemStatus] = useState<any>(null);

  // Fetch system status on component mount
  useState(() => {
    fetch('/api/secure-upload/status')
      .then(res => res.json())
      .then(data => setSystemStatus(data))
      .catch(err => console.error('Error fetching system status:', err));
  });

  const handleUploadComplete = (result: any) => {
    console.log('Upload completed:', result);

    if (result.successful && result.successful.length > 0) {
      const file = result.successful[0];
      setUploadLogs(prev => [...prev, {
        id: Date.now().toString(),
        fileName: file.name,
        status: 'success',
        timestamp: new Date().toLocaleString('fa-IR'),
        report: 'آپلود موفقیت‌آمیز بود'
      }]);
    }
  };

  const handleSecurityCheck = (fileName: string, isSecure: boolean, report?: string) => {
    console.log('Security check:', { fileName, isSecure, report });

    if (!isSecure) {
      setUploadLogs(prev => [...prev, {
        id: Date.now().toString(),
        fileName,
        status: 'failed',
        timestamp: new Date().toLocaleString('fa-IR'),
        errors: [report || 'بررسی امنیتی ناموفق']
      }]);
    }
  };

  return (
    <div className="container mx-auto px-4 py-8 space-y-8" dir="rtl">
      {/* Header */}
      <div className="text-center space-y-4">
        <div className="flex items-center justify-center gap-3">
          <Shield className="h-10 w-10 text-blue-600" />
          <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
            سیستم آپلود امن
          </h1>
        </div>
        <p className="text-gray-600 text-lg max-w-2xl mx-auto">
          سیستم جامع آپلود فایل با امنیت چندلایه، فشردگی خودکار تصاویر، اسکن ویروس و اعتبارسنجی پیشرفته
        </p>
      </div>

      {/* System Status */}
      {systemStatus && (
        <Card className="border-green-200 bg-green-50">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-green-800">
              <CheckCircle className="h-5 w-5" />
              وضعیت سیستم
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="text-center">
                <div className="font-semibold text-green-700">وضعیت</div>
                <Badge variant="secondary" className="bg-green-100 text-green-800">
                  {systemStatus.status === 'active' ? 'فعال' : 'غیرفعال'}
                </Badge>
              </div>
              <div className="text-center">
                <div className="font-semibold text-green-700">حداکثر حجم</div>
                <div className="text-sm">{systemStatus.features?.sizeLimit || 'نامشخص'}</div>
              </div>
              <div className="text-center">
                <div className="font-semibold text-green-700">اسکن ویروس</div>
                <Badge variant={systemStatus.features?.virusScanning ? "default" : "secondary"}>
                  {systemStatus.features?.virusScanning ? 'فعال' : 'غیرفعال'}
                </Badge>
              </div>
              <div className="text-center">
                <div className="font-semibold text-green-700">فشردگی تصاویر</div>
                <Badge variant={systemStatus.features?.imageCompression ? "default" : "secondary"}>
                  {systemStatus.features?.imageCompression ? 'فعال' : 'غیرفعال'}
                </Badge>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Upload Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Upload Interface */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileCheck className="h-5 w-5" />
              آپلود فایل امن
            </CardTitle>
            <CardDescription>
              فایل‌های خود را با اطمینان از امنیت کامل آپلود کنید
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            <SecureFileUploader
              maxNumberOfFiles={3}
              maxFileSize={10 * 1024 * 1024} // 10MB
              allowedTypes={['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'application/pdf']}
              onUploadComplete={handleUploadComplete}
              onSecurityCheck={handleSecurityCheck}
              enableCompression={true}
              enableVirusScanning={true}
              userId="demo-user"
              buttonClassName="w-full"
            >
              <div className="flex items-center gap-3">
                <Shield className="w-5 h-5" />
                <span>انتخاب فایل برای آپلود امن</span>
              </div>
            </SecureFileUploader>

            <Alert>
              <AlertTriangle className="h-4 w-4" />
              <AlertDescription>
                <div className="space-y-2">
                  <div className="font-medium">ویژگی‌های امنیتی فعال:</div>
                  <ul className="text-sm space-y-1">
                    <li>• بررسی نوع و حجم فایل</li>
                    <li>• اسکن محتوای مخرب</li>
                    <li>• فشردگی خودکار تصاویر</li>
                    <li>• اعتبارسنجی چندلایه</li>
                    <li>• گزارش امنیتی کامل</li>
                  </ul>
                </div>
              </AlertDescription>
            </Alert>
          </CardContent>
        </Card>

        {/* Upload Logs */}
        <Card>
          <CardHeader>
            <CardTitle>گزارش آپلودها</CardTitle>
            <CardDescription>
              تاریخچه آپلودها و وضعیت امنیتی آن‌ها
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3 max-h-96 overflow-y-auto">
              {uploadLogs.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  هنوز فایلی آپلود نشده است
                </div>
              ) : (
                uploadLogs.map(log => (
                  <div
                    key={log.id}
                    className={`p-3 rounded-lg border ${
                      log.status === 'success'
                        ? 'bg-green-50 border-green-200'
                        : 'bg-red-50 border-red-200'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        {log.status === 'success' ? (
                          <CheckCircle className="h-4 w-4 text-green-600" />
                        ) : (
                          <AlertTriangle className="h-4 w-4 text-red-600" />
                        )}
                        <span className="font-medium">{log.fileName}</span>
                      </div>
                      <Badge
                        variant={log.status === 'success' ? 'default' : 'destructive'}
                        className="text-xs"
                      >
                        {log.status === 'success' ? 'موفق' : 'ناموفق'}
                      </Badge>
