                  </CardContent>
                </Card>
              ))}
            </div>
          ) : products && products.length > 0 ? (
            <div className="grid md:grid-cols-2 gap-8">
              {products.map((product) => (
                <Card key={product.id} className="bg-white hover:shadow-lg transition-shadow duration-300 overflow-hidden">
                  {product.imageUrl && (
                    <div className="aspect-video w-full overflow-hidden bg-gray-100 relative">
                      <img 
                        src={product.imageUrl} 
                        alt={product.name}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          e.currentTarget.style.display = 'none';
                        }}
                      />

                      {/* Star Rating Display - Bottom Left Corner - Always Show */}
                      <div className="absolute bottom-2 left-2">
                        <div 
                          className="bg-white/90 backdrop-blur-sm rounded-md px-2 py-1 shadow-sm border border-yellow-200/50 cursor-pointer hover:bg-yellow-50/80 transition-colors"
                          onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            navigate(`/product-reviews/${product.id}`);
                          }}
                        >
                          <div className="flex items-center gap-1">
                            <div className="flex">
                              {[1,2,3,4,5].map((starNum) => {
                                // Show loading state with pulse animation
                                if (statsLoading) {
                                  return (
                                    <Star 
                                      key={starNum}
                                      className="w-3 h-3 fill-gray-300 text-gray-300 animate-pulse"
                                    />
                                  );
                                }

                                const stats = productStatsData?.[product.id];
                                const hasReviews = stats && stats.totalReviews > 0;
                                const rating = hasReviews ? stats.averageRating : 0;

                                return (
                                  <Star 
                                    key={starNum}
                                    className={`w-3 h-3 ${
                                      hasReviews 
                                        ? (starNum <= Math.floor(rating) 
                                            ? 'fill-yellow-400 text-yellow-400' 
                                            : starNum <= Math.ceil(rating)
                                            ? 'fill-yellow-200 text-yellow-200'
                                            : 'fill-gray-200 text-gray-200')
                                        : 'fill-gray-200 text-gray-200 hover:fill-yellow-300'
                                    }`}
                                  />
                                );
                              })}
                            </div>
                            <span className="text-xs text-gray-600">
                              {statsLoading ? '...' : (productStatsData?.[product.id]?.totalReviews > 0 
                                ? productStatsData[product.id].averageRating.toFixed(1)
                                : 'نظر')}
                            </span>
                          </div>
                        </div>
                      </div>
                    </div>
                  )}
                  <CardContent className="p-8">
                    <div className="flex justify-between items-start mb-4">
                      <h3 className="text-2xl font-bold text-gray-900">{product.name}</h3>
                      {product.inventoryStatus && (
                        <Badge 
                          variant="outline" 
                          className={`
                            ${product.inventoryStatus === 'in_stock' ? 'border-green-200 text-green-800 bg-green-50' : ''}
                            ${product.inventoryStatus === 'low_stock' ? 'border-yellow-200 text-yellow-800 bg-yellow-50' : ''}
                            ${product.inventoryStatus === 'out_of_stock' ? 'border-red-200 text-red-800 bg-red-50' : ''}
                          `}
                        >
                          {product.inventoryStatus === 'in_stock' ? 'In Stock' : 
                           product.inventoryStatus === 'low_stock' ? 'Low Stock' : 
                           'Out of Stock'}
                        </Badge>
                      )}
                    </div>

                    <p className="text-gray-600 mb-6">{product.description}</p>

                    {product.features && Array.isArray(product.features) && product.features.length > 0 && (
                      <div className="mb-6">
                        <h4 className="font-semibold text-gray-900 mb-3">Key Features:</h4>
                        <ul className="space-y-2">
                          {product.features.filter(Boolean).map((feature, featureIndex) => (
                            <li key={featureIndex} className="flex items-center text-gray-700">
                              <CheckCircle className="h-4 w-4 text-secondary mr-3 flex-shrink-0" />
                              {String(feature)}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {product.applications && Array.isArray(product.applications) && product.applications.length > 0 && (
                      <div className="mb-6">
                        <h4 className="font-semibold text-gray-900 mb-3">Applications:</h4>
                        <div className="flex flex-wrap gap-2">
                          {product.applications.filter(Boolean).map((app, appIndex) => (
                            <span key={appIndex} className="bg-gray-100 text-gray-700 px-3 py-1 rounded-full text-sm">
                              {String(app)}
                            </span>
                          ))}
                        </div>
                      </div>
                    )}

                    <div className="flex items-center gap-3 mt-6">
                      {product.imageUrl && (
                        <Badge variant="outline" className="text-xs">
                          <Image className="w-3 h-3 mr-1" />
                          Image Available
                        </Badge>
                      )}
                      {product.pdfCatalogUrl && (
                        <a 
                          href={product.pdfCatalogUrl} 
                          download={`${product.name}_catalog.pdf`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex"
                        >
                          <Badge variant="outline" className="text-xs hover:bg-blue-50 hover:text-blue-600 cursor-pointer transition-colors">
                            <Download className="w-3 h-3 mr-1" />
                            Download Catalog
                          </Badge>
                        </a>
                      )}
                    </div>

                    <div className="mt-6">
                      <ProductInquiryForm 
                        product={product}
                        triggerText="Get Quote"
                        triggerVariant="default"
                        triggerSize="sm"
                        className="w-full bg-blue-600 hover:bg-blue-700 text-white"
                      />
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : (
            <RandomCategoryProducts 
              categoryDisplayName="Fuel Additives" 
              category="fuel-additives"
              hideTitle={true}
            />
          )}
        </div>
      </section>

      {/* Technical Specifications */}
      <section className="py-20 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-12">
            <div>
              <h2 className="text-3xl font-bold text-gray-900 mb-6">Technical Specifications</h2>
              <p className="text-lg text-gray-600 mb-8">
