import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { Truck, Plus, Edit, Trash2, Save, X } from "lucide-react";

interface VehicleType {
  id: number;
  code: string;
  nameFa: string;
  nameEn: string | null;
  nameAr: string | null;
  nameKu: string | null;
  description: string | null;
  isActive: boolean;
  sortOrder: number;
  createdAt: string;
  updatedAt: string;
}

export default function VehicleTypesManagement() {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [editingType, setEditingType] = useState<VehicleType | null>(null);
  const [formData, setFormData] = useState({
    code: '',
    nameFa: '',
    nameEn: '',
    nameAr: '',
    nameKu: '',
    description: '',
    sortOrder: 0
  });

  // Fetch vehicle types
  const { data: vehicleTypesData, isLoading } = useQuery({
    queryKey: ['/api/logistics/vehicle-types']
  });

  // Create vehicle type mutation
  const createTypeMutation = useMutation({
    mutationFn: (data: Partial<VehicleType>) => 
      apiRequest('/api/logistics/vehicle-types', { method: 'POST', body: data }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/vehicle-types'] });
      setIsCreateDialogOpen(false);
      resetForm();
      toast({ title: "موفقیت", description: "نوع خودرو جدید ایجاد شد" });
    },
    onError: () => {
      toast({ title: "خطا", description: "خطا در ایجاد نوع خودرو", variant: "destructive" });
    }
  });

  // Update vehicle type mutation
  const updateTypeMutation = useMutation({
    mutationFn: ({ id, ...data }: Partial<VehicleType> & { id: number }) => 
      apiRequest(`/api/logistics/vehicle-types/${id}`, { method: 'PATCH', body: data }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/vehicle-types'] });
      setEditingType(null);
      resetForm();
      toast({ title: "موفقیت", description: "نوع خودرو بروزرسانی شد" });
    },
    onError: () => {
      toast({ title: "خطا", description: "خطا در بروزرسانی نوع خودرو", variant: "destructive" });
    }
  });

  // Delete vehicle type mutation
  const deleteTypeMutation = useMutation({
    mutationFn: (id: number) => 
      apiRequest(`/api/logistics/vehicle-types/${id}`, { method: 'DELETE' }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/vehicle-types'] });
      toast({ title: "موفقیت", description: "نوع خودرو حذف شد" });
    },
    onError: () => {
      toast({ title: "خطا", description: "خطا در حذف نوع خودرو", variant: "destructive" });
    }
  });

  const vehicleTypes: VehicleType[] = vehicleTypesData?.data || [];

  const resetForm = () => {
    setFormData({
      code: '',
      nameFa: '',
      nameEn: '',
      nameAr: '',
      nameKu: '',
      description: '',
      sortOrder: 0
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.code || !formData.nameFa) {
      toast({ 
        title: "خطا", 
        description: "کد و نام فارسی الزامی است", 
        variant: "destructive" 
      });
      return;
    }

    if (editingType) {
      updateTypeMutation.mutate({ 
        id: editingType.id, 
        ...formData 
      });
    } else {
      createTypeMutation.mutate(formData);
    }
  };

  const handleEdit = (vehicleType: VehicleType) => {
    setEditingType(vehicleType);
    setFormData({
      code: vehicleType.code,
      nameFa: vehicleType.nameFa,
      nameEn: vehicleType.nameEn || '',
      nameAr: vehicleType.nameAr || '',
      nameKu: vehicleType.nameKu || '',
      description: vehicleType.description || '',
      sortOrder: vehicleType.sortOrder
    });
    setIsCreateDialogOpen(true);
  };

  const handleCancelEdit = () => {
    setEditingType(null);
    setIsCreateDialogOpen(false);
    resetForm();
  };

  if (isLoading) {
    return (
      <div className="container mx-auto p-6">
        <div className="text-center">در حال بارگذاری...</div>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Truck className="w-6 h-6" />
            دسته‌بندی خودرو سطح یک
          </h1>
          <p className="text-gray-600 mt-1">
            مدیریت و تنظیم دسته‌بندی‌های سطح یک خودروها برای سیستم لجستیک
          </p>
        </div>

        <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
          <DialogTrigger asChild>
            <Button onClick={() => resetForm()}>
              <Plus className="w-4 h-4 ml-2" />
              افزودن دسته‌بندی جدید
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>
                {editingType ? 'ویرایش دسته‌بندی خودرو' : 'افزودن دسته‌بندی جدید'}
              </DialogTitle>
              <DialogDescription>
                {editingType 
                  ? 'اطلاعات دسته‌بندی خودرو را ویرایش کنید'
                  : 'اطلاعات دسته‌بندی خودرو جدید را وارد کنید'
                }
              </DialogDescription>
            </DialogHeader>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label htmlFor="code">کد انگلیسی *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({...formData, code: e.target.value})}
                  placeholder="مثال: heavy_truck"
                  required
                />
                <p className="text-xs text-gray-500 mt-1">
                  از حروف انگلیسی کوچک و خط فاصل استفاده کنید
                </p>
              </div>

              <div>
                <Label htmlFor="nameFa">نام فارسی *</Label>
                <Input
                  id="nameFa"
                  value={formData.nameFa}
                  onChange={(e) => setFormData({...formData, nameFa: e.target.value})}
                  placeholder="مثال: کامیون سنگین"
                  required
                />
              </div>

              <div>
                <Label htmlFor="nameEn">نام انگلیسی</Label>
                <Input
                  id="nameEn"
                  value={formData.nameEn}
                  onChange={(e) => setFormData({...formData, nameEn: e.target.value})}
                  placeholder="مثال: Heavy Truck"
                />
              </div>

              <div>
                <Label htmlFor="nameAr">نام عربی</Label>
                <Input
                  id="nameAr"
                  value={formData.nameAr}
                  onChange={(e) => setFormData({...formData, nameAr: e.target.value})}
                  placeholder="مثال: شاحنة ثقيلة"
                />
              </div>

              <div>
                <Label htmlFor="nameKu">نام کردی</Label>
                <Input
                  id="nameKu"
                  value={formData.nameKu}
                  onChange={(e) => setFormData({...formData, nameKu: e.target.value})}
                  placeholder="مثال: لۆری قورس"
                />
              </div>

              <div>
                <Label htmlFor="description">توضیحات</Label>
                <Input
                  id="description"
                  value={formData.description}
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  placeholder="توضیحات اختیاری در مورد این نوع خودرو"
                />
              </div>

              <div>
                <Label htmlFor="sortOrder">اولویت نمایش</Label>
                <Input
                  id="sortOrder"
                  type="number"
                  value={formData.sortOrder}
                  onChange={(e) => setFormData({...formData, sortOrder: parseInt(e.target.value) || 0})}
                  placeholder="0"
                />
                <p className="text-xs text-gray-500 mt-1">
                  عدد کمتر = نمایش بالاتر در لیست
                </p>
              </div>

              <DialogFooter className="gap-2">
                <Button type="button" variant="outline" onClick={handleCancelEdit}>
                  <X className="w-4 h-4 ml-2" />
                  لغو
                </Button>
                <Button type="submit" disabled={createTypeMutation.isPending || updateTypeMutation.isPending}>
                  <Save className="w-4 h-4 ml-2" />
                  {editingType ? 'بروزرسانی' : 'ایجاد'}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>دسته‌بندی‌های خودرو موجود</CardTitle>
        </CardHeader>
        <CardContent>
          {vehicleTypes.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              هیچ نوع خودرویی تعریف نشده است. اولین نوع خودرو را اضافه کنید.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>کد</TableHead>
                  <TableHead>نام فارسی</TableHead>
                  <TableHead>نام انگلیسی</TableHead>
                  <TableHead>نام عربی</TableHead>
                  <TableHead>نام کردی</TableHead>
                  <TableHead>اولویت</TableHead>
                  <TableHead>وضعیت</TableHead>
                  <TableHead className="text-left">عملیات</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {vehicleTypes
                  .sort((a, b) => a.sortOrder - b.sortOrder)
                  .map((vehicleType) => (
                  <TableRow key={vehicleType.id}>
                    <TableCell className="font-mono text-sm">
                      {vehicleType.code}
                    </TableCell>
                    <TableCell className="font-medium">
                      {vehicleType.nameFa}
                    </TableCell>
                    <TableCell>{vehicleType.nameEn || '-'}</TableCell>
                    <TableCell>{vehicleType.nameAr || '-'}</TableCell>
                    <TableCell>{vehicleType.nameKu || '-'}</TableCell>
                    <TableCell>{vehicleType.sortOrder}</TableCell>
                    <TableCell>
                      <Badge variant={vehicleType.isActive ? "default" : "secondary"}>
                        {vehicleType.isActive ? 'فعال' : 'غیرفعال'}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => handleEdit(vehicleType)}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => {
                            if (confirm('آیا مطمئن هستید که می‌خواهید این نوع خودرو را حذف کنید؟')) {
                              deleteTypeMutation.mutate(vehicleType.id);
                            }
                          }}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardContent className="pt-6">
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <h4 className="font-medium text-blue-900 mb-2">راهنمای استفاده:</h4>
            <ul className="text-sm text-blue-700 space-y-1">
              <li>• کد انگلیسی برای استفاده در سیستم و API ضروری است</li>
              <li>• از کدهای یکتا و بدون فاصله استفاده کنید (مثل: heavy_truck)</li>
              <li>• نام‌های چندزبانه برای نمایش در رابط کاربری استفاده می‌شود</li>
              <li>• اولویت نمایش برای ترتیب نمایش در لیست‌ها مهم است</li>
              <li>• پس از تغییرات، قالب‌های خودرو نیز بروزرسانی می‌شوند</li>
            </ul>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/simple-sms-templat.content:
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { Edit, Trash2, Plus, Copy, MessageSquare, Tag, Users } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";

// Types
interface SmsTemplate {
  id: number;
  categoryId: number;
  templateNumber: number;
  templateName: string;
  templateContent: string;
  variables: string[];
  isDefault: boolean;
  isActive: boolean;
  usageCount: number;
  lastUsed: string | null;
  createdBy: string;
  createdAt: string;
  updatedAt: string;
  categoryName: string;
}

interface TemplateCategory {
  id: number;
  categoryNumber: number;
  categoryName: string;
  categoryDescription: string;
  systemUsage: string;
  isActive: boolean;
  displayOrder: number;
  createdAt: string;
  updatedAt: string;
}

// Form schemas
const templateSchema = z.object({
  categoryId: z.number().min(1, "انتخاب دسته‌بندی الزامی است"),
  templateName: z.string().min(1, "نام قالب الزامی است"),
  templateContent: z.string().min(1, "محتوای قالب الزامی است"),
  variables: z.array(z.string()).optional(),
  isDefault: z.boolean().default(false),
  createdBy: z.string().default("admin")
});

export default function SimpleSmsTemplates() {
  const [showTemplateDialog, setShowTemplateDialog] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<SmsTemplate | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch template categories
  const { data: categoriesData = { data: [] }, isLoading: categoriesLoading } = useQuery({
    queryKey: ["/api/admin/sms/template-categories"],
    queryFn: () => apiRequest("/api/admin/sms/template-categories")
  });

  // Fetch all templates
  const { data: templatesData = { data: [] }, isLoading: templatesLoading } = useQuery({
    queryKey: ["/api/admin/sms/templates"],
    queryFn: () => apiRequest("/api/admin/sms/templates")
  });

  // Extract arrays from API responses
  const categories = Array.isArray(categoriesData) ? categoriesData : (categoriesData?.data || []);
  const templates = Array.isArray(templatesData) ? templatesData : (templatesData?.data || []);

  // Filter templates based on selected category
  const filteredTemplates = selectedCategory === "all" 
    ? templates 
    : templates.filter((t: SmsTemplate) => t.categoryId === parseInt(selectedCategory));

  // Template form
  const templateForm = useForm<z.infer<typeof templateSchema>>({
    resolver: zodResolver(templateSchema),
    defaultValues: {
      categoryId: 0,
      templateName: "",
      templateContent: "",
      variables: [],
      isDefault: false,
      createdBy: "admin"
    }
  });

  // Create template mutation
  const createTemplateMutation = useMutation({
    mutationFn: (data: z.infer<typeof templateSchema>) =>
      apiRequest("/api/admin/sms/templates", { method: "POST", body: data }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/sms/templates"] });
      setShowTemplateDialog(false);
      templateForm.reset();
      toast({ title: "موفقیت", description: "قالب پیامک ایجاد شد" });
    },
    onError: (error: any) => {
      toast({ title: "خطا", description: error.message || "خطا در ایجاد قالب", variant: "destructive" });
    }
  });

  // Update template mutation
  const updateTemplateMutation = useMutation({
    mutationFn: ({ id, data }: { id: number; data: Partial<z.infer<typeof templateSchema>> }) =>
      apiRequest(`/api/admin/sms/templates/${id}`, { method: "PUT", body: data }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/sms/templates"] });
      setShowTemplateDialog(false);
      setEditingTemplate(null);
      templateForm.reset();
      toast({ title: "موفقیت", description: "قالب بروزرسانی شد" });
    },
    onError: (error: any) => {
      toast({ title: "خطا", description: error.message || "خطا در بروزرسانی قالب", variant: "destructive" });
    }
  });

  // Delete template mutation
  const deleteTemplateMutation = useMutation({
    mutationFn: (id: number) =>
      apiRequest(`/api/admin/sms/templates/${id}`, { method: "DELETE" }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/sms/templates"] });
      toast({ title: "موفقیت", description: "قالب حذف شد" });
    },
    onError: (error: any) => {
      toast({ title: "خطا", description: error.message || "خطا در حذف قالب", variant: "destructive" });
    }
  });

  // Get next template number for category
  const getNextTemplateNumber = (categoryId: number): number => {
    const categoryTemplates = templates.filter((t: SmsTemplate) => t.categoryId === categoryId);
    const maxNumber = categoryTemplates.length > 0 
      ? Math.max(...categoryTemplates.map(t => t.templateNumber))
      : 0;
    return maxNumber + 1;
  };

  // Handle template form submission
  const onTemplateSubmit = (data: z.infer<typeof templateSchema>) => {
    // Extract variables from template content
    const extractedVars = extractVariables(data.templateContent);

    if (editingTemplate) {
      updateTemplateMutation.mutate({ 
        id: editingTemplate.id, 
        data: { ...data, variables: extractedVars }
      });
    } else {
      // Automatically assign next template number for new templates
      const templateNumber = getNextTemplateNumber(data.categoryId);
      createTemplateMutation.mutate({ 
        ...data, 
        templateNumber, 
        variables: extractedVars 
      });
    }
  };

  // Handle edit template
  const handleEditTemplate = (template: SmsTemplate) => {
    setEditingTemplate(template);
    templateForm.reset({
      categoryId: template.categoryId,
      templateName: template.templateName,
      templateContent: template.templateContent,
      variables: template.variables || [],
      isDefault: template.isDefault,
      createdBy: template.createdBy || "admin"
    });
    setShowTemplateDialog(true);
  };

  // Extract variables from template content
  const extractVariables = (content: string): string[] => {
    const matches = content.match(/\{\{([^}]+)\}\}/g);
    return matches ? matches.map(match => match.replace(/\{\{|\}\}/g, '')) : [];
  };

  // Copy template content to clipboard
  const copyToClipboard = (content: string) => {
    navigator.clipboard.writeText(content);
    toast({ title: "کپی شد", description: "محتوای قالب کپی شد" });
  };

  if (categoriesLoading || templatesLoading) {
    return (
      <div className="flex justify-center items-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">قالب‌های پیامک سیستم</h2>
          <p className="text-gray-600">مدیریت و ویرایش قالب‌های پیامک ({templates.length} قالب)</p>
        </div>
        <Dialog open={showTemplateDialog} onOpenChange={setShowTemplateDialog}>
          <DialogTrigger asChild>
            <Button onClick={() => { setEditingTemplate(null); templateForm.reset(); }}>
              <Plus className="h-4 w-4 mr-2" />
              قالب جدید
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>
                {editingTemplate ? "ویرایش قالب" : "ایجاد قالب جدید"}
              </DialogTitle>
              <DialogDescription>
                قالب پیامک جدید برای سیستم ایجاد کنید
              </DialogDescription>
            </DialogHeader>
            <Form {...templateForm}>
              <form onSubmit={templateForm.handleSubmit(onTemplateSubmit)} className="space-y-4">
                <FormField
                  control={templateForm.control}
                  name="categoryId"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>دسته‌بندی</FormLabel>
                      <Select 
                        onValueChange={(value) => field.onChange(parseInt(value))} 
                        value={field.value?.toString()}
                      >
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="انتخاب دسته‌بندی" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {categories.map((category: TemplateCategory) => (
                            <SelectItem key={category.id} value={category.id.toString()}>
                              #{category.categoryNumber} {category.categoryName}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={templateForm.control}
                  name="templateName"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>نام قالب</FormLabel>
                      <FormControl>
                        <Input placeholder="نام قالب پیامک" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={templateForm.control}
                  name="templateContent"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>محتوای قالب</FormLabel>
                      <FormControl>
                        <Textarea 
                          placeholder="محتوای پیامک (از {{variable_name}} برای متغیرها استفاده کنید)"
                          className="min-h-32"
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                      <p className="text-xs text-gray-500">
                        متغیرهای شناسایی شده: {extractVariables(field.value || "").join(", ") || "هیچ"}
                      </p>
                    </FormItem>
                  )}
                />

                <DialogFooter>
                  <Button 
                    type="submit" 
                    disabled={createTemplateMutation.isPending || updateTemplateMutation.isPending}
                  >
                    {editingTemplate ? "بروزرسانی" : "ایجاد"}
                  </Button>
                </DialogFooter>
              </form>
            </Form>
          </DialogContent>
        </Dialog>
      </div>

      {/* Filter */}
      <div className="flex gap-4 items-center">
        <Select value={selectedCategory} onValueChange={setSelectedCategory}>
          <SelectTrigger className="w-64">
            <SelectValue placeholder="فیلتر بر اساس دسته‌بندی" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">همه دسته‌بندی‌ها ({templates.length})</SelectItem>
            {categories.map((category: TemplateCategory) => {
              const count = templates.filter((t: SmsTemplate) => t.categoryId === category.id).length;
              return (
                <SelectItem key={category.id} value={category.id.toString()}>
                  #{category.categoryNumber} {category.categoryName} ({count})
                </SelectItem>
              );
            })}
          </SelectContent>
        </Select>
      </div>

      {/* Templates Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {filteredTemplates.map((template: SmsTemplate) => (
          <Card key={template.id} className="hover:shadow-lg transition-shadow">
            <CardHeader className="pb-3">
              <div className="flex justify-between items-start">
                <div className="flex items-center gap-3">
                  <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg w-14 h-14 flex items-center justify-center font-bold text-xl shrink-0">
                    {template.templateNumber}
                  </div>
                  <div>
                    <CardTitle className="text-lg">{template.templateName}</CardTitle>
                    <p className="text-sm text-blue-600 font-medium">
                      #{template.categoryNumber || template.templateNumber} • {template.categoryName}
                    </p>
                  </div>
                  {template.isDefault && (
                    <Badge variant="default" className="text-xs">پیش‌فرض</Badge>
                  )}
                </div>
                <div className="flex gap-1">
                  <Button 
                    variant="ghost" 
                    size="sm"
                    onClick={() => copyToClipboard(template.templateContent)}
                    title="کپی محتوا"
                  >
                    <Copy className="h-4 w-4" />
                  </Button>
                  <Button 
                    variant="ghost" 
                    size="sm"
                    onClick={() => handleEditTemplate(template)}
                    title="ویرایش"
                  >
                    <Edit className="h-4 w-4" />
                  </Button>
                  <Button 
                    variant="ghost" 
                    size="sm"
                    onClick={() => deleteTemplateMutation.mutate(template.id)}
                    disabled={deleteTemplateMutation.isPending}
                    title="حذف"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div className="bg-gradient-to-r from-gray-50 to-blue-50 p-4 rounded-lg border">
                  <p className="text-sm font-medium mb-2 text-gray-700">محتوای قالب:</p>
                  <p className="text-sm text-gray-800 whitespace-pre-wrap leading-relaxed">
                    {template.templateContent}
                  </p>
                </div>

                {template.variables && template.variables.length > 0 && (
                  <div>
                    <p className="text-sm font-medium mb-2 flex items-center gap-1">
                      <Tag className="h-4 w-4" />
                      متغیرها ({template.variables.length}):
                    </p>
                    <div className="flex flex-wrap gap-1">
                      {template.variables.map((variable, index) => (
                        <Badge key={index} variant="outline" className="text-xs bg-blue-50 text-blue-700">
                          {variable}
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}

                <div className="flex justify-between items-center text-xs text-gray-500 pt-2 border-t">
                  <div className="flex items-center gap-1">
                    <Users className="h-3 w-3" />
                    <span>{template.usageCount} استفاده</span>
                  </div>
                  {template.createdBy && (
                    <div className="flex items-center gap-1">
                      <MessageSquare className="h-3 w-3" />
                      <span>توسط: {template.createdBy}</span>
                    </div>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {filteredTemplates.length === 0 && (
        <div className="text-center py-12">
          <MessageSquare className="h-16 w-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-600 mb-2">قالبی یافت نشد</h3>
          <p className="text-gray-500">در دسته‌بندی انتخابی قالبی وجود ندارد</p>
        </div>
      )}
    </div>
  );
}

