import { useState, useEffect } from "react";
import { useRoute, useLocation } from "wouter";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { CheckCircle, AlertCircle, CreditCard, ArrowLeft } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import PaymentGateway from "@/components/checkout/payment-gateway";

export default function Payment() {
  const [, params] = useRoute('/payment/:orderId');
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [paymentProcessed, setPaymentProcessed] = useState(false);
  const [paymentData, setPaymentData] = useState<any>(null);

  const orderId = params?.orderId ? parseInt(params.orderId) : null;

  // Fetch order details
  const { data: orderData, isLoading: orderLoading, error: orderError } = useQuery({
    queryKey: [`/api/customers/orders/${orderId}/payment`],
    enabled: !!orderId,
  });

  // Debug order query issues
  useEffect(() => {
    if (orderError) {
      console.error('🔍 [ORDER QUERY ERROR]:', orderError);
    }
  }, [orderError]);

  // Fetch active payment gateway
  const { data: activeGateway, isLoading: gatewayLoading } = useQuery({
    queryKey: ['/api/payment/active-gateway'],
    enabled: !!orderId,
  });

  // Debug active gateway data
  useEffect(() => {
    console.log('🔍 [PAYMENT PAGE DEBUG] Order ID:', orderId);
    console.log('🔍 [PAYMENT PAGE DEBUG] Active gateway data:', activeGateway);
    console.log('🔍 [PAYMENT PAGE DEBUG] Gateway loading:', gatewayLoading);
    console.log('🔍 [PAYMENT PAGE DEBUG] Order data:', orderData);
    console.log('🔍 [PAYMENT PAGE DEBUG] Order loading:', orderLoading);
  }, [orderId, activeGateway, gatewayLoading, orderData, orderLoading]);

  // Update payment status mutation
  const updatePaymentMutation = useMutation({
    mutationFn: async (paymentData: any) => {
      return apiRequest(`/api/shop/orders/${orderId}/payment`, 'POST', paymentData);
    },
    onSuccess: () => {
      toast({
        title: "Payment Processed",
        description: "Your payment has been processed successfully.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/shop/orders'] });

      // Generate invoice after successful payment
      generateInvoiceMutation.mutate();
    },
    onError: () => {
      toast({
        title: "Payment Update Failed",
        description: "Failed to update payment status.",
        variant: "destructive",
      });
    },
  });

  // Generate invoice mutation
  const generateInvoiceMutation = useMutation({
    mutationFn: async () => {
      return apiRequest('/api/invoices', 'POST', {
        orderId: orderId,
        customerId: orderData?.customerId,
        language: 'ar' // Default to Arabic, can be made configurable
      });
    },
    onSuccess: () => {
      toast({
        title: "Invoice Generated",
        description: "Your invoice has been generated and will be sent to your email.",
      });

      // Redirect to success page
      setTimeout(() => {
        setLocation(`/checkout/success/${orderId}`);
      }, 2000);
    },
    onError: () => {
      toast({
        title: "Invoice Generation Failed",
        description: "Payment successful but invoice generation failed. Please contact support.",
        variant: "destructive",
      });
    },
  });

  const handlePaymentSuccess = (paymentResult: any) => {
    setPaymentData(paymentResult);
    setPaymentProcessed(true);

    // Update order with payment information
    updatePaymentMutation.mutate({
      paymentStatus: 'paid',
      paymentMethod: paymentResult.method,
      transactionId: paymentResult.transactionId,
      paymentData: paymentResult
    });
  };

  const handlePaymentError = (error: string) => {
    toast({
      title: "Payment Failed",
      description: error,
      variant: "destructive",
    });
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'IQD',
    }).format(amount);
  };

  if (orderLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Card className="w-full max-w-md">
          <CardContent className="p-8 text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p>Loading order details...</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!orderData) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Card className="w-full max-w-md">
          <CardContent className="p-8 text-center">
            <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-gray-700 mb-2">Order Not Found</h2>
            <p className="text-gray-500 mb-6">The order you're trying to pay for could not be found.</p>
            <Button onClick={() => setLocation("/shop")} className="w-full">
              Back to Shop
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const order = orderData?.order || orderData;

  // Skip payment for cash on delivery and company credit
  if (order.paymentMethod === 'cash_on_delivery' || order.paymentMethod === 'company_credit') {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Card className="w-full max-w-lg">
          <CardContent className="p-8 text-center">
            <CheckCircle className="w-20 h-20 text-green-600 mx-auto mb-6" />
            <h2 className="text-2xl font-bold text-gray-900 mb-4">Order Confirmed!</h2>
            <p className="text-gray-600 mb-2">Thank you for your order.</p>
            <p className="text-lg font-semibold text-gray-900 mb-6">
              Order Number: #{order.orderNumber}
            </p>
            <div className="space-y-3">
              <Button onClick={() => setLocation("/shop")} className="w-full">
                Continue Shopping
              </Button>
              <Button 
                variant="outline" 
                onClick={() => setLocation("/")}
                className="w-full"
              >
                Back to Home
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (paymentProcessed) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Card className="w-full max-w-lg">
          <CardContent className="p-8 text-center">
            <CheckCircle className="w-20 h-20 text-green-600 mx-auto mb-6" />
            <h2 className="text-2xl font-bold text-gray-900 mb-4">Payment Successful!</h2>
            <p className="text-gray-600 mb-2">Your payment has been processed successfully.</p>
            <p className="text-lg font-semibold text-gray-900 mb-2">
              Order Number: #{order.orderNumber}
            </p>
            <p className="text-lg font-semibold text-green-600 mb-6">
              Amount Paid: {formatCurrency(order.totalAmount)}
            </p>
            {paymentData && (
              <div className="bg-gray-50 p-4 rounded-lg mb-6">
                <p className="text-sm text-gray-600 mb-1">Transaction ID</p>
                <p className="font-mono text-sm text-gray-900">{paymentData.transactionId}</p>
              </div>
            )}
            <p className="text-sm text-gray-500 mb-8">
              Your invoice is being generated and will be sent to your email shortly.
            </p>
            <div className="space-y-3">
              <Button onClick={() => setLocation("/shop")} className="w-full">
                Continue Shopping
              </Button>
              <Button 
                variant="outline" 
                onClick={() => setLocation("/")}
                className="w-full"
              >
                Back to Home
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="container mx-auto px-4">
        <div className="mb-6">
          <Button
            variant="ghost"
            onClick={() => window.history.back()}
            className="mb-4"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Complete Your Payment</h1>
          <p className="text-gray-600">Secure payment for Order #{order.orderNumber}</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Payment Gateway */}
          <div className="lg:col-span-2">
            {gatewayLoading ? (
              <Card>
                <CardContent className="p-8 text-center">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-4"></div>
                  <p>در حال بارگذاری درگاه پرداخت...</p>
                </CardContent>
              </Card>
            ) : activeGateway ? (
              <PaymentGateway
                paymentMethod={order.paymentMethod}
                totalAmount={parseFloat(order.totalAmount)}
                orderId={order.orderNumber}
                onPaymentSuccess={handlePaymentSuccess}
                onPaymentError={handlePaymentError}
                activeGateway={activeGateway}
              />
            ) : (
              <Card>
                <CardContent className="p-8 text-center">
                  <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
                  <h3 className="text-lg font-semibold text-gray-700 mb-2">درگاه پرداخت در دسترس نیست</h3>
                  <p className="text-gray-500 mb-6">در حال حاضر هیچ درگاه پرداخت فعالی موجود نیست. لطفاً با پشتیبانی تماس بگیرید.</p>
                  <Button onClick={() => setLocation("/shop")} className="w-full">
                    بازگشت به فروشگاه
                  </Button>
                </CardContent>
              </Card>
            )}
          </div>

          {/* Order Summary */}
          <div className="lg:col-span-1">
            <Card>
              <CardHeader>
                <CardTitle>Order Summary</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  {order.items?.map((item: any, index: number) => (
                    <div key={index} className="flex justify-between text-sm">
                      <span>{item.productName} × {item.quantity}</span>
                      <span>{formatCurrency(item.unitPrice * item.quantity)}</span>
                    </div>
                  ))}
                </div>

                <div className="border-t pt-4 space-y-2">
                  <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>{formatCurrency(order.totalAmount - (order.totalAmount * 0.09) - 50)}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Shipping</span>
                    <span>{formatCurrency(50)}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Tax (9%)</span>
                    <span>{formatCurrency(order.totalAmount * 0.09)}</span>
                  </div>
                  <div className="border-t pt-2 flex justify-between font-bold text-lg">
                    <span>Total</span>
                    <span>{formatCurrency(order.totalAmount)}</span>
                  </div>
                </div>

                <div className="mt-6 p-4 bg-blue-50 rounded-lg">
                  <h4 className="font-semibold text-blue-900 mb-2">Payment Method</h4>
                  <Badge variant="outline" className="bg-blue-100">
                    {order.paymentMethod === 'iraqi_bank' ? 'Iraqi Bank Transfer' :
                     order.paymentMethod === 'credit_card' ? 'Credit/Debit Card' :
                     order.paymentMethod === 'bank_transfer' ? 'International Bank Transfer' :
                     order.paymentMethod === 'digital_wallet' ? 'Digital Wallet' :
                     order.paymentMethod}
                  </Badge>
                </div>

                <div className="text-xs text-gray-500 text-center">
                  <CreditCard className="w-4 h-4 inline mr-1" />
                  Secured by 256-bit SSL encryption
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
}

server/data-integrity-tools.ts.content:
import { db } from './db';
import { customerOrders, orderItems } from '@shared/customer-schema';
import { eq, and, gt, sql } from 'drizzle-orm';

/**
 * Data Integrity Tools for Order Management System
 * Helps identify and fix corrupted orders that have amounts but no items
 */

export interface CorruptedOrder {
  id: number;
  orderNumber: string;
  totalAmount: string;
  status: string;
  createdAt: Date;
  itemCount: number;
  currency: string;
  customerEmail?: string;
}

/**
 * Find orders that have total amounts but no order items
 */
export async function findCorruptedOrders(): Promise<CorruptedOrder[]> {
  const query = sql`
    SELECT 
      co.id,
      co.order_number,
      co.total_amount,
      co.status,
      co.created_at,
      co.currency,
      co.customer_email,
      COUNT(oi.id) as item_count
    FROM customer_orders co
    LEFT JOIN order_items oi ON co.id = oi.order_id
    WHERE co.total_amount > 0
      AND co.status NOT IN ('deleted', 'cancelled')
    GROUP BY co.id, co.order_number, co.total_amount, co.status, co.created_at, co.currency, co.customer_email
    HAVING COUNT(oi.id) = 0
    ORDER BY co.created_at DESC
  `;

  const results = await db.execute(query);

  return results.rows.map((row: any) => ({
    id: row.id,
    orderNumber: row.order_number,
    totalAmount: row.total_amount,
    status: row.status,
    createdAt: row.created_at,
    itemCount: row.item_count,
    currency: row.currency,
    customerEmail: row.customer_email
  }));
}

/**
 * Get detailed statistics about data integrity issues
 */
export async function getDataIntegrityStats() {
  const corruptedOrders = await findCorruptedOrders();

  const totalCorrupted = corruptedOrders.length;
  const totalCorruptedValue = corruptedOrders.reduce((sum, order) => 
    sum + parseFloat(order.totalAmount), 0
  );

  const corruptedByStatus = corruptedOrders.reduce((acc, order) => {
    acc[order.status] = (acc[order.status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return {
    totalCorrupted,
    totalCorruptedValue,
    corruptedByStatus,
    corruptedOrders: corruptedOrders.slice(0, 10) // Top 10 for display
  };
}

/**
 * Mark a corrupted order as deleted (soft delete)
 * This should only be used for orders that are genuinely corrupted
 */
export async function markCorruptedOrderAsDeleted(orderId: number, reason: string) {
  const now = new Date();
  const deleteNote = `حذف شده در ${now.toISOString()}: ${reason}`;

  await db
    .update(customerOrders)
    .set({
      status: 'deleted',
      notes: sql`COALESCE(notes, '') || ${deleteNote}`
    })
    .where(eq(customerOrders.id, orderId));

  return { success: true, message: 'Order marked as deleted' };
}

/**
 * Get order validation report
 */
export async function validateOrderIntegrity(orderId: number) {
  const orderQuery = await db
    .select()
    .from(customerOrders)
    .where(eq(customerOrders.id, orderId));

  if (orderQuery.length === 0) {
    return { valid: false, error: 'Order not found' };
  }

  const order = orderQuery[0];

  const itemsQuery = await db
    .select()
    .from(orderItems)
    .where(eq(orderItems.orderId, orderId));

  const hasItems = itemsQuery.length > 0;
  const hasAmount = parseFloat(order.totalAmount || '0') > 0;

  const validation = {
    orderId,
    orderNumber: order.orderNumber,
    hasItems,
    itemCount: itemsQuery.length,
    hasAmount,
    totalAmount: order.totalAmount,
    status: order.status,
    valid: (hasItems && hasAmount) || (!hasItems && !hasAmount),
    issues: [] as string[]
  };

  if (hasAmount && !hasItems) {
    validation.issues.push('Order has amount but no items');
  }

  if (hasItems && !hasAmount) {
    validation.issues.push('Order has items but no amount');
  }

  return validation;
}

client/src/components/ui/email-setup-pro.content:
import { useState, useEffect } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { CheckCircle, Circle, Star, Trophy, Target, Zap, Mail, Settings, Users, TestTube, Shield } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

interface EmailCategory {
  id: number;
  categoryKey: string;
  categoryName: string;
  description: string;
  isActive: boolean;
  smtp?: any;
  recipients: any[];
}

interface EmailSetupProgressProps {
  categories: EmailCategory[];
  onSelectCategory: (category: EmailCategory) => void;
  selectedCategory?: EmailCategory;
}

interface ProgressStep {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  points: number;
  isCompleted: boolean;
  category?: string;
}

const achievements = [
  { id: 'first_smtp', title: 'First Connection', icon: <Zap className="w-4 h-4" />, description: 'Configure your first SMTP server', points: 100 },
  { id: 'all_smtp', title: 'Full Coverage', icon: <Shield className="w-4 h-4" />, description: 'Configure SMTP for all categories', points: 300 },
  { id: 'first_test', title: 'Testing Hero', icon: <TestTube className="w-4 h-4" />, description: 'Successfully test an SMTP connection', points: 50 },
  { id: 'all_tests', title: 'Quality Assurance', icon: <Trophy className="w-4 h-4" />, description: 'Test all SMTP configurations', points: 200 },
  { id: 'recipients_added', title: 'Team Builder', icon: <Users className="w-4 h-4" />, description: 'Add recipients to all categories', points: 150 },
  { id: 'master_setup', title: 'Email Master', icon: <Star className="w-4 h-4" />, description: 'Complete all email configurations', points: 500 }
];

export default function EmailSetupProgress({ categories, onSelectCategory, selectedCategory }: EmailSetupProgressProps) {
  const [totalPoints, setTotalPoints] = useState(0);
  const [completedAchievements, setCompletedAchievements] = useState<string[]>([]);
  const [showAchievement, setShowAchievement] = useState<string | null>(null);

  const calculateProgress = () => {
    const steps: ProgressStep[] = [];
    let totalSteps = 0;
    let completedSteps = 0;

    categories.forEach(category => {
      // SMTP Configuration Step
      const smtpCompleted = !!(category.smtp && category.smtp.host && category.smtp.username);
      steps.push({
        id: `smtp_${category.id}`,
        title: `${category.categoryName} SMTP`,
        description: `Configure SMTP settings for ${category.categoryName}`,
        icon: <Settings className="w-4 h-4" />,
        points: 50,
        isCompleted: smtpCompleted,
        category: category.categoryKey
      });

      // SMTP Test Step
      const testCompleted = category.smtp?.testStatus === 'success';
      steps.push({
        id: `test_${category.id}`,
        title: `${category.categoryName} Test`,
        description: `Test SMTP connection for ${category.categoryName}`,
        icon: <TestTube className="w-4 h-4" />,
        points: 25,
        isCompleted: testCompleted,
        category: category.categoryKey
      });

      // Recipients Step
      const recipientsCompleted = category.recipients && category.recipients.length > 0;
      steps.push({
        id: `recipients_${category.id}`,
        title: `${category.categoryName} Recipients`,
        description: `Add email recipients for ${category.categoryName}`,
        icon: <Users className="w-4 h-4" />,
        points: 25,
        isCompleted: recipientsCompleted,
        category: category.categoryKey
      });

      totalSteps += 3;
      if (smtpCompleted) completedSteps++;
      if (testCompleted) completedSteps++;
      if (recipientsCompleted) completedSteps++;
    });

    return { steps, totalSteps, completedSteps };
  };

  const checkAchievements = () => {
    const { steps } = calculateProgress();
    const newAchievements: string[] = [];

    const smtpConfigured = steps.filter(s => s.id.startsWith('smtp_') && s.isCompleted);
    const testsCompleted = steps.filter(s => s.id.startsWith('test_') && s.isCompleted);
    const recipientsAdded = steps.filter(s => s.id.startsWith('recipients_') && s.isCompleted);

    // First SMTP
    if (smtpConfigured.length >= 1 && !completedAchievements.includes('first_smtp')) {
      newAchievements.push('first_smtp');
    }

    // All SMTP
    if (smtpConfigured.length === categories.length && !completedAchievements.includes('all_smtp')) {
      newAchievements.push('all_smtp');
    }

    // First Test
    if (testsCompleted.length >= 1 && !completedAchievements.includes('first_test')) {
      newAchievements.push('first_test');
    }

    // All Tests
    if (testsCompleted.length === categories.length && !completedAchievements.includes('all_tests')) {
      newAchievements.push('all_tests');
    }

    // Recipients Added
    if (recipientsAdded.length === categories.length && !completedAchievements.includes('recipients_added')) {
      newAchievements.push('recipients_added');
    }

    // Master Setup
    const allCompleted = smtpConfigured.length === categories.length && 
                        testsCompleted.length === categories.length && 
                        recipientsAdded.length === categories.length;
    if (allCompleted && !completedAchievements.includes('master_setup')) {
      newAchievements.push('master_setup');
    }

    // Show achievement notification
    if (newAchievements.length > 0) {
      setCompletedAchievements([...completedAchievements, ...newAchievements]);
      setShowAchievement(newAchievements[0]);
      setTimeout(() => setShowAchievement(null), 3000);
    }

    // Calculate points
    const points = [...completedAchievements, ...newAchievements]
      .reduce((total, achId) => {
        const achievement = achievements.find(a => a.id === achId);
        return total + (achievement?.points || 0);
      }, 0);

    setTotalPoints(points);
  };

  useEffect(() => {
    checkAchievements();
  }, [categories]);

  const { steps, totalSteps, completedSteps } = calculateProgress();
  const progressPercentage = totalSteps > 0 ? (completedSteps / totalSteps) * 100 : 0;

  const getProgressLevel = () => {
    if (progressPercentage === 100) return { level: 'Master', color: 'bg-yellow-500', textColor: 'text-yellow-700' };
    if (progressPercentage >= 75) return { level: 'Expert', color: 'bg-purple-500', textColor: 'text-purple-700' };
    if (progressPercentage >= 50) return { level: 'Advanced', color: 'bg-blue-500', textColor: 'text-blue-700' };
    if (progressPercentage >= 25) return { level: 'Intermediate', color: 'bg-green-500', textColor: 'text-green-700' };
    return { level: 'Beginner', color: 'bg-gray-500', textColor: 'text-gray-700' };
  };

  const level = getProgressLevel();

  return (
    <div className="space-y-6">
      {/* Achievement Notification */}
      <AnimatePresence>
        {showAchievement && (
          <motion.div
            initial={{ opacity: 0, y: -50 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -50 }}
            className="fixed top-4 right-4 z-50"
          >
            <Card className="bg-gradient-to-r from-yellow-400 to-orange-500 text-white border-0 shadow-lg">
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <Trophy className="w-6 h-6" />
                  <div>
                    <div className="font-bold">Achievement Unlocked!</div>
                    <div className="text-sm opacity-90">
                      {achievements.find(a => a.id === showAchievement)?.title}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Progress Overview */}
      <Card>
