                                    const allCoords = gpsHeatmap.data.map((point: any) => `${point.lat},${point.lng}`).join('|');
                                    const firstPoint = gpsHeatmap.data[0];
                                    const googleMapsUrl = `https://www.google.com/maps/dir/${allCoords}/@${firstPoint.lat},${firstPoint.lng},10z`;
                                    window.open(googleMapsUrl, '_blank');
                                  }}
                                  className="px-3 py-1 bg-blue-600 text-white text-xs rounded-md hover:bg-blue-700 transition-colors flex-shrink-0"
                                >
                                  🗺️ نمایش همه در Google Maps
                                </button>
                              </div>
                            </div>
                          </div>
                        </div>

                        <div className="mt-3 text-xs text-gray-600 text-center">
                          <p>📍 پراکندگی جغرافیایی {gpsHeatmap.data.length} نقطه تحویل در عراق، ایران و ترکیه. کارت‌های سبز: تحویل موفق، زرد: نیاز به بررسی</p>
                        </div>
                      </div>

                      {/* Detailed GPS Coordinates List */}
                      <div className="bg-gray-50 p-4 rounded-lg">
                        <h4 className="font-semibold text-gray-800 mb-3">جزئیات مختصات GPS</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 max-h-64 overflow-y-auto">
                          {gpsHeatmap.data.map((point: any, index: number) => (
                            <div key={index} className="flex items-center justify-between bg-white p-2 rounded border">
                              <div className="flex items-center">
                                <div className={`w-3 h-3 rounded-full mr-2 ${
                                  point.weight >= 1 ? 'bg-green-500' : 'bg-yellow-500'
                                }`}></div>
                                <div className="text-sm">
                                  <div className="font-medium">{point.lat.toFixed(4)}, {point.lng.toFixed(4)}</div>
                                  <div className="text-gray-500 text-xs">
                                    {new Date(point.timestamp).toLocaleDateString('en-US')}
                                  </div>
                                </div>
                              </div>
                              <Badge variant={point.weight >= 1 ? "default" : "secondary"} className="text-xs">
                                {point.weight >= 1 ? "دقیق" : "بررسی"}
                              </Badge>
                            </div>
                          ))}
                        </div>
                      </div>

                      <div className="text-xs text-gray-500 mt-4">
                        <p><strong>Note:</strong> GPS coordinates represent actual delivery confirmation locations in Iraq, Iran, and Turkey. Green indicators show high-accuracy deliveries, yellow indicates locations requiring review.</p>
                      </div>
                    </div>
                  ) : (
                    <div className="h-64 flex items-center justify-center text-gray-500">
                      <div className="text-center">
                        <MapPin className="h-12 w-12 mx-auto mb-4 text-gray-300" />
                        <p className="text-lg font-medium">No GPS Heatmap Data</p>
                        <p className="text-sm">GPS delivery locations will appear here when confirmations are made</p>
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            </>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

client/src/pages/product-reviews.tsx.content:
import { useState } from 'react';
import { useParams, useLocation } from 'wouter';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { ArrowLeft, Star, MessageSquare, User, Package } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { useMultilingualToast } from '@/hooks/use-multilingual-toast';
import { apiRequest } from '@/lib/queryClient';
import ProductRating from '@/components/ProductRating';
import { useLanguage } from '@/contexts/LanguageContext';
import ProductSchema from '@/components/seo/ProductSchema';
import OpenGraphTags from '@/components/seo/OpenGraphTags';
import CanonicalUrl from '@/components/seo/CanonicalUrl';
import Breadcrumbs from '@/components/seo/Breadcrumbs';

export default function ProductReviews() {
  const { id } = useParams<{ id: string }>();
  const [, navigate] = useLocation();
  const { toast } = useMultilingualToast();
  const queryClient = useQueryClient();
  const { t, direction } = useLanguage();

  // Get product details from shop products
  const { data: products, isLoading: isLoadingProduct } = useQuery({
    queryKey: ['/api/shop/products'],
    enabled: !!id,
  });

  // Find the specific product
  const product = Array.isArray(products) ? products.find((p: any) => p.id === parseInt(id || '0')) : null;

  // Get product reviews data - using proper shop products endpoint
  const { data: reviewsData, isLoading: isLoadingReviews } = useQuery({
    queryKey: [`/api/products/${id}/reviews`],
    enabled: !!id,
  });

  // Extract reviews and stats from the response data
  const reviews = (reviewsData as any)?.data?.reviews || [];
  const productStats = (reviewsData as any)?.data?.stats || { averageRating: 0, totalReviews: 0 };

  // Check if we have valid data to display
  const hasValidData = (reviewsData as any)?.success && (reviewsData as any)?.data;

  // Debug logging
  console.log('🔍 DEBUGGING REVIEWS ISSUE:');
  console.log('Product ID:', id);
  console.log('Reviews Data Full:', JSON.stringify(reviewsData, null, 2));
  console.log('Reviews Array Length:', reviews.length);
  console.log('Reviews Array:', reviews);
  console.log('Product Stats:', productStats);
  console.log('Product:', product);

  // Check if reviewsData structure is correct
  if (reviewsData) {
    console.log('ReviewsData type:', typeof reviewsData);
    console.log('ReviewsData keys:', Object.keys(reviewsData as any));
    if ((reviewsData as any).data) {
      console.log('ReviewsData.data keys:', Object.keys((reviewsData as any).data));
      console.log('ReviewsData.data.reviews:', (reviewsData as any).data.reviews);
    }
  }

  // Add review mutation
  const addReviewMutation = useMutation({
    mutationFn: async (reviewData: { rating: number; comment: string }) => {
      const payload = {
        rating: reviewData.rating,
        comment: reviewData.comment.trim(),
        title: `${t.customerReviewTitle} ${product?.name || t.shop.product}`, // Generate meaningful title
      };
      console.log('🔥 [REVIEW SUBMIT] Sending payload:', payload);
      const response = await fetch(`/api/products/${id}/reviews`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(payload)
      });
      return await response.json();
    },
    onSuccess: () => {
      // Invalidate and refetch product reviews (which includes stats)
      queryClient.invalidateQueries({ queryKey: [`/api/products/${id}/reviews`] });
      toast({
        title: 'reviewSubmitted',
        description: 'reviewSubmittedDesc',
      });
    },
    onError: (error: any) => {
      console.error('🔥 [REVIEW SUBMIT ERROR]', error);
      const errorMessage = error?.message || error?.toString() || "Unknown error";
      toast({
        title: 'reviewError',
        description: `${t.reviewErrorDesc}: ${errorMessage}`,
        variant: 'destructive',
      });
    },
  });

  const handleAddReview = async (reviewData: { rating: number; comment: string }) => {
    await addReviewMutation.mutateAsync(reviewData);
  };

  if (isLoadingProduct || isLoadingReviews) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="max-w-4xl mx-auto">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 rounded w-1/3 mb-4"></div>
            <div className="h-64 bg-gray-200 rounded mb-4"></div>
            <div className="h-32 bg-gray-200 rounded"></div>
          </div>
        </div>
      </div>
    );
  }

  // Show loading message if still waiting for valid data
  if (!hasValidData && !isLoadingReviews) {
    return (
      <div className="container mx-auto px-4 py-8" dir={direction}>
        <div className="max-w-4xl mx-auto text-center">
          <p className="text-gray-600">{t.loadingReviews}</p>
        </div>
      </div>
    );
  }

  if (!product) {
    return (
      <div className="container mx-auto px-4 py-8" dir={direction}>
        <div className="max-w-4xl mx-auto text-center">
          <Package className="w-16 h-16 text-gray-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-gray-900 mb-2">{t.productNotFound}</h1>
          <p className="text-gray-600 mb-4">{t.noReviewsDesc}</p>
          <Button onClick={() => navigate('/shop')} variant="outline">
            <ArrowLeft className={`w-4 h-4 ${direction === 'rtl' ? 'ml-2' : 'mr-2'}`} />
            {t.backToShop}
          </Button>
        </div>
      </div>
    );
  }

  return (
    <>
      {/* SEO Components */}
      <ProductSchema 
        product={product}
        rating={productStats}
      />
      <OpenGraphTags
        title={`${product.name} - Momtazchem`}
        description={product.description || `${product.name} - Premium quality chemical product`}
        image={product.imageUrl}
        url={`https://momtazchem.com/product-reviews/${id}`}
        type="product"
        price={product.price}
        currency={product.currency || 'IQD'}
        availability={product.inStock && (product.stockQuantity || 0) > 0 ? 'instock' : 'outofstock'}
      />
      <CanonicalUrl path={`/product-reviews/${id}`} />

      <div className="container mx-auto px-4 py-8" dir={direction}>
        <div className="max-w-4xl mx-auto">
          {/* Breadcrumbs */}
          <Breadcrumbs 
            items={[
              { label: 'Shop', href: '/shop' },
              { label: product.name }
            ]}
          />

          {/* Header */}
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={() => navigate('/shop')}
              className="mb-4"
            >
              <ArrowLeft className={`w-4 h-4 ${direction === 'rtl' ? 'ml-2' : 'mr-2'}`} />
              {t.backToShop}
            </Button>
          </div>

        {/* Product Info Card */}
        <Card className="mb-6">
          <CardContent className="p-6">
            <div className="flex items-start gap-4">
              <div className="w-20 h-20 bg-gray-100 rounded-lg flex-shrink-0 overflow-hidden">
                {product.imageUrl ? (
                  <img 
                    src={product.imageUrl} 
                    alt={product.name}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-400">
                    <Package className="w-8 h-8" />
                  </div>
                )}
              </div>
              <div className="flex-1">
                <h1 className="text-2xl font-bold text-gray-900 mb-2">{product.name}</h1>
                <p className="text-gray-600 mb-3">{product.description}</p>
                <div className="flex items-center gap-4">
                  <div className="flex items-center gap-1">
                    <span className="text-xl font-bold text-green-600">
                      {product.price && !isNaN(parseFloat(product.price)) ? parseFloat(product.price).toFixed(2) : '0.00'}
                    </span>
                    <span className="text-sm text-gray-500">
                      / {product.priceUnit || 'unit'}
                    </span>
                  </div>
                  <Badge variant={product.inStock ? "secondary" : "destructive"}>
                    {product.inStock ? t.inStock : t.outOfStock}
                  </Badge>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Rating Component */}
        {product && (
          <ProductRating
            productId={parseInt(id || '0')}
            productName={product.name}
            averageRating={productStats?.averageRating || 0}
            totalReviews={productStats?.totalReviews || 0}
            reviews={reviews}
            onAddReview={handleAddReview}
          />
        )}
      </div>
    </div>
    </>
  );
}

client/src/components/CustomerActivities.content:
import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useQuery } from "@tanstack/react-query";
import { Activity, UserCheck, UserX, RefreshCw } from "lucide-react";
import { Button } from "@/components/ui/button";

interface CustomerActivity {
  type: "login" | "logout";
  customerName: string;
  phone: string;
  email: string;
  timestamp: string;
}

const CustomerActivitiesCard = () => {
  const [lastRefresh, setLastRefresh] = useState(new Date());

  const { data: activities, isLoading, refetch } = useQuery({
    queryKey: ['/api/management/customer-activities', lastRefresh.getTime()],
    refetchInterval: 2 * 60 * 1000, // Refresh every 2 minutes
  });

  const formatTimeAgo = (timestamp: string) => {
    const now = new Date();
    const activityTime = new Date(timestamp);
    const diffInMinutes = Math.floor((now.getTime() - activityTime.getTime()) / (1000 * 60));

    if (diffInMinutes < 1) return "اکنون";
    if (diffInMinutes < 60) return `${diffInMinutes} دقیقه پیش`;

    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours < 24) return `${diffInHours} ساعت پیش`;

    const diffInDays = Math.floor(diffInHours / 24);
    return `${diffInDays} روز پیش`;
  };

  const handleRefresh = () => {
    setLastRefresh(new Date());
    refetch();
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center">
            <Activity className="w-5 h-5 ml-2 text-blue-500" />
            فعالیت‌های مشتریان
          </CardTitle>
          <Button
            variant="ghost"
            size="sm"
            onClick={handleRefresh}
            disabled={isLoading}
          >
            <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
          </Button>
        </div>
        <p className="text-sm text-gray-600">آخرین فعالیت‌های ورود و خروج مشتریان</p>
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <div className="flex items-center justify-center py-4">
            <div className="animate-spin w-6 h-6 border-2 border-primary border-t-transparent rounded-full" />
            <span className="mr-3 text-sm">در حال بارگذاری...</span>
          </div>
        ) : (
          <div className="space-y-3">
            {(activities as any)?.data?.map((activity: CustomerActivity, index: number) => (
              <div
                key={index}
                className={`flex items-start space-x-3 p-3 border rounded-lg ${
                  activity.type === 'login' 
                    ? 'bg-green-50 border-green-200' 
                    : 'bg-red-50 border-red-200'
                }`}
              >
                {activity.type === 'login' ? (
                  <UserCheck className="h-5 w-5 text-green-600 mt-0.5" />
                ) : (
                  <UserX className="h-5 w-5 text-red-600 mt-0.5" />
                )}
                <div className="flex-1">
                  <p className="font-medium text-gray-900">
                    {activity.type === 'login' ? 'ورود مشتری' : 'خروج مشتری'}
                  </p>
                  <div className="text-sm text-gray-700 space-y-1">
                    <p><span className="font-medium">نام:</span> {activity.customerName}</p>
                    <p><span className="font-medium">تلفن:</span> {activity.phone}</p>
                    <p><span className="font-medium">ایمیل:</span> {activity.email}</p>
                  </div>
                  <p className="text-xs text-gray-500 mt-2">
                    {formatTimeAgo(activity.timestamp)}
                  </p>
                </div>
              </div>
            ))}

            {(!(activities as any)?.data || (activities as any).data?.length === 0) && (
              <div className="text-center py-6 text-gray-500">
                <Activity className="w-8 h-8 mx-auto mb-2 opacity-50" />
                <p>فعالیت جدیدی یافت نشد</p>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default CustomerActivitiesCard;

