  // CRM Analytics
  async getLeadStatistics(): Promise<{
    totalLeads: number;
    newLeads: number;
    qualifiedLeads: number;
    closedWon: number;
    closedLost: number;
    conversionRate: number;
    averageDealSize: number;
  }> {
    const stats = await db
      .select({
        total: sql<number>`count(*)`,
        new: sql<number>`sum(case when status = 'new' then 1 else 0 end)`,
        qualified: sql<number>`sum(case when status = 'qualified' then 1 else 0 end)`,
        closedWon: sql<number>`sum(case when status = 'closed_won' then 1 else 0 end)`,
        closedLost: sql<number>`sum(case when status = 'closed_lost' then 1 else 0 end)`,
        avgDealSize: sql<number>`avg(case when estimated_value is not null then estimated_value else 0 end)`,
      })
      .from(leads);

    const result = stats[0];
    const totalClosed = result.closedWon + result.closedLost;
    const conversionRate = totalClosed > 0 ? (result.closedWon / totalClosed) * 100 : 0;

    return {
      totalLeads: result.total,
      newLeads: result.new,
      qualifiedLeads: result.qualified,
      closedWon: result.closedWon,
      closedLost: result.closedLost,
      conversionRate: Math.round(conversionRate * 100) / 100,
      averageDealSize: Math.round(result.avgDealSize * 100) / 100,
    };
  }

  // Persistent Cart Management
  async savePersistentCart(customerId: number, productId: number, quantity: number, unitPrice?: string): Promise<PersistentCart> {
    // ابتدا بررسی کنیم که آیا این محصول قبلاً در سبد وجود دارد
    const existing = await db
      .select()
      .from(persistentCarts)
      .where(and(
        eq(persistentCarts.customerId, customerId),
        eq(persistentCarts.productId, productId),
        eq(persistentCarts.isActive, true)
      ));

    if (existing.length > 0) {
      // اگر وجود دارد، کمیت را بروزرسانی کنیم
      const [updated] = await db
        .update(persistentCarts)
        .set({ 
          quantity, 
          updatedAt: new Date(),
          unitPrice: unitPrice ? unitPrice : existing[0].unitPrice
        })
        .where(eq(persistentCarts.id, existing[0].id))
        .returning();
      return updated;
    } else {
      // اگر وجود ندارد، رکورد جدید ایجاد کنیم
      const [cart] = await db
        .insert(persistentCarts)
        .values({
          customerId,
          productId,
          quantity,
          unitPrice: unitPrice || "0",
          addedAt: new Date(),
          updatedAt: new Date(),
          isActive: true
        })
        .returning();
      return cart;
    }
  }

