                  rows={4}
                />
              </div>

              {/* Action Buttons */}
              <div className="flex gap-3">
                <Button 
                  onClick={handlePrintOrder}
                  variant="outline"
                  className="flex-1"
                >
                  <FileText className="h-4 w-4 mr-2" />
                  چاپ جزئیات
                </Button>
                <Button 
                  onClick={handleApprove}
