      productName: string;
      quantity: number;
      price: number;
    }>;
  };
}

interface FinancialUser {
  id: number;
  username: string;
  email: string;
  department: string;
}

export default function FinancialDepartment() {
  const [selectedOrder, setSelectedOrder] = useState<OrderManagement | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [imageModalOpen, setImageModalOpen] = useState(false);
  const [selectedImageUrl, setSelectedImageUrl] = useState<string>("");
  const [selectedFileMimeType, setSelectedFileMimeType] = useState<string>("");
  const [user, setUser] = useState<FinancialUser | null>(null);
  const [, setLocation] = useLocation();

  // Enhanced image viewer states
  const [zoomLevel, setZoomLevel] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [panPosition, setPanPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const { toast } = useToast();

  const form = useForm({
    defaultValues: {
      notes: "",
      action: "approve" as "approve" | "reject"
    }
  });

  // Check authentication and user department
  useEffect(() => {
    const checkAuth = async () => {
      try {
        const response = await fetch('/api/financial/auth/me');
        if (response.ok) {
          const userData = await response.json();
          if (userData.success && userData.user.department === 'financial') {
            setUser(userData.user);
          } else {
            setLocation('/financial/login');
          }
        } else {
          setLocation('/financial/login');
        }
      } catch (error) {
        console.error('Auth check failed:', error);
        setLocation('/financial/login');
      }
    };

    checkAuth();
  }, [setLocation]);

  // Get refresh interval from global settings
  const getRefreshInterval = () => {
    const globalSettings = localStorage.getItem('global-refresh-settings');
    if (globalSettings) {
      const settings = JSON.parse(globalSettings);
      const financialSettings = settings.departments.financial;

      if (financialSettings?.autoRefresh) {
        const refreshInterval = settings.syncEnabled 
          ? settings.globalInterval 
          : financialSettings.interval;
        return refreshInterval * 1000; // Convert seconds to milliseconds
      }
    }
    return 600000; // Default 10 minutes if no settings found
  };

  // Fetch financial pending orders - only orders needing financial review
  const { data: ordersData, isLoading, refetch } = useQuery({
    queryKey: ["/api/financial/orders"],
    enabled: !!user,
    refetchInterval: getRefreshInterval(),
  });

  const orders = ordersData?.orders || [];

  // Process order mutation
  const processOrderMutation = useMutation({
    mutationFn: async (data: { orderId: number; action: "approve" | "reject"; notes: string }) => {
      const endpoint = data.action === 'approve' 
        ? `/api/finance/orders/${data.orderId}/approve`
        : `/api/finance/orders/${data.orderId}/reject`;

      return apiRequest(endpoint, 'POST', {
        notes: data.notes,
        reviewerId: user?.id
      });
    },
    onSuccess: (response, variables) => {
      queryClient.invalidateQueries({ queryKey: ["/api/financial/orders"] });
      setDialogOpen(false);
      setSelectedOrder(null);
      form.reset();

      // Enhanced success message based on action and wallet impact
      let description = "سفارش با موفقیت پردازش شد";

      if (variables.action === "approve" && selectedOrder?.financialNotes?.includes('مبلغ اضافی')) {
        const match = selectedOrder.financialNotes.match(/مبلغ اضافی ([\d,]+) دینار/);
        if (match) {
          const excessAmount = match[1];
          description = `سفارش تایید شد و مبلغ اضافی ${excessAmount} دینار به کیف پول مشتری اضافه شد`;
        }
      } else if (variables.action === "approve") {
        description = "سفارش تایید شد و به بخش انبار ارسال شد";
      } else {
        description = "سفارش رد شد و مشتری اطلاع‌رسانی شد";
      }

      toast({
        title: variables.action === "approve" ? "تایید موفق" : "رد موفق",
        description: description,
      });
    },
    onError: (error) => {
      toast({
        title: "خطا",
        description: "خطا در پردازش سفارش",
        variant: "destructive",
      });
    }
  });

  const handleProcessOrder = (values: { notes: string; action: "approve" | "reject" }) => {
    if (!selectedOrder) return;

    // Validate rejection reason is provided for reject action
    if (values.action === "reject" && (!values.notes || values.notes.trim() === "")) {
      toast({
        title: "خطا",
        description: "برای رد پرداخت، ذکر دلیل اجباری است",
        variant: "destructive"
      });
      return;
    }

    processOrderMutation.mutate({
      orderId: selectedOrder.customerOrderId,
      action: values.action,
      notes: values.notes
    });
  };

  const logout = async () => {
    try {
      await fetch('/api/financial/logout', { method: 'POST' });
      setLocation('/financial/login');
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };

  // Function to open image modal
  const openImageModal = (imageUrl: string, mimeType?: string) => {
    setSelectedImageUrl(imageUrl);
    setSelectedFileMimeType(mimeType || "");
    setImageModalOpen(true);
    // Reset zoom and pan when opening new image
    setZoomLevel(1);
    setRotation(0);
    setPanPosition({ x: 0, y: 0 });
  };

  // Enhanced image viewer functions
  const handleZoomIn = () => {
    setZoomLevel(prev => Math.min(prev * 1.5, 5));
  };

  const handleZoomOut = () => {
    setZoomLevel(prev => Math.max(prev / 1.5, 0.5));
  };

  const handleResetView = () => {
    setZoomLevel(1);
    setRotation(0);
    setPanPosition({ x: 0, y: 0 });
  };

  const handleRotate = () => {
    setRotation(prev => (prev + 90) % 360);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - panPosition.x, y: e.clientY - panPosition.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging && zoomLevel > 1) {
      setPanPosition({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Function to determine if URL is an image
  const isImageUrl = (url: string, mimeType?: string) => {
    if (mimeType) {
      return mimeType.startsWith('image/');
    }
    return /\.(jpg|jpeg|png|gif|webp)$/i.test(url);
  };

  // Function to determine if URL is a PDF
  const isPdfUrl = (url: string, mimeType?: string) => {
    if (mimeType) {
      return mimeType === 'application/pdf';
    }
    return /\.pdf$/i.test(url);
  };

  // Function to get file type for display
  const getFileType = (url: string, mimeType?: string) => {
    if (isImageUrl(url, mimeType)) return 'image';
    if (isPdfUrl(url, mimeType)) return 'pdf';
    return 'unknown';
  };

  if (!user) {
    return <div className="flex items-center justify-center min-h-screen">در حال بارگذاری...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
              <DollarSign className="w-8 h-8 text-green-600" />
              بخش مالی
            </h1>
            <p className="text-lg text-gray-600 mt-2">
              بررسی و تایید پرداخت‌های مشتریان و مدیریت مالیات
            </p>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 text-gray-600">
              <User className="w-4 h-4" />
              <span className="text-sm">{user.username}</span>
            </div>
            <Button 
              variant="outline" 
              onClick={logout}
              className="border-red-300 text-red-600 hover:bg-red-50"
            >
              <LogOut className="w-4 h-4 mr-2" />
              خروج
            </Button>
          </div>
        </div>

        {/* Tabs for Financial Operations */}
        <Tabs defaultValue="orders" className="mb-6" dir="rtl">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="orders" className="flex items-center gap-2">
              <FileText className="w-4 h-4" />
              سفارشات
            </TabsTrigger>
            <TabsTrigger value="vat" className="flex items-center gap-2">
              <Calculator className="w-4 h-4" />
              مدیریت مالیات (VAT)
            </TabsTrigger>
          </TabsList>

          {/* Orders Tab */}
          <TabsContent value="orders" className="space-y-6">{/* Move orders content here */}

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              <Card className="border-l-4 border-l-blue-500">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">سفارشات در انتظار</CardTitle>
                  <Clock className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">{orders.length}</div>
                </CardContent>
              </Card>

              <Card className="border-l-4 border-l-green-500">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">تایید شده امروز</CardTitle>
                  <CheckCircle className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">0</div>
                </CardContent>
              </Card>

              <Card className="border-l-4 border-l-red-500">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">رد شده امروز</CardTitle>
                  <XCircle className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">0</div>
                </CardContent>
              </Card>
            </div>

            {/* Refresh Control */}
            <div className="mb-6">
              <GlobalRefreshControl 
                pageName="financial"
                onRefresh={() => refetch()}
                isLoading={isLoading}
              />
            </div>

            {/* Orders List */}
            {isLoading ? (
              <div className="text-center py-8">در حال بارگذاری...</div>
            ) : orders.length === 0 ? (
              <Card>
                <CardContent className="text-center py-8">
                  <Clock className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-lg font-semibold text-gray-600 mb-2">هیچ سفارشی در انتظار نیست</h3>
                  <p className="text-gray-500">تمام سفارشات مالی پردازش شده‌اند</p>
                </CardContent>
              </Card>
            ) : (
              <div className="space-y-2">
                {orders.map((order: OrderManagement) => (
              <Card key={order.id} className="hover:shadow-md transition-shadow border border-gray-200">
                <CardContent className="p-3">
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <Badge variant="secondary" className="px-2 py-0.5 text-xs">
                          {order.orderNumber || `سفارش #${order.customerOrderId}`}
                        </Badge>
                        <Badge variant="outline" className="text-orange-600 border-orange-300 text-xs px-1 py-0.5">
                          در انتظار بررسی مالی
                        </Badge>
                        {order.paymentReceiptUrl && (
                          <Badge variant="default" className="bg-blue-100 text-blue-800 text-xs px-1 py-0.5">
                            <FileText className="w-3 h-3 mr-0.5" />
                            رسید
                          </Badge>
                        )}
                      </div>

                      <div className="flex items-center gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-4 text-xs">
                            <div>
                              <span className="font-medium text-gray-900">
                                {order.customerFirstName && order.customerLastName 
                                  ? `${order.customerFirstName} ${order.customerLastName}`
                                  : 'نام مشتری ناشناس'
                                }
                              </span>
                              <span className="text-gray-500 ml-2">
                                {order.customerEmail || 'ایمیل ثبت نشده'}
                              </span>
                            </div>

                            <div>
                              {order.totalAmount && (
                                <span className="font-bold text-green-600">
                                  {typeof order.totalAmount === 'number' 
                                    ? order.totalAmount.toLocaleString('fa-IR')
                                    : order.totalAmount
                                  } {order.currency || 'IQD'}
                                </span>
                              )}
                              <span className="text-gray-500 ml-2">
                                {new Date(order.createdAt).toLocaleDateString('en-US')}
                              </span>
                            </div>
                          </div>
                        </div>

                        <div className="flex items-center gap-2">
                          {/* Receipt Thumbnail - Ultra Compact */}
                          {(order.receipt?.url || order.paymentReceiptUrl) && (
                            <div 
                              className="w-8 h-8 rounded border border-gray-200 cursor-pointer hover:border-blue-400 transition-colors overflow-hidden flex items-center justify-center bg-gray-50"
                              onClick={() => {
                                const fileUrl = order.receipt?.url || order.paymentReceiptUrl!;
                                const mimeType = order.receipt?.mimeType;
                                if (isImageUrl(fileUrl, mimeType) || isPdfUrl(fileUrl, mimeType)) {
                                  openImageModal(fileUrl, mimeType);
                                } else {
                                  window.open(fileUrl, '_blank');
                                }
                              }}
                            >
                              {isImageUrl(order.receipt?.url || order.paymentReceiptUrl!, order.receipt?.mimeType) ? (
                                <img 
                                  src={order.receipt?.url || order.paymentReceiptUrl!}
                                  alt="فیش پرداخت"
                                  className="w-full h-full object-cover"
                                />
                              ) : (
                                <FileText className="w-3 h-3 text-gray-400" />
                              )}
                            </div>
                          )}

                          <Button
                            onClick={() => {
                              setSelectedOrder(order);
                              setDialogOpen(true);
                            }}
                            size="sm"
                            className="bg-blue-600 hover:bg-blue-700 text-xs px-2 py-1 h-8"
                          >
                            <Eye className="w-3 h-3 mr-1" />
                            بررسی
                          </Button>
                        </div>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
              </div>
            )}
          </TabsContent>

          {/* VAT Management Tab */}
          <TabsContent value="vat">
            <VatManagement />
          </TabsContent>
        </Tabs>

        {/* Process Order Dialog */}
        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>بررسی سفارش #{selectedOrder?.customerOrderId}</DialogTitle>
            </DialogHeader>

            {/* Order Summary */}
            {selectedOrder && (
              <div className="bg-gray-50 rounded-lg p-4 mb-4">
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <span className="text-gray-600">مشتری:</span>
                    <span className="font-medium ml-2">
                      {selectedOrder.customer?.firstName && selectedOrder.customer?.lastName 
                        ? `${selectedOrder.customer.firstName} ${selectedOrder.customer.lastName}`
                        : 'نام مشتری ناشناس'
                      }
                    </span>
                  </div>
                  <div>
                    <span className="text-gray-600">تلفن:</span>
                    <span className="font-medium ml-2">
                      {selectedOrder.customer?.phone || 'شماره تلفن ثبت نشده'}
                    </span>
                  </div>
                  <div>
                    <span className="text-gray-600">تاریخ ثبت:</span>
                    <span className="font-medium ml-2">
                      {new Date(selectedOrder.createdAt).toLocaleDateString('en-US')}
                    </span>
                  </div>
                  {selectedOrder.totalAmount && (
                    <div>
                      <span className="text-gray-600">مبلغ سفارش:</span>
                      <span className="font-bold text-blue-600 ml-2">
                        {typeof selectedOrder.totalAmount === 'number' 
                          ? selectedOrder.totalAmount.toLocaleString('fa-IR')
                          : selectedOrder.totalAmount
                        } {selectedOrder.currency || 'IQD'}
                      </span>
                    </div>
                  )}

                  {/* Wallet Impact Analysis */}
                  {selectedOrder.financialNotes && selectedOrder.financialNotes.includes('مبلغ اضافی') && (
                    <div className="col-span-2 mt-2 p-3 bg-orange-50 rounded-lg border border-orange-200">
                      <div className="flex items-center gap-2 mb-2">
                        <Wallet className="w-4 h-4 text-orange-600" />
                        <span className="text-sm font-medium text-orange-800">تأثیر بر کیف پول مشتری</span>
                      </div>
                      <div className="text-xs text-orange-700">
                        {(() => {
                          const match = selectedOrder.financialNotes?.match(/مبلغ اضافی ([\d,]+) دینار/);
                          if (match) {
                            const excessAmount = match[1];
                            return (
                              <div className="space-y-1">
                                <p>💰 <strong>مبلغ اضافی واریزی:</strong> {excessAmount} دینار</p>
                                <p>✅ <strong>تأیید سفارش:</strong> مبلغ اضافی به کیف پول مشتری اضافه می‌شود</p>
                                <p>❌ <strong>رد سفارش:</strong> مبلغ اضافی به کیف پول اضافه نمی‌شود</p>
                              </div>
                            );
                          }
                          return <p>این سفارش دارای مبلغ اضافی برای اضافه شدن به کیف پول است</p>;
                        })()}
                      </div>
                    </div>
                  )}

                  {/* Regular wallet impact when no excess */}
                  {(!selectedOrder.financialNotes || !selectedOrder.financialNotes.includes('مبلغ اضافی')) && (
                    <div className="col-span-2 mt-2 p-3 bg-green-50 rounded-lg border border-green-200">
                      <div className="flex items-center gap-2 mb-1">
                        <Wallet className="w-4 h-4 text-green-600" />
                        <span className="text-sm font-medium text-green-800">تأثیر بر کیف پول مشتری</span>
                      </div>
                      <p className="text-xs text-green-700">
                        ✅ <strong>تأیید سفارش:</strong> هیچ تغییری در کیف پول مشتری اعمال نمی‌شود (پرداخت دقیق)
                      </p>
                    </div>
                  )}
                  <div>
                    <span className="text-gray-600">فیش پرداخت:</span>
                    {(selectedOrder.receipt?.url || selectedOrder.paymentReceiptUrl) ? (
                      <div className="flex items-center gap-3 mt-2">
                        {/* Receipt Thumbnail in Modal */}
                        {isImageUrl(selectedOrder.receipt?.url || selectedOrder.paymentReceiptUrl!, selectedOrder.receipt?.mimeType) ? (
                          <div 
                            className="relative w-16 h-16 rounded-lg overflow-hidden border border-gray-200 cursor-pointer hover:border-blue-400 transition-colors"
                            onClick={() => openImageModal(selectedOrder.receipt?.url || selectedOrder.paymentReceiptUrl!, selectedOrder.receipt?.mimeType)}
                          >
                            <img 
                              src={selectedOrder.receipt?.url || selectedOrder.paymentReceiptUrl!}
                              alt="فیش پرداخت"
                              className="w-full h-full object-cover"
                            />
                            <div className="absolute inset-0 bg-black bg-opacity-0 hover:bg-opacity-20 transition-opacity flex items-center justify-center">
                              <ZoomIn className="w-3 h-3 text-white opacity-0 hover:opacity-100 transition-opacity" />
                            </div>
                          </div>
                        ) : (
                          <div 
                            className="w-16 h-16 rounded-lg border border-gray-200 flex items-center justify-center cursor-pointer hover:border-blue-400 bg-gray-50"
                            onClick={() => window.open(selectedOrder.receipt?.url || selectedOrder.paymentReceiptUrl!, '_blank')}
                          >
                            <FileText className="w-4 h-4 text-gray-400" />
                          </div>
                        )}

                      </div>
                    ) : (
                      <span className="text-red-600 ml-2">فیش ارسال نشده</span>
                    )}
                  </div>
                </div>
              </div>
            )}

            <Form {...form}>
              <form onSubmit={form.handleSubmit(handleProcessOrder)} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <Button
                    type="button"
                    variant={form.watch("action") === "approve" ? "default" : "outline"}
                    onClick={() => form.setValue("action", "approve")}
                    className="h-16"
                  >
                    <CheckCircle className="w-5 h-5 mr-2" />
                    تایید پرداخت
                  </Button>

                  <Button
                    type="button"
                    variant={form.watch("action") === "reject" ? "destructive" : "outline"}
                    onClick={() => form.setValue("action", "reject")}
                    className="h-16"
                  >
                    <XCircle className="w-5 h-5 mr-2" />
                    رد پرداخت
                  </Button>
                </div>

                <FormField
                  control={form.control}
                  name="notes"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>
                        {form.watch("action") === "reject" 
                          ? "دلیل رد پرداخت (اجباری - مشتری این متن را خواهد دید)" 
                          : "یادداشت تایید (اختیاری)"
                        }
                      </FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          placeholder={
                            form.watch("action") === "reject"
                              ? "مثال: فیش پرداخت نامشخص است، مبلغ واریزی کمتر از مبلغ سفارش است، اطلاعات بانکی صحیح نیست..."
                              : "یادداشت اضافی درباره تایید پرداخت..."
                          }
                          rows={4}
                          className={form.watch("action") === "reject" ? "border-red-300 focus:border-red-500" : ""}
                        />
                      </FormControl>
                      {form.watch("action") === "reject" && (
                        <div className="text-xs text-red-600 mt-1">
                          ⚠️ این متن به عنوان دلیل رد سفارش به مشتری نمایش داده خواهد شد
                        </div>
                      )}
                    </FormItem>
                  )}
                />

                <div className="flex justify-end gap-2 pt-4">
                  <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>
                    انصراف
                  </Button>
                  <Button 
                    type="submit" 
                    disabled={processOrderMutation.isPending}
                    className={form.watch("action") === "approve" ? "bg-green-600 hover:bg-green-700" : "bg-red-600 hover:bg-red-700"}
                  >
                    {processOrderMutation.isPending ? "در حال پردازش..." : 
                     form.watch("action") === "approve" ? "تایید نهایی" : "رد نهایی"}
                  </Button>
                </div>
              </form>
            </Form>
          </DialogContent>
        </Dialog>

        {/* Enhanced Image Modal for Receipt Viewing with Zoom */}
        <Dialog open={imageModalOpen} onOpenChange={setImageModalOpen}>
          <DialogContent className="max-w-[95vw] max-h-[95vh] p-0" style={{ width: '95vw', height: '95vh' }}>
            <DialogHeader className="p-4 pb-2 border-b">
              <DialogTitle className="flex items-center justify-between">
                <span className="flex items-center gap-2">
                  <FileText className="w-5 h-5 text-blue-600" />
                  مشاهده فیش پرداخت
                </span>
                <div className="flex items-center gap-2">
                  {/* Zoom Controls */}
                  <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={handleZoomOut}
                      disabled={zoomLevel <= 0.5}
                      className="h-8 w-8 p-0 hover:bg-gray-200"
                      title="کوچک‌تر کردن"
                    >
                      <ZoomOut className="h-4 w-4" />
                    </Button>

                    <span className="text-xs px-2 font-mono min-w-[50px] text-center">
                      {Math.round(zoomLevel * 100)}%
                    </span>

                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={handleZoomIn}
                      disabled={zoomLevel >= 5}
                      className="h-8 w-8 p-0 hover:bg-gray-200"
                      title="بزرگ‌تر کردن"
                    >
                      <ZoomIn className="h-4 w-4" />
                    </Button>
                  </div>

                  {/* Action Controls */}
                  <div className="flex items-center gap-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={handleRotate}
                      className="h-8 w-8 p-0 hover:bg-gray-200"
                      title="چرخاندن ۹۰ درجه"
                    >
                      <RotateCw className="h-4 w-4" />
                    </Button>

                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={handleResetView}
                      className="h-8 w-8 p-0 hover:bg-gray-200"
                      title="بازگشت به حالت اولیه"
                    >
                      <Move className="h-4 w-4" />
                    </Button>
                  </div>

                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setImageModalOpen(false)}
                    className="h-8 w-8 p-0 hover:bg-red-100 hover:text-red-600"
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              </DialogTitle>
            </DialogHeader>

            <div 
              className="flex-1 overflow-hidden bg-gray-50 relative"
              style={{ height: 'calc(95vh - 80px)' }}
            >
              {selectedImageUrl && (
                <>
                  {getFileType(selectedImageUrl, selectedFileMimeType) === 'image' ? (
                    <div
                      className="w-full h-full flex items-center justify-center cursor-move select-none"
                      onMouseDown={handleMouseDown}
                      onMouseMove={handleMouseMove}
                      onMouseUp={handleMouseUp}
                      onMouseLeave={handleMouseUp}
                      style={{ cursor: isDragging ? 'grabbing' : (zoomLevel > 1 ? 'grab' : 'default') }}
                    >
                      <img
                        src={selectedImageUrl}
                        alt="فیش پرداخت"
                        className="max-w-none transition-transform duration-200"
                        style={{
                          transform: `scale(${zoomLevel}) rotate(${rotation}deg) translate(${panPosition.x / zoomLevel}px, ${panPosition.y / zoomLevel}px)`,
                          transformOrigin: 'center center'
                        }}
                        draggable={false}
                      />
                    </div>
                  ) : getFileType(selectedImageUrl, selectedFileMimeType) === 'pdf' ? (
                    <div className="w-full h-full">
                      <iframe
                        src={selectedImageUrl}
                        className="w-full h-full border-0"
                        title="فیش پرداخت PDF"
                        style={{
                          transform: `scale(${zoomLevel}) rotate(${rotation}deg)`,
                          transformOrigin: 'center center',
                          transition: 'transform 0.2s ease'
                        }}
                      />
                    </div>
                  ) : (
                    // If it's a PDF file but not handled above, open directly in new tab
                    isPdfUrl(selectedImageUrl, selectedFileMimeType) ? (
                      window.open(selectedImageUrl, '_blank'),
                      setImageModalOpen(false),
                      <div className="w-full h-full flex items-center justify-center">
                        <div className="text-center p-8">
                          <FileText className="w-16 h-16 text-green-400 mx-auto mb-4" />
                          <p className="text-lg text-gray-600">در حال باز کردن PDF در تب جدید...</p>
                        </div>
                      </div>
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <div className="text-center p-8">
                          <FileText className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                          <p className="text-lg text-gray-600 mb-4">نوع فایل پشتیبانی نمی‌شود</p>
                          <Button
                            variant="outline"
                            onClick={() => window.open(selectedImageUrl, '_blank')}
                            className="flex items-center gap-2"
                          >
                            <Eye className="w-4 h-4" />
                            باز کردن در تب جدید
                          </Button>
                        </div>
                      </div>
                    )
                  )}
                </>
              )}

              {/* Zoom hint */}
              {zoomLevel > 1 && (
                <div className="absolute bottom-4 left-4 bg-black bg-opacity-75 text-white text-xs px-2 py-1 rounded">
                  برای جابجایی تصویر آن را بکشید
                </div>
              )}
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
}

server/secureObjectStorage.ts.content:
import { ObjectStorageService } from './objectStorage';
import { fileSecurityService, productImageSecurityService, FileValidationResult } from './fileSecurityService';
import { randomUUID } from 'crypto';

export interface SecureUploadResult {
  success: boolean;
  uploadUrl?: string;
  errors?: string[];
  fileId?: string;
  securityReport?: string;
}

export interface SecureUploadRequest {
  fileName: string;
  fileSize: number;
  mimeType?: string;
  userId?: string;
  allowedTypes?: string[];
  customSizeLimit?: number;
  uploadType?: string; // 'product-image', 'general', etc.
}

export class SecureObjectStorageService extends ObjectStorageService {

  /**
   * Generate secure upload URL with validation
   */
  async generateSecureUploadUrl(request: SecureUploadRequest): Promise<SecureUploadResult> {
    try {
      const errors: string[] = [];

      // Determine upload configuration based on type
      let sizeLimit: number;
      let allowedExtensions: string[];
      let allowedMimeTypes: string[];
      let compressionType: string;

      if (request.uploadType === 'product-image') {
        sizeLimit = 5 * 1024 * 1024; // 5MB for product images
        allowedExtensions = ['.jpg', '.jpeg', '.png', '.webp', '.gif'];
        allowedMimeTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
        compressionType = 'smart-product-compression';
        console.log('🖼️ [PRODUCT IMAGE CONFIG] Using optimized settings: 5MB limit, smart compression');
      } else {
        sizeLimit = request.customSizeLimit || 10 * 1024 * 1024; // 10MB default
        allowedExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.pdf', '.txt', '.doc', '.docx'];
        allowedMimeTypes = request.allowedTypes || ['image/jpeg', 'image/png', 'image/webp', 'application/pdf'];
        compressionType = 'standard-compression';
      }

      // Pre-upload validation
      if (request.fileSize > sizeLimit) {
        errors.push(`حجم فایل نباید بیشتر از ${this.formatFileSize(sizeLimit)} باشد`);
      }

      // Validate file extension
      const fileExtension = this.getFileExtension(request.fileName);
      if (!allowedExtensions.includes(fileExtension)) {
        errors.push(`پسوند فایل مجاز نیست: ${fileExtension}`);
      }

      // Validate MIME type if provided
      if (request.mimeType && !allowedMimeTypes.includes(request.mimeType)) {
        errors.push(`نوع فایل مجاز نیست: ${request.mimeType}`);
      }

      if (errors.length > 0) {
        return { success: false, errors };
      }

      // Generate unique file ID
      const fileId = randomUUID();
      const sanitizedFileName = this.sanitizeFileName(request.fileName);
      const finalFileName = `${fileId}_${sanitizedFileName}`;

      // Get upload URL from parent class
      const uploadUrl = await this.getObjectEntityUploadURL();

      const logMessage = request.uploadType === 'product-image' ? 
        `🖼️ [PRODUCT IMAGE] Generated smart compression upload URL for: ${finalFileName}` :
        `🔐 [SECURE UPLOAD] Generated secure upload URL for: ${finalFileName}`;

      console.log(logMessage);
      console.log(`📊 [UPLOAD CONFIG] File size: ${this.formatFileSize(request.fileSize)}, Type: ${request.uploadType || 'general'}`);
      console.log(`👤 [UPLOAD CONFIG] User: ${request.userId || 'anonymous'}, Compression: ${compressionType}`);

      return {
        success: true,
        uploadUrl,
        fileId,
        securityReport: this.generateUploadReport(request, fileId)
      };

    } catch (error) {
      console.error('❌ [SECURE UPLOAD] Error generating upload URL:', error);
      return {
        success: false,
        errors: ['خطا در تولید لینک آپلود']
      };
    }
  }

  /**
   * Validate uploaded file after upload
   */
  async validateUploadedFile(fileBuffer: Buffer, originalName: string, fileId: string): Promise<FileValidationResult & { fileId: string }> {
    console.log(`🔍 [POST-UPLOAD VALIDATION] Starting validation for file: ${fileId}`);

    const validationResult = await fileSecurityService.validateFile(fileBuffer, originalName);

    if (validationResult.isValid) {
      console.log(`✅ [POST-UPLOAD VALIDATION] File ${fileId} passed all security checks`);
    } else {
      console.log(`❌ [POST-UPLOAD VALIDATION] File ${fileId} failed validation:`, validationResult.errors);
    }

    // Log security report
    const securityReport = fileSecurityService.generateSecurityReport(validationResult);
    console.log(`📋 [SECURITY REPORT] ${fileId}:\n${securityReport}`);

    return {
      ...validationResult,
      fileId
    };
  }

  /**
   * Secure file processing pipeline
   */
  async processSecureUpload(fileBuffer: Buffer, originalName: string, userId?: string): Promise<{
    success: boolean;
    processedFile?: Buffer;
    metadata?: any;
    errors?: string[];
    fileId: string;
  }> {
    const fileId = randomUUID();

    try {
      console.log(`🚀 [SECURE PIPELINE] Starting processing for file: ${fileId}`);

      // Step 1: Comprehensive validation
      const validationResult = await this.validateUploadedFile(fileBuffer, originalName, fileId);

      if (!validationResult.isValid) {
        return {
          success: false,
          errors: validationResult.errors,
          fileId
        };
      }

      // Step 2: Store metadata
      const fileMetadata = {
        fileId,
        originalName,
        userId,
        uploadedAt: new Date().toISOString(),
        ...validationResult.metadata
      };

      console.log(`💾 [SECURE PIPELINE] File ${fileId} processed successfully`);

      return {
        success: true,
        processedFile: validationResult.processedBuffer,
        metadata: fileMetadata,
        fileId
      };

    } catch (error) {
      console.error(`❌ [SECURE PIPELINE] Processing failed for file ${fileId}:`, error);
      return {
        success: false,
        errors: ['خطا در پردازش فایل'],
        fileId
      };
    }
  }

  /**
   * Sanitize file name to prevent path traversal
   */
  private sanitizeFileName(fileName: string): string {
    // Remove dangerous characters and paths
    return fileName
      .replace(/[<>:"/\\|?*]/g, '_') // Replace dangerous chars
      .replace(/\.\./g, '_') // Remove parent directory references
      .replace(/^\.+/, '_') // Remove leading dots
      .substring(0, 100); // Limit length
  }

  /**
   * Get file extension safely
   */
  private getFileExtension(fileName: string): string {
    const match = fileName.match(/\.[^.]*$/);
    return match ? match[0].toLowerCase() : '';
  }

  /**
   * Format file size for display
   */
  private formatFileSize(bytes: number): string {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;

    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }

    return `${size.toFixed(1)} ${units[unitIndex]}`;
  }

  /**
   * Generate upload report
   */
  private generateUploadReport(request: SecureUploadRequest, fileId: string): string {
    let report = `📋 گزارش آپلود امن:\n`;
    report += `🆔 شناسه فایل: ${fileId}\n`;
    report += `📁 نام فایل: ${request.fileName}\n`;
    report += `📊 حجم: ${this.formatFileSize(request.fileSize)}\n`;
    report += `👤 کاربر: ${request.userId || 'ناشناس'}\n`;
    report += `⏰ زمان: ${new Date().toLocaleString('fa-IR')}\n`;
    report += `🔐 وضعیت: آماده برای آپلود امن\n`;

    return report;
  }

  /**
   * Check file against blacklisted patterns
   */
  async checkFileAgainstBlacklist(fileName: string, fileBuffer: Buffer): Promise<{
    isBlacklisted: boolean;
    reason?: string;
  }> {
    // Check file name patterns
    const dangerousPatterns = [
      /\.exe$/i, /\.bat$/i, /\.cmd$/i, /\.scr$/i, /\.vbs$/i, 
      /\.js$/i, /\.jar$/i, /\.com$/i, /\.pif$/i
    ];

    for (const pattern of dangerousPatterns) {
      if (pattern.test(fileName)) {
        return {
          isBlacklisted: true,
          reason: `نوع فایل خطرناک: ${fileName}`
        };
      }
    }

    // Check file content for suspicious patterns
    const content = fileBuffer.toString('utf8', 0, Math.min(fileBuffer.length, 1024));
    const suspiciousContent = [
      /eval\s*\(/gi,
      /exec\s*\(/gi,
      /system\s*\(/gi,
      /shell_exec/gi,
      /base64_decode/gi
    ];

    for (const pattern of suspiciousContent) {
      if (pattern.test(content)) {
        return {
          isBlacklisted: true,
          reason: 'محتوای مشکوک در فایل'
        };
      }
    }

    return { isBlacklisted: false };
  }
}

// Export configured instance
export const secureObjectStorageService = new SecureObjectStorageService();

shared/shop-schema.ts.content:
import { pgTable, text, serial, timestamp, decimal, boolean, integer, json, date } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// =============================================================================
// SHOP/ECOMMERCE SCHEMA - For actual product sales and inventory management
// =============================================================================

// Shop Inventory Movements - Track all shop inventory movements
export const shopInventoryMovements = pgTable("shop_inventory_movements", {
  id: serial("id").primaryKey(),
  productId: integer("product_id").notNull(),
  orderId: integer("order_id"), // ارتباط با سفارش
  customerId: integer("customer_id"),
  transactionType: text("transaction_type").notNull(), // 'sale', 'reserve', 'transit', 'delivered', 'returned', 'cancelled'
  quantity: integer("quantity").notNull(),
  previousStock: integer("previous_stock").notNull(),
  newStock: integer("new_stock").notNull(),
  notes: text("notes"),
  createdBy: integer("created_by"), // Admin ID
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

// Goods in Transit - کالاهای در راه
export const goodsInTransit = pgTable("goods_in_transit", {
  id: serial("id").primaryKey(),
  orderId: integer("order_id").notNull(),
  customerId: integer("customer_id").notNull(),
  productId: integer("product_id").notNull(),
  quantity: integer("quantity").notNull(),
  status: text("status").notNull().default("paid"), // 'paid', 'prepared', 'shipped', 'delivered'
  paymentDate: timestamp("payment_date").notNull(),
  expectedDeliveryDate: timestamp("expected_delivery_date"),
  actualDeliveryDate: timestamp("actual_delivery_date"),
  trackingNumber: text("tracking_number"),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// Product Waste Tracking - تتبع ضایعات محصولات
export const productWaste = pgTable("product_waste", {
  id: serial("id").primaryKey(),
  productId: integer("product_id").notNull(),
  wasteAmount: decimal("waste_amount", { precision: 10, scale: 2 }).notNull().default("0"),
  reason: text("reason"), // دلیل ضایعات
  reportedBy: integer("reported_by"), // Admin ID
  reportedAt: timestamp("reported_at").notNull().defaultNow(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// Batch Sales Tracking - ردیابی فروش بچ‌ها
export const batchSalesTracking = pgTable("batch_sales_tracking", {
  id: serial("id").primaryKey(),
  orderId: integer("order_id").notNull(),
  customerId: integer("customer_id").notNull(),
  productId: integer("product_id").notNull(),
  barcode: text("barcode").notNull(),
  batchNumber: text("batch_number").notNull(),
  quantitySold: integer("quantity_sold").notNull(),
  wasteAmount: decimal("waste_amount", { precision: 10, scale: 2 }).default("0"), // ضایعات احتساب شده
  effectiveQuantity: integer("effective_quantity").notNull(), // مقدار مؤثر (quantity_sold + waste_amount)
  unitPrice: decimal("unit_price", { precision: 10, scale: 2 }).notNull(),
  totalPrice: decimal("total_price", { precision: 10, scale: 2 }).notNull(),
  batchExpiryDate: timestamp("batch_expiry_date"),
  manufacturingDate: timestamp("manufacturing_date"),
  saleDate: timestamp("sale_date").notNull().defaultNow(),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

// Shop products with actual pricing and inventory
export const shopProducts = pgTable("shop_products", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  category: text("category").notNull(),
  description: text("description").notNull(),
  shortDescription: text("short_description"),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  compareAtPrice: decimal("compare_at_price", { precision: 10, scale: 2 }), // Original price for discounts
  priceUnit: text("price_unit").notNull(), // per liter, per kg, per ton
  inStock: boolean("in_stock").default(true),
  stockQuantity: integer("stock_quantity").default(0),
  reservedQuantity: integer("reserved_quantity").default(0), // کالای رزرو شده
  transitQuantity: integer("transit_quantity").default(0), // کالای در راه
  availableQuantity: integer("available_quantity").default(0), // موجودی قابل فروش
  minStockLevel: integer("min_stock_level").default(5), // حد مینیمم برای اعلام به مدیر تولید
  lowStockThreshold: integer("low_stock_threshold").default(10), // آستانه برای نمایش هشدار به مشتری
  maxStockLevel: integer("max_stock_level").default(1000), // حداکثر موجودی مجاز
  sku: text("sku").unique().notNull(),
  barcode: text("barcode"),
  // Weight fields - Enhanced with net and gross weights
  netWeight: decimal("net_weight", { precision: 8, scale: 2 }), // وزن خالص - Net weight (product only)
  grossWeight: decimal("gross_weight", { precision: 8, scale: 2 }), // وزن ناخالص - Gross weight (product + packaging)
  weightUnit: text("weight_unit").default("kg"), // Weight unit (kg, g, lb, oz, t)
  // Legacy weight field for backward compatibility
  weight: decimal("weight", { precision: 8, scale: 2 }), // Deprecated: use grossWeight for calculations
  dimensions: json("dimensions"), // {length, width, height}
  imageUrls: json("image_urls"), // Array of product images
  thumbnailUrl: text("thumbnail_url"),
  specifications: json("specifications"),
  features: json("features"),
  applications: json("applications"),
  tags: json("tags"), // For search and filtering
  minimumOrderQuantity: integer("minimum_order_quantity").default(1),
  maximumOrderQuantity: integer("maximum_order_quantity"),
  leadTime: text("lead_time"), // Delivery time
  shippingClass: text("shipping_class"), // standard, hazardous, etc.
  taxClass: text("tax_class").default("standard"),
  quantityDiscounts: json("quantity_discounts"), // [{minQty: 10, discount: 0.05}, {minQty: 50, discount: 0.10}]
  isActive: boolean("is_active").default(true),
  isFeatured: boolean("is_featured").default(false),
  // Marketplace vendor field
  vendorId: integer("vendor_id"), // Reference to vendor (null = owned by Momtazchem)
  visibleInShop: boolean("visible_in_shop").default(true), // کنترل نمایش در فروشگاه
  showWhenOutOfStock: boolean("show_when_out_of_stock").default(false), // نمایش در فروشگاه حتی با موجودی صفر
  metaTitle: text("meta_title"),
  metaDescription: text("meta_description"),
  // MSDS (Material Safety Data Sheet) fields
  msdsUrl: text("msds_url"), // URL to MSDS PDF file
  showMsdsToCustomers: boolean("show_msds_to_customers").default(false), // Checkbox to control visibility
  msdsFileName: text("msds_file_name"), // Original filename for display
  msdsUploadDate: timestamp("msds_upload_date"), // When MSDS was uploaded
  // Product Catalog fields
  pdfCatalogUrl: text("pdf_catalog_url"), // URL to product catalog PDF file
  showCatalogToCustomers: boolean("show_catalog_to_customers").default(false), // Checkbox to control visibility
  catalogFileName: text("catalog_file_name"), // Original filename for display
  catalogUploadDate: timestamp("catalog_upload_date"), // When catalog was uploaded
  // Safety and hazard information
  isFlammable: boolean("is_flammable").default(false), // آتش‌زا بودن کالا
  // 3D Model Fields - For interactive 3D product viewing
  displayMode: text("display_mode").default("images"), // 'images' or '3d_model' - Controls what customers see in shop
  model3dKey: text("model3d_key"), // S3 key for 3D model file (GLB/GLTF format)
  model3dFileName: text("model3d_file_name"), // Original filename for display
  model3dUploadDate: timestamp("model3d_upload_date"), // When 3D model was uploaded
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),

  // Parent product relationship for variants
  parentProductId: integer("parent_product_id"),
  isVariant: boolean("is_variant").default(false),
  variantType: text("variant_type"), // size, concentration, packaging, etc.
  variantValue: text("variant_value"), // 1kg, 5kg, 25kg, 50%, 80%, etc.
  sortOrder: integer("sort_order").default(0), // Display order for variants
});

// Product variants relationship table
export const productVariants = pgTable("product_variants", {
  id: serial("id").primaryKey(),
  parentProductId: integer("parent_product_id").notNull(),
  variantProductId: integer("variant_product_id").notNull(),
  variantType: text("variant_type").notNull(), // size, concentration, packaging, purity
  variantName: text("variant_name").notNull(), // 1kg Bottle, 5kg Container, 95% Purity
  variantValue: text("variant_value").notNull(), // 1kg, 5kg, 95%
  sortOrder: integer("sort_order").default(0),
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

// Product variant options for different attributes
export const productVariantOptions = pgTable("product_variant_options", {
  id: serial("id").primaryKey(),
  parentProductId: integer("parent_product_id").notNull(),
  optionName: text("option_name").notNull(), // Size, Concentration, Package Type
  optionValues: json("option_values").notNull(), // ["1kg", "5kg", "25kg"] or ["50%", "80%", "95%"]
  isRequired: boolean("is_required").default(true),
  displayType: text("display_type").default("dropdown"), // dropdown, radio, buttons
  sortOrder: integer("sort_order").default(0),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

// Payment gateways configuration table
export const paymentGateways = pgTable("payment_gateways", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(), // e.g., "Rasheed Bank", "Visa Iraq"
  type: text("type").notNull(), // 'iraqi_bank' | 'credit_card' | 'digital_wallet' | 'bank_transfer'
  enabled: boolean("enabled").default(true),
  config: json("config").notNull(), // Payment gateway specific configuration
  testMode: boolean("test_mode").default(false),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// Discount settings table for admin management
export const discountSettings = pgTable("discount_settings", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(), // e.g., "Bulk Discount 1"
  type: text("type").notNull().default("quantity"), // quantity, percentage, fixed
  minQuantity: integer("min_quantity").default(1),
  discountPercentage: decimal("discount_percentage", { precision: 5, scale: 2 }).notNull(),
  isActive: boolean("is_active").default(true),
  description: text("description"),
  applicableProducts: json("applicable_products"), // Array of selected product IDs
  applyToAllProducts: boolean("apply_to_all_products").default(true), // If false, apply only to selected products
  applicableCategories: json("applicable_categories"), // Array of category IDs for category-based discounts
  // Date range fields for discount validity
  validFrom: date("valid_from"), // Start date (Gregorian)
  validTo: date("valid_to"), // End date (Gregorian)
  // Usage limits
  usageLimit: integer("usage_limit"), // Maximum number of times this discount can be used
  usedCount: integer("used_count").default(0), // Current usage count
  // Minimum order amount
  minOrderAmount: decimal("min_order_amount", { precision: 10, scale: 2 }), // Minimum order value to apply discount
  maxDiscountAmount: decimal("max_discount_amount", { precision: 10, scale: 2 }), // Maximum discount amount (cap)
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertDiscountSettingsSchema = createInsertSchema(discountSettings).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type InsertDiscountSetting = z.infer<typeof insertDiscountSettingsSchema>;
export type DiscountSetting = typeof discountSettings.$inferSelect;

// Financial transactions table for accounting
export const financialTransactions = pgTable("financial_transactions", {
  id: serial("id").primaryKey(),
  type: text("type").notNull(), // 'sale', 'refund', 'adjustment', 'return'
  orderId: integer("order_id"), // Reference to orders table (foreign key will be added separately)
  amount: decimal("amount", { precision: 10, scale: 2 }).notNull(),
  description: text("description").notNull(),
  referenceNumber: text("reference_number"),
  status: text("status").notNull().default("completed"), // completed, pending, cancelled
  processingDate: timestamp("processing_date").notNull().defaultNow(),
  metadata: json("metadata"), // Additional transaction details
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

export const insertFinancialTransactionSchema = createInsertSchema(financialTransactions).omit({
  id: true,
  createdAt: true,
});

export type InsertFinancialTransaction = z.infer<typeof insertFinancialTransactionSchema>;
export type FinancialTransaction = typeof financialTransactions.$inferSelect;

