import { db } from "./db";
import { customerCommunications, emailCategories, CustomerCommunication, InsertCustomerCommunication } from "@shared/email-schema";
import { eq, desc, and, or, ilike } from "drizzle-orm";

export class CustomerCommunicationStorage {
  // Send a new message to customer with intelligent email routing
  async sendMessage(data: InsertCustomerCommunication): Promise<CustomerCommunication> {
    const [communication] = await db
      .insert(customerCommunications)
      .values(data)
      .returning();

    // If this is an outbound message, send actual email using category SMTP
    if (data.messageType === 'outbound') {
      await this.sendActualEmail(communication);
    }

    return communication;
  }

  // Send actual email using category-specific SMTP configuration
  private async sendActualEmail(communication: CustomerCommunication): Promise<void> {
    try {
      // Import smtpSettings from schema
      const { smtpSettings } = await import("@shared/email-schema");

      // Get category SMTP configuration
      const [categoryConfig] = await db
        .select({
          categoryName: emailCategories.categoryName,
          smtpHost: smtpSettings.host,
          smtpPort: smtpSettings.port,
          smtpSecure: smtpSettings.secure,
          smtpUsername: smtpSettings.username,
          smtpPassword: smtpSettings.password,
          smtpFromName: smtpSettings.fromName,
          smtpFromEmail: smtpSettings.fromEmail
        })
        .from(emailCategories)
        .leftJoin(smtpSettings, eq(emailCategories.id, smtpSettings.categoryId))
        .where(eq(emailCategories.id, communication.categoryId));

      if (!categoryConfig?.smtpHost) {
        console.error(`No SMTP configuration found for category ${communication.categoryId}`);
        return;
      }

      const nodemailer = await import('nodemailer');

      const transporter = nodemailer.default.createTransport({
        host: categoryConfig.smtpHost,
        port: categoryConfig.smtpPort,
        secure: categoryConfig.smtpSecure,
        auth: {
          user: categoryConfig.smtpUsername,
          pass: categoryConfig.smtpPassword,
        },
      });

      const mailOptions = {
        from: `"${categoryConfig.smtpFromName}" <${categoryConfig.smtpFromEmail}>`,
        to: communication.customerEmail,
        subject: communication.subject,
        html: `
          <div style="font-family: Arial, sans-serif; direction: rtl; text-align: right;">
            <h2 style="color: #2563eb;">شرکت مومتاز کم</h2>
            <p>عزیز ${communication.customerName},</p>
            <div style="background: #f8fafc; padding: 20px; border-radius: 8px; margin: 20px 0;">
              ${communication.message.replace(/\n/g, '<br>')}
            </div>
            <p>با تشکر,<br>تیم ${categoryConfig.categoryName}</p>
            <hr style="margin: 20px 0;">
            <p style="font-size: 12px; color: #6b7280;">
              این ایمیل از سیستم مدیریت ارتباط با مشتریان مومتاز کم ارسال شده است.
            </p>
          </div>
        `
      };

      await transporter.sendMail(mailOptions);
      console.log(`Email sent successfully to ${communication.customerEmail} via ${categoryConfig.categoryName}`);

      // Update communication status
      await db
        .update(customerCommunications)
        .set({ 
          status: 'delivered',
          updatedAt: new Date()
        })
        .where(eq(customerCommunications.id, communication.id));

    } catch (error) {
      console.error('Error sending email:', error);

      // Update communication status to failed
      await db
        .update(customerCommunications)
        .set({ 
          status: 'failed',
          updatedAt: new Date()
        })
        .where(eq(customerCommunications.id, communication.id));
    }
  }

  // Get all communications for a specific category
  async getCommunicationsByCategory(categoryId: number): Promise<CustomerCommunication[]> {
    return await db
      .select()
      .from(customerCommunications)
      .where(eq(customerCommunications.categoryId, categoryId))
      .orderBy(desc(customerCommunications.createdAt));
  }

  // Get all communications with a specific customer
  async getCommunicationsByCustomer(customerEmail: string): Promise<CustomerCommunication[]> {
    return await db
      .select()
      .from(customerCommunications)
      .where(eq(customerCommunications.customerEmail, customerEmail))
      .orderBy(desc(customerCommunications.createdAt));
  }

  // Get communication thread (message and its replies)
  async getCommunicationThread(messageId: number): Promise<CustomerCommunication[]> {
    return await db
      .select()
      .from(customerCommunications)
      .where(
        or(
          eq(customerCommunications.id, messageId),
          eq(customerCommunications.replyToMessageId, messageId)
        )
      )
      .orderBy(customerCommunications.createdAt);
  }

  // Mark message as read
  async markAsRead(messageId: number): Promise<void> {
    await db
      .update(customerCommunications)
      .set({ 
        readAt: new Date(),
        status: 'read'
      })
      .where(eq(customerCommunications.id, messageId));
  }

  // Mark message as replied
  async markAsReplied(messageId: number): Promise<void> {
    await db
      .update(customerCommunications)
      .set({ 
        repliedAt: new Date(),
        status: 'replied'
      })
      .where(eq(customerCommunications.id, messageId));
  }

  // Get recent communications (last 30 days)
  async getRecentCommunications(limit: number = 50): Promise<CustomerCommunication[]> {
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    return await db
      .select()
      .from(customerCommunications)
      .where(eq(customerCommunications.createdAt, thirtyDaysAgo))
      .orderBy(desc(customerCommunications.createdAt))
      .limit(limit);
  }

  // Get communication stats by category
  async getCommunicationStats(categoryId?: number) {
    let query = db.select().from(customerCommunications);

    if (categoryId) {
      query = query.where(eq(customerCommunications.categoryId, categoryId));
    }

    const communications = await query;

    const stats = {
      total: communications.length,
      sent: communications.filter(c => c.messageType === 'outbound').length,
      received: communications.filter(c => c.messageType === 'inbound').length,
      followUps: communications.filter(c => c.messageType === 'follow_up').length,
      replied: communications.filter(c => c.status === 'replied').length,
      pending: communications.filter(c => c.status === 'sent' || c.status === 'delivered').length,
    };

    return stats;
  }

  // Search communications by customer name or email
  async searchCommunications(searchTerm: string): Promise<CustomerCommunication[]> {
    return await db
      .select()
      .from(customerCommunications)
      .where(
        or(
          ilike(customerCommunications.customerEmail, `%${searchTerm}%`),
          ilike(customerCommunications.customerName, `%${searchTerm}%`),
          ilike(customerCommunications.subject, `%${searchTerm}%`),
          ilike(customerCommunications.message, `%${searchTerm}%`)
        )
      )
      .orderBy(desc(customerCommunications.createdAt));
  }

  // Update communication status
  async updateStatus(messageId: number, status: string): Promise<void> {
    await db
      .update(customerCommunications)
      .set({ 
        status,
        updatedAt: new Date()
      })
      .where(eq(customerCommunications.id, messageId));
  }

  // Delete communication
  async deleteCommunication(messageId: number): Promise<void> {
    await db
      .delete(customerCommunications)
      .where(eq(customerCommunications.id, messageId));
  }

  // Get communication by ID
  async getCommunicationById(messageId: number): Promise<CustomerCommunication | undefined> {
    const [communication] = await db
      .select()
      .from(customerCommunications)
      .where(eq(customerCommunications.id, messageId))
      .limit(1);

    return communication;
  }
}

export const customerCommunicationStorage = new CustomerCommunicationStorage();

server/cart-storage.ts.content:
import { neon } from "@neondatabase/serverless";
import { drizzle } from "drizzle-orm/neon-http";
import { eq, and, desc, gte, lte, sql } from "drizzle-orm";
import { 
  cartSessions, 
  abandonedCartSettings, 
  abandonedCartNotifications, 
  cartRecoveryAnalytics,
  type CartSession,
  type InsertCartSession,
  type AbandonedCartSettings,
  type InsertAbandonedCartSettings,
  type AbandonedCartNotification,
  type InsertAbandonedCartNotification,
  type CartRecoveryAnalytics
} from "@shared/cart-schema";

const sql_client = neon(process.env.DATABASE_URL!);
const cartDb = drizzle(sql_client);

export class CartStorage {

  // =============================================================================
  // CART SESSION MANAGEMENT
  // =============================================================================

  async createOrUpdateCartSession(data: {
    customerId: number;
    sessionId: string;
    cartData: any;
    itemCount: number;
    totalValue: number;
  }) {
    const existing = await cartDb
      .select()
      .from(cartSessions)
      .where(and(
        eq(cartSessions.customerId, data.customerId),
        eq(cartSessions.isActive, true)
      ))
      .limit(1);

    if (existing.length > 0) {
      // Update existing session
      await cartDb
        .update(cartSessions)
        .set({
          cartData: data.cartData,
          itemCount: data.itemCount,
          totalValue: data.totalValue.toString(),
          lastActivity: new Date(),
          updatedAt: new Date(),
          isAbandoned: false,
          abandonedAt: null
        })
        .where(eq(cartSessions.id, existing[0].id));

      return existing[0].id;
    } else {
      // Create new session
      const [newSession] = await cartDb
        .insert(cartSessions)
        .values({
          customerId: data.customerId,
          sessionId: data.sessionId,
          cartData: data.cartData,
          itemCount: data.itemCount,
          totalValue: data.totalValue.toString(),
          lastActivity: new Date(),
          createdAt: new Date(),
          updatedAt: new Date(),
          isActive: true,
          isAbandoned: false
        })
        .returning();

      return newSession.id;
    }
  }

  async getActiveCartSessions(customerId?: number) {
    let query = cartDb
      .select()
      .from(cartSessions)
      .where(eq(cartSessions.isActive, true));

    if (customerId) {
      query = cartDb
        .select()
        .from(cartSessions)
        .where(and(
          eq(cartSessions.isActive, true),
          eq(cartSessions.customerId, customerId)
        ));
    }

    return await query.orderBy(desc(cartSessions.lastActivity));
  }

  async markCartAsAbandoned(sessionId: number) {
    await cartDb
      .update(cartSessions)
      .set({
        isAbandoned: true,
        abandonedAt: new Date(),
        updatedAt: new Date()
      })
      .where(eq(cartSessions.id, sessionId));
  }

  async markCartAsCompleted(sessionId: number) {
    await cartDb
      .update(cartSessions)
      .set({
        isActive: false,
        updatedAt: new Date()
      })
      .where(eq(cartSessions.id, sessionId));
  }

  async getAbandonedCarts(timeoutMinutes: number = 30) {
    // Get all carts that are already marked as abandoned OR should be marked as abandoned
    const timeoutDate = new Date();
    timeoutDate.setMinutes(timeoutDate.getMinutes() - timeoutMinutes);

    return await cartDb
      .select()
      .from(cartSessions)
      .where(and(
        gte(cartSessions.itemCount, 1), // Has items in cart
        // Show both: already abandoned carts OR active carts that are now abandoned
        sql`(${cartSessions.isAbandoned} = true OR (${cartSessions.isActive} = true AND ${cartSessions.isAbandoned} = false AND ${cartSessions.lastActivity} <= ${timeoutDate.toISOString()}))`
      ))
      .orderBy(desc(cartSessions.lastActivity));
  }

  async clearCartSession(customerId: number) {
    await cartDb
      .update(cartSessions)
      .set({
        isActive: false,
        updatedAt: new Date()
      })
      .where(eq(cartSessions.customerId, customerId));
  }

  async getAbandonedCartAnalytics() {
    // Get basic analytics for abandoned carts
    const [
      totalAbandoned,
      recentAbandoned,
      totalValue
    ] = await Promise.all([
      // Total abandoned carts
      cartDb
        .select({ count: sql`count(*)` })
        .from(cartSessions)
        .where(and(
          eq(cartSessions.isAbandoned, true),
          gte(cartSessions.itemCount, 1)
        )),

      // Recent abandoned carts (last 7 days)
      cartDb
        .select({ count: sql`count(*)` })
        .from(cartSessions)
        .where(and(
          eq(cartSessions.isAbandoned, true),
          gte(cartSessions.itemCount, 1),
          gte(cartSessions.abandonedAt, sql`NOW() - INTERVAL '7 days'`)
        )),

      // Total value of abandoned carts
      cartDb
        .select({ sum: sql`COALESCE(SUM(CAST(total_value AS NUMERIC)), 0)` })
        .from(cartSessions)
        .where(and(
          eq(cartSessions.isAbandoned, true),
          gte(cartSessions.itemCount, 1)
        ))
    ]);

    return {
      totalAbandoned: totalAbandoned[0]?.count || 0,
      recentAbandoned: recentAbandoned[0]?.count || 0,
      totalValue: totalValue[0]?.sum || 0,
    };
  }

  async getAbandonedCartsByCustomer(customerId: number): Promise<CartSession[]> {
    try {
      console.log(`🛒 [DEBUG] Getting abandoned carts for customer ${customerId}`);

      // Return all carts that are already marked as abandoned (regardless of isActive status)
      const abandonedCarts = await cartDb
        .select()
        .from(cartSessions)
        .where(and(
          eq(cartSessions.customerId, customerId),
          gte(cartSessions.itemCount, 1), // Has items in cart
          eq(cartSessions.isAbandoned, true) // Already marked as abandoned
        ))
        .orderBy(desc(cartSessions.lastActivity));

      console.log(`🛒 [DEBUG] Found ${abandonedCarts.length} abandoned carts for customer ${customerId}`);

      // Also check for carts that should be marked as abandoned (1 hour threshold)
      const settings = await this.getAbandonedCartSettings();
      const thresholdHours = Math.max(settings?.timeoutMinutes ? settings.timeoutMinutes / 60 : 1, 1); // Minimum 1 hour
      const cutoffTime = new Date();
      cutoffTime.setHours(cutoffTime.getHours() - thresholdHours);

      const cartsToMark = await cartDb
        .select()
        .from(cartSessions)
        .where(and(
          eq(cartSessions.customerId, customerId),
          eq(cartSessions.isActive, true),
          gte(cartSessions.itemCount, 1), // Has items in cart
          eq(cartSessions.isAbandoned, false), // Not yet marked
          lte(cartSessions.lastActivity, cutoffTime) // Past threshold
        ));

      // Mark newly abandoned carts
      for (const cart of cartsToMark) {
        await cartDb
          .update(cartSessions)
          .set({
            isAbandoned: true,
            abandonedAt: new Date()
          })
          .where(eq(cartSessions.id, cart.id));
        console.log(`🛒 [MARKED] Cart ${cart.id} marked as abandoned`);
      }

      // Return all abandoned carts (existing + newly marked) regardless of isActive status
      const allAbandonedCarts = await cartDb
        .select()
        .from(cartSessions)
        .where(and(
          eq(cartSessions.customerId, customerId),
          gte(cartSessions.itemCount, 1),
          eq(cartSessions.isAbandoned, true)
        ))
        .orderBy(desc(cartSessions.lastActivity));

      console.log(`🛒 [RESULT] Returning ${allAbandonedCarts.length} total abandoned carts`);
      return allAbandonedCarts;
    } catch (error) {
      console.error('Error getting abandoned carts by customer:', error);
      return [];
    }
  }

  // Process abandoned cart notifications and cleanup
  async processAbandonedCartCleanup() {
    try {
      console.log('🛒 [CART CLEANUP] Starting abandoned cart processing...');

      const now = new Date();

      // Find carts that need first notification (1 hour)
      const oneHourAgo = new Date(now.getTime() - (1 * 60 * 60 * 1000));
      const cartsForFirstNotification = await cartDb
        .select()
        .from(cartSessions)
        .where(and(
          eq(cartSessions.isActive, true),
          gte(cartSessions.itemCount, 1),
          lte(cartSessions.lastActivity, oneHourAgo),
          eq(cartSessions.isAbandoned, false)
        ));

      // Find carts that need second notification (3 hours)
      const threeHoursAgo = new Date(now.getTime() - (3 * 60 * 60 * 1000));
      const cartsForSecondNotification = await cartDb
        .select()
        .from(cartSessions)
        .where(and(
          eq(cartSessions.isActive, true),
          gte(cartSessions.itemCount, 1),
          lte(cartSessions.lastActivity, threeHoursAgo),
          eq(cartSessions.isAbandoned, true)
        ));

      // Find carts to delete (48 hours)
      const fortyEightHoursAgo = new Date(now.getTime() - (48 * 60 * 60 * 1000));
      const cartsToDelete = await cartDb
        .select()
        .from(cartSessions)
        .where(and(
          eq(cartSessions.isActive, true),
          gte(cartSessions.itemCount, 1),
          lte(cartSessions.lastActivity, fortyEightHoursAgo)
        ));

      console.log(`🛒 [CART CLEANUP] Found ${cartsForFirstNotification.length} carts for first notification`);
      console.log(`🛒 [CART CLEANUP] Found ${cartsForSecondNotification.length} carts for second notification`);
      console.log(`🛒 [CART CLEANUP] Found ${cartsToDelete.length} carts to delete`);

      return {
        firstNotifications: cartsForFirstNotification.length,
        secondNotifications: cartsForSecondNotification.length,
        deletedCarts: cartsToDelete.length,
        cartsForFirstNotification,
        cartsForSecondNotification,
        cartsToDelete
      };

    } catch (error) {
      console.error('🛒 [CART CLEANUP] Error in processing:', error);
      return {
        firstNotifications: 0,
        secondNotifications: 0,
        deletedCarts: 0,
        cartsForFirstNotification: [],
        cartsForSecondNotification: [],
        cartsToDelete: []
      };
    }
  }

  // Mark cart as abandoned after first notification
  async markCartAsAbandonedWithNotification(cartId: number) {
    await cartDb
      .update(cartSessions)
      .set({
        isAbandoned: true,
        abandonedAt: new Date(),
        updatedAt: new Date()
      })
      .where(eq(cartSessions.id, cartId));
  }

  // Delete abandoned cart after 4 hours
  async getCartSessionById(cartId: number): Promise<CartSession | null> {
    try {
      const cart = await cartDb
        .select()
        .from(cartSessions)
        .where(eq(cartSessions.id, cartId))
        .limit(1);

      return cart[0] || null;
    } catch (error) {
      console.error('Error getting cart session by ID:', error);
      return null;
    }
  }

  async updateCartSession(cartId: number, updateData: Partial<CartSession>) {
    try {
      await cartDb
        .update(cartSessions)
        .set({
          ...updateData,
          updatedAt: new Date()
        })
        .where(eq(cartSessions.id, cartId));

      console.log(`🛒 [UPDATE] Cart session ${cartId} updated`);
    } catch (error) {
      console.error('Error updating cart session:', error);
      throw error;
    }
  }

  async deleteAbandonedCart(cartId: number) {
    await cartDb
      .update(cartSessions)
      .set({
        isActive: false,
        updatedAt: new Date()
      })
      .where(eq(cartSessions.id, cartId));
  }

  // =============================================================================
  // ABANDONED CART SETTINGS
  // =============================================================================

  async getAbandonedCartSettings(): Promise<AbandonedCartSettings | null> {
    const results = await cartDb
      .select()
      .from(abandonedCartSettings)
      .limit(1);

    return results[0] || null;
  }

  async updateAbandonedCartSettings(data: Partial<AbandonedCartSettings>) {
    const existing = await this.getAbandonedCartSettings();

    if (existing) {
      await cartDb
        .update(abandonedCartSettings)
        .set({
          ...data,
          updatedAt: new Date()
        })
        .where(eq(abandonedCartSettings.id, existing.id));
    } else {
      await cartDb
        .insert(abandonedCartSettings)
        .values({
          ...data,
          createdAt: new Date(),
          updatedAt: new Date()
        });
    }
  }

  // =============================================================================
  // NOTIFICATIONS
  // =============================================================================

  async createNotification(data: {
    cartSessionId: number;
    customerId: number;
    notificationType: string;
    title: string;
    message: string;
  }) {
    const [notification] = await cartDb
      .insert(abandonedCartNotifications)
      .values({
        cartSessionId: data.cartSessionId,
        customerId: data.customerId,
        notificationType: data.notificationType,
        title: data.title,
        message: data.message,
        sentAt: new Date(),
        createdAt: new Date()
      })
      .returning();

    return notification;
  }

  async getNotificationsForCart(cartSessionId: number) {
    return await cartDb
      .select()
      .from(abandonedCartNotifications)
      .where(eq(abandonedCartNotifications.cartSessionId, cartSessionId))
      .orderBy(desc(abandonedCartNotifications.sentAt));
  }

  async getCustomerNotifications(customerId: number, limit: number = 10) {
    return await cartDb
      .select()
      .from(abandonedCartNotifications)
      .where(eq(abandonedCartNotifications.customerId, customerId))
      .orderBy(desc(abandonedCartNotifications.sentAt))
      .limit(limit);
  }

  async markNotificationAsRead(notificationId: number) {
    await cartDb
      .update(abandonedCartNotifications)
      .set({
        isRead: true,
        readAt: new Date()
      })
      .where(eq(abandonedCartNotifications.id, notificationId));
  }

  async markNotificationAsClicked(notificationId: number) {
    await cartDb
      .update(abandonedCartNotifications)
      .set({
        clickedAt: new Date()
      })
      .where(eq(abandonedCartNotifications.id, notificationId));
  }

  async markNotificationAsConverted(notificationId: number, conversionValue: number) {
    await cartDb
      .update(abandonedCartNotifications)
      .set({
        converted: true,
        conversionValue: conversionValue.toString()
      })
      .where(eq(abandonedCartNotifications.id, notificationId));
  }

  // =============================================================================
  // ANALYTICS
  // =============================================================================

  async getCartRecoveryAnalytics(days: number = 30) {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    return await cartDb
      .select()
      .from(cartRecoveryAnalytics)
      .where(gte(cartRecoveryAnalytics.date, startDate))
      .orderBy(desc(cartRecoveryAnalytics.date));
  }

  async createDailyAnalytics(data: {
    totalAbandonedCarts: number;
    notificationsSent: number;
    cartsRecovered: number;
    totalRecoveredValue: number;
    averageAbandonedValue: number;
  }) {
    const recoveryRate = data.totalAbandonedCarts > 0 
      ? (data.cartsRecovered / data.totalAbandonedCarts * 100)
      : 0;

    await cartDb
      .insert(cartRecoveryAnalytics)
      .values({
        date: new Date(),
        totalAbandonedCarts: data.totalAbandonedCarts,
        notificationsSent: data.notificationsSent,
        cartsRecovered: data.cartsRecovered,
        recoveryRate: recoveryRate.toString(),
        totalRecoveredValue: data.totalRecoveredValue.toString(),
        averageAbandonedValue: data.averageAbandonedValue.toString(),
        createdAt: new Date()
      });
  }

  async getOverallStats() {
    const totalAbandonedQuery = await cartDb
      .select({
        count: sql<number>`count(*)`
      })
      .from(cartSessions)
      .where(eq(cartSessions.isAbandoned, true));

    const totalNotificationsQuery = await cartDb
      .select({
        count: sql<number>`count(*)`
      })
      .from(abandonedCartNotifications);

    const totalRecoveredQuery = await cartDb
      .select({
        count: sql<number>`count(*)`
      })
      .from(abandonedCartNotifications)
      .where(eq(abandonedCartNotifications.converted, true));

    return {
      totalAbandonedCarts: totalAbandonedQuery[0]?.count || 0,
      totalNotificationsSent: totalNotificationsQuery[0]?.count || 0,
      totalRecovered: totalRecoveredQuery[0]?.count || 0,
      overallRecoveryRate: totalAbandonedQuery[0]?.count > 0 
        ? ((totalRecoveredQuery[0]?.count || 0) / (totalAbandonedQuery[0]?.count || 1) * 100).toFixed(2)
        : "0.00"
    };
  }
}

export const cartStorage = new CartStorage();

