import { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useWebRTC } from "@/hooks/useWebRTC";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Mic, MicOff, Video, VideoOff, Monitor, MonitorOff, Phone, PhoneOff, MessageCircle, Users, Settings } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface Room {
  id: string;
  name: string;
  description?: string;
  participantCount: number;
  maxParticipants: number;
  isActive: boolean;
  createdBy: string;
  createdAt: string;
}

export default function WebRTC() {
  const [newRoomName, setNewRoomName] = useState("");
  const [newRoomDescription, setNewRoomDescription] = useState("");
  const [userName, setUserName] = useState("کاربر مهمان");
  const [userId] = useState(`user_${Date.now()}`);
  const [chatMessage, setChatMessage] = useState("");
  const [showCreateRoom, setShowCreateRoom] = useState(false);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const {
    localStream,
    remoteStreams,
    participants,
    messages,
    isConnected,
    currentRoom,
    isMuted,
    hasVideo,
    isScreenSharing,
    localVideoRef,
    joinRoom,
    leaveRoom,
    toggleAudio,
    toggleVideo,
    startScreenShare,
    stopScreenShare,
    sendMessage
  } = useWebRTC();

  // Fetch rooms
  const { data: roomsResponse, isLoading } = useQuery<{data: Room[]}>({
    queryKey: ["/api/webrtc/rooms"],
    refetchInterval: 5000 // Update every 5 seconds
  });

  const rooms = roomsResponse?.data || [];

  // Create room mutation
  const createRoomMutation = useMutation({
    mutationFn: async (roomData: { name: string; description?: string; maxParticipants: number; createdBy: string }) => {
      return await apiRequest("/api/webrtc/rooms", {
        method: "POST",
        body: JSON.stringify(roomData)
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/webrtc/rooms"] });
      setNewRoomName("");
      setNewRoomDescription("");
      setShowCreateRoom(false);
      toast({
        title: "اتاق ایجاد شد",
        description: "اتاق جدید با موفقیت ایجاد شد",
        variant: "default"
      });
    },
    onError: (error) => {
      toast({
        title: "خطا",
        description: "خطا در ایجاد اتاق",
        variant: "destructive"
      });
    }
  });

  const handleCreateRoom = () => {
    if (!newRoomName.trim()) {
      toast({
        title: "خطا",
        description: "نام اتاق الزامی است",
        variant: "destructive"
      });
      return;
    }

    createRoomMutation.mutate({
      name: newRoomName,
      description: newRoomDescription,
      maxParticipants: 10,
      createdBy: userId
    });
  };

  const handleJoinRoom = (roomId: string) => {
    joinRoom(roomId, userName, userId);
  };

  const handleLeaveRoom = () => {
    leaveRoom();
  };

  const handleSendMessage = () => {
    if (chatMessage.trim()) {
      sendMessage(chatMessage);
      setChatMessage("");
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  return (
