                              <p className="mt-2 text-sm text-gray-500">
                                {t.checkout_page.thisNumberForDelivery}
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                    )}

                    <div className="text-xs text-gray-500 mt-4">
                      {t.checkout_page.orderCodeAfterCheckout}
                    </div>
                  </div>
                </CardContent>
              )}
            </Card>

            {/* Cart Management Card */}
            <Card>
              <CardHeader 
                className="cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                onClick={() => setShowCartManagement(!showCartManagement)}
              >
                <CardTitle className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <ShoppingCart className="w-5 h-5 text-purple-600" />
                    <span className="text-purple-600">Cart Management</span>
                    <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded">NEW</span>
                  </div>
                  <span className="text-sm text-gray-500">
                    {showCartManagement ? '−' : '+'}
                  </span>
                </CardTitle>
              </CardHeader>
              {showCartManagement && (
                <CardContent className="space-y-4">
                  {/* Cart Items */}
                  <div className="space-y-3">
                    {cartItems.map((item) => (
                      <div key={item.id} className="bg-gray-50 dark:bg-gray-800 p-3 rounded-lg">
                        <div className="flex justify-between items-start mb-2">
                          <div className="flex-1">
                            <div className="flex items-center gap-2">
                              <h4 className="font-medium text-sm">{item.name}</h4>
                              {item.isFlammable && (
                                <div className="flex items-center">
                                  <Flame className="w-4 h-4 text-red-500" />
                                  <span className="text-xs text-red-600 font-medium ml-1">Flammable</span>
                                </div>
                              )}
                            </div>
                            <p className="text-xs text-gray-500 mt-1">
                              {t.checkout_page.productCode} {item.sku || 'N/A'}
                            </p>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            className="text-red-500 hover:text-red-700 h-6 w-6 p-0"
                            onClick={() => {
                              // Remove item from cart logic would go here
                              toast({
                                title: t.checkout_page.removeFromCart,
                                description: `${item.name} ${t.checkout_page.removedFromCartMsg}`,
                              });
                            }}
                          >
                            ×
                          </Button>
                        </div>
                        <div className="flex justify-between items-center text-sm">
                          <div className="flex items-center gap-2">
                            <Button
                              variant="outline"
                              size="sm"
                              className="h-6 w-6 p-0"
                              onClick={() => {
                                // Decrease quantity logic
                              }}
                            >
                              −
                            </Button>
                            <span className="min-w-[20px] text-center">{item.quantity}</span>
                            <Button
                              variant="outline"
                              size="sm"
                              className="h-6 w-6 p-0"
                              onClick={() => {
                                // Increase quantity logic
                              }}
                            >
                              +
                            </Button>
                          </div>
                          <div className="text-right">
                            <div className="text-xs text-gray-500">
                              {item.quantity} × {parseFloat(item.price).toLocaleString()} IQD
                            </div>
                            <div className="font-medium">
                              {item.totalPrice.toLocaleString()} IQD
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>



                  {/* CRM Default Address Information in Cart Management */}
                  {isUserLoggedIn && customerData?.customer && (
                    <div className={`p-2 rounded border transition-all duration-300 ${
                      (isPrimaryAddressDisabled || isPrimaryMobileDisabled) 
                        ? 'bg-gray-100 dark:bg-gray-800 border-gray-300 dark:border-gray-600 opacity-60' 
                        : 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800'
                    }`}>
                      <div className={`text-xs font-medium mb-1 flex items-center gap-1 ${
                        (isPrimaryAddressDisabled || isPrimaryMobileDisabled)
                          ? 'text-gray-600 dark:text-gray-400'
                          : 'text-blue-800 dark:text-blue-300'
                      }`}>
                        <MapPin className="w-3 h-3" />
                        {(isPrimaryAddressDisabled || isPrimaryMobileDisabled) 
                          ? t.checkout_page.defaultAddressInactive 
                          : t.checkout_page.defaultAddressCRM}
                      </div>
                      <div className={`space-y-1 text-xs ${
                        (isPrimaryAddressDisabled || isPrimaryMobileDisabled)
                          ? 'text-gray-500 dark:text-gray-500'
                          : 'text-blue-700 dark:text-blue-400'
                      }`}>
                        <div className="flex justify-between">
                          <span>{t.checkout_page.provinceField}</span>
                          <span className="font-medium">{customerData.customer.province || customerData.customer.state || t.checkout_page.unknown}</span>
                        </div>
                        <div className="flex justify-between">
                          <span>{t.checkout_page.cityField}</span>
                          <span className="font-medium">{customerData.customer.city || t.checkout_page.unknown}</span>
                        </div>
                        <div className="flex justify-between">
                          <span>{t.checkout_page.phoneField}</span>
                          <span className="font-medium">{customerData.customer.phone || t.checkout_page.unknown}</span>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Second Delivery Address Section in Cart Management */}
                  {isUserLoggedIn && (
                    <div className="space-y-3 pt-3 border-t">
                      <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300">{t.checkout_page.secondAddressTitle}</h4>

                      {/* Second Address Option */}
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <span className="text-xs font-medium text-gray-700 dark:text-gray-300">{t.checkout_page.secondAddressOptional}</span>
                          <Button
                            type="button"
                            size="sm"
                            variant="ghost"
                            onClick={() => setShowSecondAddress(!showSecondAddress)}
                            className="text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-200 h-5 w-5 p-0"
                          >
                            {showSecondAddress ? '−' : '+'}
                          </Button>
                        </div>

                        {showSecondAddress && (
                          <div className="bg-white dark:bg-gray-700 p-2 rounded border text-xs space-y-2">
                            <FormField
                              control={form.control}
                              name="secondDeliveryAddress"
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel className="text-xs">{t.checkout_page.fullAddressLabel}</FormLabel>
                                  <FormControl>
                                    <Textarea
                                      {...field}
                                      placeholder={t.checkout_page.secondAddressDeliveryPlaceholder}
                                      className="min-h-[50px] text-xs"
                                    />
                                  </FormControl>
                                </FormItem>
                              )}
                            />
                            <div className="grid grid-cols-3 gap-1">
                              <FormField
                                control={form.control}
                                name="secondDeliveryProvince"
                                render={({ field }) => (
                                  <FormItem>
                                    <FormLabel className="text-xs">{t.checkout_page.provinceLabel}</FormLabel>
                                    <Select 
                                      onValueChange={(value) => {
                                        field.onChange(value);
                                        // Find province ID and set it for city filtering
                                        const selectedProvince = provinces.find((p: any) => p.nameEnglish === value || p.name === value);
                                        if (selectedProvince) {
                                          setSelectedSecondaryProvinceId(selectedProvince.id);
                                          // Clear city selection when province changes
                                          form.setValue("secondDeliveryCity", "");
                                        }
                                      }} 
                                      value={field.value}
                                    >
                                      <FormControl>
                                        <SelectTrigger className="text-xs h-7">
                                          <SelectValue placeholder={t.checkout_page.selectProvincePlaceholder} />
                                        </SelectTrigger>
                                      </FormControl>
                                      <SelectContent>
                                        {Array.isArray(provinces) && provinces.map((province: any) => (
                                          <SelectItem key={province.id} value={province.nameEnglish || province.name}>
                                            {province.nameEnglish} / {province.name}
                                          </SelectItem>
                                        ))}
                                      </SelectContent>
                                    </Select>
                                  </FormItem>
                                )}
                              />
                              <FormField
                                control={form.control}
                                name="secondDeliveryCity"
                                render={({ field }) => (
                                  <FormItem>
                                    <FormLabel className="text-xs">{t.checkout_page.citySelectLabel}</FormLabel>
                                    <Select 
                                      onValueChange={field.onChange} 
                                      value={field.value}
                                      disabled={!selectedSecondaryProvinceId}
                                    >
                                      <FormControl>
                                        <SelectTrigger className="text-xs h-7">
                                          <SelectValue placeholder={selectedSecondaryProvinceId ? t.checkout_page.selectCityPlaceholder : t.checkout_page.selectProvinceFirst} />
                                        </SelectTrigger>
                                      </FormControl>
                                      <SelectContent>
                                        {Array.isArray(secondaryCities) && secondaryCities.map((city: any) => (
                                          <SelectItem key={city.id} value={city.nameEnglish || city.name}>
                                            {city.nameEnglish} / {city.nameArabic || city.name}
                                          </SelectItem>
                                        ))}
                                      </SelectContent>
                                    </Select>
                                  </FormItem>
                                )}
                              />
                              <FormField
                                control={form.control}
                                name="secondDeliveryPostalCode"
                                render={({ field }) => (
                                  <FormItem>
                                    <FormLabel className="text-xs">{t.checkout_page.postalCodeLabel}</FormLabel>
                                    <FormControl>
                                      <Input {...field} placeholder="12345" className="text-xs h-7" />
                                    </FormControl>
                                  </FormItem>
                                )}
                              />
                            </div>
                          </div>
                        )}
                      </div>

                      {/* Recipient Mobile */}
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <span className="text-xs font-medium text-gray-700 dark:text-gray-300">{t.checkout_page.differentMobileNumberLabel}</span>
                          <Button
                            type="button"
                            size="sm"
                            variant="ghost"
                            onClick={() => setShowRecipientMobile(!showRecipientMobile)}
                            className="text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-200 h-5 w-5 p-0"
                          >
                            {showRecipientMobile ? '−' : '+'}
                          </Button>
                        </div>

                        {showRecipientMobile && (
                          <div className="bg-white dark:bg-gray-700 p-2 rounded border">
                            <FormField
                              control={form.control}
                              name="recipientMobile"
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel className="text-xs">{t.checkout_page.recipientMobileLabel}</FormLabel>
                                  <FormControl>
                                    <Input
                                      {...field}
                                      placeholder="09123456789"
                                      className="text-xs h-7"
                                      type="tel"
                                    />
                                  </FormControl>
                                </FormItem>
                              )}
                            />
                            <p className="mt-1 text-xs text-gray-500">
                              {t.checkout_page.thisNumberForDelivery}
                            </p>
                          </div>
                        )}
                      </div>
                    </div>
                  )}

                  {/* Cart Actions */}
                  <div className="space-y-2 pt-3 border-t">
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full text-xs"
                      onClick={() => setLocation("/shop")}
                    >
                      {t.checkout_page.continueShoppingBtn}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full text-xs text-red-600 hover:text-red-700"
                      onClick={() => {
                        // Clear cart logic
                        toast({
                          title: t.checkout_page.cartClearedTitle,
                          description: t.checkout_page.allProductsRemoved,
                        });
                      }}
                    >
                      {t.checkout_page.clearCartBtn}
                    </Button>
                  </div>
                </CardContent>
              )}
            </Card>

            {/* Payment Summary */}
            <Card>
              <CardHeader>
                <CardTitle>{t.checkout_page.paymentSummaryTitle}</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <span>{t.checkout_page.itemsTotal}</span>
                    <span>{subtotal.toLocaleString()} IQD</span>
                  </div>
                  <div className="flex justify-between">
                    <span>{t.checkout_page.shippingCostSummary}</span>
                    <span>{shippingCost === 0 ? t.checkout_page.free : `${shippingCost.toLocaleString()} ${t.checkout_page.iqd}`}</span>
                  </div>
                  {vatAmount > 0 && (
                    <div className="flex justify-between">
                      <span>{t.checkout_page.valueAddedTax} ({(vatRate * 100).toFixed(0)}%):</span>
                      <span>{vatAmount.toLocaleString()} IQD</span>
                    </div>
                  )}
                  {dutiesAmount > 0 && (
                    <div className="flex justify-between">
                      <span>{t.checkout_page.valueAddedDuty} ({(dutiesRate * 100).toFixed(0)}%):</span>
                      <span>{dutiesAmount.toLocaleString()} IQD</span>
                    </div>
                  )}
                  <Separator />
                  {actualWalletUsage > 0 && (
                    <div className="flex justify-between text-green-600">
                      <span>{t.checkout_page.walletUsedSummary}</span>
                      <span>-{actualWalletUsage.toLocaleString()} IQD</span>
                    </div>
                  )}
                  <div className="flex justify-between text-lg font-bold">
                    <span>{t.checkout_page.totalPayable}</span>
                    <span>{totalAmount.toLocaleString()} IQD</span>
                  </div>
                </div>

                {shippingCost === 0 && (
                  <div className="bg-green-50 dark:bg-green-900/20 p-3 rounded-lg border border-green-200 dark:border-green-800">
                    <p className="text-sm text-green-800 dark:text-green-300">
                      {t.checkout_page.freeShippingEligible}
                    </p>
                  </div>
                )}

                {actualWalletUsage >= beforeWalletTotal && (
                  <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg border border-blue-200 dark:border-blue-800">
                    <p className="text-sm text-blue-800 dark:text-blue-300">
                      {t.checkout_page.fullyPaidByWallet}
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </div>
      </div>

      {/* Auth Modal */}
      <AuthModal 
        isOpen={authModalOpen}
        onClose={() => setAuthModalOpen(false)}
        onAuthSuccess={async () => {
          setAuthModalOpen(false);
          // Refetch customer data to update authentication status
          await refetchCustomer();
          setIsLoggedIn(true);
          // Force form to re-validate with new authentication status
          form.trigger();
          // Show success message
          toast({
            title: t.loginSuccessful,
            description: t.welcomeMessage,
          });
        }}
        initialMode={authMode}
      />
    </div>
  );
}

server/whatsapp-service.ts.content:
import https from 'https';
import http from 'http';

interface WhatsAppSettings {
  isEnabled: boolean;
  provider: string;
  apiKey?: string;
  apiSecret?: string;
  instanceId?: string;
  accessToken?: string;
  apiEndpoint?: string;
  webhookUrl?: string;
}

interface WhatsAppMessage {
  to: string;
  message: string;
  messageType?: 'text' | 'template';
  templateName?: string;
  variables?: Record<string, string>;
}

export class WhatsAppService {
  private settings: WhatsAppSettings;

  constructor(settings?: WhatsAppSettings) {
    this.settings = settings || {
      isEnabled: true,
      provider: 'whatsapp_business_api', // Default provider
      apiEndpoint: 'https://graph.facebook.com/v18.0'
    };
  }

  async sendMessage(message: WhatsAppMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    if (!this.settings.isEnabled) {
      return { success: false, error: 'WhatsApp service is disabled' };
    }

    try {
      switch (this.settings.provider) {
        case 'whatsapp_business_api':
          return await this.sendWhatsAppBusinessMessage(message);
        case 'twilio_whatsapp':
          return await this.sendTwilioWhatsAppMessage(message);
        case 'green_api':
          return await this.sendGreenApiMessage(message);
        case 'ultramsg':
          return await this.sendUltraMsgMessage(message);
        default:
          return { success: false, error: 'Unsupported WhatsApp provider' };
      }
    } catch (error: any) {
      console.error('WhatsApp sending error:', error);
      return { success: false, error: error.message || 'Unknown error' };
    }
  }

  private async sendWhatsAppBusinessMessage(message: WhatsAppMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    return new Promise((resolve) => {
      const phoneNumber = this.formatPhoneNumber(message.to);

      const postData = JSON.stringify({
        messaging_product: 'whatsapp',
        to: phoneNumber,
        type: 'text',
        text: {
          body: message.message
        }
      });

      const options = {
        hostname: 'graph.facebook.com',
        port: 443,
        path: `/v18.0/${this.settings.instanceId}/messages`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.settings.accessToken}`,
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });
        res.on('end', () => {
          try {
            const response = JSON.parse(data);
            if (res.statusCode === 200 && response.messages) {
              console.log('✅ [WHATSAPP] Message sent successfully:', response.messages[0]?.id);
              resolve({ success: true, messageId: response.messages[0]?.id });
            } else {
              console.error('❌ [WHATSAPP] Failed to send message:', response);
              resolve({ success: false, error: response.error?.message || 'Failed to send WhatsApp message' });
            }
          } catch (parseError) {
            console.error('❌ [WHATSAPP] Error parsing response:', parseError);
            resolve({ success: false, error: 'Invalid response from WhatsApp API' });
          }
        });
      });

      req.on('error', (error) => {
        console.error('❌ [WHATSAPP] Request error:', error);
        resolve({ success: false, error: error.message });
      });

      req.write(postData);
      req.end();
    });
  }

  private async sendTwilioWhatsAppMessage(message: WhatsAppMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    return new Promise((resolve) => {
      const phoneNumber = this.formatPhoneNumber(message.to);

      const postData = new URLSearchParams({
        From: 'whatsapp:+14155238886', // Twilio WhatsApp sandbox number
        To: `whatsapp:${phoneNumber}`,
        Body: message.message
      }).toString();

      const auth = Buffer.from(`${this.settings.apiKey}:${this.settings.apiSecret}`).toString('base64');

      const options = {
        hostname: 'api.twilio.com',
        port: 443,
        path: `/2010-04-01/Accounts/${this.settings.apiKey}/Messages.json`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Authorization': `Basic ${auth}`,
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });
        res.on('end', () => {
          try {
            const response = JSON.parse(data);
            if (res.statusCode === 201) {
              console.log('✅ [WHATSAPP-TWILIO] Message sent successfully:', response.sid);
              resolve({ success: true, messageId: response.sid });
            } else {
              console.error('❌ [WHATSAPP-TWILIO] Failed to send message:', response);
              resolve({ success: false, error: response.message || 'Failed to send WhatsApp message via Twilio' });
            }
          } catch (parseError) {
            console.error('❌ [WHATSAPP-TWILIO] Error parsing response:', parseError);
            resolve({ success: false, error: 'Invalid response from Twilio WhatsApp API' });
          }
        });
      });

      req.on('error', (error) => {
        console.error('❌ [WHATSAPP-TWILIO] Request error:', error);
        resolve({ success: false, error: error.message });
      });

      req.write(postData);
      req.end();
    });
  }

  private async sendGreenApiMessage(message: WhatsAppMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    return new Promise((resolve) => {
      const phoneNumber = this.formatPhoneNumber(message.to, false);

      const postData = JSON.stringify({
        chatId: `${phoneNumber}@c.us`,
        message: message.message
      });

      const options = {
        hostname: 'api.green-api.com',
        port: 443,
        path: `/waInstance${this.settings.instanceId}/sendMessage/${this.settings.accessToken}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });
        res.on('end', () => {
          try {
            const response = JSON.parse(data);
            if (res.statusCode === 200 && response.idMessage) {
              console.log('✅ [WHATSAPP-GREEN] Message sent successfully:', response.idMessage);
              resolve({ success: true, messageId: response.idMessage });
            } else {
              console.error('❌ [WHATSAPP-GREEN] Failed to send message:', response);
              resolve({ success: false, error: response.error?.message || 'Failed to send WhatsApp message via Green API' });
            }
          } catch (parseError) {
            console.error('❌ [WHATSAPP-GREEN] Error parsing response:', parseError);
            resolve({ success: false, error: 'Invalid response from Green API' });
          }
        });
      });

      req.on('error', (error) => {
        console.error('❌ [WHATSAPP-GREEN] Request error:', error);
        resolve({ success: false, error: error.message });
      });

      req.write(postData);
      req.end();
    });
  }

  private async sendUltraMsgMessage(message: WhatsAppMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    return new Promise((resolve) => {
      const phoneNumber = this.formatPhoneNumber(message.to, false);

      const postData = new URLSearchParams({
        token: this.settings.accessToken || '',
        to: phoneNumber,
        body: message.message
      }).toString();

      const options = {
        hostname: 'api.ultramsg.com',
        port: 443,
        path: `/${this.settings.instanceId}/messages/chat`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });
        res.on('end', () => {
          try {
            const response = JSON.parse(data);
            if (res.statusCode === 200 && response.sent) {
              console.log('✅ [WHATSAPP-ULTRA] Message sent successfully:', response.id);
              resolve({ success: true, messageId: response.id });
            } else {
              console.error('❌ [WHATSAPP-ULTRA] Failed to send message:', response);
              resolve({ success: false, error: response.error || 'Failed to send WhatsApp message via UltraMsg' });
            }
          } catch (parseError) {
            console.error('❌ [WHATSAPP-ULTRA] Error parsing response:', parseError);
            resolve({ success: false, error: 'Invalid response from UltraMsg API' });
          }
        });
      });

      req.on('error', (error) => {
        console.error('❌ [WHATSAPP-ULTRA] Request error:', error);
        resolve({ success: false, error: error.message });
      });

      req.write(postData);
      req.end();
    });
  }

  private formatPhoneNumber(phoneNumber: string, includeCountryCode: boolean = true): string {
    // Remove all non-digit characters
    let cleaned = phoneNumber.replace(/\D/g, '');

    // Handle Iraqi numbers
    if (cleaned.startsWith('964')) {
      return includeCountryCode ? cleaned : cleaned.substring(3);
    } else if (cleaned.startsWith('07')) {
      return includeCountryCode ? `964${cleaned.substring(1)}` : cleaned.substring(1);
    } else if (cleaned.startsWith('7')) {
      return includeCountryCode ? `964${cleaned}` : cleaned;
    }

    // For other international numbers
    if (cleaned.length >= 10 && !cleaned.startsWith('964')) {
      return includeCountryCode ? cleaned : cleaned;
    }

    return includeCountryCode ? cleaned : cleaned;
  }

  // Method to create WhatsApp service instance from environment or database
  static async createService(): Promise<WhatsAppService> {
    // You can later implement database loading for WhatsApp settings
    // For now, use environment variables
    const settings: WhatsAppSettings = {
      isEnabled: process.env.WHATSAPP_ENABLED === 'true',
      provider: process.env.WHATSAPP_PROVIDER || 'whatsapp_business_api',
      apiKey: process.env.WHATSAPP_API_KEY,
      apiSecret: process.env.WHATSAPP_API_SECRET,
      instanceId: process.env.WHATSAPP_INSTANCE_ID,
      accessToken: process.env.WHATSAPP_ACCESS_TOKEN,
      apiEndpoint: process.env.WHATSAPP_API_ENDPOINT || 'https://graph.facebook.com/v18.0',
      webhookUrl: process.env.WHATSAPP_WEBHOOK_URL
    };

    return new WhatsAppService(settings);
  }

  // Helper method to send authentication codes
  async sendAuthenticationCode(phoneNumber: string, code: string, customerName?: string): Promise<{ success: boolean; messageId?: string; error?: string }> {
    const message = customerName 
      ? `${customerName} عزیز، کد تایید شما: ${code}\nاین کد در ۵ دقیقه منقضی می‌شود.\nممتازکم`
      : `کد تایید شما: ${code}\nاین کد در ۵ دقیقه منقضی می‌شود.\nممتازکم`;

    return this.sendMessage({
      to: phoneNumber,
      message: message,
      messageType: 'text'
    });
  }

  // Helper method to send delivery codes
  async sendDeliveryCode(phoneNumber: string, code: string, customerName?: string, orderNumber?: string): Promise<{ success: boolean; messageId?: string; error?: string }> {
    const message = customerName 
      ? `${customerName} عزیز، سفارش ${orderNumber || 'شما'} در راه است.\nکد تحویل: ${code}\nاین کد را هنگام تحویل به پیک اعلام کنید.\nممتازکم`
      : `سفارش ${orderNumber || 'شما'} در راه است.\nکد تحویل: ${code}\nاین کد را هنگام تحویل به پیک اعلام کنید.\nممتازکم`;

    return this.sendMessage({
      to: phoneNumber,
      message: message,
      messageType: 'text'
    });
  }

  // Helper method to send password reset links
  async sendPasswordResetLink(phoneNumber: string, resetLink: string, customerName?: string): Promise<{ success: boolean; messageId?: string; error?: string }> {
    const message = customerName 
      ? `${customerName} عزیز، برای بازیابی رمز عبور خود روی لینک زیر کلیک کنید:\n${resetLink}\nاین لینک در ۱ ساعت منقضی می‌شود.\nممتازکم`
      : `برای بازیابی رمز عبور خود روی لینک زیر کلیک کنید:\n${resetLink}\nاین لینک در ۱ ساعت منقضی می‌شود.\nممتازکم`;

    return this.sendMessage({
      to: phoneNumber,
      message: message,
      messageType: 'text'
    });
  }
}

// Export function to create WhatsApp service
export async function createWhatsAppService(): Promise<WhatsAppService> {
  return WhatsAppService.createService();
}

