          </CardContent>
        </Card>
      </div>

      {/* Template Distribution Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
        {Object.entries(TEMPLATE_DISTRIBUTION).map(([categoryName, category]) => {
