            راهنمای یکپارچه‌سازی
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <h4 className="font-semibold text-indigo-700">✅ مزایای توزیع قالب‌ها:</h4>
              <ul className="text-sm text-indigo-600 space-y-1">
                <li>• دسترسی آسان قالب‌ها در بخش مرتبط</li>
                <li>• کاهش پیچیدگی مدیریت</li>
                <li>• سازماندهی بهتر ایمیل‌ها</li>
                <li>• افزایش کارایی تیم‌ها</li>
              </ul>
            </div>
            <div className="space-y-2">
              <h4 className="font-semibold text-indigo-700">🔧 نحوه استفاده:</h4>
              <ul className="text-sm text-indigo-600 space-y-1">
                <li>• روی دکمه "مشاهده در..." کلیک کنید</li>
                <li>• قالب مورد نظر را انتخاب کنید</li>
                <li>• متغیرها را شخصی‌سازی کنید</li>
                <li>• ایمیل را ارسال کنید</li>
              </ul>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/sales-analytics.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import { useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  LineChart, Line, PieChart, Pie, Cell, Area, AreaChart
} from "recharts";
import { 
  DollarSign, ShoppingCart, TrendingUp, Package, Users, 
  Calendar, ArrowUp, ArrowDown, Target, Activity, ArrowLeft
} from "lucide-react";
import { format, subDays, parseISO } from "date-fns";

interface SalesData {
  totalRevenue: number;
  totalOrders: number;
  averageOrderValue: number;
  totalCustomers: number;
  conversionRate: number;
  growthRate: number;
  dailySales: Array<{
    date: string;
    revenue: number;
    orders: number;
  }>;
  topProducts: Array<{
    name: string;
    revenue: number;
    quantity: number;
    orders: number;
  }>;
  ordersByStatus: Array<{
    status: string;
    count: number;
    percentage: number;
  }>;
  revenueByCategory: Array<{
    category: string;
    revenue: number;
    percentage: number;
  }>;
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8'];

export default function SalesAnalytics() {
  const [, setLocation] = useLocation();
  const { user, isAuthenticated, isLoading: authLoading } = useAuth();

  // Authentication check
  useEffect(() => {
    if (!authLoading && !isAuthenticated) {
      setLocation("/admin/login");
    }
  }, [authLoading, isAuthenticated, setLocation]);

  const { data: salesData, isLoading, error } = useQuery<SalesData>({
    queryKey: ["/api/analytics/sales"],
    enabled: isAuthenticated,
    retry: false,
  });

  if (authLoading) {
    return (
      <div className="h-screen flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-4 border-primary border-t-transparent rounded-full" />
      </div>
    );
  }

  if (!isAuthenticated) {
    return null;
  }

  if (isLoading) {
    return (
      <div className="h-screen flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-4 border-primary border-t-transparent rounded-full" />
      </div>
    );
  }

  if (error || !salesData) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Sales Analytics</h1>
            <p className="text-gray-600 dark:text-gray-400 mt-2">
              Comprehensive sales performance dashboard
            </p>
          </div>
          <Button variant="outline" onClick={() => setLocation("/admin")}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Admin
          </Button>
        </div>
        <div className="text-center">
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-4">
            {error ? "Error Loading Analytics" : "No Sales Data Available"}
          </h2>
          <p className="text-gray-600 dark:text-gray-400">
            {error ? "Failed to load sales analytics. Please try again." : "Start making sales to see analytics data here."}
          </p>
        </div>
      </div>
    );
  }

  const formatCurrency = (amount: number, currency: string = 'IQD') => {
    const validCurrencies = ['USD', 'EUR', 'IQD'];
    const currencyCode = validCurrencies.includes(currency) ? currency : 'IQD';

    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currencyCode
    }).format(amount);
  };

  const StatCard = ({ title, value, icon: Icon, trend, trendValue }: {
    title: string;
    value: string | number;
    icon: any;
    trend?: "up" | "down";
    trendValue?: string;
  }) => (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-400">
          {title}
        </CardTitle>
        <Icon className="h-4 w-4 text-blue-600" />
      </CardHeader>
      <CardContent>
        <div className="text-2xl font-bold text-gray-900 dark:text-white">{value}</div>
        {trend && trendValue && (
          <div className={`flex items-center text-xs ${
            trend === "up" ? "text-green-600" : "text-red-600"
          }`}>
            {trend === "up" ? <ArrowUp className="w-3 h-3 mr-1" /> : <ArrowDown className="w-3 h-3 mr-1" />}
            {trendValue}
          </div>
        )}
      </CardContent>
    </Card>
  );

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Sales Analytics</h1>
          <p className="text-gray-600 dark:text-gray-400 mt-2">
            Comprehensive sales performance dashboard
          </p>
        </div>
        {user?.id === 1 && (
          <Button variant="outline" onClick={() => setLocation("/admin")}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Admin
          </Button>
        )}
      </div>

      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <StatCard
          title="Total Revenue"
          value={formatCurrency(salesData.totalRevenue)}
          icon={DollarSign}
          trend="up"
          trendValue={`+${salesData.growthRate.toFixed(1)}%`}
        />
        <StatCard
          title="Total Orders"
          value={salesData.totalOrders}
          icon={ShoppingCart}
        />
        <StatCard
          title="Average Order Value"
          value={formatCurrency(salesData.averageOrderValue)}
          icon={TrendingUp}
        />
        <StatCard
          title="Total Customers"
          value={salesData.totalCustomers}
          icon={Users}
        />
      </div>

      <Tabs defaultValue="overview" className="space-y-6">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="products">Products</TabsTrigger>
          <TabsTrigger value="orders">Orders</TabsTrigger>
          <TabsTrigger value="trends">Trends</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Revenue Trend */}
            <Card>
              <CardHeader>
                <CardTitle>Revenue Trend (Last 30 Days)</CardTitle>
                <CardDescription>Daily revenue performance</CardDescription>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <AreaChart data={salesData.dailySales}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis 
                      dataKey="date" 
                      tick={{ fontSize: 12 }}
                      tickFormatter={(value) => format(parseISO(value), 'MMM dd')}
                    />
                    <YAxis tick={{ fontSize: 12 }} />
                    <Tooltip 
                      formatter={(value, name) => [formatCurrency(Number(value)), 'Revenue']}
                      labelFormatter={(value) => format(parseISO(value), 'MMM dd, yyyy')}
                    />
                    <Area 
                      type="monotone" 
                      dataKey="revenue" 
                      stroke="#0088FE" 
                      fill="#0088FE" 
                      fillOpacity={0.6}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>

            {/* Order Status Distribution */}
            <Card>
              <CardHeader>
                <CardTitle>Order Status Distribution</CardTitle>
                <CardDescription>Current order status breakdown</CardDescription>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <PieChart>
                    <Pie
                      data={salesData.ordersByStatus}
                      cx="50%"
                      cy="50%"
                      outerRadius={80}
                      fill="#8884d8"
                      dataKey="count"
                    >
                      {salesData.ordersByStatus.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                    <Legend />
                  </PieChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </div>

          {/* Revenue by Category */}
          <Card>
            <CardHeader>
              <CardTitle>Revenue by Category</CardTitle>
              <CardDescription>Sales performance across product categories</CardDescription>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={salesData.revenueByCategory}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="category" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip formatter={(value) => [formatCurrency(Number(value)), 'Revenue']} />
                  <Bar dataKey="revenue" fill="#00C49F" />
                </BarChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="products" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Top Performing Products</CardTitle>
              <CardDescription>Best selling products by revenue and quantity</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {salesData.topProducts.map((product, index) => (
                  <div key={product.name} className="flex items-center justify-between p-4 border rounded-lg">
                    <div className="flex items-center space-x-3">
                      <div className="flex items-center justify-center w-8 h-8 bg-blue-100 dark:bg-blue-900 rounded-full">
                        <span className="text-sm font-bold text-blue-600 dark:text-blue-400">
                          {index + 1}
                        </span>
                      </div>
                      <div>
                        <h3 className="font-medium text-gray-900 dark:text-white">{product.name}</h3>
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                          {product.quantity} units sold in {product.orders} orders
                        </p>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="font-bold text-gray-900 dark:text-white">
                        {formatCurrency(product.revenue)}
                      </div>
                      <div className="text-sm text-gray-600 dark:text-gray-400">
                        ${(product.revenue / product.quantity).toFixed(2)} avg
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="orders" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <Card>
              <CardHeader>
                <CardTitle>Order Metrics</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex justify-between">
                  <span className="text-gray-600 dark:text-gray-400">Total Orders</span>
                  <span className="font-bold">{salesData.totalOrders}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600 dark:text-gray-400">Average Order Value</span>
                  <span className="font-bold">{formatCurrency(salesData.averageOrderValue)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600 dark:text-gray-400">Conversion Rate</span>
                  <span className="font-bold">{salesData.conversionRate.toFixed(2)}%</span>
                </div>
              </CardContent>
            </Card>

            <Card className="md:col-span-2">
              <CardHeader>
                <CardTitle>Daily Orders</CardTitle>
                <CardDescription>Order volume over time</CardDescription>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={200}>
                  <LineChart data={salesData.dailySales}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis 
                      dataKey="date" 
                      tick={{ fontSize: 12 }}
                      tickFormatter={(value) => format(parseISO(value), 'MMM dd')}
                    />
                    <YAxis tick={{ fontSize: 12 }} />
                    <Tooltip 
                      formatter={(value, name) => [value, 'Orders']}
                      labelFormatter={(value) => format(parseISO(value), 'MMM dd, yyyy')}
                    />
                    <Line 
                      type="monotone" 
                      dataKey="orders" 
                      stroke="#FF8042" 
                      strokeWidth={2}
                    />
                  </LineChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="trends" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Sales Trends Analysis</CardTitle>
              <CardDescription>Revenue and order trends comparison</CardDescription>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={400}>
                <LineChart data={salesData.dailySales}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis 
                    dataKey="date" 
                    tick={{ fontSize: 12 }}
                    tickFormatter={(value) => format(parseISO(value), 'MMM dd')}
                  />
                  <YAxis yAxisId="left" tick={{ fontSize: 12 }} />
                  <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 12 }} />
                  <Tooltip 
                    formatter={(value, name) => [
                      name === 'revenue' ? formatCurrency(Number(value)) : value,
                      name === 'revenue' ? 'Revenue' : 'Orders'
                    ]}
                    labelFormatter={(value) => format(parseISO(value), 'MMM dd, yyyy')}
                  />
                  <Line 
                    yAxisId="left"
                    type="monotone" 
                    dataKey="revenue" 
                    stroke="#0088FE" 
                    strokeWidth={2}
                    name="revenue"
                  />
                  <Line 
                    yAxisId="right"
                    type="monotone" 
                    dataKey="orders" 
                    stroke="#FF8042" 
                    strokeWidth={2}
                    name="orders"
                  />
                </LineChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

client/src/pages/detailed-inventory.tsx.content:
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { apiRequest } from '@/lib/queryClient';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { 
  Package, 
  Hash, 
  Calendar, 
  FileText, 
  Search,
  Eye,
  RefreshCw
} from 'lucide-react';

interface BatchDetails {
  batchNumber: string;
  stock: number;
  createdAt: Date;
  isActive: boolean;
  notes?: string;
}

interface ProductInventory {
  productName: string;
  barcode: string;
  totalStock: number;
  currentSellingBatch: string;
  batches: BatchDetails[];
}

export default function DetailedInventory() {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedBarcode, setSelectedBarcode] = useState<string | null>(null);

  // Fetch detailed inventory with batch information
  const { data: inventoryData, isLoading, refetch } = useQuery({
    queryKey: ['/api/inventory/detailed-with-batches'],
    queryFn: async () => {
      const response = await apiRequest('/api/inventory/detailed-with-batches');
      return response.data || [];
    },
    refetchInterval: 30000, // Auto-refresh every 30 seconds
  });

  // Fetch specific product batch details
  const { data: productBatchData, isLoading: productBatchLoading } = useQuery({
    queryKey: ['/api/inventory/product-batch-details', selectedBarcode],
    queryFn: async () => {
      if (!selectedBarcode) return null;
      const response = await apiRequest(`/api/inventory/product-batch-details/${selectedBarcode}`);
      return response.data || null;
    },
    enabled: !!selectedBarcode,
  });

  // Filter inventory based on search term
  const filteredInventory = inventoryData?.filter((item: ProductInventory) =>
    item.productName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.barcode.includes(searchTerm)
  ) || [];

  const formatDate = (dateString: string | Date) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('fa-IR', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <Card>
          <CardContent className="text-center p-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p>در حال بارگذاری اطلاعات موجودی...</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8" dir="rtl">
      {/* Header */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Package className="w-6 h-6" />
            موجودی انبار با جزئیات بچ
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4 items-end">
            <div className="flex-1">
              <Label htmlFor="search">جستجو در محصولات</Label>
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <Input
                  id="search"
                  placeholder="نام محصول یا بارکد..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
            <Button onClick={() => refetch()} variant="outline">
              <RefreshCw className="w-4 h-4 mr-2" />
              بروزرسانی
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Statistics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <Card>
          <CardContent className="p-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-600">
                {filteredInventory.length}
              </div>
              <div className="text-sm text-gray-600">کل محصولات</div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-green-600">
                {filteredInventory.reduce((sum, item) => sum + item.totalStock, 0)}
              </div>
              <div className="text-sm text-gray-600">کل موجودی</div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-orange-600">
                {filteredInventory.reduce((sum, item) => sum + item.batches.length, 0)}
              </div>
              <div className="text-sm text-gray-600">کل بچ‌ها</div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Products Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {filteredInventory.map((item: ProductInventory) => (
          <Card key={item.barcode} className="hover:shadow-lg transition-shadow">
            <CardHeader className="pb-3">
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <CardTitle className="text-lg">{item.productName}</CardTitle>
                  <div className="flex items-center gap-2 mt-1">
                    <Hash className="w-4 h-4 text-gray-500" />
                    <span className="text-sm text-gray-600">{item.barcode}</span>
                  </div>
                </div>
                <Badge variant="secondary" className="text-lg px-3 py-1">
                  {item.totalStock} واحد
                </Badge>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {/* Current Selling Batch (LIFO) */}
                <div className="bg-green-50 border border-green-200 rounded-lg p-3">
                  <div className="flex justify-between items-center">
                    <span className="text-sm font-medium text-green-700">بچ فعال (در حال فروش):</span>
                    <Badge variant="default" className="bg-green-600 text-white">
                      {item.currentSellingBatch}
                    </Badge>
                  </div>
                  <div className="text-xs text-green-600 mt-1">
                    سیستم FIFO - قدیمی‌ترین بچ برای فروش
                  </div>
                </div>

                <div className="flex justify-between items-center">
                  <span className="text-sm font-medium">همه بچ‌ها ({item.batches.length}):</span>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => setSelectedBarcode(item.barcode)}
                  >
                    <Eye className="w-4 h-4 mr-2" />
                    مشاهده جزئیات
                  </Button>
                </div>

                <div className="space-y-2">
                  {item.batches.slice(0, 3).map((batch, index) => (
                    <div key={index} className={`flex justify-between items-center p-2 rounded ${
                      batch.isActive ? 'bg-green-100 border border-green-300' : 'bg-gray-50'
                    }`}>
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-medium">بچ {batch.batchNumber}</span>
                        <Badge variant={batch.isActive ? "default" : "outline"} 
                               className={`text-xs ${batch.isActive ? 'bg-green-600 text-white' : ''}`}>
                          {batch.stock} واحد
                        </Badge>
                        {batch.isActive && (
                          <Badge variant="secondary" className="text-xs bg-yellow-100 text-yellow-800">
                            فعال
                          </Badge>
                        )}
                      </div>
                      <span className="text-xs text-gray-500">
                        {formatDate(batch.createdAt)}
                      </span>
                    </div>
                  ))}

                  {item.batches.length > 3 && (
                    <div className="text-center text-sm text-gray-500">
                      و {item.batches.length - 3} بچ دیگر...
                    </div>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Product Batch Details Modal */}
      {selectedBarcode && (
        <Card className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-semibold">جزئیات بچ محصول</h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setSelectedBarcode(null)}
              >
                ✕
              </Button>
            </div>

            {productBatchLoading ? (
              <div className="text-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-2"></div>
                <p className="text-sm text-gray-600">در حال بارگذاری...</p>
              </div>
            ) : productBatchData ? (
              <div className="space-y-4">
                <div className="bg-blue-50 p-4 rounded-lg">
                  <h4 className="font-semibold text-blue-800">{productBatchData.productName}</h4>
                  <p className="text-sm text-blue-600">بارکد: {productBatchData.barcode}</p>
                  <p className="text-sm text-blue-600">کل موجودی: {productBatchData.totalStock} واحد</p>
                </div>

                <Separator />

                <div className="space-y-3">
                  <h5 className="font-medium">تمام بچ‌ها:</h5>
                  {productBatchData.batches.map((batch: BatchDetails, index: number) => (
                    <div key={index} className="border rounded-lg p-3">
                      <div className="flex justify-between items-start mb-2">
                        <div className="flex items-center gap-2">
                          <span className="font-medium">بچ {batch.batchNumber}</span>
                          <Badge variant="secondary">{batch.stock} واحد</Badge>
                        </div>
                        <div className="flex items-center gap-1 text-sm text-gray-500">
                          <Calendar className="w-4 h-4" />
                          {formatDate(batch.createdAt)}
                        </div>
                      </div>
                      {batch.notes && (
                        <div className="flex items-start gap-2 text-sm text-gray-600">
                          <FileText className="w-4 h-4 mt-0.5" />
                          <span>{batch.notes}</span>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <p className="text-center text-gray-500 py-8">اطلاعات بچ یافت نشد</p>
            )}
          </div>
        </Card>
      )}

      {/* No Results */}
      {filteredInventory.length === 0 && !isLoading && (
        <Card>
          <CardContent className="text-center p-12">
            <Package className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold mb-2">موجودی یافت نشد</h3>
            <p className="text-gray-600">
              {searchTerm ? 'هیچ محصولی با این جستجو یافت نشد' : 'هیچ محصولی در انبار موجود نیست'}
            </p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

shared/order-management-schema.ts.content:
import {
  pgTable,
  serial,
  text,
  integer,
  decimal,
  timestamp,
  boolean,
  varchar,
  index,
  json,
} from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// Order statuses for different departments
export const orderStatuses = {
  // Initial statuses
  PENDING_PAYMENT: 'pending_payment',
  PAYMENT_GRACE_PERIOD: 'payment_grace_period', // 3-day grace period for bank transfer
  PAYMENT_UPLOADED: 'payment_uploaded',

  // Financial department statuses
  FINANCIAL_REVIEWING: 'financial_reviewing',
  FINANCIAL_APPROVED: 'financial_approved',
  FINANCIAL_REJECTED: 'financial_rejected',
  FINANCIAL_AUTO_APPROVED: 'financial_auto_approved', // 5-minute auto approval

  // Warehouse department statuses
  WAREHOUSE_PENDING: 'warehouse_pending',
  WAREHOUSE_NOTIFIED: 'warehouse_notified',
  WAREHOUSE_PROCESSING: 'warehouse_processing',
  WAREHOUSE_APPROVED: 'warehouse_approved',
  WAREHOUSE_REJECTED: 'warehouse_rejected',

  // Logistics department statuses
  LOGISTICS_ASSIGNED: 'logistics_assigned',
  LOGISTICS_PROCESSING: 'logistics_processing',
  LOGISTICS_DISPATCHED: 'logistics_dispatched',
  LOGISTICS_DELIVERED: 'logistics_delivered',

  // Final statuses
  COMPLETED: 'completed',
  CANCELLED: 'cancelled'
} as const;

// Payment method types
export const paymentMethods = {
  BANK_GATEWAY: 'bank_gateway',           // پرداخت از طریق درگاه بانکی
  WALLET: 'wallet',                       // پرداخت از کیف پول
  BANK_TRANSFER: 'bank_transfer',         // انتقال بانکی با آپلود فیش
  GRACE_PERIOD: 'grace_period'            // سفارش مهلت‌دار 3 روزه
} as const;

// Payment source identification
export const paymentSources = {
  BANK_GATEWAY: 'از طریق درگاه بانکی',
  WALLET: 'از طریق کیف پول',
  BANK_TRANSFER: 'انتقال بانکی',
  GRACE_PERIOD: 'سفارش مهلت‌دار 3 روزه'
} as const;

// Order management table - extends customer orders with department workflow
export const orderManagement = pgTable("order_management", {
  id: serial("id").primaryKey(),
  customerOrderId: integer("customer_order_id").notNull().unique(),

  // Current status and tracking
  currentStatus: varchar("current_status", { length: 50 }).notNull().default(orderStatuses.PENDING_PAYMENT),
  deliveryCode: varchar("delivery_code", { length: 10 }).unique(), // SMS code for delivery verification

  // Financial department
  financialReviewerId: integer("financial_reviewer_id"),
  financialReviewedAt: timestamp("financial_reviewed_at"),
  financialNotes: text("financial_notes"),
  paymentReceiptUrl: text("payment_receipt_url"), // Uploaded payment receipt

  // Payment method and source tracking
  paymentMethod: varchar("payment_method", { length: 50 }), // bank_gateway, wallet, bank_transfer, grace_period
  paymentSourceLabel: text("payment_source_label"), // Display label for payment source
  walletAmountUsed: decimal("wallet_amount_used", { precision: 10, scale: 2 }).default("0.00"),
  bankAmountPaid: decimal("bank_amount_paid", { precision: 10, scale: 2 }).default("0.00"),
  excessAmountCredited: decimal("excess_amount_credited", { precision: 10, scale: 2 }).default("0.00"),

  // Grace period for bank transfer payments
  paymentGracePeriodStart: timestamp("payment_grace_period_start"),
  paymentGracePeriodEnd: timestamp("payment_grace_period_end"),
  isOrderLocked: boolean("is_order_locked").default(false), // Lock order details during grace period

  // Auto-approval system
  autoApprovalScheduledAt: timestamp("auto_approval_scheduled_at"), // When 5-minute timer started
  isAutoApprovalEnabled: boolean("is_auto_approval_enabled").default(true),
  autoApprovalExecutedAt: timestamp("auto_approval_executed_at"),

  // Warehouse department
  warehouseAssigneeId: integer("warehouse_assignee_id"),
  warehouseProcessedAt: timestamp("warehouse_processed_at"),
  warehouseNotes: text("warehouse_notes"),

  // Logistics department
  logisticsAssigneeId: integer("logistics_assignee_id"),
  logisticsProcessedAt: timestamp("logistics_processed_at"),
  logisticsNotes: text("logistics_notes"),
  trackingNumber: varchar("tracking_number", { length: 100 }),
  estimatedDeliveryDate: timestamp("estimated_delivery_date"),
  actualDeliveryDate: timestamp("actual_delivery_date"),
  deliveryPersonName: text("delivery_person_name"),
  deliveryPersonPhone: text("delivery_person_phone"),

  // Carrier delivery and verification status
  isCarrierDispatched: boolean("is_carrier_dispatched").default(false),
  carrierDispatchedAt: timestamp("carrier_dispatched_at"),
  carrierName: text("carrier_name"),
  carrierPhone: text("carrier_phone"),
  isVerified: boolean("is_verified").default(false),
  verifiedAt: timestamp("verified_at"),
  verificationLocation: text("verification_location"),

  // Recipient information (can be different from customer)
  recipientName: text("recipient_name"), // نام گیرنده
  recipientPhone: text("recipient_phone"), // شماره موبایل گیرنده
  recipientAddress: text("recipient_address"), // آدرس دریافت کالا

  // Carrier location tracking for geography analytics
  carrierLatitude: decimal("carrier_latitude", { precision: 10, scale: 8 }), // GPS latitude coordinates
  carrierLongitude: decimal("carrier_longitude", { precision: 11, scale: 8 }), // GPS longitude coordinates
  carrierLocationAccuracy: decimal("carrier_location_accuracy", { precision: 6, scale: 2 }), // GPS accuracy in meters
  carrierLocationCapturedAt: timestamp("carrier_location_captured_at"), // When location was captured
  carrierLocationSource: varchar("carrier_location_source", { length: 20 }).default("mobile"), // mobile, gps_device, manual

  // Delivery method and transportation details
  deliveryMethod: varchar("delivery_method", { length: 50 }).default("courier"), // post, courier, truck, personal_pickup
  transportationType: varchar("transportation_type", { length: 50 }), // motorcycle, car, truck, van

  // Total weight calculation for entire order
  totalWeight: decimal("total_weight", { precision: 10, scale: 3 }), // Total weight of all order items in kg
  weightUnit: varchar("weight_unit", { length: 10 }).default("kg"), // kg, ton, gram

  // Postal service details (for post delivery)
  postalServiceName: text("postal_service_name"), // Iran Post, Pishtaz, etc.
  postalTrackingCode: varchar("postal_tracking_code", { length: 100 }),
  postalWeight: decimal("postal_weight", { precision: 8, scale: 2 }),
  postalPrice: decimal("postal_price", { precision: 10, scale: 2 }),
  postalInsurance: boolean("postal_insurance").default(false),

  // Vehicle details (for courier/truck delivery)
  vehicleType: varchar("vehicle_type", { length: 50 }), // motorcycle, car, truck, van
  vehiclePlate: varchar("vehicle_plate", { length: 20 }),
  vehicleModel: text("vehicle_model"),
  vehicleColor: text("vehicle_color"),
  driverName: text("driver_name"),
  driverPhone: text("driver_phone"),
  driverLicense: varchar("driver_license", { length: 50 }),

  // Company delivery details
  deliveryCompanyName: text("delivery_company_name"), // Tipax, Mahex, etc.
  deliveryCompanyPhone: text("delivery_company_phone"),
  deliveryCompanyAddress: text("delivery_company_address"),

  // Timestamps
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => [
  index("idx_order_management_status").on(table.currentStatus),
  index("idx_order_management_customer_order").on(table.customerOrderId),
  index("idx_order_management_delivery_code").on(table.deliveryCode),
]);

// Order status history - track all status changes
export const orderStatusHistory = pgTable("order_status_history", {
  id: serial("id").primaryKey(),
  orderManagementId: integer("order_management_id").notNull(),
  fromStatus: varchar("from_status", { length: 50 }),
  toStatus: varchar("to_status", { length: 50 }).notNull(),
  changedBy: integer("changed_by"), // Admin user ID
  changedByDepartment: varchar("changed_by_department", { length: 20 }), // financial, warehouse, logistics
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("idx_order_status_history_order").on(table.orderManagementId),
  index("idx_order_status_history_status").on(table.toStatus),
]);

// Department assignments - which admin users belong to which department
export const departmentAssignments = pgTable("department_assignments", {
  id: serial("id").primaryKey(),
  adminUserId: integer("admin_user_id").notNull(),
  department: varchar("department", { length: 20 }).notNull(), // financial, warehouse, logistics
  isActive: boolean("is_active").default(true),
  assignedAt: timestamp("assigned_at").notNull().defaultNow(),
  assignedBy: integer("assigned_by"), // Admin who made the assignment
}, (table) => [
  index("idx_department_assignments_user").on(table.adminUserId),
  index("idx_department_assignments_dept").on(table.department),
]);

// Payment receipts uploaded by customers
export const paymentReceipts = pgTable("payment_receipts", {
  id: serial("id").primaryKey(),
  customerOrderId: integer("customer_order_id").notNull(),
  customerId: integer("customer_id").notNull(),
  receiptUrl: text("receipt_url").notNull(),
  originalFileName: text("original_file_name").notNull(),
  fileSize: integer("file_size").notNull(),
  mimeType: varchar("mime_type", { length: 100 }).notNull(),
  uploadedAt: timestamp("uploaded_at").notNull().defaultNow(),
  notes: text("notes"), // Customer can add notes about the payment
}, (table) => [
  index("idx_payment_receipts_order").on(table.customerOrderId),
  index("idx_payment_receipts_customer").on(table.customerId),
]);

// Delivery verification codes
export const deliveryCodes = pgTable("delivery_codes", {
  id: serial("id").primaryKey(),
  orderManagementId: integer("order_management_id").notNull().unique(),
  code: varchar("code", { length: 6 }).notNull().unique(), // 6-digit SMS code
  isUsed: boolean("is_used").default(false),
  usedAt: timestamp("used_at"),
  verifiedBy: text("verified_by"), // Delivery person name/ID
  expiresAt: timestamp("expires_at").notNull(), // Code expires after 7 days
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("idx_delivery_codes_code").on(table.code),
  index("idx_delivery_codes_order").on(table.orderManagementId),
]);

// Shipping rates table - pricing for different delivery methods
export const shippingRates = pgTable("shipping_rates", {
  id: serial("id").primaryKey(),
  deliveryMethod: varchar("delivery_method", { length: 50 }).notNull(), // post, courier, truck, personal_pickup
  transportationType: varchar("transportation_type", { length: 50 }), // motorcycle, car, truck, van

  // Geographic coverage
  cityName: text("city_name"), // null means national/all cities
  provinceName: text("province_name"), // null means all provinces

  // Weight and size limits
  minWeight: decimal("min_weight", { precision: 8, scale: 2 }).default("0"), // kg
  maxWeight: decimal("max_weight", { precision: 8, scale: 2 }), // kg (null = no limit)
  maxDimensions: text("max_dimensions"), // "length x width x height cm"

  // Pricing structure
  basePrice: decimal("base_price", { precision: 10, scale: 2 }).notNull(), // Base shipping cost
  pricePerKg: decimal("price_per_kg", { precision: 8, scale: 2 }).default("0"), // Additional cost per kg
  freeShippingThreshold: decimal("free_shipping_threshold", { precision: 10, scale: 2 }), // Order value for free shipping

  // Service details
  estimatedDays: integer("estimated_days"), // Delivery time in days
  trackingAvailable: boolean("tracking_available").default(false),
  insuranceAvailable: boolean("insurance_available").default(false),
  insuranceRate: decimal("insurance_rate", { precision: 5, scale: 4 }).default("0"), // % of order value

  // Status and management
  isActive: boolean("is_active").default(true),
  smsVerificationEnabled: boolean("sms_verification_enabled").default(true), // SMS verification for delivery
  description: text("description"), // Service description for customers
  internalNotes: text("internal_notes"), // Admin notes

  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => [
  index("shipping_rates_method_idx").on(table.deliveryMethod),
  index("shipping_rates_city_idx").on(table.cityName),
  index("shipping_rates_active_idx").on(table.isActive),
]);



// Delivery methods table - configurable delivery method types
export const deliveryMethods = pgTable("delivery_methods", {
  id: serial("id").primaryKey(),
  value: varchar("value", { length: 50 }).unique().notNull(), // Unique identifier (e.g., 'cod', 'express')
  label: varchar("label", { length: 100 }).notNull(), // Display name (e.g., 'پس کرایه', 'ارسال اکسپرس')
  icon: varchar("icon", { length: 20 }).default("package"), // Icon name for UI
  color: varchar("color", { length: 20 }).default("blue"), // Color scheme for UI

  // Cost fields
  baseCost: decimal("base_cost", { precision: 10, scale: 2 }).default("0"), // Base cost for this delivery method
  costPerKg: decimal("cost_per_kg", { precision: 8, scale: 2 }).default("0"), // Additional cost per kg
  minimumOrder: decimal("minimum_order", { precision: 10, scale: 2 }).default("0"), // Minimum order value for this method
  freeShippingThreshold: decimal("free_shipping_threshold", { precision: 10, scale: 2 }), // Order value for free shipping

  // Time and availability
  estimatedDays: integer("estimated_days").default(1), // Delivery time in days
  maxDistance: integer("max_distance"), // Maximum delivery distance in km
  availableAreas: json("available_areas"), // Array of available cities/areas

  isActive: boolean("is_active").default(true), // Whether this method is available
  sortOrder: integer("sort_order").default(0), // Display order
  description: text("description"), // Description for customers

  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => [
  index("delivery_methods_value_idx").on(table.value),
  index("delivery_methods_active_idx").on(table.isActive),
  index("delivery_methods_sort_idx").on(table.sortOrder),
]);

// Order counter table for M[YY][NNNNN] pattern - M2511111, M2511112, etc.
export const orderCounter = pgTable("order_counter", {
  id: serial("id").primaryKey(),
  year: integer("year").notNull(), // Current year (e.g., 2025)
  counter: integer("counter").notNull().default(11111), // Sequential counter starting from 11111
  prefix: varchar("prefix", { length: 1 }).notNull().default("M"), // Fixed prefix 'M'
  lastReset: timestamp("last_reset").notNull().defaultNow(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => [
  index("order_counter_year_idx").on(table.year),
]);

// Insert schemas
export const insertOrderManagementSchema = createInsertSchema(orderManagement).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertOrderStatusHistorySchema = createInsertSchema(orderStatusHistory).omit({
  id: true,
  createdAt: true,
});

export const insertDepartmentAssignmentSchema = createInsertSchema(departmentAssignments).omit({
  id: true,
  assignedAt: true,
});

export const insertPaymentReceiptSchema = createInsertSchema(paymentReceipts).omit({
  id: true,
  uploadedAt: true,
});

export const insertDeliveryCodeSchema = createInsertSchema(deliveryCodes).omit({
  id: true,
  createdAt: true,
});

export const insertShippingRateSchema = createInsertSchema(shippingRates).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});



export const insertOrderCounterSchema = createInsertSchema(orderCounter).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// Type definitions
export type OrderCounter = typeof orderCounter.$inferSelect;
export type InsertOrderCounter = z.infer<typeof insertOrderCounterSchema>;

// Consolidated Order Data - Complete order information after financial approval
export const consolidatedOrderData = pgTable("consolidated_order_data", {
  id: serial("id").primaryKey(),
  orderManagementId: integer("order_management_id").notNull().unique(),
  customerOrderId: integer("customer_order_id").notNull().unique(),
