}

/* RTL and Language Support */
[dir="rtl"] {
  direction: rtl;
}

[dir="ltr"] {
  direction: ltr;
}

/* Language-specific fonts - Premium Arabic Fonts */
.lang-ar {
  font-family: "Cairo", "Tajawal", "Almarai", "IBM Plex Sans Arabic", "Arabic UI Text", "Segoe UI", "Tahoma", Arial, sans-serif;
  font-weight: 500;
}

.lang-ku {
  font-family: "Cairo", "Tajawal", "Almarai", "IBM Plex Sans Arabic", "Arabic UI Text", "Segoe UI", "Tahoma", Arial, sans-serif;
