}

.lang-en {
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-weight: 500;
}

/* Required Field Styling */
.required-field {
  font-weight: 600;
}

.required-field .text-red-500 {
  font-weight: 700;
