}

/* RTL text direction */
[dir="rtl"] {
  text-align: right;
}

[dir="ltr"] {
  text-align: left;
}

/* RTL-specific utilities */
.rtl-flex {
  display: flex;
  flex-direction: row-reverse;
}

.ltr-flex {
  display: flex;
  flex-direction: row;
}

/* Better Arabic and Kurdish font rendering - Premium Typography */
