                className="absolute top-4 right-4 w-80 h-80 border-4 border-white rounded-lg overflow-hidden bg-white shadow-2xl opacity-0 transition-opacity duration-200 pointer-events-none"
                style={{
                  backgroundImage: `url(${selectedImageForZoom})`,
                  backgroundRepeat: 'no-repeat',
                  backgroundSize: '400%',
                  zIndex: 10,
                }}
                id="zoom-result"
              />
            </div>

            {/* Dot indicators */}
            {(() => {
              const images = getImages(selectedProductForZoom);

              return images.length > 1 ? (
                <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 z-10 flex space-x-3 bg-black/60 px-4 py-2 rounded-full">
                  {images.map((_, index) => (
                    <button
                      key={index}
                      onClick={(e) => {
                        e.stopPropagation();
                        setZoomedImageIndex(index);
                        setSelectedImageForZoom(images[index]);
                      }}
                      className={`w-3 h-3 rounded-full transition-all duration-200 ${
                        index === zoomedImageIndex 
                          ? 'bg-white scale-125' 
                          : 'bg-white/50 hover:bg-white/80 hover:scale-110'
                      }`}
                    />
                  ))}
                </div>
              ) : null;
            })()}
          </div>
        </div>
      )}

      {/* 3D Model Fullscreen Dialog */}
      <Dialog open={!!selected3DModel} onOpenChange={() => setSelected3DModel(null)}>
        <DialogContent className="max-w-5xl w-[95vw] h-[90vh] p-0">
          <DialogHeader className="p-6 pb-4">
            <DialogTitle className="text-2xl font-bold" dir={direction}>
              {selected3DModel?.name}
            </DialogTitle>
            <DialogDescription dir={direction}>
              {direction === 'rtl' ? 'استخدم الماوس للتدوير والتكبير' : 'Use your mouse to rotate and zoom the 3D model'}
            </DialogDescription>
          </DialogHeader>
          <div className="flex-1 p-6 pt-0">
            {selected3DModel && (
              <ProductModel3DViewer
                model3dKey={selected3DModel.key}
                productName={selected3DModel.name}
                className="w-full h-full min-h-[600px]"
              />
            )}
          </div>
        </DialogContent>
      </Dialog>

      {/* Auth Dialog */}
      <CustomerAuth 
        open={showAuth}
        onOpenChange={setShowAuth}
        onLoginSuccess={handleLoginSuccess}
        onRegisterSuccess={handleRegisterSuccess}
        initialMode={authMode}
        existingCustomer={undefined}
      />
    </div>
  );
};

// Helper components for skeleton loading
const ProductCardSkeleton = ({ viewMode }: { viewMode: "grid" | "list" }) => (
  <Card className={`animate-pulse ${viewMode === "list" ? "flex" : ""}`}>
    <div className={`bg-gray-200 ${viewMode === "list" ? "w-32 h-32" : "aspect-square"} rounded-t-lg`}></div>
    <CardContent className="p-4">
      <div className="h-4 bg-gray-200 rounded mb-2"></div>
      <div className="h-3 bg-gray-200 rounded mb-2"></div>
      <div className="h-6 bg-gray-200 rounded"></div>
    </CardContent>
  </Card>
);

