import { Progress } from "@/components/ui/progress";
import { 
  ArrowLeft, 
  Plus, 
  Edit, 
  Trash2, 
  Eye,
  FileText, 
  Shield, 
  BookOpen,
  CheckCircle,
  Clock,
  AlertTriangle,
  Star,
  Search,
  Filter,
  Download,
  Upload,
