                            type="button"
                            variant="ghost"
                            size="sm"
                            onClick={() => removeDocument(index)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                <div className="flex justify-end gap-2">
                  <Button type="button" variant="outline" onClick={closeDialog}>
                    انصراف
                  </Button>
                  <Button type="submit">
                    {editingItem ? 'به‌روزرسانی دستورالعمل' : 'ایجاد دستورالعمل'}
                  </Button>
                </div>
              </form>
            </Form>
          )}

          {dialogType === 'safety' && (
            <Form {...safetyForm}>
              <form onSubmit={safetyForm.handleSubmit(onSubmitSafety)} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <FormField
                    control={safetyForm.control}
                    name="title"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>عنوان پروتکل</FormLabel>
                        <FormControl>
                          <Input {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={safetyForm.control}
                    name="category"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>دسته‌بندی</FormLabel>
                        <FormControl>
                          <Input {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>
                <FormField
                  control={safetyForm.control}
                  name="description"
