                      <FormControl>
                        <Textarea {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Document Upload Section */}
                <div className="space-y-4 pt-4 border-t">
                  <h4 className="font-medium">Document Attachments</h4>
                  <div className="space-y-2">
                    <Label htmlFor="safety-documents">Upload Safety Documents</Label>
                    <Input
                      id="safety-documents"
