import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { User, Phone, Mail, MapPin, Building, CreditCard, ShoppingBag, Calendar, Edit, Save, X, Eye, FileText, Activity } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import PaymentMethodBadge from "@/components/PaymentMethodBadge";

interface UnifiedCustomerProfileProps {
  customerId: number;
  mode?: 'view' | 'edit' | 'admin';
  onUpdate?: () => void;
}

interface CustomerProfile {
  id: number;
  email: string;
  firstName: string;
  lastName: string;
  company?: string;
  phone: string;
  country: string;
  city: string;
  address: string;
  postalCode?: string;
  alternatePhone?: string;
  state?: string;
  industry?: string;
  businessType?: string;
  companySize?: string;
  customerType: string;
  customerStatus: string;
  customerSource: string;
  totalOrdersCount: number;
  totalSpent: string;
  averageOrderValue: string;
  lastOrderDate?: string;
  firstOrderDate?: string;
  communicationPreference: string;
  preferredLanguage: string;
  marketingConsent: boolean;
  productInterests?: any[];
  creditLimit?: string;
  paymentTerms: string;
  preferredPaymentMethod?: string;
  notes?: string;
  createdAt: string;
  updatedAt: string;
}

interface CustomerActivity {
  id: number;
  activityType: string;
  description: string;
  performedBy: string;
  createdAt: string;
  activityData?: any;
}

interface CustomerOrder {
  id: number;
  orderNumber: string;
  status: string;
  totalAmount: string;
  paymentMethod?: string;
  carrier?: string;
  createdAt: string;
  items?: any[];
}

export default function UnifiedCustomerProfile({ customerId, mode = 'view', onUpdate }: UnifiedCustomerProfileProps) {
  const [isEditing, setIsEditing] = useState(mode === 'edit');
  const [editData, setEditData] = useState<Partial<CustomerProfile>>({});
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch customer profile
  const { data: customer, isLoading } = useQuery<CustomerProfile>({
    queryKey: ['/api/crm/customers', customerId],
    queryFn: async () => {
      const response = await apiRequest(`/api/crm/customers/${customerId}`, 'GET');
      return response.data;
    },
  });

  // Fetch customer activities
  const { data: activities = [] } = useQuery<CustomerActivity[]>({
    queryKey: ['/api/crm/customers', customerId, 'activities'],
    queryFn: async () => {
      const response = await apiRequest(`/api/crm/customers/${customerId}/activities`, 'GET');
      return response.data || [];
    },
  });

  // Fetch customer orders
  const { data: orders = [] } = useQuery<CustomerOrder[]>({
    queryKey: ['/api/crm/customers', customerId, 'orders'],
    queryFn: async () => {
      const response = await apiRequest(`/api/crm/customers/${customerId}/orders`, 'GET');
      return response.data || [];
    },
  });

  // Update customer mutation
  const updateCustomerMutation = useMutation({
    mutationFn: async (updateData: Partial<CustomerProfile>) => {
      console.log("Frontend update mutation data:", updateData);

      // Clean the updates data - remove undefined values and ensure proper formatting
      const cleanedUpdates = Object.entries(updateData).reduce((acc, [key, value]) => {
        if (value !== undefined && value !== null && value !== '') {
          // Handle specific field types
          if (key === 'customerType' || key === 'customerStatus' || key === 'customerSource') {
            acc[key] = String(value); // Ensure these are strings
          } else {
            acc[key] = value;
          }
        }
        return acc;
      }, {} as any);

      console.log("Cleaned updates:", cleanedUpdates);

      return apiRequest(`/api/crm/customers/${customerId}`, 'PUT', cleanedUpdates);
    },
    onSuccess: (result) => {
      console.log("Update success:", result);
      toast({ title: "Success", description: "Customer profile updated successfully" });
      setIsEditing(false);
      setEditData({});
      queryClient.invalidateQueries({ queryKey: ['/api/crm/customers', customerId] });
      queryClient.invalidateQueries({ queryKey: ['/api/crm/customers'] });
      onUpdate?.();
    },
    onError: (error: any) => {
      console.error("Update error:", error);
      toast({ 
        title: "Error", 
        description: error.message || "Failed to update customer profile",
        variant: "destructive"
      });
    }
  });

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const formatCurrency = (amount: string | number, currency: string = 'IQD') => {
    const validCurrencies = ['USD', 'EUR', 'IQD'];
    const currencyCode = validCurrencies.includes(currency) ? currency : 'IQD';
    const numAmount = typeof amount === 'string' ? parseFloat(amount) : amount;

    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currencyCode,
      minimumFractionDigits: 2,
    }).format(numAmount);
  };

  const getStatusColor = (status: string | undefined | null) => {
    if (!status) return 'bg-gray-100 text-gray-800';

    switch (status) {
      case 'active': return 'bg-green-100 text-green-800';
      case 'vip': return 'bg-purple-100 text-purple-800';
      case 'inactive': return 'bg-gray-100 text-gray-800';
      case 'blacklisted': return 'bg-red-100 text-red-800';
      default: return 'bg-blue-100 text-blue-800';
    }
  };

  const handleEditChange = (field: string, value: any) => {
    setEditData(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = () => {
    updateCustomerMutation.mutate(editData);
  };

  const handleCancel = () => {
    setIsEditing(false);
    setEditData({});
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p>Loading customer profile...</p>
        </div>
      </div>
    );
  }

  if (!customer) {
    return (
      <div className="text-center p-8">
