// Dynamic schemas based on language
const createLoginSchema = (lang: Language) => z.object({
  email: z.string().email(translations[lang].emailRequired),
  password: z.string().min(6, translations[lang].passwordMin),
});

const createRegisterSchema = (lang: Language) => z.object({
  email: z.string().email(translations[lang].emailRequired),
  password: z.string().min(6, translations[lang].passwordMin),
  confirmPassword: z.string(),
  firstName: z.string().min(2, translations[lang].firstNameMin),
  lastName: z.string().min(2, translations[lang].lastNameMin),
  phone: z.string().min(10, translations[lang].phoneRequired),
  company: z.string().optional(),
}).refine((data) => data.password === data.confirmPassword, {
  message: translations[lang].passwordMatch,
  path: ["confirmPassword"],
});

const createCheckoutSchema = (lang: Language) => z.object({
  address: z.string().min(10, translations[lang].addressRequired),
  city: z.string().min(2, translations[lang].cityRequired),
  postalCode: z.string().optional(),
  notes: z.string().optional(),
  gpsLatitude: z.number().optional(),
  gpsLongitude: z.number().optional(),
});

interface AuthCheckoutProps {
  cart: {[key: number]: number};
  products: any[];
  onOrderComplete: () => void;
  onClose: () => void;
}

// GPS location functionality
const getCurrentLocation = (): Promise<{latitude: number, longitude: number}> => {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      reject(new Error('Geolocation is not supported'));
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude
        });
      },
      (error) => {
        reject(error);
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 600000
      }
    );
  });
};

export default function AuthCheckout({ cart, products, onOrderComplete, onClose }: AuthCheckoutProps) {
  const [currentStep, setCurrentStep] = useState<"auth" | "checkout" | "complete">("auth");
  const [authMode, setAuthMode] = useState<"login" | "register">("login");
  const [customer, setCustomer] = useState<any>(null);
  const [orderNumber, setOrderNumber] = useState("");
  const [emailExists, setEmailExists] = useState(false);
  const [savedCartData, setSavedCartData] = useState<any>(null);
  const [language] = useState<Language>('ar'); // Default language
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Create schemas based on current language
  const loginSchema = createLoginSchema(language);
  const registerSchema = createRegisterSchema(language);
  const checkoutSchema = createCheckoutSchema(language);

  // Save cart data to preserve during authentication
  useEffect(() => {
    if (cart && products) {
      const cartData = {
        cart,
        products,
        timestamp: Date.now(),
      };
      setSavedCartData(cartData);
      localStorage.setItem('pendingCart', JSON.stringify(cartData));
    }
  }, [cart, products]);

  // Check if customer is already logged in
  const { data: customerData, refetch: refetchCustomer } = useQuery<any>({
    queryKey: ["/api/customers/me"],
    retry: false,
  });

  useEffect(() => {
    if (customerData?.success && customerData.customer) {
      setCustomer(customerData.customer);
      setCurrentStep("checkout");
    }
  }, [customerData]);

  // Authentication forms
  const loginForm = useForm({
    resolver: zodResolver(loginSchema),
    defaultValues: { email: "", password: "" },
  });

  const registerForm = useForm({
    resolver: zodResolver(registerSchema.extend({
      phone: z.string().min(1, "Phone number is required"),
      country: z.string().min(1, "Country is required"),
      city: z.string().min(1, "City is required"),
      address: z.string().min(1, "Address is required"),
    })),
    defaultValues: {
      email: "",
      password: "",
      confirmPassword: "",
      firstName: "",
      lastName: "",
      phone: "",
      company: "",
      country: "",
      city: "",
      address: "",
      postalCode: "",
      alternatePhone: "",
      industry: "",
      businessType: "retail",
      communicationPreference: "email",
      preferredLanguage: "fa",
      marketingConsent: false,
    },
  });

  // Checkout form
  const checkoutForm = useForm({
    resolver: zodResolver(checkoutSchema),
    defaultValues: {
      address: "",
      city: "",
      postalCode: "",
      notes: "",
    },
  });

  // Auto-fill checkout form when customer data is available
  useEffect(() => {
    if (customer) {
      if (customer.address) checkoutForm.setValue("address", customer.address);
      if (customer.city) checkoutForm.setValue("city", customer.city);
      if (customer.postalCode) checkoutForm.setValue("postalCode", customer.postalCode);
    }
  }, [customer, checkoutForm]);

  // Login mutation
  const loginMutation = useMutation({
    mutationFn: async (data: any) => {
      const result = await apiRequest("/api/customers/login", "POST", data);
      return result;
    },
    onSuccess: async (data: any) => {
      if (data.success) {
        setCustomer(data.customer);
        setCurrentStep("checkout");
        setEmailExists(false);
        await refetchCustomer();
        toast({
          title: "ورود موفق",
          description: `خوش آمدید ${data.customer.firstName}`,
        });
      }
    },
    onError: (error: any) => {
      toast({
        title: "خطا در ورود",
        description: "ایمیل یا رمز عبور اشتباه است",
        variant: "destructive",
      });
    },
  });

  // Register mutation
  const registerMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest("/api/customers/register", "POST", data);
    },
    onSuccess: async (data: any) => {
      if (data.success) {
        setCustomer(data.customer);
        setCurrentStep("checkout");
        setEmailExists(false);
        await refetchCustomer();
        toast({
          title: "ثبت نام موفق",
          description: `حساب کاربری شما ایجاد شد`,
        });
      }
    },
    onError: (error: any) => {
      if (error.message?.includes("already exists") || error.message?.includes("موجود") || error.message?.includes("duplicate")) {
        setEmailExists(true);
        toast({
          title: "ایمیل تکراری",
          description: "این ایمیل قبلاً ثبت شده است. لطفاً وارد شوید",
          variant: "destructive",
        });
      } else {
        toast({
          title: "خطا در ثبت نام",
          description: "مشکلی در ایجاد حساب کاربری رخ داده است",
          variant: "destructive",
        });
      }
    },
  });

  // Order creation mutation
  const createOrderMutation = useMutation({
    mutationFn: async (orderData: any) => {
      return apiRequest("/api/shop/orders", "POST", orderData);
    },
    onSuccess: async (data: any) => {
      setOrderNumber(data.order.id);
      setCurrentStep("complete");
      // Clear saved cart data
      localStorage.removeItem('pendingCart');

      // Force refresh inventory using dedicated endpoint - CRITICAL FOR SYNC
      try {
        const refreshResult = await apiRequest("/api/inventory/force-refresh", "POST", {});
        console.log("✓ Inventory force refresh completed:", refreshResult);
      } catch (error) {
        console.error("✗ Failed to trigger inventory refresh:", error);
        // Retry once if it fails
        try {
          await apiRequest("/api/inventory/force-refresh", "POST", {});
          console.log("✓ Inventory force refresh completed on retry");
        } catch (retryError) {
          console.error("✗ Inventory refresh failed on retry:", retryError);
        }
      }

      // Invalidate all product-related queries to fetch fresh inventory data
      queryClient.invalidateQueries({ queryKey: ["/api/shop/products"] });
      queryClient.invalidateQueries({ queryKey: ["/api/shop/search"] });
      queryClient.invalidateQueries({ queryKey: ["/api/products"] }); // Admin products page
      queryClient.invalidateQueries({ queryKey: ["/api/admin/products"] });

      onOrderComplete();
      toast({
        title: "سفارش ثبت شد",
        description: `شماره سفارش: ${data.order.id}`,
      });
    },
    onError: () => {
      toast({
        title: "خطا در ثبت سفارش",
        description: "مشکلی در ثبت سفارش رخ داده است",
        variant: "destructive",
      });
    },
  });

  // Calculate cart totals using saved cart data or current cart
  const currentCart = savedCartData?.cart || cart;
  const currentProducts = savedCartData?.products || products;

  const cartItems = Object.entries(currentCart).map(([productId, quantity]) => {
    const product = currentProducts.find((p: any) => p.id === parseInt(productId));
    return product ? {
      ...product,
      quantity: quantity as number,
      totalPrice: parseFloat(product.price) * (quantity as number)
    } : null;
  }).filter(Boolean);

  const subtotal = cartItems.reduce((sum: number, item: any) => sum + item.totalPrice, 0);
  const shippingCost = subtotal > 1000 ? 0 : 50;
  const totalAmount = subtotal + shippingCost;

  // Handle login form submission
  const onLogin = (data: any) => {
    loginMutation.mutate(data);
  };

  // Handle register form submission
  const onRegister = (data: any) => {
    const { confirmPassword, ...registerData } = data;
    registerMutation.mutate(registerData);
  };

  // Handle checkout form submission
  const onCheckout = (data: any) => {
    const orderData = {
      customerInfo: {
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        phone: customer.phone,
        company: customer.company || '',
        address: data.address,
        city: data.city,
        postalCode: data.postalCode,
        country: 'Iran',
      },
      items: cartItems.map((item: any) => ({
        productId: item.id,
        productName: item.name,
        quantity: item.quantity,
        unitPrice: parseFloat(item.price),
      })),
      totalAmount,
      notes: data.notes || '',
    };

    createOrderMutation.mutate(orderData);
  };

  // Switch to login when email exists
  const switchToLogin = () => {
    const email = registerForm.getValues("email");
    setAuthMode("login");
    loginForm.setValue("email", email);
    setEmailExists(false);
  };

  if (Object.keys(currentCart).length === 0) {
    return (
      <div className="text-center p-8">
        <ShoppingCart className="w-16 h-16 text-gray-300 mx-auto mb-4" />
        <h2 className="text-xl font-semibold text-gray-700 mb-2">سبد خرید خالی است</h2>
        <p className="text-gray-500 mb-6">محصولاتی به سبد خرید اضافه کنید</p>
        <Button onClick={onClose}>ادامه خرید</Button>
      </div>
    );
  }

  if (currentStep === "complete") {
    return (
      <div className="text-center p-8">
        <CheckCircle className="w-20 h-20 text-green-600 mx-auto mb-6" />
        <h2 className="text-2xl font-bold text-gray-900 mb-4">سفارش تأیید شد!</h2>
        <p className="text-gray-600 mb-2">از خرید شما متشکریم</p>
        <p className="text-lg font-semibold text-gray-900 mb-6">
          شماره سفارش: #{orderNumber}
        </p>
        <div className="space-y-3">
          <Button onClick={onClose} className="w-full">
            ادامه خرید
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Authentication/Checkout Form */}
        <div>
          {currentStep === "auth" && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <User className="w-5 h-5" />
                  ورود یا ثبت نام برای تسویه حساب
                </CardTitle>
                <p className="text-sm text-gray-600">
                  برای تکمیل سفارش باید وارد حساب کاربری شوید
                </p>
              </CardHeader>
              <CardContent>
                {emailExists && (
                  <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-4">
                    <div className="flex items-center gap-2 text-yellow-800 mb-2">
                      <AlertCircle className="w-4 h-4" />
                      <span className="text-sm font-medium">
                        این ایمیل قبلاً ثبت شده است
                      </span>
                    </div>
                    <p className="text-sm text-yellow-700 mb-3">
                      با همین ایمیل حساب کاربری دارید. لطفاً وارد شوید تا سفارش شما حفظ شود.
                    </p>
                    <Button 
                      variant="outline"
                      size="sm" 
                      onClick={switchToLogin}
                      className="text-yellow-700 border-yellow-300"
                    >
                      انتقال به صفحه ورود
                    </Button>
                  </div>
                )}

                <Tabs value={authMode} onValueChange={(value) => setAuthMode(value as any)}>
                  <TabsList className="grid w-full grid-cols-2 mb-6">
                    <TabsTrigger value="login">ورود</TabsTrigger>
                    <TabsTrigger value="register">ثبت نام</TabsTrigger>
                  </TabsList>

                  <TabsContent value="login">
                    <Form {...loginForm}>
                      <form onSubmit={loginForm.handleSubmit(onLogin)} className="space-y-4">
                        <FormField
                          control={loginForm.control}
                          name="email"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>ایمیل</FormLabel>
                              <FormControl>
                                <Input {...field} type="email" />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={loginForm.control}
                          name="password"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>رمز عبور</FormLabel>
                              <FormControl>
                                <Input {...field} type="password" />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <Button 
                          type="submit" 
                          className="w-full" 
                          disabled={loginMutation.isPending}
                        >
                          {loginMutation.isPending ? "در حال ورود..." : "ورود و ادامه تسویه"}
                        </Button>
                      </form>
                    </Form>
                  </TabsContent>

                  <TabsContent value="register">
                    <Form {...registerForm}>
                      <form onSubmit={registerForm.handleSubmit(onRegister)} className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <FormField
                            control={registerForm.control}
                            name="firstName"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel>نام</FormLabel>
                                <FormControl>
                                  <Input {...field} />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={registerForm.control}
                            name="lastName"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel>نام خانوادگی</FormLabel>
                                <FormControl>
                                  <Input {...field} />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        </div>
                        <FormField
                          control={registerForm.control}
                          name="email"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>ایمیل</FormLabel>
                              <FormControl>
                                <Input {...field} type="email" />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={registerForm.control}
                          name="phone"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>شماره تلفن *</FormLabel>
                              <FormControl>
                                <Input {...field} required />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={registerForm.control}
                          name="company"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>نام شرکت *</FormLabel>
                              <FormControl>
                                <Input {...field} required />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <div className="grid grid-cols-2 gap-4">
                          <FormField
                            control={registerForm.control}
                            name="country"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel>کشور *</FormLabel>
                                <FormControl>
                                  <Input {...field} required />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={registerForm.control}
                            name="city"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel>شهر *</FormLabel>
                                <FormControl>
                                  <Input {...field} required />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        </div>
                        <FormField
                          control={registerForm.control}
                          name="address"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>آدرس *</FormLabel>
                              <FormControl>
                                <Input {...field} required />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={registerForm.control}
                          name="postalCode"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>کد پستی</FormLabel>
                              <FormControl>
                                <Input {...field} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={registerForm.control}
                          name="alternatePhone"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>تلفن دوم</FormLabel>
                              <FormControl>
                                <Input {...field} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={registerForm.control}
                          name="industry"
                          render={({ field }) => (
                            <FormItem>
