      if (isNaN(date.getTime())) return 'تاریخ نامعتبر';

      // فرمت میلادی صریح برای پرینت انبار
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
