      title: 'مستندات کامل',
      titleEn: 'Complete Documentation',
      description: 'تمام مستندات در یک فایل جامع',
      descriptionEn: 'All documentation in one comprehensive file',
      icon: FileText,
      color: 'bg-gray-500',
      features: [
        'شامل تمام بخش‌های فوق',
