                              <span className="text-sm text-muted-foreground">Priority: {method.priority}</span>
                            </div>
                            <Switch
                              checked={method.enabled}
                              onCheckedChange={(checked) => {
                                updatePaymentMethodMutation.mutate({
                                  methodKey: method.methodKey,
