import { useState, useEffect } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { queryClient, apiRequest } from '@/lib/queryClient';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/hooks/use-toast';
import { 
  MessageCircle, 
  Users, 
  Send, 
  Search, 
  Filter,
  CheckCircle,
  XCircle,
  Phone,
  Mail,
  Eye,
  TrendingUp,
  Calendar,
  UserCheck,
  MessageSquare,
  Settings,
  Key,
  Save,
  TestTube
} from 'lucide-react';

interface WhatsAppCustomer {
  id: number;
  first_name: string;
  last_name: string;
  email: string;
  phone: string;
  whatsapp_number: string;
  communication_preference: string;
  created_at: string;
  last_login: string;
  total_orders: number;
  total_spent: number;
}

interface WhatsAppStats {
  overview: {
    total_customers: number;
    whatsapp_customers: number;
    whatsapp_preferred: number;
    email_preferred: number;
    sms_preferred: number;
    phone_preferred: number;
  };
  recentActivity: Array<{
    date: string;
    new_customers: number;
  }>;
}

export default function WhatsAppCRMEnglish() {
  const [selectedCustomers, setSelectedCustomers] = useState<number[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const [bulkMessageModal, setBulkMessageModal] = useState(false);
  const [bulkMessage, setBulkMessage] = useState('');
  const [testModal, setTestModal] = useState(false);
  const [testPhoneNumber, setTestPhoneNumber] = useState('');
  const [testMessage, setTestMessage] = useState('');

  // API Settings state
  const [apiSettings, setApiSettings] = useState({
    provider: 'twilio', // twilio, whatsapp_business, custom
    twilioAccountSid: '',
    twilioAuthToken: '',
    twilioWhatsAppNumber: '',
    businessApiToken: '',
    businessPhoneNumberId: '',
    customApiUrl: '',
    customApiKey: ''
  });

  const { toast } = useToast();

  // Fetch WhatsApp customers
  const { data: customersData, isLoading: customersLoading } = useQuery({
    queryKey: ['/api/admin/whatsapp/customers', page, searchTerm],
    staleTime: 30000,
  });

  // Fetch WhatsApp statistics
  const { data: statsData, isLoading: statsLoading } = useQuery({
    queryKey: ['/api/admin/whatsapp/stats'],
    staleTime: 60000,
  });

  // Test WhatsApp message mutation
  const testWhatsAppMutation = useMutation({
    mutationFn: async (data: { phoneNumber: string; message: string }) => {
      return apiRequest('/api/admin/whatsapp/test', {
        method: 'POST',
        body: JSON.stringify(data),
      });
    },
    onSuccess: (data) => {
      toast({
        title: "Success",
        description: data.message || "WhatsApp message sent successfully",
      });
      setTestModal(false);
      setTestPhoneNumber('');
      setTestMessage('');
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error?.message || "Failed to send WhatsApp message",
        variant: "destructive",
      });
    }
  });

  // Bulk message mutation
  const bulkMessageMutation = useMutation({
    mutationFn: async (data: { customerIds: number[]; message: string }) => {
      return apiRequest('/api/admin/whatsapp/bulk-send', {
        method: 'POST',
        body: JSON.stringify(data),
      });
    },
    onSuccess: (data) => {
      toast({
        title: "Success",
        description: data.message || "Bulk messages sent successfully",
      });
      setBulkMessageModal(false);
      setBulkMessage('');
      setSelectedCustomers([]);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error?.message || "Failed to send bulk messages",
        variant: "destructive",
      });
    }
  });

  // Handle search
  useEffect(() => {
    const timer = setTimeout(() => {
      setPage(1); // Reset to first page when searching
    }, 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  const customers = (customersData as any)?.data?.customers || [];
  const pagination = (customersData as any)?.data?.pagination || {};
  const stats = (statsData as any)?.data as WhatsAppStats;

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedCustomers(customers.map((c: WhatsAppCustomer) => c.id));
    } else {
      setSelectedCustomers([]);
    }
  };

  const handleSelectCustomer = (customerId: number, checked: boolean) => {
    if (checked) {
      setSelectedCustomers([...selectedCustomers, customerId]);
    } else {
      setSelectedCustomers(selectedCustomers.filter(id => id !== customerId));
    }
  };

  const getPreferenceIcon = (preference: string) => {
    switch (preference) {
      case 'whatsapp':
        return <MessageCircle className="w-4 h-4 text-green-500" />;
      case 'email':
        return <Mail className="w-4 h-4 text-blue-500" />;
      case 'sms':
        return <MessageSquare className="w-4 h-4 text-orange-500" />;
      case 'phone':
        return <Phone className="w-4 h-4 text-purple-500" />;
      default:
        return <Mail className="w-4 h-4 text-gray-500" />;
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(amount);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
            <MessageCircle className="w-8 h-8 text-green-600" />
            WhatsApp CRM Management
          </h1>
          <p className="text-lg text-gray-600 mt-2">
            Manage WhatsApp customers and send bulk messages
          </p>
        </div>

        <div className="flex items-center gap-4">
          <Button 
            onClick={() => setTestModal(true)}
            variant="outline"
            className="flex items-center gap-2"
          >
            <TestTube className="w-4 h-4" />
            Test WhatsApp
          </Button>
          <Button 
            onClick={() => setBulkMessageModal(true)}
            disabled={selectedCustomers.length === 0}
            className="flex items-center gap-2"
          >
            <Send className="w-4 h-4" />
            Bulk Message ({selectedCustomers.length})
          </Button>
        </div>
      </div>

      <Tabs defaultValue="customers" className="space-y-6">
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="customers" className="flex items-center gap-2">
            <Users className="w-4 h-4" />
            Customer List
          </TabsTrigger>
          <TabsTrigger value="stats" className="flex items-center gap-2">
            <TrendingUp className="w-4 h-4" />
            Statistics & Reports
          </TabsTrigger>
          <TabsTrigger value="settings" className="flex items-center gap-2">
            <Settings className="w-4 h-4" />
            API Settings
          </TabsTrigger>
        </TabsList>

        <TabsContent value="customers" className="space-y-6">
          {/* Search and Filters */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Search className="w-5 h-5" />
                Search & Filter
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex gap-4">
                <div className="flex-1">
                  <Input
                    placeholder="Search by name, email, or WhatsApp number..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full"
                  />
                </div>
                <Button variant="outline" className="flex items-center gap-2">
                  <Filter className="w-4 h-4" />
                  Filter
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Customers Table */}
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="flex items-center gap-2">
                  <Users className="w-5 h-5" />
                  WhatsApp Customers ({pagination.total || 0})
                </CardTitle>
                <div className="flex items-center gap-2">
                  <Checkbox
                    checked={selectedCustomers.length === customers.length && customers.length > 0}
                    onCheckedChange={handleSelectAll}
                  />
                  <span className="text-sm text-gray-600">Select All</span>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              {customersLoading ? (
                <div className="flex justify-center items-center h-32">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead className="w-12">
                          <Checkbox
                            checked={selectedCustomers.length === customers.length && customers.length > 0}
                            onCheckedChange={handleSelectAll}
                          />
                        </TableHead>
                        <TableHead>Name</TableHead>
                        <TableHead>Email</TableHead>
                        <TableHead>WhatsApp Number</TableHead>
                        <TableHead>Communication Preference</TableHead>
                        <TableHead>Orders</TableHead>
                        <TableHead>Total Spent</TableHead>
                        <TableHead>Join Date</TableHead>
                        <TableHead>Actions</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {customers.map((customer: WhatsAppCustomer) => (
                        <TableRow key={customer.id}>
                          <TableCell>
                            <Checkbox
                              checked={selectedCustomers.includes(customer.id)}
                              onCheckedChange={(checked) => handleSelectCustomer(customer.id, checked as boolean)}
                            />
                          </TableCell>
                          <TableCell className="font-medium">
                            {customer.first_name} {customer.last_name}
                          </TableCell>
                          <TableCell>{customer.email}</TableCell>
                          <TableCell className="font-mono text-sm">
                            {customer.whatsapp_number}
                          </TableCell>
                          <TableCell>
                            <div className="flex items-center gap-2">
                              {getPreferenceIcon(customer.communication_preference)}
                              <span className="capitalize">{customer.communication_preference}</span>
                            </div>
                          </TableCell>
                          <TableCell>
                            <Badge variant="secondary">
                              {customer.total_orders}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            {formatCurrency(Number(customer.total_spent))}
                          </TableCell>
                          <TableCell>
                            {formatDate(customer.created_at)}
                          </TableCell>
                          <TableCell>
                            <div className="flex items-center gap-2">
                              <Button
                                size="sm"
                                variant="outline"
                                className="flex items-center gap-1"
                                onClick={() => {
                                  setTestPhoneNumber(customer.whatsapp_number);
                                  setTestMessage(`Hello ${customer.first_name}!`);
                                  setTestModal(true);
                                }}
                              >
                                <MessageCircle className="w-3 h-3" />
                                Message
                              </Button>
                              <Button
                                size="sm"
                                variant="ghost"
                                className="flex items-center gap-1"
                              >
                                <Eye className="w-3 h-3" />
                                View
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              )}

              {/* Pagination */}
              {pagination.totalPages > 1 && (
                <div className="flex items-center justify-between mt-6">
                  <div className="text-sm text-gray-600">
                    Showing {((pagination.page - 1) * pagination.limit) + 1} to {Math.min(pagination.page * pagination.limit, pagination.total)} of {pagination.total} customers
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setPage(Math.max(1, page - 1))}
                      disabled={page === 1}
                    >
                      Previous
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setPage(Math.min(pagination.totalPages, page + 1))}
                      disabled={page === pagination.totalPages}
                    >
                      Next
                    </Button>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="stats" className="space-y-6">
          {/* Statistics Overview */}
          {statsLoading ? (
            <div className="flex justify-center items-center h-32">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
            </div>
          ) : stats && (
            <>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">Total Customers</CardTitle>
                    <Users className="h-4 w-4 text-muted-foreground" />
                  </CardHeader>
                  <CardContent>
                    <div className="text-2xl font-bold">{stats.overview.total_customers?.toLocaleString('en-US')}</div>
                    <p className="text-xs text-muted-foreground">All customers in system</p>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">WhatsApp Customers</CardTitle>
                    <MessageCircle className="h-4 w-4 text-green-600" />
                  </CardHeader>
                  <CardContent>
                    <div className="text-2xl font-bold text-green-600">{stats.overview.whatsapp_customers?.toLocaleString('en-US')}</div>
                    <p className="text-xs text-muted-foreground">
                      {stats.overview.total_customers > 0 ? Math.round((stats.overview.whatsapp_customers / stats.overview.total_customers) * 100) : 0}% of all customers
                    </p>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">WhatsApp Preference</CardTitle>
                    <UserCheck className="h-4 w-4 text-blue-600" />
                  </CardHeader>
                  <CardContent>
                    <div className="text-2xl font-bold text-blue-600">{stats.overview.whatsapp_preferred?.toLocaleString('en-US')}</div>
                    <p className="text-xs text-muted-foreground">Customers who prefer WhatsApp</p>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">Other Preferences</CardTitle>
                    <Calendar className="h-4 w-4 text-muted-foreground" />
                  </CardHeader>
                  <CardContent>
                    <div className="text-sm space-y-1">
                      <div className="flex justify-between">
                        <span>Email:</span>
                        <span>{stats.overview.email_preferred}</span>
                      </div>
                      <div className="flex justify-between">
                        <span>SMS:</span>
                        <span>{stats.overview.sms_preferred}</span>
                      </div>
                      <div className="flex justify-between">
                        <span>Phone:</span>
                        <span>{stats.overview.phone_preferred}</span>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </div>

              {/* Recent Activity Chart */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <TrendingUp className="w-5 h-5" />
                    Last 30 Days Activity - New WhatsApp Customers
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="h-64 flex items-end gap-2 overflow-x-auto">
                    {stats.recentActivity.map((activity, index) => (
                      <div key={index} className="flex flex-col items-center min-w-[60px]">
                        <div 
                          className="bg-green-500 w-8 rounded-t"
                          style={{ 
                            height: `${Math.max(4, (activity.new_customers / Math.max(...stats.recentActivity.map(a => a.new_customers), 1)) * 200)}px` 
                          }}
                        />
                        <div className="text-xs mt-1 text-center">
                          {new Date(activity.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                        </div>
                        <div className="text-xs font-bold text-green-600">
                          {activity.new_customers}
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </>
          )}
        </TabsContent>

        <TabsContent value="settings" className="space-y-6">
          {/* API Settings */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Settings className="w-5 h-5" />
                WhatsApp API Settings
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">

              {/* Provider Selection */}
              <div>
                <label className="text-sm font-medium mb-2 block">Service Provider</label>
                <select 
                  value={apiSettings.provider}
                  onChange={(e) => setApiSettings(prev => ({ ...prev, provider: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="twilio">Twilio WhatsApp</option>
                  <option value="whatsapp_business">WhatsApp Business API</option>
                  <option value="custom">Custom Service</option>
                </select>
              </div>

              {/* Twilio Settings */}
              {apiSettings.provider === 'twilio' && (
                <div className="space-y-4 p-4 bg-blue-50 rounded-lg">
                  <h3 className="font-medium text-blue-900 flex items-center gap-2">
                    <Key className="w-4 h-4" />
                    Twilio Settings
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="text-sm font-medium mb-1 block">Account SID</label>
                      <Input
                        value={apiSettings.twilioAccountSid}
                        onChange={(e) => setApiSettings(prev => ({ ...prev, twilioAccountSid: e.target.value }))}
                        placeholder="ACxxxxxxxxxx"
                        type="password"
                      />
                    </div>
                    <div>
                      <label className="text-sm font-medium mb-1 block">Auth Token</label>
                      <Input
                        value={apiSettings.twilioAuthToken}
                        onChange={(e) => setApiSettings(prev => ({ ...prev, twilioAuthToken: e.target.value }))}
                        placeholder="xxxxxxxxxx"
                        type="password"
                      />
                    </div>
                    <div className="md:col-span-2">
                      <label className="text-sm font-medium mb-1 block">WhatsApp Phone Number</label>
                      <Input
                        value={apiSettings.twilioWhatsAppNumber}
                        onChange={(e) => setApiSettings(prev => ({ ...prev, twilioWhatsAppNumber: e.target.value }))}
                        placeholder="whatsapp:+1234567890"
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* WhatsApp Business API Settings */}
              {apiSettings.provider === 'whatsapp_business' && (
                <div className="space-y-4 p-4 bg-green-50 rounded-lg">
                  <h3 className="font-medium text-green-900 flex items-center gap-2">
                    <MessageCircle className="w-4 h-4" />
                    WhatsApp Business API Settings
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="text-sm font-medium mb-1 block">Access Token</label>
                      <Input
                        value={apiSettings.businessApiToken}
                        onChange={(e) => setApiSettings(prev => ({ ...prev, businessApiToken: e.target.value }))}
                        placeholder="Bearer token"
                        type="password"
                      />
                    </div>
                    <div>
                      <label className="text-sm font-medium mb-1 block">Phone Number ID</label>
                      <Input
                        value={apiSettings.businessPhoneNumberId}
                        onChange={(e) => setApiSettings(prev => ({ ...prev, businessPhoneNumberId: e.target.value }))}
                        placeholder="Phone Number ID"
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* Custom API Settings */}
              {apiSettings.provider === 'custom' && (
                <div className="space-y-4 p-4 bg-purple-50 rounded-lg">
                  <h3 className="font-medium text-purple-900 flex items-center gap-2">
                    <Settings className="w-4 h-4" />
                    Custom API Settings
                  </h3>
                  <div className="space-y-4">
                    <div>
                      <label className="text-sm font-medium mb-1 block">API URL</label>
                      <Input
                        value={apiSettings.customApiUrl}
                        onChange={(e) => setApiSettings(prev => ({ ...prev, customApiUrl: e.target.value }))}
                        placeholder="https://api.example.com/whatsapp"
                      />
                    </div>
                    <div>
                      <label className="text-sm font-medium mb-1 block">API Key</label>
                      <Input
                        value={apiSettings.customApiKey}
                        onChange={(e) => setApiSettings(prev => ({ ...prev, customApiKey: e.target.value }))}
                        placeholder="Your API Key"
                        type="password"
                      />
                    </div>
                  </div>
                </div>
              )}

              <Button className="w-full flex items-center gap-2">
                <Save className="w-4 h-4" />
                Save API Settings
              </Button>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Test WhatsApp Modal */}
      <Dialog open={testModal} onOpenChange={setTestModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <TestTube className="w-5 h-5" />
              Test WhatsApp Message
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium mb-1 block">Phone Number</label>
              <Input
                value={testPhoneNumber}
                onChange={(e) => setTestPhoneNumber(e.target.value)}
                placeholder="+1234567890"
              />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Message</label>
              <Textarea
                value={testMessage}
                onChange={(e) => setTestMessage(e.target.value)}
                placeholder="Enter your test message..."
                rows={4}
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                onClick={() => setTestModal(false)}
              >
                Cancel
              </Button>
              <Button
                onClick={() => testWhatsAppMutation.mutate({ phoneNumber: testPhoneNumber, message: testMessage })}
                disabled={!testPhoneNumber || !testMessage || testWhatsAppMutation.isPending}
                className="flex items-center gap-2"
              >
                {testWhatsAppMutation.isPending ? (
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white" />
                ) : (
                  <Send className="w-4 h-4" />
                )}
                Send Test
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Bulk Message Modal */}
      <Dialog open={bulkMessageModal} onOpenChange={setBulkMessageModal}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Send className="w-5 h-5" />
              Send Bulk Message to {selectedCustomers.length} Customers
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium mb-1 block">Message</label>
              <Textarea
                value={bulkMessage}
                onChange={(e) => setBulkMessage(e.target.value)}
                placeholder="Enter your bulk message..."
                rows={6}
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                onClick={() => setBulkMessageModal(false)}
              >
                Cancel
              </Button>
              <Button
                onClick={() => bulkMessageMutation.mutate({ customerIds: selectedCustomers, message: bulkMessage })}
                disabled={!bulkMessage || bulkMessageMutation.isPending}
                className="flex items-center gap-2"
              >
                {bulkMessageMutation.isPending ? (
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white" />
                ) : (
                  <Send className="w-4 h-4" />
                )}
                Send to {selectedCustomers.length} Customers
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

