import { useState, useRef, useEffect } from "react";
import JsBarcode from "jsbarcode";
import QRCode from "qrcode";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { QrCode, BarChart3, Download, Copy, RefreshCw } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface BarcodeGeneratorProps {
  productId?: number;
  productName?: string;
  sku?: string;
  onBarcodeGenerated?: (barcode: string, type: string) => void;
  className?: string;
}

export const BarcodeGenerator: React.FC<BarcodeGeneratorProps> = ({
  productId,
  productName,
  sku,
  onBarcodeGenerated,
  className = ""
}) => {
  const [barcodeText, setBarcodeText] = useState(sku || '');
  const [barcodeFormat, setBarcodeFormat] = useState('CODE128');
  const [qrText, setQrText] = useState('');
  const [customBarcode, setCustomBarcode] = useState('');
  const [generatedBarcodes, setGeneratedBarcodes] = useState<{barcode?: string, qr?: string}>({});

  const barcodeCanvasRef = useRef<HTMLCanvasElement>(null);
  const qrCanvasRef = useRef<HTMLCanvasElement>(null);
  const { toast } = useToast();

  useEffect(() => {
    if (productId && productName) {
      // Generate default QR code data
      const qrData = JSON.stringify({
        productId,
        name: productName,
        sku: sku || `SKU${productId.toString().padStart(4, '0')}`,
        type: 'product'
      });
      setQrText(qrData);

      // Set default barcode if SKU exists
      if (sku) {
        setBarcodeText(sku);
      } else {
        setBarcodeText(`${productId.toString().padStart(10, '0')}`);
      }
    }
  }, [productId, productName, sku]);

  const generateRandomBarcode = (format: string) => {
    let code = '';
    const digits = format === 'EAN13' ? 12 : format === 'EAN8' ? 7 : 10;

    for (let i = 0; i < digits; i++) {
      code += Math.floor(Math.random() * 10);
    }

    // Add check digit for EAN codes
    if (format === 'EAN13' || format === 'EAN8') {
      const checkDigit = calculateEANCheckDigit(code);
      code += checkDigit;
    }

    return code;
  };

  const calculateEANCheckDigit = (code: string) => {
    let sum = 0;
    for (let i = 0; i < code.length; i++) {
      const digit = parseInt(code[i]);
      sum += i % 2 === 0 ? digit : digit * 3;
    }
    return (10 - (sum % 10)) % 10;
  };

  const generateBarcode = async () => {
    if (!barcodeCanvasRef.current || !barcodeText.trim()) return;

    try {
      JsBarcode(barcodeCanvasRef.current, barcodeText, {
        format: barcodeFormat,
        width: 2,
        height: 80,
        displayValue: true,
        fontSize: 12,
        textMargin: 5,
      });

      setGeneratedBarcodes(prev => ({ ...prev, barcode: barcodeText }));

      toast({
        title: "Barcode Generated",
        description: `${barcodeFormat} barcode created successfully`,
        variant: "default"
      });
    } catch (error) {
      console.error('Barcode generation error:', error);
      toast({
        title: "Generation Error",
        description: "Failed to generate barcode. Check the format and input.",
        variant: "destructive"
      });
    }
  };

  const generateQRCode = async () => {
    if (!qrCanvasRef.current || !qrText.trim()) return;

    try {
      await QRCode.toCanvas(qrCanvasRef.current, qrText, {
        width: 200,
        margin: 2,
        color: {
          dark: '#000000',
          light: '#FFFFFF'
        }
      });

      setGeneratedBarcodes(prev => ({ ...prev, qr: qrText }));

      toast({
        title: "QR Code Generated",
        description: "QR code created successfully",
        variant: "default"
      });
    } catch (error) {
      console.error('QR code generation error:', error);
      toast({
        title: "Generation Error",
        description: "Failed to generate QR code",
        variant: "destructive"
      });
    }
  };

  const downloadBarcode = (type: 'barcode' | 'qr') => {
    const canvas = type === 'barcode' ? barcodeCanvasRef.current : qrCanvasRef.current;
    if (!canvas) return;

    const link = document.createElement('a');
    link.download = `${productName || 'product'}-${type}.png`;
    link.href = canvas.toDataURL();
    link.click();
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text).then(() => {
      toast({
        title: "Copied",
        description: "Code copied to clipboard",
        variant: "default"
      });
    });
  };

  const assignToProduct = (type: 'barcode' | 'qr') => {
    const code = type === 'barcode' ? generatedBarcodes.barcode : generatedBarcodes.qr;
    if (code && onBarcodeGenerated) {
      onBarcodeGenerated(code, type === 'barcode' ? barcodeFormat : 'QR');
    }
  };

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <QrCode className="h-5 w-5" />
          Barcode Generator
          {productName && <Badge variant="outline">{productName}</Badge>}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="barcode" className="space-y-4">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="barcode">Barcode</TabsTrigger>
            <TabsTrigger value="qrcode">QR Code</TabsTrigger>
          </TabsList>

          {/* Barcode Tab */}
          <TabsContent value="barcode" className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="barcode-format">Barcode Format</Label>
                  <Select value={barcodeFormat} onValueChange={setBarcodeFormat}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="CODE128">Code 128</SelectItem>
                      <SelectItem value="CODE39">Code 39</SelectItem>
                      <SelectItem value="EAN13">EAN-13</SelectItem>
                      <SelectItem value="EAN8">EAN-8</SelectItem>
                      <SelectItem value="UPC">UPC-A</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="barcode-text">Barcode Data</Label>
                  <Input
                    id="barcode-text"
                    value={barcodeText}
                    onChange={(e) => setBarcodeText(e.target.value)}
                    placeholder="Enter barcode data"
                  />
                </div>

                <div className="flex gap-2">
                  <Button onClick={generateBarcode} className="flex-1">
                    <BarChart3 className="h-4 w-4 mr-2" />
                    Generate
                  </Button>
                  <Button 
                    variant="outline" 
                    onClick={() => setBarcodeText(generateRandomBarcode(barcodeFormat))}
                  >
                    <RefreshCw className="h-4 w-4" />
                  </Button>
                </div>

                {customBarcode && (
                  <div className="space-y-2">
                    <Label>Custom Barcode</Label>
                    <Input
                      value={customBarcode}
                      onChange={(e) => setCustomBarcode(e.target.value)}
                      placeholder="Enter custom barcode"
                    />
                    <Button 
                      variant="outline" 
                      onClick={() => setBarcodeText(customBarcode)}
                      className="w-full"
                    >
                      Use Custom Code
                    </Button>
                  </div>
                )}
              </div>

              <div className="space-y-4">
                <div className="border rounded-lg p-4 bg-white">
                  <canvas
                    ref={barcodeCanvasRef}
                    className="w-full h-auto"
                  />
                </div>

                {generatedBarcodes.barcode && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2">
                      <code className="flex-1 p-2 bg-gray-100 rounded text-sm font-mono">
                        {generatedBarcodes.barcode}
                      </code>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => copyToClipboard(generatedBarcodes.barcode!)}
                      >
                        <Copy className="h-4 w-4" />
                      </Button>
                    </div>

                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => downloadBarcode('barcode')}
                        className="flex-1"
                      >
                        <Download className="h-4 w-4 mr-2" />
                        Download
                      </Button>
                      {onBarcodeGenerated && (
                        <Button
                          size="sm"
                          onClick={() => assignToProduct('barcode')}
                          className="flex-1"
                        >
                          Assign to Product
                        </Button>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </TabsContent>

          {/* QR Code Tab */}
          <TabsContent value="qrcode" className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="qr-text">QR Code Data</Label>
                  <textarea
                    id="qr-text"
                    value={qrText}
                    onChange={(e) => setQrText(e.target.value)}
                    placeholder="Enter QR code data (URL, text, JSON, etc.)"
                    className="w-full p-2 border rounded-md resize-none"
                    rows={4}
                  />
                </div>

                <Button onClick={generateQRCode} className="w-full">
                  <QrCode className="h-4 w-4 mr-2" />
                  Generate QR Code
                </Button>

                <div className="space-y-2">
                  <Label>Quick Templates</Label>
                  <div className="grid grid-cols-1 gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setQrText(`https://example.com/product/${productId}`)}
                    >
                      Product URL
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setQrText(JSON.stringify({
                        productId,
                        name: productName,
                        sku: sku || `SKU${productId?.toString().padStart(4, '0')}`,
                        type: 'product'
                      }, null, 2))}
                    >
                      Product Info JSON
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setQrText(sku || `SKU${productId?.toString().padStart(4, '0')}`)}
                    >
                      Simple SKU
                    </Button>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <div className="border rounded-lg p-4 bg-white flex items-center justify-center">
                  <canvas
                    ref={qrCanvasRef}
                    className="max-w-full h-auto"
                  />
                </div>

                {generatedBarcodes.qr && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2">
                      <code className="flex-1 p-2 bg-gray-100 rounded text-xs font-mono max-h-20 overflow-y-auto">
                        {generatedBarcodes.qr.length > 100 
                          ? `${generatedBarcodes.qr.substring(0, 100)}...` 
                          : generatedBarcodes.qr
                        }
                      </code>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => copyToClipboard(generatedBarcodes.qr!)}
                      >
                        <Copy className="h-4 w-4" />
                      </Button>
                    </div>

                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => downloadBarcode('qr')}
                        className="flex-1"
                      >
                        <Download className="h-4 w-4 mr-2" />
                        Download
                      </Button>
                      {onBarcodeGenerated && (
                        <Button
                          size="sm"
                          onClick={() => assignToProduct('qr')}
                          className="flex-1"
                        >
                          Assign to Product
                        </Button>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </TabsContent>
        </Tabs>

        {/* Usage Instructions */}
        <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
          <h4 className="font-medium text-blue-900 mb-2">Usage Tips</h4>
          <ul className="text-sm text-blue-800 space-y-1">
            <li>• Code 128: Best for alphanumeric data, variable length</li>
            <li>• EAN-13/EAN-8: Standard retail barcodes with check digits</li>
            <li>• QR Codes: Can store URLs, JSON data, or plain text</li>
            <li>• Use "Assign to Product" to link codes to inventory items</li>
          </ul>
        </div>
      </CardContent>
    </Card>
  );
};

export default BarcodeGenerator;

client/src/components/KardexSyncPanel-ol.content:
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { 
  RefreshCw, 
  Database, 
  ArrowRight, 
  CheckCircle, 
  AlertTriangle,
  Eye
} from "lucide-react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";

interface SyncStatus {
  kardexCount: number;
  shopCount: number;
  hiddenCount: number;
  inSync: boolean;
  missingInShop: string[];
  extraInShop: string[];
}

interface SyncResult {
  added: number;
  updated: number;
  removed: number;
  unchanged: number;
  deletedFromShop?: number;
  addedToShop?: number;
  kardexProducts?: number;
}

export function KardexSyncPanel() {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isExpanded, setIsExpanded] = useState(false);

  // Get refresh interval from global settings
  const getRefreshInterval = () => {
    const globalSettings = localStorage.getItem('global-refresh-settings');
    if (globalSettings) {
      const settings = JSON.parse(globalSettings);
      const inventorySettings = settings.departments.inventory;

      if (inventorySettings?.autoRefresh) {
        const refreshInterval = settings.syncEnabled 
          ? settings.globalInterval 
          : inventorySettings.interval;
        return refreshInterval * 1000; // Convert seconds to milliseconds
      }
    }
    return 300000; // Default 5 minutes if no settings found
  };

  // Query for sync status
  const { data: syncStatus, isLoading: statusLoading, error: statusError } = useQuery({
    queryKey: ['/api/kardex-sync/status'],
    queryFn: () => apiRequest<{ data: SyncStatus }>('/api/kardex-sync/status'),
    refetchInterval: getRefreshInterval(),
    retry: false, // Don't retry on auth errors
  });

  // Smart sync mutation
  const smartSyncMutation = useMutation({
    mutationFn: () => apiRequest<{ data: SyncResult }>('/api/kardex-sync/smart-sync', {
      method: 'POST'
    }),
    onSuccess: (data) => {
      toast({
        title: "همگام‌سازی هوشمند انجام شد",
        description: `${data.data.added} اضافه، ${data.data.updated} بروزرسانی، ${data.data.removed} حذف شد`,
      });
      // فوری بروزرسانی کنید تا اعداد جدید نمایش داده شود
      queryClient.invalidateQueries({ queryKey: ['/api/kardex-sync/status'] });
      queryClient.invalidateQueries({ queryKey: ['/api/shop/products'] });
      queryClient.invalidateQueries({ queryKey: ['/api/products'] });
      // رفرش فوری وضعیت
      setTimeout(() => {
        queryClient.refetchQueries({ queryKey: ['/api/kardex-sync/status'] });
      }, 500);
      // Immediate refresh to show changes
      window.location.reload();
    },
    onError: () => {
      toast({
        title: "خطا در همگام‌سازی",
        description: "لطفاً مجدداً تلاش کنید",
        variant: "destructive",
      });
    }
  });

  // Full rebuild mutation
  const fullRebuildMutation = useMutation({
    mutationFn: () => apiRequest<{ data: SyncResult }>('/api/kardex-sync/full-rebuild', {
      method: 'POST'
    }),
    onSuccess: (data) => {
      toast({
        title: "بازسازی کامل انجام شد",
        description: `${data.data.addedToShop} محصول از کاردکس به فروشگاه کپی شد`,
      });
      // فوری بروزرسانی کنید تا اعداد جدید نمایش داده شود
      queryClient.invalidateQueries({ queryKey: ['/api/kardex-sync/status'] });
      queryClient.invalidateQueries({ queryKey: ['/api/shop/products'] });
      queryClient.invalidateQueries({ queryKey: ['/api/products'] });
      // رفرش فوری وضعیت
      setTimeout(() => {
        queryClient.refetchQueries({ queryKey: ['/api/kardex-sync/status'] });
      }, 500);
      // Immediate refresh to show changes
      window.location.reload();
    },
    onError: () => {
      toast({
        title: "خطا در بازسازی",
        description: "لطفاً مجدداً تلاش کنید",
        variant: "destructive",
      });
    }
  });

  // Cleanup extra products mutation
  const cleanupMutation = useMutation({
    mutationFn: () => apiRequest<{ data: { deletedCount: number; deletedProducts: string[] } }>('/api/kardex-sync/cleanup-extra', {
      method: 'POST'
    }),
    onSuccess: (data) => {
      toast({
        title: "حذف محصولات اضافی انجام شد",
        description: `${data.data.deletedCount} محصول از فروشگاه حذف شد`,
      });
      // فوری بروزرسانی کنید تا اعداد جدید نمایش داده شود
      queryClient.invalidateQueries({ queryKey: ['/api/kardex-sync/status'] });
      queryClient.invalidateQueries({ queryKey: ['/api/shop/products'] });
      queryClient.invalidateQueries({ queryKey: ['/api/products'] });
      // رفرش فوری وضعیت
      setTimeout(() => {
        queryClient.refetchQueries({ queryKey: ['/api/kardex-sync/status'] });
      }, 500);
      // Immediate refresh to show changes
      window.location.reload();
    },
    onError: () => {
      toast({
        title: "خطا در حذف محصولات اضافی",
        description: "لطفاً مجدداً تلاش کنید",
        variant: "destructive",
      });
    }
  });

  // Cleanup duplicate SKUs mutation
  const cleanupDuplicatesMutation = useMutation({
    mutationFn: () => apiRequest<{ data: { deletedCount: number; duplicates: Array<{sku: string; deletedProduct: string; keptProduct: string}> } }>('/api/kardex-sync/cleanup-duplicates', {
      method: 'POST'
    }),
    onSuccess: (data) => {
      toast({
        title: "حذف SKU تکراری انجام شد",
        description: `${data.data.deletedCount} محصول با SKU تکراری حذف شد`,
      });
      console.log('🔍 [SKU-CLEANUP] جزئیات:', data.data.duplicates);
      // فوری بروزرسانی کنید تا اعداد جدید نمایش داده شود
      queryClient.invalidateQueries({ queryKey: ['/api/kardex-sync/status'] });
      queryClient.invalidateQueries({ queryKey: ['/api/shop/products'] });
      queryClient.invalidateQueries({ queryKey: ['/api/products'] });
      // رفرش فوری وضعیت
      setTimeout(() => {
        queryClient.refetchQueries({ queryKey: ['/api/kardex-sync/status'] });
      }, 500);
    },
    onError: () => {
      toast({
        title: "خطا در حذف SKU تکراری",
        description: "لطفاً مجدداً تلاش کنید",
        variant: "destructive",
      });
    }
  });

  const status = syncStatus?.data;
  const isInSync = status?.inSync;
  const hasMissingProducts = status?.missingInShop?.length > 0;
  const hasExtraProducts = status?.extraInShop?.length > 0;
  const isAuthError = statusError && String(statusError).includes('احراز هویت');

  return (
    <Card className="w-full">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Database className="h-5 w-5 text-blue-600" />
            <CardTitle>همگام‌سازی کاردکس ↔ فروشگاه</CardTitle>
            {isInSync ? (
              <Badge variant="secondary" className="bg-green-100 text-green-800">
                <CheckCircle className="h-3 w-3 mr-1" />
                همگام
              </Badge>
            ) : (
              <Badge variant="destructive">
                <AlertTriangle className="h-3 w-3 mr-1" />
                نیاز به همگام‌سازی
              </Badge>
            )}
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setIsExpanded(!isExpanded)}
          >
            <Eye className="h-4 w-4" />
            {isExpanded ? 'بستن' : 'جزئیات'}
          </Button>
        </div>
        <CardDescription>
          کاردکس منبع اصلی است - فروشگاه باید همیشه کپی کاردکس باشد
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Authentication Error */}
        {isAuthError && (
          <div className="p-4 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center text-red-800 mb-2">
              <AlertTriangle className="h-4 w-4 mr-2" />
              <span className="font-medium">نیاز به ورود به پنل ادمین</span>
            </div>
            <p className="text-sm text-red-700">
              برای استفاده از سیستم همگام‌سازی، ابتدا باید وارد پنل ادمین شوید.
            </p>
            <Button 
              className="mt-3" 
              size="sm" 
              onClick={() => window.location.href = '/admin/login'}
            >
              ورود به پنل ادمین
            </Button>
          </div>
        )}

        {/* Status Overview */}
        {!isAuthError && (
          <>
            <div className="grid grid-cols-3 gap-3">
              <div className="flex items-center justify-between p-3 bg-blue-50 rounded-lg">
                <span className="text-sm font-medium">کاردکس</span>
                <span className="text-lg font-bold text-blue-600">
                  {statusLoading ? "..." : status?.kardexCount || 0}
                </span>
              </div>
              <div className="flex items-center justify-between p-3 bg-green-50 rounded-lg">
                <span className="text-sm font-medium">فروشگاه</span>
                <span className="text-lg font-bold text-green-600">
                  {statusLoading ? "..." : status?.shopCount || 0}
                </span>
              </div>
              <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                <span className="text-sm font-medium">مخفی</span>
                <span className="text-lg font-bold text-gray-600">
                  {statusLoading ? "..." : status?.hiddenCount || 0}
                </span>
              </div>
            </div>

            {/* Sync Status Hint */}
            {!statusLoading && status && (
              <div className={`p-3 rounded-lg border ${
                isInSync 
                  ? 'bg-green-50 border-green-200' 
                  : 'bg-orange-50 border-orange-200'
              }`}>
                <div className="flex items-center text-sm">
                  {isInSync ? (
                    <CheckCircle className="h-4 w-4 mr-2 text-green-600" />
                  ) : (
                    <AlertTriangle className="h-4 w-4 mr-2 text-orange-600" />
                  )}
                  <span className={isInSync ? 'text-green-700' : 'text-orange-700'}>
                    {isInSync 
                      ? `همگام‌سازی کامل: ${status.shopCount} محصول فعال + ${status.hiddenCount} محصول مخفی = ${status.kardexCount} کاردکس`
                      : `نیاز به همگام‌سازی: ${status.missingInShop?.length || 0} محصول کمبود، ${status.extraInShop?.length || 0} محصول اضافی، ${status.hiddenCount} محصول مخفی`
                    }
                  </span>
                </div>
              </div>
            )}
          </>
        )}

        {/* Sync Actions */}
        {!isAuthError && (
          <div className="space-y-2">
            <div className="flex gap-2">
              <Button
                onClick={() => smartSyncMutation.mutate()}
                disabled={smartSyncMutation.isPending || statusLoading}
                className="flex-1"
                variant={isInSync ? "secondary" : "default"}
              >
                <RefreshCw className="h-4 w-4 mr-2" />
                {smartSyncMutation.isPending ? "در حال همگام‌سازی..." : "همگام‌سازی هوشمند"}
              </Button>

              <Button
                onClick={() => fullRebuildMutation.mutate()}
                disabled={fullRebuildMutation.isPending || statusLoading}
                variant="outline"
                className="flex-1"
              >
                <RefreshCw className="h-4 w-4 mr-2" />
                {fullRebuildMutation.isPending ? "در حال بازسازی..." : "بازسازی کامل"}
              </Button>
            </div>

            {/* Cleanup Extra Products Button */}
            {hasExtraProducts && (
              <Button
                onClick={() => cleanupMutation.mutate()}
                disabled={cleanupMutation.isPending || statusLoading}
                variant="outline"
                className="w-full border-red-300 text-red-600 hover:bg-red-50"
              >
                <AlertTriangle className="h-4 w-4 mr-2" />
                {cleanupMutation.isPending ? "در حال حذف..." : `حذف ${status?.extraInShop?.length || 0} محصول اضافی از فروشگاه`}
              </Button>
            )}

            {/* دکمه حذف SKU تکراری */}
            <Button
              onClick={() => cleanupDuplicatesMutation.mutate()}
              disabled={cleanupDuplicatesMutation.isPending || statusLoading}
              variant="outline"
              className="w-full border-orange-300 text-orange-600 hover:bg-orange-50"
            >
              <AlertTriangle className="h-4 w-4 mr-2" />
              {cleanupDuplicatesMutation.isPending ? "در حال بررسی SKU تکراری..." : "بررسی و حذف SKU تکراری"}
            </Button>
          </div>
        )}

        {/* Detailed Status (Expandable) */}
        {!isAuthError && isExpanded && status && (
          <>
            <Separator />
            <div className="space-y-3">
              {hasMissingProducts && (
                <div className="p-3 bg-orange-50 rounded-lg">
                  <h4 className="font-medium text-orange-800 mb-2">
                    محصولات موجود در کاردکس ولی غایب در فروشگاه ({status.missingInShop.length})
                  </h4>
                  <div className="space-y-1">
                    {status.missingInShop.slice(0, 3).map((name, index) => (
                      <div key={index} className="text-sm text-orange-700 flex items-center">
                        <ArrowRight className="h-3 w-3 mr-1" />
                        {name}
                      </div>
                    ))}
                    {status.missingInShop.length > 3 && (
                      <div className="text-sm text-orange-600 font-medium">
                        و {status.missingInShop.length - 3} محصول دیگر...
                      </div>
                    )}
                  </div>
                </div>
              )}

              {hasExtraProducts && (
                <div className="p-3 bg-red-50 rounded-lg">
                  <h4 className="font-medium text-red-800 mb-2">
                    محصولات اضافی در فروشگاه که در کاردکس نیستند ({status.extraInShop.length})
                  </h4>
                  <div className="space-y-1">
                    {status.extraInShop.slice(0, 3).map((name, index) => (
                      <div key={index} className="text-sm text-red-700 flex items-center">
                        <ArrowRight className="h-3 w-3 mr-1" />
                        {name}
                      </div>
                    ))}
                    {status.extraInShop.length > 3 && (
                      <div className="text-sm text-red-600 font-medium">
                        و {status.extraInShop.length - 3} محصول دیگر...
                      </div>
                    )}
                  </div>
                </div>
              )}

              {isInSync && (
                <div className="p-3 bg-green-50 rounded-lg">
                  <div className="flex items-center text-green-800">
                    <CheckCircle className="h-4 w-4 mr-2" />
                    <span className="font-medium">همه چیز همگام است!</span>
                  </div>
                  <p className="text-sm text-green-700 mt-1">
                    فروشگاه کاملاً با کاردکس هماهنگ است
                  </p>
                </div>
              )}
            </div>
          </>
        )}

        {/* Help Text */}
        {!isAuthError && (
          <div className="text-xs text-gray-500 bg-gray-50 p-3 rounded-lg">
            <strong>همگام‌سازی هوشمند:</strong> فقط تغییرات را اعمال می‌کند<br />
            <strong>بازسازی کامل:</strong> فروشگاه را پاک کرده و از کاردکس بازسازی می‌کند
          </div>
        )}
      </CardContent>
    </Card>
  );
}

