import puppeteer from 'puppeteer';
import { format } from 'date-fns';

interface CustomerAnalytics {
  totalCustomers: number;
  activeCustomers: number;
  newCustomersThisMonth: number;
  totalRevenue: number;
  averageOrderValue: number;
  topCustomers: Array<{
    id: number;
    name: string;
    email: string;
    totalSpent: number;
    totalOrders: number;
  }>;
  customersByType: Array<{
    type: string;
    count: number;
  }>;
  recentActivities: Array<{
    id: number;
    activityType: string;
    description: string;
    performedBy: string;
    createdAt: string;
  }>;
}

export async function generateCustomerAnalyticsPDF(analytics: CustomerAnalytics): Promise<Buffer> {
  console.log('Starting analytics PDF generation...');
  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium',
    args: [
      '--no-sandbox', 
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
      '--no-first-run',
      '--no-zygote',
      '--single-process',
      '--disable-extensions'
    ]
  });

  try {
    const page = await browser.newPage();

    const html = generateAnalyticsHTML(analytics);
    await page.setContent(html, { 
      waitUntil: 'networkidle0',
      timeout: 30000 
    });

    await page.waitForTimeout(1000);

    const pdf = await page.pdf({
      format: 'A4',
      printBackground: true,
      preferCSSPageSize: false,
      displayHeaderFooter: false,
      margin: {
        top: '20mm',
        right: '15mm',
        bottom: '20mm',
        left: '15mm'
      },
      tagged: true,
      waitForFonts: true
    });

    return pdf;
  } finally {
    await browser.close();
  }
}

function generateAnalyticsHTML(analytics: CustomerAnalytics): string {
  const currentDate = format(new Date(), 'MMMM dd, yyyy');
  const generatedTime = format(new Date(), 'HH:mm:ss');

  return `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <title>Customer Analytics Report</title>
      <style>
        * {
          margin: 0;
          padding: 0;
          box-sizing: border-box;
        }

        body {
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
          line-height: 1.6;
          color: #333;
          background: white;
        }

        .header {
          background: linear-gradient(135deg, #1e40af 0%, #3b82f6 100%);
          color: white;
          padding: 30px;
          text-align: center;
          margin-bottom: 30px;
        }

        .header h1 {
          font-size: 28px;
          margin-bottom: 8px;
          font-weight: 600;
        }

        .header .subtitle {
          font-size: 16px;
          opacity: 0.9;
        }

        .report-info {
          background: #f8fafc;
          padding: 20px;
          border-radius: 8px;
          margin-bottom: 30px;
          border-left: 4px solid #3b82f6;
        }

        .report-info h2 {
          color: #1e40af;
          margin-bottom: 10px;
          font-size: 18px;
        }

        .info-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 15px;
        }

        .info-item {
          display: flex;
          justify-content: space-between;
          padding: 8px 0;
