export async function generateCustomerDetailPDF(customer: any, analytics: any, activities: any[]): Promise<Buffer> {
  console.log('Starting customer detail PDF generation for:', customer?.firstName, customer?.lastName);
  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium',
    args: [
      '--no-sandbox', 
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
      '--no-first-run',
      '--no-zygote',
      '--single-process',
      '--disable-extensions'
    ]
  });

  try {
    const page = await browser.newPage();

    const html = generateCustomerDetailHTML(customer, analytics, activities);
    await page.setContent(html, { 
      waitUntil: 'networkidle0',
      timeout: 30000 
    });

    await page.waitForTimeout(1000);

    const pdf = await page.pdf({
      format: 'A4',
      printBackground: true,
      preferCSSPageSize: false,
      displayHeaderFooter: false,
      margin: {
        top: '20mm',
        right: '15mm',
        bottom: '20mm',
        left: '15mm'
      },
      tagged: true,
      waitForFonts: true
    });

    return pdf;
  } finally {
    await browser.close();
  }
}

