                                    onClick={() => handleOrderAction(order.id, 'warehouse_processing')}
                                    disabled={loadingOrderId === order.id}
                                    className="bg-orange-500 hover:bg-orange-600 text-xs"
                                  >
                                    <Package className="w-4 h-4 mr-1" />
                                    {loadingOrderId === order.id ? 'در حال پردازش...' : 'شروع پردازش'}
                                  </Button>
                                )}
                                {order.currentStatus === 'warehouse_processing' && (
                                  <Button
                                    size="sm"
                                    variant="default"
                                    onClick={() => handleOrderAction(order.id, 'warehouse_verified')}
                                    disabled={loadingOrderId === order.id}
                                    className="bg-blue-500 hover:bg-blue-600 text-xs"
                                  >
                                    <CheckCircle className="w-4 h-4 mr-1" />
                                    {loadingOrderId === order.id ? 'در حال تایید...' : 'تایید مرحله اول'}
                                  </Button>
                                )}
                                {order.currentStatus === 'warehouse_verified' && (
                                  <Button
                                    size="sm"
                                    variant="default"
                                    onClick={() => handleOrderAction(order.id, 'warehouse_approved')}
                                    disabled={loadingOrderId === order.id}
                                    className="bg-green-500 hover:bg-green-600 text-xs"
                                  >
                                    <CheckCircle className="w-4 h-4 mr-1" />
                                    {loadingOrderId === order.id ? 'در حال تایید...' : 'تایید نهایی'}
                                  </Button>
                                )}
                                {order.currentStatus === 'warehouse_approved' && (
                                  <Button
                                    size="sm"
                                    variant="default"
                                    onClick={() => handleOrderAction(order.id, 'logistics_dispatched')}
                                    disabled={loadingOrderId === order.id}
                                    className="bg-blue-500 hover:bg-blue-600 text-xs"
                                  >
                                    <Truck className="w-4 h-4 mr-1" />
                                    {loadingOrderId === order.id ? 'در حال ارسال...' : 'ارسال به لجستیک'}
                                  </Button>
                                )}
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>

        {/* Order Details Modal - Using SafeModal (No React Portal Issues) */}
        <SafeModal
          isOpen={showOrderDetails}
          onClose={() => setShowOrderDetails(false)}
          title={`جزئیات سفارش ${selectedOrder?.orderNumber || `#${selectedOrder?.customerOrderId}` || ''}`}
          maxWidth="max-w-4xl"
          maxHeight="max-h-[80vh]"
        >
            {loadingOrderDetails ? (
              <div className="text-center py-8">
                <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                <p className="mt-4 text-gray-600">در حال بارگیری جزئیات سفارش...</p>
              </div>
            ) : orderDetails ? (
              <div className="space-y-6">
                {/* Customer Information */}
                <div>
                  <h3 className="font-semibold mb-3 text-lg">اطلاعات مشتری</h3>
                  <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-lg">
                    <div>
                      <Label className="text-sm font-medium text-gray-700">نام مشتری</Label>
                      <p className="text-sm mt-1 font-medium">{
                        orderDetails.customer?.firstName && orderDetails.customer?.lastName 
                          ? `${orderDetails.customer.firstName} ${orderDetails.customer.lastName}` 
                          : 'نامشخص'
                      }</p>
                    </div>
                    <div>
                      <Label className="text-sm font-medium text-gray-700">شماره موبایل</Label>
                      <p className="text-sm mt-1 font-medium">{orderDetails.customer?.phone || 'شماره نامشخص'}</p>
                    </div>
                    <div>
                      <Label className="text-sm font-medium text-gray-700">ایمیل</Label>
                      <p className="text-sm mt-1 font-medium">{orderDetails.customer?.email || 'ایمیل نامشخص'}</p>
                    </div>
                    <div>
                      <Label className="text-sm font-medium text-gray-700">مبلغ کل</Label>
                      <p className="text-sm mt-1 font-medium text-green-600">{formatCurrency(parseFloat(orderDetails.totalAmount) || 0)}</p>
                    </div>
                  </div>
                </div>

                {/* Order Summary */}
                <div>
                  <h3 className="font-semibold mb-3 text-lg">خلاصه سفارش</h3>
                  <div className="grid grid-cols-3 gap-4 bg-blue-50 p-4 rounded-lg">
                    <div className="text-center">
                      <Label className="text-sm font-medium text-gray-700">تعداد آیتم‌ها</Label>
                      <p className="text-2xl font-bold text-blue-600">{orderDetails.totalItems}</p>
                    </div>
                    <div className="text-center">
                      <Label className="text-sm font-medium text-gray-700">مجموع وزن ناخالص</Label>
                      <p className="text-2xl font-bold text-blue-600">{orderDetails.totalWeight ? `${parseFloat(orderDetails.totalWeight).toFixed(1)} kg` : 'محاسبه نشده'}</p>
                    </div>
                    <div className="text-center">
                      <Label className="text-sm font-medium text-gray-700">تاریخ سفارش</Label>
                      <p className="text-sm font-medium text-gray-900">{new Date(orderDetails.orderDate).toLocaleDateString('en-GB')}</p>
                    </div>
                  </div>
                </div>

                {/* Order Items */}
                <div>
                  <h3 className="font-semibold mb-3 text-lg">آیتم‌های سفارش</h3>
                  <div className="border rounded-lg overflow-hidden">
                    <table className="w-full border-collapse" style={{ tableLayout: 'fixed' }}>
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="text-right p-3 text-sm font-medium text-gray-700" style={{ width: '35%' }}>نام محصول</th>
                          <th className="text-right p-3 text-sm font-medium text-gray-700" style={{ width: '20%' }}>کد محصول</th>
                          <th className="text-center p-3 text-sm font-medium text-gray-700" style={{ width: '15%' }}>تعداد</th>
                          <th className="text-right p-3 text-sm font-medium text-gray-700" style={{ width: '15%' }}>قیمت واحد</th>
                          <th className="text-right p-3 text-sm font-medium text-gray-700" style={{ width: '15%' }}>قیمت کل</th>
                        </tr>
                      </thead>
                      <tbody>
                        {orderDetails.items?.map((item: any, index: number) => (
                          <tr key={item.id} className={index % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                            <td className="p-3 text-sm truncate" style={{ width: '35%' }} title={item.productName}>{item.productName}</td>
                            <td className="p-3 text-sm font-mono text-gray-600 truncate" style={{ width: '20%' }} title={item.productSku}>{item.productSku}</td>
                            <td className="p-3 text-sm text-center font-medium" style={{ width: '15%' }}>{item.quantity}</td>
                            <td className="p-3 text-sm truncate" style={{ width: '15%' }}>{formatCurrency(parseFloat(item.unitPrice) || 0)}</td>
                            <td className="p-3 text-sm font-medium truncate" style={{ width: '15%' }}>{formatCurrency(parseFloat(item.totalPrice) || 0)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>

                {/* Order Status */}
                <div>
                  <h3 className="font-semibold mb-3 text-lg">وضعیت سفارش</h3>
                  <div className="grid grid-cols-3 gap-4">
                    <div className={`p-3 rounded-lg border ${orderDetails.financialApproved ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}`}>
                      <div className="flex items-center gap-2">
                        {orderDetails.financialApproved ? (
                          <CheckCircle className="w-5 h-5 text-green-600" />
                        ) : (
                          <Clock className="w-5 h-5 text-gray-400" />
                        )}
                        <span className={`text-sm font-medium ${orderDetails.financialApproved ? 'text-green-800' : 'text-gray-600'}`}>
                          تایید مالی
                        </span>
                      </div>
                    </div>
                    <div className={`p-3 rounded-lg border ${orderDetails.warehouseProcessed ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}`}>
                      <div className="flex items-center gap-2">
                        {orderDetails.warehouseProcessed ? (
                          <CheckCircle className="w-5 h-5 text-green-600" />
                        ) : (
                          <Clock className="w-5 h-5 text-gray-400" />
                        )}
                        <span className={`text-sm font-medium ${orderDetails.warehouseProcessed ? 'text-green-800' : 'text-gray-600'}`}>
                          پردازش انبار
                        </span>
                      </div>
                    </div>
                    <div className={`p-3 rounded-lg border ${orderDetails.logisticsProcessed ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}`}>
                      <div className="flex items-center gap-2">
                        {orderDetails.logisticsProcessed ? (
                          <CheckCircle className="w-5 h-5 text-green-600" />
                        ) : (
                          <Clock className="w-5 h-5 text-gray-400" />
                        )}
                        <span className={`text-sm font-medium ${orderDetails.logisticsProcessed ? 'text-green-800' : 'text-gray-600'}`}>
                          پردازش لجستیک
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Order Notes */}
                <div>
                  <Label htmlFor="warehouseNotes">یادداشت انبار</Label>
                  <Textarea
                    id="warehouseNotes"
                    value={warehouseNotes}
                    onChange={(e) => setWarehouseNotes(e.target.value)}
                    placeholder="یادداشت برای این سفارش..."
                    className="mt-2"
                  />
                  <div className="flex justify-end mt-2">
                    <Button
                      size="sm"
                      onClick={handleSaveNotes}
                      disabled={saveNotesMutation.isPending}
                      className="bg-blue-600 hover:bg-blue-700"
                    >
                      {saveNotesMutation.isPending ? 'در حال ذخیره...' : 'ذخیره یادداشت'}
                    </Button>
                  </div>
                </div>

                {/* Actions */}
                <div className="flex justify-end gap-3">
                  <Button
                    variant="outline"
                    onClick={() => setShowOrderDetails(false)}
                  >
                    انصراف
                  </Button>
                  <Button
                    variant="outline"
                    onClick={handlePrintOrder}
                    className="bg-blue-50 hover:bg-blue-100 text-blue-700 border-blue-200"
                  >
                    <Printer className="w-4 h-4 mr-1" />
                    پرینت جزئیات
                  </Button>
                  {selectedOrder?.currentStatus === 'warehouse_approved' && (
                    <Button
                      onClick={() => handleOrderAction(selectedOrder.id, 'logistics_dispatched')}
                      disabled={loadingOrderId === selectedOrder.id}
                    >
                      <Truck className="w-4 h-4 mr-1" />
                      {loadingOrderId === selectedOrder.id ? 'در حال ارسال...' : 'ارسال به لجستیک'}
                    </Button>
                  )}
                </div>
              </div>
            ) : (
              <div className="text-center py-8">
                <p className="text-gray-600">خطا در بارگیری جزئیات سفارش</p>
              </div>
            )}
        </SafeModal>
      </div>
    </div>
  );
};

export default WarehouseManagementFixed;

client/src/components/admin/VehicleTempl.content:
/**
 * Vehicle Template Editor Component
 * Allows editing and modification of existing vehicle patterns/templates
 * for the optimization algorithm system
 */
import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Form, FormControl, FormDescription, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";

import { Edit3, Truck, Save, X, Plus, Settings, AlertTriangle, CheckCircle, Trash2 } from "lucide-react";
import { VehicleTemplate } from "@shared/logistics-schema";
import { apiRequest } from "@/lib/queryClient";

// Vehicle Template editing schema
const vehicleTemplateSchema = z.object({
  name: z.string().min(2, "نام باید حداقل 2 کاراکتر باشد"),
  nameEn: z.string().optional(),
  vehicleType: z.string().min(1, "نوع خودرو باید انتخاب شود"),
  maxWeightKg: z.string().refine((val) => !isNaN(Number(val)) && Number(val) > 0, "وزن باید عدد مثبت باشد"),
  maxVolumeM3: z.string().optional(),
  allowedRoutes: z.array(z.string()).min(1, "حداقل یک نوع مسیر را انتخاب کنید"),
  basePrice: z.string().refine((val) => !isNaN(Number(val)) && Number(val) >= 0, "قیمت پایه باید عدد مثبت باشد"),
  pricePerKm: z.string().refine((val) => !isNaN(Number(val)) && Number(val) >= 0, "قیمت هر کیلومتر باید عدد مثبت باشد"),
  pricePerKg: z.string().refine((val) => !isNaN(Number(val)) && Number(val) >= 0, "قیمت هر کیلوگرم باید عدد مثبت باشد"),
  supportsHazardous: z.boolean(),
  supportsFlammable: z.boolean(),
  supportsRefrigerated: z.boolean(),
  supportsFragile: z.boolean(),
  notAllowedFlammable: z.boolean(),
  averageSpeedKmh: z.string().refine((val) => !isNaN(Number(val)) && Number(val) > 0, "سرعت متوسط باید عدد مثبت باشد"),
  isActive: z.boolean(),
  priority: z.string().refine((val) => !isNaN(Number(val)) && Number(val) >= 0, "اولویت باید عدد مثبت باشد")
});

type VehicleTemplateForm = z.infer<typeof vehicleTemplateSchema>;

const VEHICLE_TYPES = {
  passenger_bus: "اتوبوس مسافربری",
  city_bus: "اتوبوس شهری",
  heavy_truck: "کامیون سنگین",
  medium_truck: "کامیون متوسط",
  light_pickup: "وانت سبک",
  light_van: "ون سبک",
  motorcycle: "موتورسیکلت",
  passenger_car: "خودرو سواری",
  trailer: "تریلر",
  tractor: "کشنده",
  van: "ون",
  light_truck: "کامیون سبک", 
  mini_truck: "کامیون کوچک",
  pickup: "وانت",
  semi_trailer: "نیم تریلر",
  flatbed: "کامیون بار باز",
  refrigerated_truck: "کامیون یخچالی",
  tanker: "تانکر",
  crane_truck: "کامیون جرثقیل",
  dump_truck: "کامیون کمپرسی",
  garbage_truck: "کامیون زباله",
  fire_truck: "ماشین آتش‌نشانی",
  ambulance: "آمبولانس",
  tow_truck: "یدک‌کش",
  bus: "اتوبوس",
  minibus: "مینی‌بوس",
  taxi: "تاکسی",
  bicycle: "دوچرخه",
  electric_scooter: "اسکوتر برقی",
  drone: "پهپاد حمل کالا"
};

const ROUTE_TYPES = {
  urban: "شهری",
  interurban: "بین شهری",
  highway: "آزادراه"
};

interface VehicleTemplateEditorProps {
  className?: string;
}

export default function VehicleTemplateEditor({ className = "" }: VehicleTemplateEditorProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [editingTemplate, setEditingTemplate] = useState<VehicleTemplate | null>(null);

  // State for add dialog
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [allowedRoutes, setAllowedRoutes] = useState<string[]>(['urban']);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [selectedRoutes, setSelectedRoutes] = useState<string[]>([]);

  // Fetch vehicle templates
  const { data: templatesData, isLoading, error } = useQuery({
    queryKey: ['/api/logistics/vehicle-templates'],
    queryFn: () => apiRequest({ url: '/api/logistics/vehicle-templates' })
  });

  const templates: VehicleTemplate[] = templatesData?.templates || [];

  // Form setup
  const form = useForm<VehicleTemplateForm>({
    resolver: zodResolver(vehicleTemplateSchema),
    defaultValues: {
      name: "",
      nameEn: "",
      vehicleType: "",
      maxWeightKg: "1000",
      maxVolumeM3: "10",
      allowedRoutes: ["urban"],
      basePrice: "50000",
      pricePerKm: "1000",
      pricePerKg: "500",
      supportsHazardous: false,
      supportsFlammable: false,
      supportsRefrigerated: false,
      supportsFragile: true,
      notAllowedFlammable: false,
      averageSpeedKmh: "50",
      isActive: true,
      priority: "0"
    }
  });

  // Add vehicle template mutation
  const addTemplateMutation = useMutation({
    mutationFn: (data: any) => 
      apiRequest({ 
        url: '/api/logistics/vehicle-templates', 
        method: 'POST', 
        data 
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/vehicle-templates'] });
      setIsAddDialogOpen(false);
      form.reset();
      setAllowedRoutes(['urban']);
      toast({ 
        title: "موفقیت", 
        description: "الگوی خودرو جدید با موفقیت اضافه شد" 
      });
    },
    onError: (error: any) => {
      toast({ 
        title: "خطا", 
        description: error?.message || "خطا در اضافه کردن الگوی خودرو", 
        variant: "destructive" 
      });
    }
  });

  // Update vehicle template mutation
  const updateTemplateMutation = useMutation({
    mutationFn: ({ id, data }: { id: number; data: Partial<VehicleTemplate> }) => 
      apiRequest({ 
        url: `/api/logistics/vehicle-templates/${id}`, 
        method: 'PUT', 
        data 
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/vehicle-templates'] });
      setIsEditDialogOpen(false);
      setEditingTemplate(null);
      toast({ 
        title: "موفقیت", 
        description: "الگوی خودرو با موفقیت بروزرسانی شد" 
      });
    },
    onError: (error: any) => {
      toast({ 
        title: "خطا", 
        description: error?.message || "خطا در بروزرسانی الگوی خودرو", 
        variant: "destructive" 
      });
    }
  });

  // Delete vehicle template mutation
  const deleteTemplateMutation = useMutation({
    mutationFn: (id: number) => 
      apiRequest({ 
        url: `/api/logistics/vehicle-templates/${id}`, 
        method: 'DELETE' 
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/vehicle-templates'] });
      toast({ 
        title: "موفقیت", 
        description: "الگوی خودرو حذف شد" 
      });
    },
    onError: (error: any) => {
      toast({ 
        title: "خطا", 
        description: error?.message || "خطا در حذف الگوی خودرو", 
        variant: "destructive" 
      });
    }
  });

  // Handle add new template
  const onAdd = (formData: VehicleTemplateForm) => {
    const submitData = {
      ...formData,
      allowedRoutes,
      maxWeightKg: parseInt(formData.maxWeightKg),
      maxVolumeM3: parseFloat(formData.maxVolumeM3) || undefined,
      basePrice: parseInt(formData.basePrice),
      pricePerKm: parseInt(formData.pricePerKm),
      pricePerKg: parseInt(formData.pricePerKg) || undefined,
      averageSpeedKmh: parseInt(formData.averageSpeedKmh),
      priority: parseInt(formData.priority) || 0,
    };

    addTemplateMutation.mutate(submitData);
  };

  // Open edit dialog
  const handleEdit = (template: VehicleTemplate) => {
    setEditingTemplate(template);
    setSelectedRoutes(template.allowedRoutes || []);

    // Populate form with existing data
    form.reset({
      name: template.name,
      nameEn: template.nameEn || "",
      vehicleType: template.vehicleType as any,
      maxWeightKg: template.maxWeightKg.toString(),
      maxVolumeM3: template.maxVolumeM3?.toString() || "",
      allowedRoutes: template.allowedRoutes || [],
      basePrice: template.basePrice.toString(),
      pricePerKm: template.pricePerKm.toString(),
      pricePerKg: template.pricePerKg?.toString() || "0",
      supportsHazardous: template.supportsHazardous || false,
      supportsFlammable: template.supportsFlammable || false,
      supportsRefrigerated: template.supportsRefrigerated || false,
      supportsFragile: template.supportsFragile !== false,
      notAllowedFlammable: (template as any).notAllowedFlammable || false,
      averageSpeedKmh: template.averageSpeedKmh?.toString() || "50",
      isActive: template.isActive !== false,
      priority: template.priority?.toString() || "0"
    });

    setIsEditDialogOpen(true);
  };

  // Handle route selection
  const handleRouteToggle = (routeType: string) => {
    const newRoutes = selectedRoutes.includes(routeType)
      ? selectedRoutes.filter(r => r !== routeType)
      : [...selectedRoutes, routeType];

    setSelectedRoutes(newRoutes);
    form.setValue('allowedRoutes', newRoutes);
  };

  // Submit form
  const onSubmit = (data: VehicleTemplateForm) => {
    if (!editingTemplate) return;

    const updateData = {
      ...data,
      maxWeightKg: parseFloat(data.maxWeightKg),
      maxVolumeM3: data.maxVolumeM3 ? parseFloat(data.maxVolumeM3) : null,
      basePrice: parseFloat(data.basePrice),
      pricePerKm: parseFloat(data.pricePerKm),
      pricePerKg: parseFloat(data.pricePerKg),
      averageSpeedKmh: parseFloat(data.averageSpeedKmh),
      priority: parseInt(data.priority),
      allowedRoutes: selectedRoutes
    };

    updateTemplateMutation.mutate({ id: editingTemplate.id, data: updateData });
  };

  // Handle delete
  const handleDelete = (template: VehicleTemplate) => {
    if (confirm(`آیا از حذف الگوی "${template.name}" مطمئن هستید؟`)) {
      deleteTemplateMutation.mutate(template.id);
    }
  };

  // Loading state
  if (isLoading) {
    return (
      <div className={`space-y-4 ${className}`} dir="rtl">
        {[1, 2, 3].map(i => (
          <Card key={i} className="animate-pulse">
            <CardContent className="p-6">
              <div className="h-4 bg-gray-200 rounded w-1/3 mb-2"></div>
              <div className="h-3 bg-gray-200 rounded w-1/2"></div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className={`text-center py-8 ${className}`} dir="rtl">
        <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-600">خطا در بارگذاری الگوهای خودرو</p>
      </div>
    );
  }

  return (
    <div className={`space-y-6 ${className}`} dir="rtl">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold flex items-center gap-2">
            <Settings className="h-6 w-6" />
            ویرایش الگوهای خودرو
          </h2>
          <p className="text-muted-foreground">
            تغییر و بروزرسانی الگوهای موجود برای سیستم انتخاب بهینه وسیله نقلیه
          </p>
        </div>

