      if (metadata?.messageId) updateData.smsMessageId = metadata.messageId;
      if (metadata?.provider) updateData.smsProvider = metadata.provider;
    }

    const [code] = await db
      .update(deliveryVerificationCodes)
      .set(updateData)
      .where(eq(deliveryVerificationCodes.id, id))
      .returning();

    return code;
  }

