${verificationCode}
این کد را هنگام تحویل به پیک اعلام کنید.
ممتازکم - Momtazchem`;

    const [updatedCode] = await db
      .update(deliveryVerificationCodes)
      .set({
        verificationCode,
        smsMessage,
        expiresAt,
        smsStatus: 'pending',
        smsSentAt: null,
        updatedAt: new Date()
      })
      .where(eq(deliveryVerificationCodes.id, existingCode.id))
      .returning();

    return updatedCode;
  }

