                          <Input {...field} type="number" placeholder="تعداد روز" onChange={(e) => field.onChange(e.target.value ? Number(e.target.value) : undefined)} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <FormField
                  control={shippingRateForm.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
