                  <Button type="button" variant="outline" onClick={() => setShippingRateDialogOpen(false)}>
                    انصراف
                  </Button>
                  <Button type="submit" disabled={saveShippingRateMutation.isPending}>
                    {saveShippingRateMutation.isPending ? "در حال ذخیره..." : "ذخیره"}
                  </Button>
                </div>
              </form>
            </Form>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
}

