                        <strong>CC:</strong> info@momtazchem.com (automatic archive)
                      </p>
                      {selectedLog.category_key && selectedLog.category_key !== 'admin' && (
                        <p className="text-sm bg-orange-50 p-2 rounded text-orange-800">
