                      </label>
                    </div>
                  </div>

                  {/* Website Text Edit */}
                  <div className="space-y-3">
                    <h4 className="font-medium text-gray-900">تنظیمات وب‌سایت</h4>

                    <div>
                      <label htmlFor="websiteText" className="text-sm font-medium text-gray-700 block mb-1">
