                              onClick={() => product.msdsUrl && window.open(product.msdsUrl, '_blank')}
                            >
                              <FileText className="w-3 h-3 text-white" />
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </CardContent>
                  </Card>
