                                    onCheckedChange={field.onChange}
                                  />
                                </FormControl>
                              </FormItem>
                            )}
                          />

                          <FormField
                            control={form.control}
                            name="msdsUrl"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="text-sm text-gray-600">{t.productManagement.msdsURL}</FormLabel>
