                                  />
                                </FormControl>
                              </FormItem>
                            )}
                          />

                          {/* MSDS action buttons */}
                          <div className="flex items-center gap-2">
                            {form.watch('msdsUrl') && (
                              <Button
                                type="button"
                                variant="outline"
                                size="sm"
                                className="text-blue-600 border-blue-300 hover:bg-blue-50"
                                onClick={() => window.open(form.getValues('msdsUrl'), '_blank')}
                              >
                                <Eye className="w-4 h-4 mr-1" />
                                {t.productManagement.viewMSDS}
                              </Button>
                            )}

                            <div className="relative">
                              <Button
                                type="button"
                                variant="outline"
                                size="sm"
                                className="text-orange-600 border-orange-300 hover:bg-orange-50"
                                onClick={() => {
                                  const fileInput = document.querySelector('#msds-upload-btn') as HTMLInputElement;
                                  fileInput?.click();
                                }}
                              >
                                <FileText className="w-4 h-4 mr-1" />
                                {t.productManagement.uploadMSDS}
                              </Button>
                              <input
                                id="msds-upload-btn"
                                type="file"
                                accept="application/pdf"
                                className="hidden"
                                onChange={(e) => {
                                  const file = e.target.files?.[0];
                                  if (file) {
                                    handleMsdsUpload(file);
                                    e.target.value = ''; // Reset input
                                  }
                                }}
                              />
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                    )}
                  </div>
                </div>

                <div className="flex justify-end gap-3 pt-4 border-t">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => {
                      setDialogOpen(false);
                      setEditingProduct(null);
                      form.reset();
                    }}
                    className="px-6"
                  >
                    {t.productManagement.cancel}
                  </Button>
                  <Button 
                    type="submit" 
                    disabled={isSubmitting}
                    className="px-6 bg-blue-600 hover:bg-blue-700"
                  >
                    {isSubmitting && <RefreshCw className="mr-2 h-4 w-4 animate-spin" />}
