                    toast({
                      title: "ترتیب بازنشانی شد",
                      description: "ترتیب بلوک‌های مدیریتی به حالت اولیه بازگشت",
                    });
                  }}
                  className="text-gray-500 hover:text-gray-700"
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
