import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { FileText, Download } from 'lucide-react';
import pdfMake from 'pdfmake/build/pdfmake';
import pdfFonts from 'pdfmake/build/vfs_fonts';
// Import Vazir fonts from client lib
import { vazirRegular, vazirBold } from '@/lib/vazir-fonts';

// Initialize pdfMake with Vazir fonts
pdfMake.vfs = pdfFonts.pdfMake?.vfs || {};

// Add Vazir fonts to VFS
pdfMake.vfs['Vazir-Regular.ttf'] = vazirRegular;
pdfMake.vfs['Vazir-Bold.ttf'] = vazirBold;

// Configure fonts
pdfMake.fonts = {
  Vazir: {
    normal: 'Vazir-Regular.ttf',
    bold: 'Vazir-Bold.ttf',
    italics: 'Vazir-Regular.ttf',
    bolditalics: 'Vazir-Bold.ttf'
  }
};

interface PDFGeneratorProps {
  title?: string;
  showInvoiceGenerator?: boolean;
  showCustomerReport?: boolean;
}

export default function PDFGenerator({ 
  title = "PDF Generator", 
  showInvoiceGenerator = true,
  showCustomerReport = false 
}: PDFGeneratorProps) {
  const [invoiceData, setInvoiceData] = useState({
    invoiceNumber: 'INV-001',
    customerName: 'نام مشتری',
    customerEmail: 'customer@example.com',
    customerPhone: '0912xxxxxxx',
    items: [
      { name: 'محصول نمونه', quantity: 1, unitPrice: 100000 }
    ],
    totalAmount: 100000
  });

  const [isGenerating, setIsGenerating] = useState(false);

  function handleDownloadPDF() {
    setIsGenerating(true);

    try {
      const docDefinition: any = {
        defaultStyle: {
          fontSize: 10
        },
        content: [
          // Header
          {
            text: 'فاکتور فروش - Momtaz Chem',
            fontSize: 20,
            bold: true,
            alignment: 'center',
            margin: [0, 0, 0, 20]
          },
          {
            text: 'شرکت مواد شیمیایی ممتاز',
            fontSize: 14,
            font: 'Vazir',
            alignment: 'center',
            margin: [0, 0, 0, 30]
          },

          // Invoice Details
          {
            columns: [
              {
                width: '50%',
                text: `شماره فاکتور: ${invoiceData.invoiceNumber}`,
                font: 'Vazir',
                fontSize: 12,
                alignment: 'right'
              },
              {
                width: '50%',
                text: `تاریخ: ${new Date().toLocaleDateString('fa-IR')}`,
                font: 'Vazir',
                fontSize: 12,
                alignment: 'left'
              }
            ],
            margin: [0, 0, 0, 20]
          },

          // Customer Information
          {
            text: 'اطلاعات مشتری',
            fontSize: 14,
            bold: true,
            margin: [0, 0, 0, 10]
          },
          {
            table: {
              widths: ['25%', '75%'],
              body: [
                ['نام مشتری:', invoiceData.customerName],
                ['ایمیل:', invoiceData.customerEmail],
                ['شماره تماس:', invoiceData.customerPhone]
              ]
            },
            layout: 'lightHorizontalLines',
            margin: [0, 0, 0, 20]
          },

          // Items Table
          {
            text: 'اقلام سفارش',
            fontSize: 14,
            bold: true,
            margin: [0, 0, 0, 10]
          },
          {
            table: {
              headerRows: 1,
              widths: ['10%', '40%', '15%', '15%', '20%'],
              body: [
                ['ردیف', 'نام محصول', 'تعداد', 'قیمت واحد', 'مجموع'],
                ...invoiceData.items.map((item, index) => [
                  (index + 1).toString(),
                  item.name,
                  item.quantity.toString(),
                  `${item.unitPrice.toLocaleString()} دینار`,
                  `${(item.quantity * item.unitPrice).toLocaleString()} دینار`
                ])
              ]
            },
            layout: 'lightHorizontalLines',
            margin: [0, 0, 0, 20]
          },

          // Total
          {
            columns: [
              { width: '70%', text: '' },
              {
                width: '30%',
                table: {
                  widths: ['50%', '50%'],
                  body: [
                    ['مجموع کل:', `${invoiceData.totalAmount.toLocaleString()} دینار`]
                  ]
                },
                layout: 'noBorders'
              }
            ]
          }
        ],
        pageOrientation: 'portrait',
        pageSize: 'A4'
      };

      // Use pdfMake with createPdf().download() pattern
      console.log('📄 Generating client-side PDF with pdfMake...');
      pdfMake.createPdf(docDefinition).download(`invoice-${invoiceData.invoiceNumber}.pdf`);
      console.log('✅ PDF download initiated successfully');

    } catch (error) {
      console.error('خطا در تولید PDF:', error);
    } finally {
      setIsGenerating(false);
    }
  }

  // Server-side PDF generation
  async function handleServerPDFGeneration() {
    setIsGenerating(true);

    try {
      const response = await fetch('/api/pdf/invoice', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(invoiceData)
      });

      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = `invoice-${invoiceData.invoiceNumber}.pdf`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
      } else {
        console.error('خطا در تولید PDF از سرور');
      }
    } catch (error) {
      console.error('خطا در ارتباط با سرور:', error);
    } finally {
      setIsGenerating(false);
    }
  }

  return (
    <div className="space-y-6">
      {showInvoiceGenerator && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              {title}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="invoiceNumber">شماره فاکتور</Label>
                <Input
                  id="invoiceNumber"
                  value={invoiceData.invoiceNumber}
                  onChange={(e) => setInvoiceData(prev => ({
                    ...prev,
                    invoiceNumber: e.target.value
                  }))}
                />
              </div>
              <div>
                <Label htmlFor="customerName">نام مشتری</Label>
                <Input
                  id="customerName"
                  value={invoiceData.customerName}
                  onChange={(e) => setInvoiceData(prev => ({
                    ...prev,
                    customerName: e.target.value
                  }))}
                />
              </div>
              <div>
                <Label htmlFor="customerEmail">ایمیل مشتری</Label>
                <Input
                  id="customerEmail"
                  type="email"
                  value={invoiceData.customerEmail}
                  onChange={(e) => setInvoiceData(prev => ({
                    ...prev,
                    customerEmail: e.target.value
                  }))}
                />
              </div>
              <div>
                <Label htmlFor="customerPhone">شماره تماس</Label>
                <Input
                  id="customerPhone"
                  value={invoiceData.customerPhone}
                  onChange={(e) => setInvoiceData(prev => ({
                    ...prev,
                    customerPhone: e.target.value
                  }))}
                />
              </div>
            </div>

            <div>
              <Label htmlFor="totalAmount">مجموع کل (دینار)</Label>
              <Input
                id="totalAmount"
                type="number"
                value={invoiceData.totalAmount}
                onChange={(e) => setInvoiceData(prev => ({
                  ...prev,
                  totalAmount: parseInt(e.target.value) || 0
                }))}
              />
            </div>

            <div className="flex gap-2">
              <Button 
                onClick={handleDownloadPDF}
                disabled={isGenerating}
                className="flex items-center gap-2"
              >
                <Download className="h-4 w-4" />
                دانلود PDF (Frontend)
              </Button>

              <Button 
                onClick={handleServerPDFGeneration}
                disabled={isGenerating}
                variant="outline"
                className="flex items-center gap-2"
              >
                <Download className="h-4 w-4" />
                دانلود PDF (Server)
              </Button>
            </div>

            {isGenerating && (
              <p className="text-sm text-muted-foreground">
                در حال تولید PDF...
              </p>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/components/PostalServicesTab..content:
import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useToast } from '@/hooks/use-toast';
import { 
  Mail, 
  Plus, 
  Edit, 
  Trash2, 
  Package, 
  Flame, 
  Weight, 
  MapPin,
  Phone,
  Globe,
  Clock,
  Shield,
  CheckCircle,
  XCircle
} from 'lucide-react';

interface PostalService {
  id: number;
  name: string;
  nameEn?: string;
  contactInfo?: string;
  phone: string;
  email?: string;
  website?: string;
  maxWeightKg: number;
  allowsFlammable: boolean;
  basePrice: number;
  pricePerKg: number;
  estimatedDays: number;
  trackingAvailable: boolean;
  isActive: boolean;
  supportedRegions?: string[];
  specialRequirements?: string;
}

const PostalServicesTab = () => {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [editingService, setEditingService] = useState<PostalService | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    nameEn: '',
    contactInfo: '',
    phone: '',
    email: '',
    website: '',
    maxWeightKg: 0,
    allowsFlammable: false,
    basePrice: 0,
    pricePerKg: 0,
    estimatedDays: 1,
    trackingAvailable: false,
    isActive: true,
    supportedRegions: '',
    specialRequirements: ''
  });

  // Fetch postal services data
  const { data: postalServicesResponse, isLoading: loadingPostalServices } = useQuery({
    queryKey: ['/api/logistics/postal-services'],
    enabled: true
  });

  const postalServices = (postalServicesResponse as any)?.data || [];

  // Create postal service mutation
  const createPostalServiceMutation = useMutation({
    mutationFn: async (data: any) => {
      const response = await fetch('/api/logistics/postal-services', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...data,
          supportedRegions: data.supportedRegions ? data.supportedRegions.split(',').map((r: string) => r.trim()) : []
        })
      });
      if (!response.ok) throw new Error('Failed to create postal service');
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/postal-services'] });
      setIsCreateDialogOpen(false);
      resetForm();
      toast({ title: "موفق", description: "سرویس پستی جدید ثبت شد" });
    },
    onError: () => {
      toast({ title: "خطا", description: "خطا در ایجاد سرویس پستی", variant: "destructive" });
    }
  });

  // Update postal service mutation
  const updatePostalServiceMutation = useMutation({
    mutationFn: async (data: any) => {
      const response = await fetch(`/api/logistics/postal-services/${data.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...data,
          supportedRegions: data.supportedRegions ? data.supportedRegions.split(',').map((r: string) => r.trim()) : []
        })
      });
      if (!response.ok) throw new Error('Failed to update postal service');
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/postal-services'] });
      setEditingService(null);
      resetForm();
      toast({ title: "موفق", description: "سرویس پستی بروزرسانی شد" });
    },
    onError: () => {
      toast({ title: "خطا", description: "خطا در بروزرسانی سرویس پستی", variant: "destructive" });
    }
  });

  // Delete postal service mutation
  const deletePostalServiceMutation = useMutation({
    mutationFn: async (id: number) => {
      const response = await fetch(`/api/logistics/postal-services/${id}`, {
        method: 'DELETE'
      });
      if (!response.ok) throw new Error('Failed to delete postal service');
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/logistics/postal-services'] });
      toast({ title: "موفق", description: "سرویس پستی حذف شد" });
    },
    onError: () => {
      toast({ title: "خطا", description: "خطا در حذف سرویس پستی", variant: "destructive" });
    }
  });

  const resetForm = () => {
    setFormData({
      name: '',
      nameEn: '',
      contactInfo: '',
      phone: '',
      email: '',
      website: '',
      maxWeightKg: 0,
      allowsFlammable: false,
      basePrice: 0,
      pricePerKg: 0,
      estimatedDays: 1,
      trackingAvailable: false,
      isActive: true,
      supportedRegions: '',
      specialRequirements: ''
    });
  };

  const handleEdit = (service: PostalService) => {
    setEditingService(service);
    setFormData({
      name: service.name,
      nameEn: service.nameEn || '',
      contactInfo: service.contactInfo || '',
      phone: service.phone,
      email: service.email || '',
      website: service.website || '',
      maxWeightKg: service.maxWeightKg,
      allowsFlammable: service.allowsFlammable,
      basePrice: service.basePrice,
      pricePerKg: service.pricePerKg,
      estimatedDays: service.estimatedDays,
      trackingAvailable: service.trackingAvailable,
      isActive: service.isActive,
      supportedRegions: service.supportedRegions?.join(', ') || '',
      specialRequirements: service.specialRequirements || ''
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.name || !formData.phone) {
      toast({ 
        title: "خطا", 
        description: "لطفاً نام سرویس و شماره تماس را وارد کنید",
        variant: "destructive"
      });
      return;
    }

    if (editingService) {
      updatePostalServiceMutation.mutate({ ...formData, id: editingService.id });
    } else {
      createPostalServiceMutation.mutate(formData);
    }
  };

  const handleDelete = (id: number) => {
    if (confirm('آیا از حذف این سرویس پستی اطمینان دارید؟')) {
      deletePostalServiceMutation.mutate(id);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <Mail className="w-5 h-5 text-orange-600" />
          <h3 className="text-lg font-semibold">خدمات پستی</h3>
          <Badge variant="outline">{postalServices.length} سرویس ثبت شده</Badge>
        </div>
        <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
          <DialogTrigger asChild>
            <Button onClick={() => { resetForm(); setEditingService(null); }}>
              <Plus className="w-4 h-4 mr-2" />
              سرویس پستی جدید
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>
                {editingService ? 'ویرایش سرویس پستی' : 'ثبت سرویس پستی جدید'}
              </DialogTitle>
            </DialogHeader>

            <form onSubmit={handleSubmit} className="space-y-4">
              {/* Basic Information */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="name">نام سرویس پستی *</Label>
                  <Input
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    placeholder="مثال: پست عراق"
                    required
                  />
                </div>
                <div>
                  <Label htmlFor="nameEn">نام انگلیسی</Label>
                  <Input
                    id="nameEn"
                    value={formData.nameEn}
                    onChange={(e) => setFormData(prev => ({ ...prev, nameEn: e.target.value }))}
                    placeholder="Iraq Post"
                  />
                </div>
              </div>

              {/* Contact Information */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="phone">شماره تماس *</Label>
                  <Input
                    id="phone"
                    value={formData.phone}
                    onChange={(e) => setFormData(prev => ({ ...prev, phone: e.target.value }))}
                    placeholder="+964xxxxxxxxx"
                    required
                  />
                </div>
                <div>
                  <Label htmlFor="email">ایمیل</Label>
                  <Input
                    id="email"
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
                    placeholder="info@iraqpost.com"
                  />
                </div>
              </div>

              <div>
                <Label htmlFor="website">وب‌سایت</Label>
                <Input
                  id="website"
                  type="url"
                  value={formData.website}
                  onChange={(e) => setFormData(prev => ({ ...prev, website: e.target.value }))}
                  placeholder="https://www.iraqpost.com"
                />
              </div>

              <div>
                <Label htmlFor="contactInfo">اطلاعات تماس اضافی</Label>
                <Textarea
                  id="contactInfo"
                  value={formData.contactInfo}
