                  placeholder="آدرس دفتر مرکزی، شعبه‌ها و سایر اطلاعات"
                  rows={2}
                />
              </div>

              {/* Service Specifications */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="maxWeightKg">حداکثر وزن (کیلوگرم)</Label>
                  <Input
