          />
        </div>
      </div>

      {/* Main Content */}
      <Tabs defaultValue="products" className="space-y-6">
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="products">Products</TabsTrigger>
          <TabsTrigger value="generator">EAN-13 Generator</TabsTrigger>
          <TabsTrigger value="records">Barcode Records</TabsTrigger>
        </TabsList>

        {/* Products Tab */}
        <TabsContent value="products" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Product EAN-13 Status</CardTitle>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product</TableHead>
                    <TableHead>SKU</TableHead>
                    <TableHead>Current Barcode</TableHead>
                    <TableHead>Visual Barcode</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredProducts.map((product) => {
                    const hasEAN13 = product.barcode?.length === 13;
                    const isValid = hasEAN13 ? validateEAN13(product.barcode!) : false;

                    return (
                      <TableRow key={product.id}>
                        <TableCell>
                          <div>
                            <div className="font-medium">{product.name}</div>
                            <div className="text-sm text-gray-500">{product.category}</div>
                          </div>
                        </TableCell>
                        <TableCell>
                          <code className="text-xs bg-gray-100 px-2 py-1 rounded">
                            {product.sku}
                          </code>
                        </TableCell>
                        <TableCell>
                          {product.barcode ? (
                            <code className="text-xs bg-gray-100 px-2 py-1 rounded">
                              {product.barcode}
                            </code>
                          ) : (
                            <span className="text-gray-400">None</span>
                          )}
                        </TableCell>
                        <TableCell>
                          {product.barcode && product.barcode.length === 13 ? (
                            <div className="flex items-center justify-center">
                              <VisualBarcode 
                                value={product.barcode}
                                width={1.5}
                                height={40}
                                fontSize={10}
                                className="bg-white p-1 border rounded"
                              />
                            </div>
                          ) : (
                            <span className="text-gray-400 text-sm">No valid barcode</span>
                          )}
                        </TableCell>
                        <TableCell>
                          {hasEAN13 ? (
                            <Badge variant={isValid ? "default" : "destructive"}>
                              {isValid ? "Valid EAN-13" : "Invalid EAN-13"}
                            </Badge>
                          ) : (
                            <Badge variant="secondary">No EAN-13</Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          <Button
                            size="sm"
                            onClick={() => {
                              setSelectedProduct(product);
                              setShowGenerator(true);
                            }}
                          >
                            <Edit className="h-4 w-4 mr-1" />
                            {hasEAN13 ? 'Edit' : 'Generate'}
                          </Button>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Generator Tab */}
        <TabsContent value="generator" className="space-y-6">
          <EAN13Generator onBarcodeGenerated={handleBarcodeGenerated} />
        </TabsContent>

        {/* Records Tab */}
        <TabsContent value="records" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>EAN-13 Barcode Records</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-sm text-gray-500 mb-4">
                This feature will be available when backend EAN-13 record tracking is implemented.
              </div>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product</TableHead>
                    <TableHead>EAN-13</TableHead>
                    <TableHead>Visual Barcode</TableHead>
                    <TableHead>Country</TableHead>
                    <TableHead>Company</TableHead>
                    <TableHead>Product Code</TableHead>
                    <TableHead>Created</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {productsWithEAN13.map((product) => (
                    <TableRow key={product.id}>
                      <TableCell>{product.name}</TableCell>
                      <TableCell>
                        <code className="text-xs bg-gray-100 px-2 py-1 rounded">
                          {product.barcode}
                        </code>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center justify-center">
                          <VisualBarcode 
                            value={product.barcode!}
                            width={1.2}
                            height={35}
                            fontSize={8}
                            className="bg-white p-1 border rounded"
                          />
                        </div>
                      </TableCell>
                      <TableCell>{product.barcode?.substring(0, 3)}</TableCell>
                      <TableCell>{product.barcode?.substring(3, 8)}</TableCell>
                      <TableCell>{product.barcode?.substring(8, 12)}</TableCell>
                      <TableCell>
                        <span className="text-gray-400">N/A</span>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Generator Dialog */}
      <Dialog open={showGenerator} onOpenChange={setShowGenerator}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              Generate EAN-13 for {selectedProduct?.name}
            </DialogTitle>
            <DialogDescription>
              Create a GS1-compliant EAN-13 barcode for retail distribution
            </DialogDescription>
          </DialogHeader>
          <EAN13Generator
            productId={selectedProduct?.id}
            productName={selectedProduct?.name}
            onBarcodeGenerated={handleBarcodeGenerated}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
}

