import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { DollarSign, Eye, EyeOff } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useLocation } from "wouter";

const loginSchema = z.object({
  username: z.string().min(1, "نام کاربری الزامی است"),
  password: z.string().min(1, "رمز عبور الزامی است"),
});

type LoginFormData = z.infer<typeof loginSchema>;

export default function FinancialLogin() {
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  const form = useForm<LoginFormData>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      username: "",
      password: "",
    },
  });

  const onSubmit = async (data: LoginFormData) => {
    setIsLoading(true);
    try {
      const response = await fetch('/api/financial/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      });

      const result = await response.json();

      if (response.ok && result.success) {
        toast({
          title: "ورود موفق",
          description: "به بخش مالی خوش آمدید",
        });
        setLocation('/financial');
      } else {
        toast({
          title: "خطا در ورود",
          description: result.message || "نام کاربری یا رمز عبور اشتباه است",
          variant: "destructive",
        });
      }
    } catch (error) {
      toast({
        title: "خطا در اتصال",
        description: "مشکل در برقراری ارتباط با سرور",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-green-100">
            <DollarSign className="h-8 w-8 text-green-600" />
          </div>
          <CardTitle className="text-2xl font-bold text-gray-900">بخش مالی</CardTitle>
          <CardDescription className="text-gray-600">
            ورود به سیستم مدیریت مالی
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <FormField
                control={form.control}
                name="username"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>نام کاربری</FormLabel>
                    <FormControl>
                      <Input
                        {...field}
                        placeholder="نام کاربری خود را وارد کنید"
                        disabled={isLoading}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="password"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>رمز عبور</FormLabel>
                    <FormControl>
                      <div className="relative">
                        <Input
                          {...field}
                          type={showPassword ? "text" : "password"}
                          placeholder="رمز عبور خود را وارد کنید"
                          disabled={isLoading}
                          className="pr-10"
                        />
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          className="absolute left-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                          onClick={() => setShowPassword(!showPassword)}
                          disabled={isLoading}
                        >
                          {showPassword ? (
                            <EyeOff className="h-4 w-4 text-gray-400" />
                          ) : (
                            <Eye className="h-4 w-4 text-gray-400" />
                          )}
                        </Button>
                      </div>
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <Button
                type="submit"
                className="w-full bg-green-600 hover:bg-green-700"
                disabled={isLoading}
              >
                {isLoading ? "در حال ورود..." : "ورود به بخش مالی"}
              </Button>
            </form>
          </Form>
        </CardContent>
      </Card>
    </div>
  );
}

server/cleanup-migrated-files.ts.content:
import fs from 'fs';
import path from 'path';

interface MigrationReport {
  timestamp: string;
  totalFiles: number;
  migratedFiles: number;
  failedFiles: number;
  errors: string[];
  urlMapping: Array<[string, string]>;
}

async function cleanupMigratedFiles() {
  console.log('🧹 Starting cleanup of migrated files...\n');

  // Read migration report
  const reportPath = 'migration-report.json';
  if (!fs.existsSync(reportPath)) {
    console.error('❌ Migration report not found!');
    console.error('Please run migration first before cleanup.');
    process.exit(1);
  }

  const reportContent = fs.readFileSync(reportPath, 'utf8');
  const report: MigrationReport = JSON.parse(reportContent);

  console.log('📊 Migration Report Summary:');
  console.log(`   Total files: ${report.totalFiles}`);
  console.log(`   Successfully migrated: ${report.migratedFiles}`);
  console.log(`   Failed: ${report.failedFiles}\n`);

  if (report.migratedFiles === 0) {
    console.log('⚠️  No files were migrated, nothing to clean up.');
    process.exit(0);
  }

  // Get list of successfully migrated files
  const migratedFiles = report.urlMapping.map(([oldUrl, newUrl]) => {
    // Convert URL to local path
    // Example: /uploads/images/product-123.png → uploads/images/product-123.png
    return oldUrl.startsWith('/') ? oldUrl.substring(1) : oldUrl;
  });

  console.log(`🗑️  Preparing to delete ${migratedFiles.length} migrated files...\n`);

  let deletedCount = 0;
  let errorCount = 0;
  const errors: string[] = [];

  for (const filePath of migratedFiles) {
    try {
      if (fs.existsSync(filePath)) {
        fs.unlinkSync(filePath);
        deletedCount++;
        console.log(`  ✅ Deleted: ${filePath}`);
      } else {
        console.log(`  ⚠️  Not found (already deleted?): ${filePath}`);
      }
    } catch (error: any) {
      errorCount++;
      errors.push(`${filePath}: ${error.message}`);
      console.error(`  ❌ Error deleting ${filePath}: ${error.message}`);
    }
  }

  // Clean up empty directories
  console.log('\n🧹 Cleaning up empty directories...');
  const directories = [
    'uploads/images',
    'uploads/catalogs',
    'uploads/msds',
    'uploads/receipts',
    'uploads/logos',
    'uploads/documents'
  ];

  for (const dir of directories) {
    try {
      if (fs.existsSync(dir)) {
        const files = fs.readdirSync(dir);
        if (files.length === 0) {
          fs.rmdirSync(dir);
          console.log(`  ✅ Removed empty directory: ${dir}`);
        } else {
          console.log(`  ℹ️  Directory not empty: ${dir} (${files.length} files remaining)`);
        }
      }
    } catch (error: any) {
      console.error(`  ⚠️  Could not remove directory ${dir}: ${error.message}`);
    }
  }

  // Print summary
  console.log('\n' + '='.repeat(60));
  console.log('📊 CLEANUP SUMMARY');
  console.log('='.repeat(60));
  console.log(`Files deleted: ${deletedCount}`);
  console.log(`Errors: ${errorCount}`);

  if (errors.length > 0) {
    console.log(`\n⚠️ Errors (${errors.length}):`);
    errors.forEach((err, i) => {
      console.log(`   ${i + 1}. ${err}`);
    });
  }

  // Show disk space saved
  console.log('\n💾 Checking disk space...');
  const uploadsSize = getDirSize('uploads');
  console.log(`   Remaining uploads folder size: ${formatBytes(uploadsSize)}`);

  console.log('='.repeat(60) + '\n');
  console.log('✅ Cleanup completed!');
}

function getDirSize(dirPath: string): number {
  let totalSize = 0;

  if (!fs.existsSync(dirPath)) {
    return 0;
  }

  const files = fs.readdirSync(dirPath);

  for (const file of files) {
    const filePath = path.join(dirPath, file);
    const stats = fs.statSync(filePath);

    if (stats.isDirectory()) {
      totalSize += getDirSize(filePath);
    } else {
      totalSize += stats.size;
    }
  }

  return totalSize;
}

function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 Bytes';

  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));

  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

// Run cleanup if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  cleanupMigratedFiles()
    .then(() => {
      console.log('✅ All done!');
      process.exit(0);
    })
    .catch((error) => {
      console.error('❌ Cleanup failed:', error);
      process.exit(1);
    });
}

client/src/components/ui/product-inquiry.content:
import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { MessageCircle, Send, CheckCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import type { ShowcaseProduct } from "@shared/showcase-schema";

// Form validation schema
const inquiryFormSchema = z.object({
  contactEmail: z.string().email("Please enter a valid email address"),
  contactPhone: z.string().optional(),
  company: z.string().optional(),
  subject: z.string().min(5, "Subject must be at least 5 characters"),
  message: z.string().min(10, "Message must be at least 10 characters"),
  type: z.enum(["product_info", "quote_request", "technical_support", "general"]),
  priority: z.enum(["normal", "high", "urgent"]).default("normal"),
});

type InquiryFormData = z.infer<typeof inquiryFormSchema>;

interface ProductInquiryFormProps {
  product?: ShowcaseProduct;
  productName?: string;
  triggerText?: string;
  triggerVariant?: "default" | "outline" | "ghost";
  triggerSize?: "default" | "sm" | "lg";
  className?: string;
  triggerClassName?: string;
}

export function ProductInquiryForm({ 
  product, 
  productName,
  triggerText = "Inquire About Product",
  triggerVariant = "default",
  triggerSize = "default",
  className = "",
  triggerClassName = ""
}: ProductInquiryFormProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const { toast } = useToast();

  const displayProductName = product?.name || productName || "Product";

  const form = useForm<InquiryFormData>({
    resolver: zodResolver(inquiryFormSchema),
    defaultValues: {
      contactEmail: "",
      contactPhone: "",
      company: "",
      subject: `Inquiry about ${displayProductName}`,
      message: `I am interested in learning more about ${displayProductName}. Please provide me with detailed information including pricing, specifications, and availability.`,
      type: "product_info",
      priority: "normal",
    },
  });

  const submitInquiryMutation = useMutation({
    mutationFn: async (data: InquiryFormData) => {
      const inquiryData = {
        ...data,
        category: product?.category || "agricultural-fertilizers",
        productIds: product ? [product.id] : [],
        customerId: null, // Guest inquiry
      };

      return apiRequest("/api/inquiries", "POST", inquiryData);
    },
    onSuccess: () => {
      setIsSubmitted(true);
      form.reset();
      toast({
        title: "Inquiry Submitted",
        description: "Thank you! We'll get back to you within 24 hours.",
      });

      // Auto-close dialog after 3 seconds
      setTimeout(() => {
        setIsOpen(false);
        setIsSubmitted(false);
      }, 3000);
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to submit inquiry. Please try again.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: InquiryFormData) => {
    submitInquiryMutation.mutate(data);
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button 
          variant={triggerVariant} 
          size={triggerSize}
          className={triggerClassName || className}
        >
          <MessageCircle className="w-4 h-4 mr-2" />
          {triggerText}
        </Button>
      </DialogTrigger>

      <DialogContent className="sm:max-w-[500px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MessageCircle className="w-5 h-5" />
            Product Inquiry
          </DialogTitle>
        </DialogHeader>

        {isSubmitted ? (
          <div className="text-center py-8">
            <CheckCircle className="w-16 h-16 text-green-600 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-gray-900 mb-2">
              Inquiry Submitted Successfully!
            </h3>
            <p className="text-gray-600">
              We'll get back to you within 24 hours with detailed information.
            </p>
          </div>
        ) : (
          <div className="space-y-6">
            {/* Product Info */}
            <div className="bg-gray-50 rounded-lg p-4">
              <div className="flex items-start gap-3">
                {product?.imageUrl && (
                  <img 
                    src={product.imageUrl} 
                    alt={product.name}
                    className="w-16 h-16 object-cover rounded-lg"
                  />
                )}
                <div className="flex-1">
                  <h4 className="font-semibold text-gray-900">{displayProductName}</h4>
                  <Badge variant="outline" className="mt-1 text-xs">
                    {product?.category?.replace('-', ' ').replace(/\b\w/g, l => l.toUpperCase()) || "Agricultural Products"}
                  </Badge>
                  {product?.priceRange && (
                    <p className="text-sm text-gray-600 mt-1">{product.priceRange}</p>
                  )}
                </div>
              </div>
            </div>

            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="contactEmail"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Email Address *</FormLabel>
                        <FormControl>
                          <Input {...field} type="email" placeholder="your@email.com" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="contactPhone"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Phone Number</FormLabel>
                        <FormControl>
                          <Input {...field} placeholder="+1 (555) 123-4567" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <FormField
                  control={form.control}
                  name="company"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Company</FormLabel>
                      <FormControl>
                        <Input {...field} placeholder="Your company name" />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="type"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Inquiry Type</FormLabel>
                        <FormControl>
                          <Select value={field.value} onValueChange={field.onChange}>
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="product_info">Product Information</SelectItem>
                              <SelectItem value="quote_request">Request Quote</SelectItem>
                              <SelectItem value="technical_support">Technical Support</SelectItem>
                              <SelectItem value="general">General Inquiry</SelectItem>
                            </SelectContent>
                          </Select>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="priority"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Priority</FormLabel>
                        <FormControl>
                          <Select value={field.value} onValueChange={field.onChange}>
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="normal">Normal</SelectItem>
                              <SelectItem value="high">High</SelectItem>
                              <SelectItem value="urgent">Urgent</SelectItem>
                            </SelectContent>
                          </Select>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <FormField
                  control={form.control}
                  name="subject"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Subject *</FormLabel>
                      <FormControl>
                        <Input {...field} placeholder="Brief description of your inquiry" />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="message"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Message *</FormLabel>
                      <FormControl>
                        <Textarea 
                          {...field} 
                          placeholder="Please provide details about your requirements, quantities, timeline, or any specific questions..."
                          rows={4}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <div className="flex justify-end gap-2 pt-4">
                  <Button 
                    type="button" 
                    variant="outline" 
                    onClick={() => setIsOpen(false)}
                  >
                    Cancel
                  </Button>
                  <Button 
                    type="submit" 
                    disabled={submitInquiryMutation.isPending}
                  >
                    {submitInquiryMutation.isPending ? (
                      "Submitting..."
                    ) : (
                      <>
                        <Send className="w-4 h-4 mr-2" />
                        Submit Inquiry
                      </>
                    )}
                  </Button>
                </div>
              </form>
            </Form>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

