import { pgTable, text, serial, timestamp, decimal, boolean, integer, varchar, index } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// =============================================================================
// GPS DELIVERY TRACKING SCHEMA
// =============================================================================

// GPS delivery confirmations - track exact location when delivery verification codes are confirmed
export const gpsDeliveryConfirmations = pgTable("gps_delivery_confirmations", {
  id: serial("id").primaryKey(),
  deliveryVerificationId: integer("delivery_verification_id"),
  customerOrderId: integer("customer_order_id").notNull(),

  // GPS Location Data  
  latitude: decimal("latitude", { precision: 10, scale: 8 }).notNull(), // GPS coordinate
  longitude: decimal("longitude", { precision: 11, scale: 8 }).notNull(), // GPS coordinate
  accuracy: decimal("accuracy", { precision: 8, scale: 2 }), // GPS accuracy in meters

  // Delivery Person Information
  deliveryPersonName: text("delivery_person_name").notNull(),
  deliveryPersonPhone: text("delivery_person_phone").notNull(),

  // Location Analysis
  addressMatched: boolean("address_matched").default(false),
  customerAddress: text("customer_address"),
  detectedAddress: text("detected_address"), 
  distanceFromCustomer: decimal("distance_from_customer", { precision: 8, scale: 2 }),

  // Geographic Information
  country: text("country"),
  city: text("city"),
  region: text("region"),

  // Verification Details
  verificationTime: timestamp("verification_time").notNull().defaultNow(),

  // Notes
  deliveryNotes: text("delivery_notes"),

  // Timestamps
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("gps_delivery_verification_idx").on(table.deliveryVerificationId),
  index("gps_delivery_order_idx").on(table.customerOrderId),
  index("gps_delivery_location_idx").on(table.latitude, table.longitude),
  index("gps_delivery_time_idx").on(table.verificationTime),
  index("gps_delivery_person_idx").on(table.deliveryPersonPhone),
  index("gps_delivery_address_idx").on(table.city, table.region),
]);

// GPS delivery analytics - aggregated data for analytics
export const gpsDeliveryAnalytics = pgTable("gps_delivery_analytics", {
  id: serial("id").primaryKey(),

  // Date and Geographic Grouping
  analysisDate: timestamp("analysis_date").notNull(), // Date for this analytics record
  country: text("country").notNull(),
  city: text("city").notNull(),
  region: text("region"),

  // Delivery Statistics
  totalDeliveries: integer("total_deliveries").default(0),
  successfulDeliveries: integer("successful_deliveries").default(0),
  addressMatchedDeliveries: integer("address_matched_deliveries").default(0),
  averageAccuracy: decimal("average_accuracy", { precision: 8, scale: 2 }),
  averageDistanceFromCustomer: decimal("average_distance_from_customer", { precision: 10, scale: 2 }),

  // Geographic Coverage
  coverageAreaKm2: decimal("coverage_area_km2", { precision: 12, scale: 4 }), // Coverage area in km²
  uniqueNeighborhoods: integer("unique_neighborhoods").default(0),
  northeastLat: decimal("northeast_lat", { precision: 10, scale: 8 }),
  northeastLng: decimal("northeast_lng", { precision: 11, scale: 8 }),
  southwestLat: decimal("southwest_lat", { precision: 10, scale: 8 }),
  southwestLng: decimal("southwest_lng", { precision: 11, scale: 8 }),

  // Performance Metrics
  averageDeliveryTimeMinutes: integer("average_delivery_time_minutes"),
  deliverySuccessRate: decimal("delivery_success_rate", { precision: 5, scale: 2 }), // Percentage
  customerSatisfactionRate: decimal("customer_satisfaction_rate", { precision: 5, scale: 2 }),

  // Delivery Person Performance
  uniqueDeliveryPersons: integer("unique_delivery_persons").default(0),
  averageDeliveriesPerPerson: decimal("average_deliveries_per_person", { precision: 8, scale: 2 }),

  // Issues and Problems
  totalIssuesReported: integer("total_issues_reported").default(0),
  commonIssueTypes: text("common_issue_types"), // JSON array of common issues

  // Timestamps
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => [
  index("gps_analytics_date_idx").on(table.analysisDate),
  index("gps_analytics_location_idx").on(table.country, table.city),
  index("gps_analytics_performance_idx").on(table.deliverySuccessRate),
]);

// Zod schemas for validation
export const insertGpsDeliveryConfirmationSchema = createInsertSchema(gpsDeliveryConfirmations).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertGpsDeliveryAnalyticsSchema = createInsertSchema(gpsDeliveryAnalytics).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// TypeScript types
export type GpsDeliveryConfirmation = typeof gpsDeliveryConfirmations.$inferSelect;
export type InsertGpsDeliveryConfirmation = z.infer<typeof insertGpsDeliveryConfirmationSchema>;
export type GpsDeliveryAnalytics = typeof gpsDeliveryAnalytics.$inferSelect;
export type InsertGpsDeliveryAnalytics = z.infer<typeof insertGpsDeliveryAnalyticsSchema>;

// Geographic zones for analysis
export const deliveryZones = {
  IRAQ_CENTRAL: { name: 'Iraq Central', countries: ['Iraq'], cities: ['Baghdad', 'Karbala', 'Najaf'] },
  IRAQ_NORTH: { name: 'Iraq North', countries: ['Iraq'], cities: ['Erbil', 'Kirkuk', 'Sulaymaniyah'] },
  IRAQ_SOUTH: { name: 'Iraq South', countries: ['Iraq'], cities: ['Basra', 'Nasiriyah', 'Diwaniyah'] },
  IRAN_WEST: { name: 'Iran West', countries: ['Iran'], cities: ['Tehran', 'تویسرکان', 'Kermanshah'] },
  TURKEY_SOUTHEAST: { name: 'Turkey Southeast', countries: ['Turkey'], cities: ['Diyarbakır', 'Mardin', 'Şanlıurfa'] },
} as const;

// Delivery performance metrics
export const deliveryMetrics = {
  EXCELLENT: { minAccuracy: 0, maxAccuracy: 10, minSuccessRate: 95 },
  GOOD: { minAccuracy: 10, maxAccuracy: 50, minSuccessRate: 85 },
  FAIR: { minAccuracy: 50, maxAccuracy: 100, minSuccessRate: 75 },
  POOR: { minAccuracy: 100, maxAccuracy: 999999, minSuccessRate: 0 },
} as const;

server/sms-service.ts.content:
import https from 'https';
import http from 'http';

interface SmsSettings {
  isEnabled: boolean;
  provider: string;
  customProviderName?: string;
  apiKey?: string;
  apiSecret?: string;
  username?: string;
  password?: string;
  senderNumber?: string;
  apiEndpoint?: string;
  serviceType?: string;
  patternId?: string;
  serviceCode?: string;
  codeLength: number;
  codeExpiry: number;
  maxAttempts: number;
  rateLimitMinutes: number;
}

interface SmsMessage {
  to: string;
  message: string;
  code?: string;
}

export class SmsService {
  private settings: SmsSettings;

  constructor(settings?: SmsSettings) {
    this.settings = settings || {
      isEnabled: true,
      provider: 'infobip',
      codeLength: 6,
      codeExpiry: 300,
      maxAttempts: 3,
      rateLimitMinutes: 5
    };
  }

  async sendSms(message: SmsMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    if (!this.settings.isEnabled) {
      return { success: false, error: 'SMS service is disabled' };
    }

    try {
      switch (this.settings.provider) {
        case 'infobip':
          return await this.sendInfobipSms(message);
        case 'twilio':
          return await this.sendTwilioSms(message);
        case 'asiacell':
        case 'zain_iraq':
        case 'korek_telecom':
          return await this.sendIraqiOperatorSms(message);
        case 'custom':
          return await this.sendCustomProviderSms(message);
        default:
          return { success: false, error: 'Unsupported SMS provider' };
      }
    } catch (error: any) {
      console.error('SMS sending error:', error);
      return { success: false, error: error.message || 'Unknown error' };
    }
  }

  private async sendInfobipSms(message: SmsMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    return new Promise((resolve) => {
      const postData = JSON.stringify({
        messages: [
          {
            destinations: [{ to: message.to }],
            from: this.settings.senderNumber || '447491163443',
            text: message.message
          }
        ]
      });

      const options = {
        method: 'POST',
        hostname: 'api.infobip.com',
        path: this.settings.serviceCode ? `/sms/2/text/advanced?serviceCode=${this.settings.serviceCode}` : '/sms/2/text/advanced',
        headers: {
          'Authorization': `App ${this.settings.apiKey}`,
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        },
        maxRedirects: 20
      };

      const req = https.request(options, (res) => {
        const chunks: Buffer[] = [];

        res.on('data', (chunk) => {
          chunks.push(chunk);
        });

        res.on('end', () => {
          const body = Buffer.concat(chunks);
          const response = JSON.parse(body.toString());

          if (res.statusCode === 200 && response.messages && response.messages[0]) {
            const messageStatus = response.messages[0];
            if (messageStatus.status && messageStatus.status.groupId === 1) {
              resolve({ 
                success: true, 
                messageId: messageStatus.messageId 
              });
            } else {
              resolve({ 
                success: false, 
                error: `Infobip error: ${messageStatus.status?.description || 'Unknown error'}` 
              });
            }
          } else {
            resolve({ 
              success: false, 
              error: `HTTP ${res.statusCode}: ${response.requestError?.serviceException?.text || 'Unknown error'}` 
            });
          }
        });

        res.on('error', (error) => {
          resolve({ success: false, error: `Network error: ${error.message}` });
        });
      });

      req.on('error', (error) => {
        resolve({ success: false, error: `Request error: ${error.message}` });
      });

      req.write(postData);
      req.end();
    });
  }

  private async sendTwilioSms(message: SmsMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    return new Promise((resolve) => {
      const auth = Buffer.from(`${this.settings.username}:${this.settings.password}`).toString('base64');

      const postData = new URLSearchParams({
        To: message.to,
        From: this.settings.senderNumber || '',
        Body: message.message
      }).toString();

      const options = {
        method: 'POST',
        hostname: 'api.twilio.com',
        path: `/2010-04-01/Accounts/${this.settings.username}/Messages.json`,
        headers: {
          'Authorization': `Basic ${auth}`,
          'Content-Type': 'application/x-www-form-urlencoded',
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        const chunks: Buffer[] = [];

        res.on('data', (chunk) => {
          chunks.push(chunk);
        });

        res.on('end', () => {
          const body = Buffer.concat(chunks);
          const response = JSON.parse(body.toString());

          if (res.statusCode === 201 && response.sid) {
            resolve({ 
              success: true, 
              messageId: response.sid 
            });
          } else {
            resolve({ 
              success: false, 
              error: `Twilio error: ${response.message || 'Unknown error'}` 
            });
          }
        });

        res.on('error', (error) => {
          resolve({ success: false, error: `Network error: ${error.message}` });
        });
      });

      req.on('error', (error) => {
        resolve({ success: false, error: `Request error: ${error.message}` });
      });

      req.write(postData);
      req.end();
    });
  }

  private async sendIraqiOperatorSms(message: SmsMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    // Iraqi operators typically use custom APIs
    // This is a generic implementation that can be customized
    return new Promise((resolve) => {
      if (!this.settings.apiEndpoint) {
        resolve({ success: false, error: 'API endpoint not configured for Iraqi operator' });
        return;
      }

      const postData = JSON.stringify({
        username: this.settings.username,
        password: this.settings.password,
        to: message.to,
        from: this.settings.senderNumber,
        text: message.message,
        serviceCode: this.settings.serviceCode
      });

      const url = new URL(this.settings.apiEndpoint);
      const isHttps = url.protocol === 'https:';
      const httpModule = isHttps ? https : http;

      const options = {
        method: 'POST',
        hostname: url.hostname,
        port: url.port || (isHttps ? 443 : 80),
        path: url.pathname + url.search,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = httpModule.request(options, (res) => {
        const chunks: Buffer[] = [];

        res.on('data', (chunk) => {
          chunks.push(chunk);
        });

        res.on('end', () => {
          const body = Buffer.concat(chunks);
          try {
            const response = JSON.parse(body.toString());

            if (res.statusCode === 200) {
              resolve({ 
                success: true, 
                messageId: response.messageId || response.id || 'success' 
              });
            } else {
              resolve({ 
                success: false, 
                error: `${this.settings.provider} error: ${response.message || response.error || 'Unknown error'}` 
              });
            }
          } catch (parseError) {
            resolve({ 
              success: false, 
              error: `Response parsing error: ${parseError}` 
            });
          }
        });

        res.on('error', (error) => {
          resolve({ success: false, error: `Network error: ${error.message}` });
        });
      });

      req.on('error', (error) => {
        resolve({ success: false, error: `Request error: ${error.message}` });
      });

      req.write(postData);
      req.end();
    });
  }

  private async sendCustomProviderSms(message: SmsMessage): Promise<{ success: boolean; messageId?: string; error?: string }> {
    // Generic implementation for custom providers
    return new Promise((resolve) => {
      if (!this.settings.apiEndpoint) {
        resolve({ success: false, error: 'API endpoint not configured for custom provider' });
        return;
      }

      const postData = JSON.stringify({
        apiKey: this.settings.apiKey,
        apiSecret: this.settings.apiSecret,
        username: this.settings.username,
        password: this.settings.password,
        to: message.to,
        from: this.settings.senderNumber,
        message: message.message,
        serviceCode: this.settings.serviceCode,
        patternId: this.settings.patternId
      });

      const url = new URL(this.settings.apiEndpoint);
      const isHttps = url.protocol === 'https:';
      const httpModule = isHttps ? https : http;

      const options = {
        method: 'POST',
        hostname: url.hostname,
        port: url.port || (isHttps ? 443 : 80),
        path: url.pathname + url.search,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': this.settings.apiKey ? `Bearer ${this.settings.apiKey}` : undefined,
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = httpModule.request(options, (res) => {
        const chunks: Buffer[] = [];

        res.on('data', (chunk) => {
          chunks.push(chunk);
        });

        res.on('end', () => {
          const body = Buffer.concat(chunks);
          try {
            const response = JSON.parse(body.toString());

            if (res.statusCode === 200 || res.statusCode === 201) {
              resolve({ 
                success: true, 
                messageId: response.messageId || response.id || response.reference || 'success' 
              });
            } else {
              resolve({ 
                success: false, 
                error: `${this.settings.customProviderName || 'Custom provider'} error: ${response.message || response.error || 'Unknown error'}` 
              });
            }
          } catch (parseError) {
            resolve({ 
              success: false, 
              error: `Response parsing error: ${parseError}` 
            });
          }
        });

        res.on('error', (error) => {
          resolve({ success: false, error: `Network error: ${error.message}` });
        });
      });

      req.on('error', (error) => {
        resolve({ success: false, error: `Request error: ${error.message}` });
      });

      req.write(postData);
      req.end();
    });
  }

  async sendVerificationCode(phone: string, code: string): Promise<{ success: boolean; messageId?: string; error?: string }> {
    const message = {
      to: phone,
      message: `کد تایید شما: ${code}`,
      code: code
    };

    return await this.sendSms(message);
  }

  async sendSmsUsingTemplate(templateId: number, phone: string, variables: Record<string, string>): Promise<{ success: boolean; messageId?: string; error?: string }> {
    try {
      const { pool } = await import('./db');

      // Get template from database
      const templateResult = await pool.query('SELECT * FROM sms_templates WHERE id = $1 AND is_active = true', [templateId]);

      if (templateResult.rows.length === 0) {
        return { success: false, error: `Template ${templateId} not found or inactive` };
      }

      const template = templateResult.rows[0];
      let message = template.template_content;

      // Replace template variables
      for (const [key, value] of Object.entries(variables)) {
        const regex = new RegExp(`{{${key}}}`, 'g');
        message = message.replace(regex, value);
      }

      console.log(`📱 [SMS TEMPLATE ${templateId}] Sending to ${phone}:`, message);

      // Send SMS
      const result = await this.sendSms({ to: phone, message });

      // Update template usage count
      if (result.success) {
        await pool.query(
          'UPDATE sms_templates SET usage_count = usage_count + 1, last_used = NOW() WHERE id = $1',
          [templateId]
        );
      }

      return result;
    } catch (error: any) {
      console.error(`❌ [SMS TEMPLATE ${templateId}] Error:`, error);
      return { success: false, error: error.message };
    }
  }

  async testConnection(): Promise<{ success: boolean; error?: string }> {
    try {
      const testResult = await this.sendSms({
        to: '9647503533769', // Test number
        message: 'Test message from Momtaz Chemical SMS System'
      });

      return testResult;
    } catch (error: any) {
      return { success: false, error: error.message };
    }
  }
}

export async function createSmsService(): Promise<SmsService> {
  try {
    const { pool } = await import('./db');

    const result = await pool.query('SELECT * FROM sms_settings WHERE id = 1');
    const dbSettings = result.rows[0];

    const settings: SmsSettings = {
      isEnabled: dbSettings?.is_enabled ?? true,
      provider: dbSettings?.provider ?? 'infobip',
      customProviderName: dbSettings?.custom_provider_name,
      apiKey: dbSettings?.api_key,
      apiSecret: dbSettings?.api_secret,
      username: dbSettings?.username,
      password: dbSettings?.password,
      senderNumber: dbSettings?.sender_number,
      apiEndpoint: dbSettings?.api_endpoint,
      serviceType: dbSettings?.service_type,
      patternId: dbSettings?.pattern_id,
      serviceCode: dbSettings?.service_code,
      codeLength: dbSettings?.code_length ?? 6,
      codeExpiry: dbSettings?.code_expiry ?? 300,
      maxAttempts: dbSettings?.max_attempts ?? 3,
      rateLimitMinutes: dbSettings?.rate_limit_minutes ?? 5
    };

    return new SmsService(settings);
  } catch (error) {
    console.error('Error loading SMS settings from database, using defaults:', error);

    // Fallback to default settings
    const defaultSettings: SmsSettings = {
      isEnabled: true,
      provider: 'infobip',
      codeLength: 6,
      codeExpiry: 300,
      maxAttempts: 3,
      rateLimitMinutes: 5
    };

    return new SmsService(defaultSettings);
  }
}

server/objectStorage.ts.content:
import { Storage, File } from "@google-cloud/storage";
import { Response } from "express";
import { randomUUID } from "crypto";
import {
  ObjectAclPolicy,
  ObjectPermission,
  canAccessObject,
  getObjectAclPolicy,
  setObjectAclPolicy,
} from "./objectAcl";

const REPLIT_SIDECAR_ENDPOINT = "http://127.0.0.1:1106";

// The object storage client is used to interact with the object storage service.
export const objectStorageClient = new Storage({
  credentials: {
    audience: "replit",
    subject_token_type: "access_token",
    token_url: `${REPLIT_SIDECAR_ENDPOINT}/token`,
    type: "external_account",
    credential_source: {
      url: `${REPLIT_SIDECAR_ENDPOINT}/credential`,
      format: {
        type: "json",
        subject_token_field_name: "access_token",
      },
    },
    universe_domain: "googleapis.com",
  },
  projectId: "",
});

export class ObjectNotFoundError extends Error {
  constructor() {
    super("Object not found");
    this.name = "ObjectNotFoundError";
    Object.setPrototypeOf(this, ObjectNotFoundError.prototype);
  }
}

// The object storage service is used to interact with the object storage service.
export class ObjectStorageService {
  constructor() {}

  // Gets the public object search paths.
  getPublicObjectSearchPaths(): Array<string> {
    const pathsStr = process.env.PUBLIC_OBJECT_SEARCH_PATHS || "";
    const paths = Array.from(
      new Set(
        pathsStr
          .split(",")
          .map((path) => path.trim())
          .filter((path) => path.length > 0)
      )
    );
    if (paths.length === 0) {
      throw new Error(
        "PUBLIC_OBJECT_SEARCH_PATHS not set. Create a bucket in 'Object Storage' " +
          "tool and set PUBLIC_OBJECT_SEARCH_PATHS env var (comma-separated paths)."
      );
    }
    return paths;
  }

  // Gets the private object directory.
  getPrivateObjectDir(): string {
    const dir = process.env.PRIVATE_OBJECT_DIR || "";
    if (!dir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }
    return dir;
  }

  // Search for a public object from the search paths.
  async searchPublicObject(filePath: string): Promise<File | null> {
    for (const searchPath of this.getPublicObjectSearchPaths()) {
      const fullPath = `${searchPath}/${filePath}`;

      // Full path format: /<bucket_name>/<object_name>
      const { bucketName, objectName } = parseObjectPath(fullPath);
      const bucket = objectStorageClient.bucket(bucketName);
      const file = bucket.file(objectName);

      // Check if file exists
      const [exists] = await file.exists();
      if (exists) {
        return file;
      }
    }

    return null;
  }

  // Downloads an object to the response.
  async downloadObject(file: File, res: Response, cacheTtlSec: number = 3600) {
    try {
      // Get file metadata
      const [metadata] = await file.getMetadata();
      // Get the ACL policy for the object.
      const aclPolicy = await getObjectAclPolicy(file);
      const isPublic = aclPolicy?.visibility === "public";
      // Set appropriate headers
      res.set({
        "Content-Type": metadata.contentType || "application/octet-stream",
        "Content-Length": metadata.size,
        "Cache-Control": `${
          isPublic ? "public" : "private"
        }, max-age=${cacheTtlSec}`,
      });

      // Stream the file to the response
      const stream = file.createReadStream();

      stream.on("error", (err) => {
        console.error("Stream error:", err);
        if (!res.headersSent) {
          res.status(500).json({ error: "Error streaming file" });
        }
      });

      stream.pipe(res);
    } catch (error) {
      console.error("Error downloading file:", error);
      if (!res.headersSent) {
        res.status(500).json({ error: "Error downloading file" });
      }
    }
  }

  // Gets the upload URL for an object entity.
  async getObjectEntityUploadURL(): Promise<string> {
    const privateObjectDir = this.getPrivateObjectDir();
    if (!privateObjectDir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }

    const objectId = randomUUID();
    const fullPath = `${privateObjectDir}/uploads/${objectId}`;

    const { bucketName, objectName } = parseObjectPath(fullPath);

    // Sign URL for PUT method with TTL
    return signObjectURL({
      bucketName,
      objectName,
      method: "PUT",
      ttlSec: 900,
    });
  }

  // Gets the object entity file from the object path.
  async getObjectEntityFile(objectPath: string): Promise<File> {
    if (!objectPath.startsWith("/objects/")) {
      throw new ObjectNotFoundError();
    }

    const parts = objectPath.slice(1).split("/");
    if (parts.length < 2) {
      throw new ObjectNotFoundError();
    }

    const entityId = parts.slice(1).join("/");
    let entityDir = this.getPrivateObjectDir();
    if (!entityDir.endsWith("/")) {
      entityDir = `${entityDir}/`;
    }
    const objectEntityPath = `${entityDir}${entityId}`;
    const { bucketName, objectName } = parseObjectPath(objectEntityPath);
    const bucket = objectStorageClient.bucket(bucketName);
    const objectFile = bucket.file(objectName);
    const [exists] = await objectFile.exists();
    if (!exists) {
      throw new ObjectNotFoundError();
    }
    return objectFile;
  }

  normalizeObjectEntityPath(
    rawPath: string,
  ): string {
    if (!rawPath.startsWith("https://storage.googleapis.com/")) {
      return rawPath;
    }

    // Extract the path from the URL by removing query parameters and domain
    const url = new URL(rawPath);
    const rawObjectPath = url.pathname;

    let objectEntityDir = this.getPrivateObjectDir();
    if (!objectEntityDir.endsWith("/")) {
      objectEntityDir = `${objectEntityDir}/`;
    }

    if (!rawObjectPath.startsWith(objectEntityDir)) {
      return rawObjectPath;
    }

    // Extract the entity ID from the path
    const entityId = rawObjectPath.slice(objectEntityDir.length);
    return `/objects/${entityId}`;
  }

  // Tries to set the ACL policy for the object entity and return the normalized path.
  async trySetObjectEntityAclPolicy(
    rawPath: string,
    aclPolicy: ObjectAclPolicy
  ): Promise<string> {
    const normalizedPath = this.normalizeObjectEntityPath(rawPath);
    if (!normalizedPath.startsWith("/")) {
      return normalizedPath;
    }

    const objectFile = await this.getObjectEntityFile(normalizedPath);
    await setObjectAclPolicy(objectFile, aclPolicy);
    return normalizedPath;
  }

  // Checks if the user can access the object entity.
  async canAccessObjectEntity({
    userId,
    objectFile,
    requestedPermission,
  }: {
    userId?: string;
    objectFile: File;
    requestedPermission?: ObjectPermission;
  }): Promise<boolean> {
    return canAccessObject({
      userId,
      objectFile,
      requestedPermission: requestedPermission ?? ObjectPermission.READ,
    });
  }
}

function parseObjectPath(path: string): {
  bucketName: string;
  objectName: string;
} {
  if (!path.startsWith("/")) {
    path = `/${path}`;
  }
  const pathParts = path.split("/");
  if (pathParts.length < 3) {
    throw new Error("Invalid path: must contain at least a bucket name");
  }

  const bucketName = pathParts[1];
  const objectName = pathParts.slice(2).join("/");

  return {
    bucketName,
    objectName,
  };
}

async function signObjectURL({
  bucketName,
  objectName,
  method,
  ttlSec,
}: {
  bucketName: string;
  objectName: string;
  method: "GET" | "PUT" | "DELETE" | "HEAD";
  ttlSec: number;
}): Promise<string> {
  const request = {
    bucket_name: bucketName,
    object_name: objectName,
    method,
    expires_at: new Date(Date.now() + ttlSec * 1000).toISOString(),
  };
  const response = await fetch(
    `${REPLIT_SIDECAR_ENDPOINT}/object-storage/signed-object-url`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(request),
    }
  );
  if (!response.ok) {
    throw new Error(
      `Failed to sign object URL, errorcode: ${response.status}, ` +
        `make sure you're running on Replit`
    );
  }

  const { signed_url: signedURL } = await response.json();
  return signedURL;
}

