                          <span className="font-medium">گیرنده:</span>
                          <div className="text-gray-600">
                            {log.recipient_name && <div>{log.recipient_name}</div>}
                            <div>{log.recipient_email}</div>
                          </div>
                        </div>

                        <div>
                          <span className="font-medium">موضوع:</span>
