import { useEffect, useState } from 'react';
import { useRoute } from 'wouter';
import { useQuery } from '@tanstack/react-query';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { CheckCircle2, Clock, XCircle, ExternalLink, Copy, Smartphone } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { useLanguage } from '@/contexts/LanguageContext';

export default function FibPaymentPage() {
  const [, params] = useRoute('/payment/fib/:paymentId');
  const paymentId = params?.paymentId;
  const { toast } = useToast();
  const { language } = useLanguage();
  const [timeRemaining, setTimeRemaining] = useState<string>('');
  const [enablePolling, setEnablePolling] = useState<boolean>(false);

  const { data: paymentData, isLoading, error, refetch } = useQuery<{
    success: boolean;
    data: {
      paymentId: string;
      amount: string;
      currency: string;
      status: string;
      readableCode: string;
      qrCode: string;
      personalAppLink?: string;
      businessAppLink?: string;
      corporateAppLink?: string;
      validUntil: string;
      createdAt: string;
      paidAt?: string;
      description?: string;
    };
  }>({
    queryKey: [`/api/payment/fib/${paymentId}`],
    enabled: !!paymentId,
    refetchInterval: enablePolling ? 5000 : false, // Poll every 5 seconds only after 15-second wait
  });

  // FIB Best Practice: Wait 15 seconds for callback, then start polling
  useEffect(() => {
    if (!paymentId) return;

    console.log('🏦 [FIB] Waiting 15 seconds for callback before polling...');

    const timer = setTimeout(() => {
      console.log('🔄 [FIB] Starting status polling (every 5 seconds)');
      setEnablePolling(true);
    }, 15000); // Wait 15 seconds as per FIB best practices

    return () => clearTimeout(timer);
  }, [paymentId]);

  const payment = paymentData?.data;

  // Calculate time remaining
  useEffect(() => {
    if (!payment?.validUntil) return;

    const interval = setInterval(() => {
      const now = new Date();
      const expiry = new Date(payment.validUntil);
      const diff = expiry.getTime() - now.getTime();

      if (diff <= 0) {
        setTimeRemaining(language === 'ar' ? 'منتهية الصلاحية' : 'Expired');
        return;
      }

      const minutes = Math.floor(diff / 60000);
      const seconds = Math.floor((diff % 60000) / 1000);
      setTimeRemaining(`${minutes}:${seconds.toString().padStart(2, '0')}`);
    }, 1000);

    return () => clearInterval(interval);
  }, [payment?.validUntil, language]);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({
      title: language === 'ar' ? 'تم النسخ' : 'Copied',
      description: language === 'ar' ? 'تم نسخ الرمز إلى الحافظة' : 'Code copied to clipboard',
    });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 flex items-center justify-center p-4">
        <Card className="w-full max-w-2xl">
          <CardContent className="p-12 text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto"></div>
            <p className="mt-4 text-muted-foreground">
              {language === 'ar' ? 'جاري التحميل...' : 'Loading...'}
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error || !payment) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 flex items-center justify-center p-4">
        <Card className="w-full max-w-2xl">
          <CardContent className="p-12 text-center">
            <XCircle className="h-16 w-16 text-destructive mx-auto mb-4" />
            <h2 className="text-2xl font-bold mb-2">
              {language === 'ar' ? 'الدفعة غير موجودة' : 'Payment Not Found'}
            </h2>
            <p className="text-muted-foreground">
              {language === 'ar'
                ? 'لم نتمكن من العثور على معلومات الدفع'
                : 'We could not find the payment information'}
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'paid':
      case 'completed':
        return (
          <div className="flex items-center gap-2 text-green-600 dark:text-green-400">
            <CheckCircle2 className="h-5 w-5" />
            <span className="font-semibold">
              {language === 'ar' ? 'مدفوع' : 'Paid'}
            </span>
          </div>
        );
      case 'pending':
        return (
          <div className="flex items-center gap-2 text-amber-600 dark:text-amber-400">
            <Clock className="h-5 w-5" />
            <span className="font-semibold">
              {language === 'ar' ? 'في انتظار الدفع' : 'Pending Payment'}
            </span>
          </div>
        );
      case 'expired':
      case 'cancelled':
        return (
          <div className="flex items-center gap-2 text-red-600 dark:text-red-400">
            <XCircle className="h-5 w-5" />
            <span className="font-semibold">
              {language === 'ar' ? 'منتهية الصلاحية' : 'Expired'}
            </span>
          </div>
        );
      default:
        return <span className="text-muted-foreground">{status}</span>;
    }
  };

  const isPaid = payment.status === 'paid' || payment.status === 'completed';
  const isExpired = payment.status === 'expired' || payment.status === 'cancelled';

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 flex items-center justify-center p-4">
      <Card className="w-full max-w-2xl shadow-xl">
        <CardHeader className="text-center border-b">
          <div className="flex justify-center mb-4">
            <div className="w-24 h-24 bg-gradient-to-br from-blue-500 to-purple-600 rounded-full flex items-center justify-center">
              <Smartphone className="h-12 w-12 text-white" />
            </div>
          </div>
          <CardTitle className="text-3xl font-bold">
            {language === 'ar' ? 'دفع عبر FIB' : 'FIB Payment'}
          </CardTitle>
          <CardDescription className="text-lg">
            {language === 'ar' ? 'البنك العراقي الأول' : 'First Iraqi Bank'}
          </CardDescription>
        </CardHeader>

        <CardContent className="p-8 space-y-6">
          {/* Status */}
          <div className="flex justify-between items-center p-4 bg-slate-100 dark:bg-slate-800 rounded-lg">
            <span className="text-sm font-medium text-muted-foreground">
              {language === 'ar' ? 'الحالة:' : 'Status:'}
            </span>
            {getStatusBadge(payment.status)}
          </div>

          {/* Amount */}
          <div className="text-center py-6 border-y">
            <p className="text-sm text-muted-foreground mb-2">
              {language === 'ar' ? 'المبلغ المطلوب' : 'Amount Due'}
            </p>
            <p className="text-5xl font-bold text-primary">
              {parseFloat(payment.amount).toLocaleString()} {payment.currency}
            </p>
          </div>

          {!isPaid && !isExpired && (
            <>
              {/* Timer */}
              <Alert>
                <Clock className="h-4 w-4" />
                <AlertDescription className="flex justify-between items-center">
                  <span>
                    {language === 'ar'
                      ? 'الوقت المتبقي لإتمام الدفع:'
                      : 'Time remaining to complete payment:'}
                  </span>
                  <span className="font-mono text-lg font-bold">{timeRemaining}</span>
                </AlertDescription>
              </Alert>

              {/* QR Code */}
              <div className="text-center space-y-4">
                <h3 className="text-lg font-semibold">
                  {language === 'ar' ? 'امسح رمز QR باستخدام تطبيق FIB' : 'Scan QR Code with FIB App'}
                </h3>
                <div className="flex justify-center">
                  <div className="p-4 bg-white dark:bg-slate-800 rounded-lg shadow-md">
                    <img
                      src={payment.qrCode}
                      alt="QR Code"
                      className="w-64 h-64"
                      data-testid="qr-code-image"
                    />
                  </div>
                </div>
              </div>

              {/* Readable Code */}
              <div className="space-y-2">
                <label className="text-sm font-medium">
                  {language === 'ar' ? 'أو أدخل الرمز يدويًا:' : 'Or enter code manually:'}
                </label>
                <div className="flex gap-2">
                  <div className="flex-1 p-4 bg-slate-100 dark:bg-slate-800 rounded-lg font-mono text-2xl font-bold text-center tracking-wider">
                    {payment.readableCode}
                  </div>
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => copyToClipboard(payment.readableCode)}
                    data-testid="button-copy-code"
                  >
                    <Copy className="h-4 w-4" />
                  </Button>
                </div>
              </div>

              {/* App Links */}
              <div className="space-y-3">
                <h3 className="text-sm font-semibold text-center">
                  {language === 'ar' ? 'افتح في تطبيق FIB:' : 'Open in FIB App:'}
                </h3>
                <div className="grid gap-3">
                  {payment.personalAppLink && (
                    <Button
                      variant="outline"
                      className="w-full"
                      asChild
                      data-testid="button-personal-app"
                    >
                      <a href={payment.personalAppLink} target="_blank" rel="noopener noreferrer">
                        <Smartphone className="mr-2 h-4 w-4" />
                        {language === 'ar' ? 'حساب شخصي' : 'Personal Account'}
                        <ExternalLink className="ml-2 h-4 w-4" />
                      </a>
                    </Button>
                  )}
                  {payment.businessAppLink && (
                    <Button
                      variant="outline"
                      className="w-full"
                      asChild
                      data-testid="button-business-app"
                    >
                      <a href={payment.businessAppLink} target="_blank" rel="noopener noreferrer">
                        <Smartphone className="mr-2 h-4 w-4" />
                        {language === 'ar' ? 'حساب تجاري' : 'Business Account'}
                        <ExternalLink className="ml-2 h-4 w-4" />
                      </a>
                    </Button>
                  )}
                  {payment.corporateAppLink && (
                    <Button
                      variant="outline"
                      className="w-full"
                      asChild
                      data-testid="button-corporate-app"
                    >
                      <a href={payment.corporateAppLink} target="_blank" rel="noopener noreferrer">
                        <Smartphone className="mr-2 h-4 w-4" />
                        {language === 'ar' ? 'حساب شركات' : 'Corporate Account'}
                        <ExternalLink className="ml-2 h-4 w-4" />
                      </a>
                    </Button>
                  )}
                </div>
              </div>
            </>
          )}

          {isPaid && (
            <Alert className="bg-green-50 dark:bg-green-950 border-green-500">
              <CheckCircle2 className="h-5 w-5 text-green-600 dark:text-green-400" />
              <AlertDescription className="text-green-800 dark:text-green-200 text-lg">
                {language === 'ar'
                  ? 'تم الدفع بنجاح! شكراً لك.'
                  : 'Payment successful! Thank you.'}
              </AlertDescription>
            </Alert>
          )}

          {isExpired && (
            <Alert className="bg-red-50 dark:bg-red-950 border-red-500">
              <XCircle className="h-5 w-5 text-red-600 dark:text-red-400" />
              <AlertDescription className="text-red-800 dark:text-red-200">
                {language === 'ar'
                  ? 'انتهت صلاحية هذه الدفعة. يرجى إنشاء دفعة جديدة.'
                  : 'This payment has expired. Please create a new payment.'}
              </AlertDescription>
            </Alert>
          )}

          {/* Payment ID */}
          <div className="text-center text-xs text-muted-foreground pt-4 border-t">
            <p>
              {language === 'ar' ? 'معرف الدفع:' : 'Payment ID:'} {payment.paymentId}
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/UnifiedOrderDetail.content:
import { useQuery } from '@tanstack/react-query';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Skeleton } from '@/components/ui/skeleton';
import { 
  Package, 
  User, 
  Phone, 
  Mail, 
  MapPin, 
  CreditCard, 
  Calendar,
  Hash,
  Weight,
  DollarSign,
  Clock,
  FileText,
  AlertCircle
} from 'lucide-react';

interface UnifiedOrderDetailsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  orderNumber?: string;
  orderId?: number;
  hidePrice?: boolean; // برای بخش لجستیک
}

export default function UnifiedOrderDetailsDialog({ 
  open, 
  onOpenChange, 
  orderNumber,
  orderId,
  hidePrice = false 
}: UnifiedOrderDetailsDialogProps) {
  // Fetch order details
  const { data, isLoading, error } = useQuery({
    queryKey: ['/api/admin/orders', orderId || orderNumber],
    queryFn: async () => {
      const url = orderId 
        ? `/api/admin/orders/${orderId}`
        : `/api/customers/orders/${orderNumber}/details`;
      const res = await fetch(url, { credentials: 'include' });
      if (!res.ok) throw new Error('Failed to fetch order');
      return res.json();
    },
    enabled: open && (!!orderId || !!orderNumber),
  });

  const order = data?.order || data?.data;
  const items = data?.items || order?.items || [];

  // فرمت تاریخ
  const formatDate = (dateString?: string) => {
    if (!dateString) return 'نامشخص';
    try {
      const date = new Date(dateString);
      return new Intl.DateTimeFormat('fa-IR', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }).format(date);
    } catch {
      return 'نامشخص';
    }
  };

  // فرمت قیمت
  const formatPrice = (price?: string | number) => {
    if (!price) return '0';
    const numPrice = typeof price === 'string' ? parseFloat(price) : price;
    return numPrice.toLocaleString('en-US', { maximumFractionDigits: 0 });
  };

  // ترجمه روش پرداخت
  const translatePaymentMethod = (method?: string) => {
    if (!method) return 'نامشخص';
    const translations: Record<string, string> = {
      'bank_transfer': 'انتقال بانکی',
      'wallet': 'کیف پول',
      'wallet_partial': 'ترکیبی (کیف پول + بانک)',
      'hybrid': 'ترکیبی (بانک + کیف پول)',
      'credit': 'مدت‌دار',
      'cash': 'نقدی',
      'card': 'کارت',
      'fib': 'درگاه FIB',
      'online_payment': 'پرداخت آنلاین'
    };
    return translations[method] || method;
  };

  // ترجمه وضعیت
  const translateStatus = (status?: string) => {
    if (!status) return 'نامشخص';
    const translations: Record<string, string> = {
      'pending': 'در انتظار',
      'finance_pending': 'در انتظار بررسی مالی',
      'financial': 'بررسی مالی',
      'warehouse_pending': 'در انتظار انبار',
      'warehouse_processing': 'در حال پردازش در انبار',
      'ready_for_delivery': 'آماده ارسال',
      'logistics_pending': 'در انتظار لجستیک',
      'in_transit': 'در حال ارسال',
      'delivered': 'تحویل داده شده',
      'cancelled': 'لغو شده',
      'rejected': 'رد شده'
    };
    return translations[status] || status;
  };

  // استخراج نام مشتری
  const getCustomerName = () => {
    if (order?.customerName) return order.customerName;
    if (order?.customer?.firstName || order?.customer?.lastName) {
      return `${order.customer.firstName || ''} ${order.customer.lastName || ''}`.trim();
    }
    if (order?.customerFirstName || order?.customerLastName) {
      return `${order.customerFirstName || ''} ${order.customerLastName || ''}`.trim();
    }
    return 'نامشخص';
  };

  // استخراج آدرس
  const getShippingAddress = () => {
    if (order?.shippingAddress) {
      if (typeof order.shippingAddress === 'string') {
        return order.shippingAddress;
      }
      // اگر یک آبجکت باشد
      const addr = order.shippingAddress;
      return `${addr.address || ''}, ${addr.city || ''}, کد پستی: ${addr.postalCode || ''}`.trim();
    }
    if (order?.recipientAddress) {
      return order.recipientAddress;
    }
    return 'آدرس وارد نشده';
  };

  const status = order?.currentStatus || order?.status || '';

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between">
            <span className="flex items-center gap-2">
              <Hash className="h-5 w-5" />
              جزئیات سفارش {order?.orderNumber || '...'}
            </span>
            {order && (
              <Badge variant={status === 'delivered' ? 'default' : 'secondary'}>
                {translateStatus(status)}
              </Badge>
            )}
          </DialogTitle>
        </DialogHeader>

        <ScrollArea className="max-h-[calc(90vh-8rem)] pr-4">
          {isLoading && (
            <div className="space-y-4">
              <Skeleton className="h-20 w-full" />
              <Skeleton className="h-40 w-full" />
              <Skeleton className="h-40 w-full" />
            </div>
          )}

          {error && (
            <div className="flex items-center gap-2 text-destructive p-4 bg-destructive/10 rounded-lg">
              <AlertCircle className="h-5 w-5" />
              <span>خطا در بارگذاری اطلاعات سفارش</span>
            </div>
          )}

          {order && (
            <div className="space-y-4">
              {/* تاریخ و ساعت سفارش */}
              <div className="flex items-center gap-2 text-sm bg-muted/50 p-3 rounded-lg">
                <Calendar className="h-4 w-4 text-muted-foreground" />
                <span className="font-medium">تاریخ ثبت سفارش:</span>
                <span className="text-muted-foreground">{formatDate(order.createdAt)}</span>
              </div>

              <Separator />

              {/* اطلاعات خریدار */}
              <div className="space-y-3">
                <h4 className="font-semibold flex items-center gap-2">
                  <User className="h-5 w-5 text-primary" />
                  اطلاعات خریدار
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mr-6 bg-muted/30 p-4 rounded-lg">
                  <div className="flex items-start gap-2">
                    <User className="h-4 w-4 text-muted-foreground mt-0.5" />
                    <div>
                      <p className="text-xs text-muted-foreground">نام و نام خانوادگی</p>
                      <p className="font-medium">{getCustomerName()}</p>
                    </div>
                  </div>
                  <div className="flex items-start gap-2">
                    <Phone className="h-4 w-4 text-muted-foreground mt-0.5" />
                    <div>
                      <p className="text-xs text-muted-foreground">شماره تماس</p>
                      <p className="font-medium" dir="ltr">
                        {order.customerPhone || order.customer?.phone || order.recipientPhone || 'وارد نشده'}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-start gap-2 col-span-1 md:col-span-2">
                    <Mail className="h-4 w-4 text-muted-foreground mt-0.5" />
                    <div>
                      <p className="text-xs text-muted-foreground">ایمیل</p>
                      <p className="font-medium" dir="ltr">
                        {order.customerEmail || order.customer?.email || 'وارد نشده'}
                      </p>
                    </div>
                  </div>
                </div>
              </div>

              <Separator />

              {/* آدرس تحویل */}
              <div className="space-y-3">
                <h4 className="font-semibold flex items-center gap-2">
                  <MapPin className="h-5 w-5 text-primary" />
                  آدرس تحویل
                </h4>
                <div className="mr-6 bg-muted/30 p-4 rounded-lg">
                  <p className="text-sm leading-relaxed">{getShippingAddress()}</p>
                  {order.recipientName && order.recipientName !== getCustomerName() && (
                    <p className="text-xs text-muted-foreground mt-2">
                      تحویل گیرنده: {order.recipientName}
                    </p>
                  )}
                </div>
              </div>

              <Separator />

              {/* اقلام سفارش */}
              <div className="space-y-3">
                <h4 className="font-semibold flex items-center gap-2">
                  <Package className="h-5 w-5 text-primary" />
                  اقلام سفارش
                </h4>
                {items && items.length > 0 ? (
                  <div className="space-y-2">
                    {items.map((item: any, index: number) => (
                      <div 
                        key={item.id || index} 
                        className="border rounded-lg p-3 bg-card hover:bg-muted/50 transition-colors"
                      >
                        <div className="flex justify-between items-start mb-2">
                          <div className="flex-1">
                            <p className="font-medium">{item.productName || item.name || 'نامشخص'}</p>
                            {item.productSku && (
                              <p className="text-xs text-muted-foreground">کد: {item.productSku}</p>
                            )}
                          </div>
                          {!hidePrice && item.totalPrice && (
                            <Badge variant="outline" className="font-semibold">
                              {formatPrice(item.totalPrice)} IQD
                            </Badge>
                          )}
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-2 text-xs text-muted-foreground">
                          <div>
                            <span className="font-medium">تعداد:</span>{' '}
                            {formatPrice(item.quantity)} {item.unit || 'عدد'}
                          </div>
                          {!hidePrice && item.unitPrice && (
                            <div>
                              <span className="font-medium">قیمت واحد:</span>{' '}
                              {formatPrice(item.unitPrice)} IQD
                            </div>
                          )}
                          {item.notes && (
                            <div className="col-span-2 md:col-span-3">
                              <span className="font-medium">توضیحات:</span> {item.notes}
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground mr-6 bg-muted/30 p-4 rounded-lg">
                    اطلاعات اقلام در دسترس نیست
                  </p>
                )}
              </div>

              <Separator />

              {/* وزن و اطلاعات حمل */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex items-center gap-2 text-sm bg-muted/30 p-3 rounded-lg">
                  <Weight className="h-4 w-4 text-muted-foreground" />
                  <span className="font-medium">وزن ناخالص:</span>
                  <span className="text-muted-foreground">
                    {order.totalWeight || order.grossWeight 
                      ? `${formatPrice(order.totalWeight || order.grossWeight)} کیلوگرم` 
                      : 'وارد نشده'}
                  </span>
                </div>
                <div className="flex items-center gap-2 text-sm bg-muted/30 p-3 rounded-lg">
                  <FileText className="h-4 w-4 text-muted-foreground" />
                  <span className="font-medium">روش ارسال:</span>
                  <span className="text-muted-foreground">
                    {order.deliveryMethod === 'courier' ? 'پیک' : 
                     order.deliveryMethod === 'postal' ? 'پست' : 
                     order.deliveryMethod || 'نامشخص'}
                  </span>
                </div>
              </div>

              <Separator />

              {/* نحوه تسویه */}
              <div className="flex items-center gap-2 text-sm bg-muted/30 p-3 rounded-lg">
                <CreditCard className="h-4 w-4 text-muted-foreground" />
                <span className="font-medium">نحوه تسویه:</span>
                <Badge variant="outline">{translatePaymentMethod(order.paymentMethod)}</Badge>
              </div>

              {/* مبلغ کل - فقط اگر hidePrice نباشد */}
              {!hidePrice && (
                <>
                  <Separator />
                  <div className="flex items-center justify-between bg-primary/10 p-4 rounded-lg">
                    <div className="flex items-center gap-2">
                      <DollarSign className="h-5 w-5 text-primary" />
                      <span className="font-semibold">مبلغ کل سفارش:</span>
                    </div>
                    <span className="text-2xl font-bold text-primary">
                      {formatPrice(order.totalAmount)} IQD
                    </span>
                  </div>
                </>
              )}

              {/* وضعیت فعلی */}
              <div className="flex items-center gap-2 text-sm bg-muted/50 p-4 rounded-lg mt-4 border-t-2 border-primary/20">
                <Clock className="h-5 w-5 text-primary" />
                <span className="font-semibold">وضعیت فعلی:</span>
                <Badge variant={status === 'delivered' ? 'default' : 'secondary'} className="text-sm">
                  {translateStatus(status)}
                </Badge>
              </div>

              {/* یادداشت‌های اضافی */}
              {(order.financialNotes || order.warehouseNotes || order.deliveryNotes) && (
                <>
                  <Separator />
                  <div className="space-y-2">
                    <h4 className="font-semibold flex items-center gap-2">
                      <FileText className="h-5 w-5 text-primary" />
                      یادداشت‌ها
                    </h4>
                    <div className="space-y-2 mr-6">
                      {order.financialNotes && (
                        <div className="bg-blue-50 dark:bg-blue-950/30 p-3 rounded-lg">
                          <p className="text-xs font-medium text-blue-900 dark:text-blue-200 mb-1">
                            یادداشت مالی:
                          </p>
                          <p className="text-sm text-blue-800 dark:text-blue-300">{order.financialNotes}</p>
                        </div>
                      )}
                      {order.warehouseNotes && (
                        <div className="bg-green-50 dark:bg-green-950/30 p-3 rounded-lg">
                          <p className="text-xs font-medium text-green-900 dark:text-green-200 mb-1">
                            یادداشت انبار:
                          </p>
                          <p className="text-sm text-green-800 dark:text-green-300">{order.warehouseNotes}</p>
                        </div>
                      )}
                      {order.deliveryNotes && (
                        <div className="bg-purple-50 dark:bg-purple-950/30 p-3 rounded-lg">
                          <p className="text-xs font-medium text-purple-900 dark:text-purple-200 mb-1">
                            یادداشت ارسال:
                          </p>
                          <p className="text-sm text-purple-800 dark:text-purple-300">{order.deliveryNotes}</p>
                        </div>
                      )}
                    </div>
                  </div>
                </>
              )}
            </div>
          )}
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/UnifiedOrderCard.t.content:
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { 
  Package, 
  User, 
  Phone, 
  Mail, 
  MapPin, 
  CreditCard, 
  Calendar,
  Hash,
  Weight,
  DollarSign,
  Clock
} from 'lucide-react';

interface OrderItem {
  id: number;
  productName: string;
  productSku?: string;
  quantity: string | number;
  unit?: string;
  unitPrice?: string | number;
  totalPrice?: string | number;
  notes?: string;
}

interface UnifiedOrderCardProps {
  order: {
    id?: number;
    orderNumber?: string;
    customerFirstName?: string;
    customerLastName?: string;
    customerName?: string;
    customerPhone?: string;
    customerEmail?: string;
    shippingAddress?: string;
    paymentMethod?: string;
    totalAmount?: string | number;
    status?: string;
    currentStatus?: string;
    createdAt?: string;
    grossWeight?: string | number;
    items?: OrderItem[];
  };
  hidePrice?: boolean; // برای بخش لجستیک
  language?: 'fa' | 'ar' | 'en';
}

export default function UnifiedOrderCard({ order, hidePrice = false, language = 'fa' }: UnifiedOrderCardProps) {
  // استخراج نام کامل مشتری
  const getCustomerName = () => {
    if (order.customerName) return order.customerName;
    if (order.customerFirstName || order.customerLastName) {
      return `${order.customerFirstName || ''} ${order.customerLastName || ''}`.trim();
    }
    return '';
  };

  // فرمت تاریخ
  const formatDate = (dateString?: string) => {
    if (!dateString) return '';
    try {
      const date = new Date(dateString);
      return new Intl.DateTimeFormat('fa-IR', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }).format(date);
    } catch {
      return dateString;
    }
  };

  // فرمت قیمت
  const formatPrice = (price?: string | number) => {
    if (!price) return '0';
    const numPrice = typeof price === 'string' ? parseFloat(price) : price;
    return numPrice.toLocaleString('en-US', { maximumFractionDigits: 0 });
  };

  // ترجمه روش پرداخت
  const translatePaymentMethod = (method?: string) => {
    if (!method) return '';
    const translations: Record<string, string> = {
      'bank_transfer': 'انتقال بانکی',
      'wallet': 'کیف پول',
      'hybrid': 'ترکیبی (بانک + کیف پول)',
      'credit': 'مدت‌دار',
      'cash': 'نقدی',
      'card': 'کارت',
      'fib': 'درگاه FIB'
    };
    return translations[method] || method;
  };

  // ترجمه وضعیت
  const translateStatus = (status?: string) => {
    if (!status) return '';
    const translations: Record<string, string> = {
      'pending': 'در انتظار',
      'financial': 'بررسی مالی',
      'warehouse_pending': 'در انتظار انبار',
      'warehouse_processing': 'در حال پردازش در انبار',
      'ready_for_delivery': 'آماده ارسال',
      'in_transit': 'در حال ارسال',
      'delivered': 'تحویل داده شده',
      'cancelled': 'لغو شده',
      'rejected': 'رد شده'
    };
    return translations[status] || status;
  };

  const customerName = getCustomerName();
  const status = order.currentStatus || order.status || '';

  return (
    <Card className="w-full">
      <CardHeader className="pb-3">
        <div className="flex justify-between items-start">
          <CardTitle className="text-lg flex items-center gap-2">
            <Hash className="h-4 w-4" />
            سفارش {order.orderNumber || '-'}
          </CardTitle>
          <Badge variant={status === 'delivered' ? 'default' : 'secondary'}>
            {translateStatus(status) || 'نامشخص'}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* تاریخ و ساعت سفارش */}
        <div className="flex items-center gap-2 text-sm">
          <Calendar className="h-4 w-4 text-muted-foreground" />
          <span className="font-medium">تاریخ سفارش:</span>
          <span className="text-muted-foreground">
            {order.createdAt ? formatDate(order.createdAt) : 'نامشخص'}
          </span>
        </div>

        <Separator />

        {/* اطلاعات خریدار */}
        <div className="space-y-2">
          <h4 className="font-semibold text-sm flex items-center gap-2">
            <User className="h-4 w-4" />
            اطلاعات خریدار
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mr-6 text-sm">
            <div className="flex items-center gap-2">
              <User className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="font-medium">نام:</span>
              <span className="text-muted-foreground">{customerName || 'وارد نشده'}</span>
            </div>
            <div className="flex items-center gap-2">
              <Phone className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="font-medium">تلفن:</span>
              <span className="text-muted-foreground" dir="ltr">{order.customerPhone || 'وارد نشده'}</span>
            </div>
            <div className="flex items-center gap-2 col-span-1 md:col-span-2">
              <Mail className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="font-medium">ایمیل:</span>
              <span className="text-muted-foreground" dir="ltr">{order.customerEmail || 'وارد نشده'}</span>
            </div>
          </div>
        </div>

        <Separator />

        {/* آدرس پستی */}
        <div className="space-y-2">
          <h4 className="font-semibold text-sm flex items-center gap-2">
            <MapPin className="h-4 w-4" />
            آدرس تحویل
          </h4>
          <p className="text-sm text-muted-foreground mr-6">
            {order.shippingAddress || 'آدرس وارد نشده'}
          </p>
        </div>

        <Separator />

        {/* اقلام سفارش */}
        <div className="space-y-2">
          <h4 className="font-semibold text-sm flex items-center gap-2">
            <Package className="h-4 w-4" />
            اقلام سفارش
          </h4>
          {order.items && order.items.length > 0 ? (
            <div className="mr-6 space-y-2">
              {order.items.map((item, index) => (
                <div key={item.id || index} className="text-sm border rounded-md p-3 bg-muted/30">
                  <div className="flex justify-between items-start mb-1">
                    <span className="font-medium">{item.productName || 'نامشخص'}</span>
                    {item.productSku && (
                      <span className="text-xs text-muted-foreground">SKU: {item.productSku}</span>
                    )}
                  </div>
                  <div className="flex gap-4 text-xs text-muted-foreground">
                    <span>تعداد: {formatPrice(item.quantity)} {item.unit || 'عدد'}</span>
                    {!hidePrice && item.unitPrice && (
                      <span>قیمت واحد: {formatPrice(item.unitPrice)} IQD</span>
                    )}
                    {!hidePrice && item.totalPrice && (
                      <span className="font-medium">جمع: {formatPrice(item.totalPrice)} IQD</span>
                    )}
                  </div>
                  {item.notes && (
                    <p className="text-xs text-muted-foreground mt-1">توضیحات: {item.notes}</p>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <p className="text-sm text-muted-foreground mr-6">اطلاعات اقلام موجود نیست</p>
          )}
        </div>

        <Separator />

        {/* وزن ناخالص */}
        <div className="flex items-center gap-2 text-sm">
          <Weight className="h-4 w-4 text-muted-foreground" />
          <span className="font-medium">وزن ناخالص:</span>
          <span className="text-muted-foreground">
            {order.grossWeight ? `${formatPrice(order.grossWeight)} کیلوگرم` : 'وارد نشده'}
          </span>
        </div>

        <Separator />

        {/* نحوه تسویه */}
        <div className="flex items-center gap-2 text-sm">
          <CreditCard className="h-4 w-4 text-muted-foreground" />
          <span className="font-medium">نحوه تسویه:</span>
          <span className="text-muted-foreground">
            {translatePaymentMethod(order.paymentMethod) || 'وارد نشده'}
          </span>
        </div>

        {/* مبلغ کل - فقط اگر hidePrice نباشد */}
        {!hidePrice && (
          <>
            <Separator />
            <div className="flex items-center gap-2 text-sm">
              <DollarSign className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium">مبلغ کل:</span>
              <span className="text-lg font-bold text-primary">
                {order.totalAmount ? `${formatPrice(order.totalAmount)} IQD` : 'نامشخص'}
              </span>
            </div>
          </>
        )}

        {/* وضعیت فعلی */}
        <div className="flex items-center gap-2 text-sm bg-muted/50 p-3 rounded-md mt-4">
          <Clock className="h-4 w-4 text-muted-foreground" />
          <span className="font-medium">وضعیت فعلی:</span>
          <Badge variant={status === 'delivered' ? 'default' : 'secondary'}>
            {translateStatus(status) || 'نامشخص'}
          </Badge>
        </div>
      </CardContent>
    </Card>
  );
}

server/convert-s3-urls-to-local.ts.content:
import { db } from './db';
import { shopProducts } from '@shared/shop-schema';
import { eq } from 'drizzle-orm';

async function convertS3UrlsToLocal() {
  console.log('🔄 Converting S3 URLs to local proxy URLs...\n');

  let updatedCount = 0;

  // Get all products with images
  const products = await db.select().from(shopProducts);

  for (const product of products) {
    let hasChanges = false;
    let newImageUrls = product.imageUrls as string[] || [];

    // Convert S3 URLs to local proxy URLs
    if (newImageUrls.length > 0) {
      const convertedUrls = newImageUrls.map(url => {
        // If it's an S3 URL, extract the filename and convert to local format
        if (url.includes('s3.') || url.includes('amazonaws.com')) {
          // Extract the S3 key (e.g., "images/1762286005740-77045086084039af.jpg")
          const match = url.match(/\/images\/([^/?]+)/);
          if (match && match[1]) {
            const fileName = match[1];
            const localUrl = `/uploads/images/${fileName}`;
            console.log(`  🔄 Converting: ${url} → ${localUrl}`);
            hasChanges = true;
            return localUrl;
          }
        }
        return url;
      });

      if (hasChanges) {
        newImageUrls = convertedUrls;
      }
    }

    // Update product if changes were made
    if (hasChanges) {
      await db
        .update(shopProducts)
        .set({ imageUrls: newImageUrls })
        .where(eq(shopProducts.id, product.id));

      console.log(`✅ Updated product ${product.id}: ${product.name}`);
      updatedCount++;
    }
  }

  console.log(`\n✅ Conversion completed! Updated ${updatedCount} products`);
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  convertS3UrlsToLocal()
    .then(() => {
      console.log('✅ Done!');
      process.exit(0);
    })
    .catch((error) => {
      console.error('❌ Error:', error);
      process.exit(1);
    });
}

export { convertS3UrlsToLocal };

server/migrate-all-files-to-s3.ts.content:
import axios from 'axios';
import { getAwsS3Service, initializeAwsS3FromDb } from './aws-s3-service';
import { db } from './db';
import { customerDb } from './customer-db';
import { shopProducts } from '@shared/shop-schema';
import { customerOrders } from '@shared/customer-schema';
import { eq, sql, isNotNull, ne } from 'drizzle-orm';
import fs from 'fs';

interface MigrationStats {
  totalFiles: number;
  migratedFiles: number;
  failedFiles: number;
  errors: string[];
}

async function migrateAllFilesToS3() {
  console.log('🚀 Starting complete migration to Amazon S3...\n');

  const stats: MigrationStats = {
    totalFiles: 0,
    migratedFiles: 0,
    failedFiles: 0,
    errors: []
  };

  try {
    // Initialize S3
    console.log('🔧 Initializing S3 service...');
    await initializeAwsS3FromDb(db);
    const s3Service = getAwsS3Service();
    console.log('✅ S3 service ready\n');

    // 1. Migrate catalogs
    console.log('📚 MIGRATING CATALOGS...\n');
    await migrateCatalogs(s3Service, stats);

    // 2. Migrate MSDS files
    console.log('\n📋 MIGRATING MSDS FILES...\n');
    await migrateMSDS(s3Service, stats);

    // 3. Migrate payment receipts
    console.log('\n💰 MIGRATING PAYMENT RECEIPTS...\n');
    await migratePaymentReceipts(s3Service, stats);

    // Save migration report
    const report = {
      timestamp: new Date().toISOString(),
      stats,
      errors: stats.errors
    };

    fs.writeFileSync('complete-migration-report.json', JSON.stringify(report, null, 2));
    console.log('\n📄 Migration report saved to: complete-migration-report.json');

  } catch (error: any) {
    console.error('\n❌ Migration failed:', error.message);
    stats.errors.push(`Fatal: ${error.message}`);
  }

  // Print summary
  console.log('\n' + '='.repeat(60));
  console.log('📊 COMPLETE MIGRATION SUMMARY');
  console.log('='.repeat(60));
  console.log(`Total files processed: ${stats.totalFiles}`);
  console.log(`✅ Successfully migrated: ${stats.migratedFiles}`);
  console.log(`❌ Failed: ${stats.failedFiles}`);
  if (stats.errors.length > 0) {
    console.log(`\n⚠️  Errors (${stats.errors.length}):`);
    stats.errors.slice(0, 10).forEach((err, i) => {
      console.log(`   ${i + 1}. ${err}`);
    });
    if (stats.errors.length > 10) {
      console.log(`   ... and ${stats.errors.length - 10} more`);
    }
  }
  console.log('='.repeat(60) + '\n');

  return stats;
}

async function migrateCatalogs(s3Service: any, stats: MigrationStats) {
  const products = await db
    .select()
    .from(shopProducts)
    .where(sql`${shopProducts.pdfCatalogUrl} IS NOT NULL AND ${shopProducts.pdfCatalogUrl} != ''`);

  console.log(`   Found ${products.length} products with catalogs`);

  for (const product of products) {
    const catalogUrl = product.pdfCatalogUrl as string;
    stats.totalFiles++;

    // Skip if already S3
    if (catalogUrl.includes('s3.') || catalogUrl.includes('amazonaws.com')) {
      console.log(`  ✅ Already in S3: ${catalogUrl}`);
      continue;
    }

    try {
      console.log(`  🔄 Migrating catalog for product ${product.id}: ${catalogUrl}`);

      let fullUrl = catalogUrl;
      if (catalogUrl.startsWith('/uploads/') || catalogUrl.startsWith('/objects/') || catalogUrl.startsWith('/replit-objstore')) {
        fullUrl = `http://localhost:5000${catalogUrl}`;
      }

      const response = await axios.get(fullUrl, { 
        responseType: 'arraybuffer',
        timeout: 60000
      });

      const fileBuffer = Buffer.from(response.data);
      const fileName = catalogUrl.split('/').pop() || `catalog-${Date.now()}.pdf`;

      const uploadResult = await s3Service.uploadFile(
        fileBuffer,
        fileName,
        'application/pdf',
        'catalogs'
      );

      if (!uploadResult.success || !uploadResult.url) {
        throw new Error(uploadResult.message || 'Upload failed');
      }

      // Convert to local proxy URL
      const localUrl = `/uploads/catalogs/${uploadResult.url.split('/').pop()}`;

      await db
        .update(shopProducts)
        .set({ pdfCatalogUrl: localUrl })
        .where(eq(shopProducts.id, product.id));

      console.log(`  ✅ Migrated and updated: ${localUrl}`);
      stats.migratedFiles++;

    } catch (error: any) {
      console.error(`  ❌ Failed: ${error.message}`);
      stats.failedFiles++;
      stats.errors.push(`Catalog ${product.id}: ${error.message}`);
    }
  }
}

async function migrateMSDS(s3Service: any, stats: MigrationStats) {
  const products = await db
    .select()
    .from(shopProducts)
    .where(sql`${shopProducts.msdsUrl} IS NOT NULL AND ${shopProducts.msdsUrl} != ''`);

  console.log(`   Found ${products.length} products with MSDS files`);

  for (const product of products) {
    const msdsUrl = product.msdsUrl as string;
    stats.totalFiles++;

    // Skip if already S3
    if (msdsUrl.includes('s3.') || msdsUrl.includes('amazonaws.com')) {
      console.log(`  ✅ Already in S3: ${msdsUrl}`);

      // Convert S3 URL to local proxy URL
      const match = msdsUrl.match(/\/msds\/([^/?]+)/);
      if (match && match[1]) {
        const fileName = match[1];
        const localUrl = `/uploads/msds/${fileName}`;

        await db
          .update(shopProducts)
          .set({ msdsUrl: localUrl })
          .where(eq(shopProducts.id, product.id));

        console.log(`  🔄 Converted to local URL: ${localUrl}`);
      }
      continue;
    }

    try {
      console.log(`  🔄 Migrating MSDS for product ${product.id}: ${msdsUrl}`);

      let fullUrl = msdsUrl;
      if (msdsUrl.startsWith('/uploads/') || msdsUrl.startsWith('/objects/') || msdsUrl.startsWith('/replit-objstore')) {
        fullUrl = `http://localhost:5000${msdsUrl}`;
      }

      const response = await axios.get(fullUrl, { 
        responseType: 'arraybuffer',
        timeout: 60000
      });

      const fileBuffer = Buffer.from(response.data);
      const fileName = msdsUrl.split('/').pop() || `msds-${Date.now()}.pdf`;

      const uploadResult = await s3Service.uploadFile(
        fileBuffer,
        fileName,
        'application/pdf',
        'msds'
      );

      if (!uploadResult.success || !uploadResult.url) {
        throw new Error(uploadResult.message || 'Upload failed');
      }

      // Convert to local proxy URL
      const localUrl = `/uploads/msds/${uploadResult.url.split('/').pop()}`;

      await db
        .update(shopProducts)
        .set({ msdsUrl: localUrl })
        .where(eq(shopProducts.id, product.id));

      console.log(`  ✅ Migrated and updated: ${localUrl}`);
      stats.migratedFiles++;

    } catch (error: any) {
      console.error(`  ❌ Failed: ${error.message}`);
      stats.failedFiles++;
      stats.errors.push(`MSDS ${product.id}: ${error.message}`);
    }
  }
}

async function migratePaymentReceipts(s3Service: any, stats: MigrationStats) {
  const orders = await customerDb
    .select()
    .from(customerOrders)
    .where(sql`${customerOrders.receiptPath} IS NOT NULL AND ${customerOrders.receiptPath} != ''`);

  console.log(`   Found ${orders.length} orders with payment receipts`);

  for (const order of orders) {
    const receiptPath = order.receiptPath as string;
    stats.totalFiles++;

    // Skip if already S3
    if (receiptPath.includes('s3.') || receiptPath.includes('amazonaws.com')) {
      console.log(`  ✅ Already in S3: Order ${order.id}`);

      // Convert S3 URL to local proxy URL if needed
      const match = receiptPath.match(/\/payment-receipts\/([^/?]+)/);
      if (match && match[1]) {
        const fileName = match[1];
        const localUrl = `/uploads/receipts/${fileName}`;

        await customerDb
          .update(customerOrders)
          .set({ receiptPath: localUrl })
          .where(eq(customerOrders.id, order.id));

        console.log(`  🔄 Converted to local URL for order ${order.id}`);
      }
      continue;
    }

    try {
      console.log(`  🔄 Migrating receipt for order ${order.id}: ${receiptPath}`);

      // Handle Replit Object Storage paths
      let fullUrl = receiptPath;
      if (receiptPath.startsWith('/replit-objstore')) {
        // This is an object storage path - need to use the object storage API
        fullUrl = `http://localhost:5000${receiptPath}`;
      } else if (receiptPath.startsWith('/uploads/')) {
        fullUrl = `http://localhost:5000${receiptPath}`;
      }

      const response = await axios.get(fullUrl, { 
        responseType: 'arraybuffer',
        timeout: 60000
      });

      const fileBuffer = Buffer.from(response.data);

      // Determine file extension from content-type or path
      let extension = 'pdf';
      if (receiptPath.includes('.')) {
        extension = receiptPath.split('.').pop() || 'pdf';
      } else if (response.headers['content-type']) {
        const contentType = response.headers['content-type'];
        if (contentType.includes('image/png')) extension = 'png';
        else if (contentType.includes('image/jpeg')) extension = 'jpg';
        else if (contentType.includes('application/pdf')) extension = 'pdf';
      }

      const fileName = `receipt-${order.id}-${Date.now()}.${extension}`;
      const contentType = response.headers['content-type'] || 'application/pdf';

      const uploadResult = await s3Service.uploadFile(
        fileBuffer,
        fileName,
        contentType,
        'payment-receipts'
      );

      if (!uploadResult.success || !uploadResult.url) {
        throw new Error(uploadResult.message || 'Upload failed');
      }

      // Convert to local proxy URL
      const localUrl = `/uploads/receipts/${uploadResult.url.split('/').pop()}`;

      await customerDb
        .update(customerOrders)
        .set({ receiptPath: localUrl })
        .where(eq(customerOrders.id, order.id));

      console.log(`  ✅ Migrated receipt for order ${order.id}: ${localUrl}`);
      stats.migratedFiles++;

    } catch (error: any) {
      console.error(`  ❌ Failed for order ${order.id}: ${error.message}`);
      stats.failedFiles++;
      stats.errors.push(`Receipt order ${order.id}: ${error.message}`);
    }
  }
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  migrateAllFilesToS3()
    .then(() => {
      console.log('✅ Migration completed!');
      process.exit(0);
    })
    .catch((error) => {
      console.error('❌ Migration failed:', error);
      process.exit(1);
    });
}

export { migrateAllFilesToS3 };

server/migrate-objects-to-s3.ts.content:
import { db } from './db';
import { shopProducts } from '../shared/schema';
import { AwsS3Service } from './aws-s3-service';
import { awsS3Settings } from '../shared/schema';
import { sql } from 'drizzle-orm';
import axios from 'axios';

async function migrateObjectsToS3() {
  console.log('🚀 [MIGRATION] Starting migration from Replit Objects to S3...\n');

  try {
    // Initialize S3 service
    const settings = await db.select().from(awsS3Settings).where(sql`is_active = true`).limit(1);

    if (settings.length === 0) {
      throw new Error('No active S3 settings found');
    }

    const s3Service = new AwsS3Service(settings[0]);
    console.log('✅ S3 Service initialized\n');

    // Get all products with images
    const products = await db.select().from(shopProducts);

    let totalMigrated = 0;
    let totalFailed = 0;

    for (const product of products) {
      if (!product.imageUrls) {
        continue;
      }

      // Handle both JSON and plain text formats
      let imageUrls: any[];
      try {
        if (typeof product.imageUrls === 'string') {
          imageUrls = JSON.parse(product.imageUrls);
        } else {
          imageUrls = product.imageUrls as any[];
        }
      } catch (e) {
        console.log(`  ⚠️  Skipping product ${product.id} - invalid image_urls format`);
        continue;
      }

      if (!Array.isArray(imageUrls) || imageUrls.length === 0) {
        continue;
      }

      const newImageUrls: string[] = [];
      let productChanged = false;

      console.log(`\n📦 Processing product: ${product.name} (ID: ${product.id})`);

      for (const url of imageUrls) {
        if (typeof url !== 'string') continue;

        // Check if URL is from Replit Objects
        if (url.includes('/objects/')) {
          try {
            console.log(`  🔄 Migrating: ${url}`);

            // Download from Replit Objects
            const fullUrl = url.startsWith('http') ? url : `https://momtazchem.com${url}`;
            const response = await axios.get(fullUrl, { responseType: 'arraybuffer' });
            const fileBuffer = Buffer.from(response.data);

            // Extract filename
            const fileName = url.split('/').pop() || 'unknown';

            // Determine content type
            let contentType = 'image/jpeg';
            if (fileName.endsWith('.png')) contentType = 'image/png';
            else if (fileName.endsWith('.webp')) contentType = 'image/webp';
            else if (fileName.endsWith('.gif')) contentType = 'image/gif';

            // Upload to S3 product-images folder with ORIGINAL filename preserved
            const uploadResult = await s3Service.uploadPublicFile(
              fileBuffer,
              fileName,
              contentType,
              'product-images',
              { preserveFileName: true }
            );

            if (uploadResult.success && uploadResult.key) {
              // Extract the actual filename that was uploaded to S3
              // (may be sanitized differently than original)
              const actualFileName = uploadResult.key.split('/').pop();
              // Convert S3 URL to local proxy format
              const newUrl = `/uploads/product-images/${actualFileName}`;
              newImageUrls.push(newUrl);
              console.log(`  ✅ Migrated to: ${newUrl} (from: ${fileName})`);
              totalMigrated++;
              productChanged = true;
            } else {
              console.log(`  ❌ Failed to upload: ${uploadResult.message}`);
              newImageUrls.push(url); // Keep original
              totalFailed++;
            }
          } catch (error) {
            console.log(`  ❌ Error migrating: ${error.message}`);
            newImageUrls.push(url); // Keep original
            totalFailed++;
          }
        } else if (url.includes('/uploads/images/')) {
          // Old local format - convert to new format
          const fileName = url.split('/').pop();
          const newUrl = `/uploads/product-images/${fileName}`;
          newImageUrls.push(newUrl);
          productChanged = true;
          console.log(`  🔄 Converted URL: ${url} → ${newUrl}`);
        } else {
          // Already in correct format
          newImageUrls.push(url);
        }
      }

      // Update database if changes were made
      if (productChanged && newImageUrls.length > 0) {
        await db
          .update(shopProducts)
          .set({ imageUrls: JSON.stringify(newImageUrls) })
          .where(sql`id = ${product.id}`);

        console.log(`  💾 Database updated with ${newImageUrls.length} images`);
      }
    }

    console.log('\n' + '='.repeat(60));
    console.log('✅ [MIGRATION] Complete!');
    console.log(`📊 Total migrated: ${totalMigrated}`);
    console.log(`❌ Total failed: ${totalFailed}`);
    console.log('='.repeat(60) + '\n');

  } catch (error) {
    console.error('❌ [MIGRATION] Error:', error);
    throw error;
  }
}

// Run migration
migrateObjectsToS3()
  .then(() => {
    console.log('Migration finished successfully');
    process.exit(0);
  })
  .catch((error) => {
    console.error('Migration failed:', error);
    process.exit(1);
  });

