import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { useToast } from "@/hooks/use-toast";
import { Store, Loader2, ArrowRight } from "lucide-react";
import { Link, useLocation } from "wouter";

const loginSchema = z.object({
  username: z.string().min(3, "نام کاربری یا ایمیل را وارد کنید"),
  password: z.string().min(6, "رمز عبور باید حداقل 6 کاراکتر باشد"),
});

type LoginForm = z.infer<typeof loginSchema>;

export default function VendorLogin() {
  const { toast } = useToast();
  const [, setLocation] = useLocation();

  const form = useForm<LoginForm>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      username: "",
      password: "",
    },
  });

  const loginMutation = useMutation({
    mutationFn: async (data: LoginForm) => {
      return apiRequest("/api/vendors/auth/login", {
        method: "POST",
        body: data,
      });
    },
    onSuccess: (data) => {
      toast({
        title: "✅ ورود موفق",
        description: `خوش آمدید ${data.vendor?.vendorName || ''}`,
        variant: "default",
      });
      // Redirect to vendor dashboard
      setLocation("/vendor/dashboard");
    },
    onError: (error: any) => {
      toast({
        title: "❌ خطا در ورود",
        description: error.message || "ایمیل یا رمز عبور اشتباه است",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: LoginForm) => {
    loginMutation.mutate(data);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 via-white to-blue-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 flex items-center justify-center p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <div className="mx-auto w-16 h-16 bg-purple-100 dark:bg-purple-900/30 rounded-full flex items-center justify-center mb-4">
            <Store className="w-8 h-8 text-purple-600 dark:text-purple-400" />
          </div>
          <CardTitle className="text-2xl">ورود فروشنده</CardTitle>
          <CardDescription>
            به پنل مدیریت فروشگاه خود وارد شوید
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <FormField
                control={form.control}
                name="username"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>ایمیل / نام کاربری</FormLabel>
                    <FormControl>
                      <Input
                        type="text"
                        placeholder="vendor@example.com"
                        {...field}
                        data-testid="input-username"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="password"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>رمز عبور</FormLabel>
                    <FormControl>
                      <Input
                        type="password"
                        placeholder="••••••••"
                        {...field}
                        data-testid="input-password"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <Button
                type="submit"
                className="w-full"
                disabled={loginMutation.isPending}
                data-testid="button-login"
              >
                {loginMutation.isPending ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    در حال ورود...
                  </>
                ) : (
                  <>
                    <ArrowRight className="w-4 h-4 mr-2" />
                    ورود به پنل
                  </>
                )}
              </Button>
            </form>
          </Form>

          <div className="mt-6 text-center space-y-2">
            <p className="text-sm text-muted-foreground">
              هنوز ثبت نام نکرده‌اید؟
            </p>
            <Link href="/vendor-registration">
              <Button variant="outline" className="w-full" data-testid="link-register">
                ثبت نام به عنوان فروشنده
              </Button>
            </Link>
          </div>

          <div className="mt-4 pt-4 border-t text-center">
            <Link href="/">
              <Button variant="ghost" size="sm" data-testid="link-home">
                بازگشت به صفحه اصلی
              </Button>
            </Link>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/vendor-add-product.tsx.content:
import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useLocation, Link } from "wouter";
import { ArrowLeft, Loader2, Package } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";

const productSchema = z.object({
  name: z.string().min(3, "نام محصول باید حداقل 3 کاراکتر باشد"),
  technicalName: z.string().optional(),
  sku: z.string().min(3, "SKU الزامی است"),
  barcode: z.string().min(8, "بارکد باید حداقل 8 رقم باشد"),
  stockQuantity: z.number().min(0, "موجودی نمی‌تواند منفی باشد"),
  unitPrice: z.number().min(0, "قیمت نمی‌تواند منفی باشد"),
  description: z.string().optional(),
});

type ProductForm = z.infer<typeof productSchema>;

export default function VendorAddProduct() {
  const { toast } = useToast();
  const [, setLocation] = useLocation();

  const form = useForm<ProductForm>({
    resolver: zodResolver(productSchema),
    defaultValues: {
      name: "",
      technicalName: "",
      sku: "",
      barcode: "",
      stockQuantity: 0,
      unitPrice: 0,
      description: "",
    },
  });

  const createProductMutation = useMutation({
    mutationFn: async (data: ProductForm) => {
      return apiRequest("/api/vendors/products", {
        method: "POST",
        body: {
          ...data,
          status: "active",
        },
      });
    },
    onSuccess: () => {
      toast({
        title: "✅ موفق",
        description: "محصول با موفقیت اضافه شد",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/vendors/products"] });
      setLocation("/vendor/dashboard");
    },
    onError: (error: any) => {
      toast({
        title: "❌ خطا",
        description: error.message || "خطا در افزودن محصول",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: ProductForm) => {
    createProductMutation.mutate(data);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 via-white to-blue-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 p-4">
      <div className="max-w-4xl mx-auto py-8">
        <Link href="/vendor/dashboard">
          <Button variant="ghost" className="mb-4">
            <ArrowLeft className="w-4 h-4 ml-2" />
            بازگشت به داشبورد
          </Button>
        </Link>

        <Card>
          <CardHeader>
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900/30 rounded-full flex items-center justify-center">
                <Package className="w-6 h-6 text-purple-600 dark:text-purple-400" />
              </div>
              <div>
                <CardTitle className="text-2xl">افزودن محصول جدید</CardTitle>
                <CardDescription>اطلاعات محصول خود را وارد کنید</CardDescription>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="name"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>نام محصول *</FormLabel>
                        <FormControl>
                          <Input placeholder="مثال: محلول شیمیایی A" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="technicalName"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>نام فنی</FormLabel>
                        <FormControl>
                          <Input placeholder="نام فنی محصول" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="sku"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>SKU *</FormLabel>
                        <FormControl>
                          <Input placeholder="VND-001" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="barcode"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>بارکد *</FormLabel>
                        <FormControl>
                          <Input placeholder="1234567890123" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="stockQuantity"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>موجودی *</FormLabel>
                        <FormControl>
                          <Input
                            type="number"
                            placeholder="100"
                            {...field}
                            onChange={(e) => field.onChange(parseInt(e.target.value) || 0)}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="unitPrice"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>قیمت واحد (IQD) *</FormLabel>
                        <FormControl>
                          <Input
                            type="number"
                            step="0.01"
                            placeholder="50000"
                            {...field}
                            onChange={(e) => field.onChange(parseFloat(e.target.value) || 0)}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>توضیحات</FormLabel>
                      <FormControl>
                        <Textarea
                          placeholder="توضیحات کامل محصول..."
                          rows={4}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <div className="flex gap-4">
                  <Button
                    type="submit"
                    disabled={createProductMutation.isPending}
                    className="flex-1"
                    data-testid="button-submit-product"
                  >
                    {createProductMutation.isPending ? (
                      <>
                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        در حال ذخیره...
                      </>
                    ) : (
                      "افزودن محصول"
                    )}
                  </Button>
                  <Link href="/vendor/dashboard">
                    <Button type="button" variant="outline">
                      انصراف
                    </Button>
                  </Link>
                </div>
              </form>
            </Form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/components/TawkToChat.tsx.content:
import { useEffect, useRef } from 'react';
import { useQuery } from '@tanstack/react-query';

interface TawkSettings {
  isEnabled: boolean;
  scriptCode: string;
}

declare global {
  interface Window {
    Tawk_API?: any;
    Tawk_LoadStart?: any;
  }
}

export default function TawkToChat() {
  const scriptLoadedRef = useRef(false);
  const lastEnabledState = useRef<boolean | null>(null);

  const { data: tawkSettings, refetch } = useQuery<{ success: boolean; data: TawkSettings }>({
    queryKey: ['/api/tawk-support'],
    refetchInterval: 10000, // Check every 10 seconds
    refetchOnWindowFocus: true, // Refetch when user comes back to tab
  });

  // Listen for custom tawk settings update event
  useEffect(() => {
    const handleTawkUpdate = () => {
      console.log('🔄 Tawk settings update event received, refetching...');
      refetch();
    };

    window.addEventListener('tawk-settings-updated', handleTawkUpdate);
    return () => window.removeEventListener('tawk-settings-updated', handleTawkUpdate);
  }, [refetch]);

  useEffect(() => {
    const isEnabled = tawkSettings?.success && tawkSettings.data?.isEnabled;
    const scriptCode = tawkSettings?.data?.scriptCode;

    const removeTawkWidget = () => {
      console.log('🔄 Attempting to remove Tawk.to widget...');

      // Remove all Tawk.to scripts
      const tawkScripts = document.querySelectorAll('script[src*="tawk.to"], script[data-tawk-script="true"]');
      tawkScripts.forEach(script => {
        script.remove();
        console.log('🗑️ Removed Tawk.to script:', script.getAttribute('src'));
      });

      // Remove all Tawk.to widget containers and iframes
      const tawkContainers = document.querySelectorAll(
        '[id^="tawk"], [class*="tawk"], div[style*="tawk"], iframe[src*="tawk"]'
      );
      tawkContainers.forEach(container => {
        container.remove();
        console.log('🗑️ Removed Tawk.to container:', container.id || container.className);
      });

      // Clear Tawk API objects
      if (window.Tawk_API) {
        try {
          if (typeof window.Tawk_API.hideWidget === 'function') {
            window.Tawk_API.hideWidget();
            console.log('👻 Hid Tawk.to widget');
          }
          if (typeof window.Tawk_API.onLoad === 'function') {
            window.Tawk_API.onLoad = null;
          }
        } catch (e) {
          console.log('⚠️ Could not interact with Tawk API:', e);
        }
        delete window.Tawk_API;
        delete window.Tawk_LoadStart;
        console.log('🧹 Cleared Tawk API objects');
      }

      scriptLoadedRef.current = false;
      lastEnabledState.current = false;
      console.log('✅ Tawk.to Live Chat completely removed');
    };

    // Check if enabled state changed
    const hasStateChanged = lastEnabledState.current !== null && lastEnabledState.current !== isEnabled;

    if (isEnabled && scriptCode) {
      // Chat is enabled
      if (hasStateChanged && lastEnabledState.current === false) {
        console.log('🔄 State changed from disabled to enabled');
        // Remove old widget first
        removeTawkWidget();
      }

      // Only load if not already loaded
      if (scriptLoadedRef.current) {
        console.log('ℹ️ Tawk.to already loaded, skipping');
        lastEnabledState.current = true;
        return;
      }

      const scriptMatch = scriptCode.match(/src=['"]([^'"]+)['"]/);
      if (scriptMatch && scriptMatch[1]) {
        const scriptSrc = scriptMatch[1];

        // Check if script already exists
        const existingScript = document.querySelector(`script[src="${scriptSrc}"]`);
        if (existingScript) {
          scriptLoadedRef.current = true;
          lastEnabledState.current = true;
          console.log('ℹ️ Tawk.to script already in DOM');
          return;
        }

        // Initialize Tawk API objects before loading script
        window.Tawk_API = window.Tawk_API || {};
        window.Tawk_LoadStart = new Date();

        // Set widget position to bottom-left
        window.Tawk_API.customStyle = {
          visibility: {
            desktop: {
              position: 'bl', // bottom-left
              xOffset: 20,
              yOffset: 20
            },
            mobile: {
              position: 'bl', // bottom-left on mobile
              xOffset: 10,
              yOffset: 10
            }
          }
        };

        console.log('📥 Loading Tawk.to widget at bottom-left position...');
        const script = document.createElement('script');
        script.src = scriptSrc;
        script.async = true;
        script.charset = 'UTF-8';
        script.setAttribute('crossorigin', '*');
        script.setAttribute('data-tawk-script', 'true');

        const firstScript = document.getElementsByTagName('script')[0];
        if (firstScript && firstScript.parentNode) {
          firstScript.parentNode.insertBefore(script, firstScript);

          script.onload = () => {
            scriptLoadedRef.current = true;
            lastEnabledState.current = true;
            console.log('✅ Tawk.to Live Chat loaded successfully at bottom-left');
          };

          script.onerror = () => {
            scriptLoadedRef.current = false;
            lastEnabledState.current = false;
            console.error('❌ Failed to load Tawk.to script');
          };
        }
      }
    } else if (tawkSettings?.success) {
      // Settings exist and chat is disabled
      if (!isEnabled && (scriptLoadedRef.current || hasStateChanged)) {
        console.log('🔄 Chat is disabled, removing widget...');
        removeTawkWidget();
      }
    }
  }, [tawkSettings]);

  return null;
}
